INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人或团体在别人心中受到尊敬和认可的好名声。", "primary_collocate": null, "pronunciation": "shēng wàng", "ipa": "ʂɤŋ˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "它不仅是资源争夺或排名晋升的显性对抗，更深层地体现为声望资本的隐性积累。", "target_word": "声望", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "虚拟世界中的声望，由持续的行为输出而非既定身份授予。", "target_word": "声望", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这位老教授在学术界很有声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠诚实赢得了很高的声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次丑闻毁掉了公司多年的声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是村里最有声望的人。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好医生的声望来自病人的信任。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学在国内外都有很高的声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想提高自己在同行中的声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多做好事能让人积累声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "声望", "label": "基本形式"}], "register": "中性", "sense_fingerprint": "人或团体在他人心中受尊敬、被认可的好名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声望", "is_correct": true, "explanation": "声望：指人或团体受到的尊敬和认可，可以与“资本”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重资本”不成词，体重与声望无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色资本”不成立，颜色不能作资本的修饰语。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与资本的积累无关，句意不通。"}], "explanations": {"声望": "声望：指人或团体受到的尊敬和认可，可以与“资本”搭配。", "体重": "搭配：“体重资本”不成词，体重与声望无关。", "颜色": "搭配：“颜色资本”不成立，颜色不能作资本的修饰语。", "温度": "语义：温度与资本的积累无关，句意不通。"}, "sentence_index": 0, "correct_answer": "声望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为一次丑闻，声望一下子高了许多。", "explanation": "这里应该用〈名气〉。声望指受人尊敬的好名声，丑闻不会让人“声望一下子高了许多”；只说知名，可用“名气”。"}, {"text": "这座小城因为一场大火，声望很大，却没有人敬重它。", "explanation": "这里应该用〈名气〉。声望指受人尊敬的好名声，“没有人敬重它”与之矛盾；只说知名，可用“名气”。"}, {"text": "这家餐厅因为卫生问题，声望却一天比一天高。", "explanation": "这里应该用〈口碑〉。声望指受人尊敬的好名声，卫生问题不会让它“一天比一天高”；说评价变差应用“口碑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声望", "is_correct": true, "explanation": "声望：指医生在病人心中受到的尊敬与认可，来自信任。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格的表现，不来自“信任”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是体貌特征，不说“来自病人的信任”。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是先天的生理特征，与“信任”无关。"}], "explanations": {"声望": "声望：指医生在病人心中受到的尊敬与认可，来自信任。", "脾气": "语义：脾气是性格的表现，不来自“信任”。", "身高": "体貌：身高是体貌特征，不说“来自病人的信任”。", "血型": "语义：血型是先天的生理特征，与“信任”无关。"}, "sentence_index": 6, "correct_answer": "声望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身上积累了一把声望，大家都很信任他。", "explanation": "这里应该用〈点〉。〈把〉用于有柄的物件，声望是抽象名词，可说“一点声望”。"}, {"text": "他身上积累了一根声望，大家都很信任他。", "explanation": "这里应该用〈点〉。〈根〉用于细长条的东西，声望是抽象名词，可说“一点声望”。"}, {"text": "他身上积累了一只声望，大家都很信任他。", "explanation": "这里应该用〈点〉。〈只〉用于成对物件之一或某些动物，声望是抽象名词，可说“一点声望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位医生在当地很有一把声望，病人都愿意找他看病。", "corrected_sentence": "这位医生在当地很有声望，病人都愿意找他看病。", "error_description": "“声望”是抽象名词，前面不能加量词“把”（“把”用于有柄的物件）。应直接说“很有声望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他多年来坚持做公益，在城里赢得了很高的声望们。", "corrected_sentence": "他多年来坚持做公益，在城里赢得了很高的声望。", "error_description": "“声望”是抽象名词，后面不能加复数词尾“们”，应说“很高的声望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
