INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "清楚地表现出来，使别人看到或感受到。", "primary_collocate": null, "pronunciation": "zhǎn xiàn", "ipa": "tʂan˨˩ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛展现了年轻人的活力。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片展现了这座城市的美。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用歌声展现了自己的才华。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前展现出一片美丽的草原。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影展现了普通人的生活。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在面试中展现自己的能力。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险时，才能展现一个人的勇气。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，大地展现出新的样子。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书展现了中国的历史变化。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈展现了这个民族的文化。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展现了", "label": "体标"}, {"form": "展现着", "label": "体标"}, {"form": "展现过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把能力、特点、面貌等清楚地表现出来，让人看到或感受到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确答案：展现（zhǎn xiàn），意思是清楚地表现出来。"}, {"text": "闪现", "is_correct": false, "explanation": "shǎn（第三声）与 zhǎn 声母不同（sh 与 zh），意思是忽然出现。"}, {"text": "占线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。"}, {"text": "战线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。"}, {"text": "产线", "is_correct": false, "explanation": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}], "explanations": {"展现": "正确答案：展现（zhǎn xiàn），意思是清楚地表现出来。", "闪现": "shǎn（第三声）与 zhǎn 声母不同（sh 与 zh），意思是忽然出现。", "占线": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。", "战线": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。", "产线": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}, "sentence_index": null, "correct_answer": "展现"}, "level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示清楚地表现出来，与“年轻人的活力”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是器物或机械，不能说“修理活力”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：参加要求的宾语是比赛、活动等，“参加活力”不成立。"}, {"text": "更换", "is_correct": false, "explanation": "语义：更换的是可以替代的东西，活力不能被换掉。"}], "explanations": {"展现": "正确：展现表示清楚地表现出来，与“年轻人的活力”搭配。", "修理": "搭配：修理的对象是器物或机械，不能说“修理活力”。", "参加": "配价：参加要求的宾语是比赛、活动等，“参加活力”不成立。", "更换": "语义：更换的是可以替代的东西，活力不能被换掉。"}, "sentence_index": 0, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个结果展现了方法是有效的。", "explanation": "这里应用“表明”。“展现”指把特点、面貌清楚地显示出来，不能带“方法是有效的”这样的判断句作宾语；由事实得出结论要用“表明”。"}, {"text": "他在比赛中展现了三个新同学。", "explanation": "这里应用“介绍”。“展现”的宾语是能力、才华等抽象内容，不能是人；把人引见给别人要用“介绍”。"}, {"text": "他把地图展现在桌上，低头研究路线。", "explanation": "这里应用“摊开”或“铺开”。“展现”指清楚地表现出来，没有把东西摊开、铺平的意思，不能用于“把地图展现在桌上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示清楚地表现出来，“一个人的勇气”是可以被表现出来的品质。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：购买的对象是商品，不能说“购买勇气”。"}, {"text": "参观", "is_correct": false, "explanation": "配价：参观的宾语是地点或展览，“参观勇气”不通。"}, {"text": "寄存", "is_correct": false, "explanation": "搭配：寄存的对象是行李或物品，“寄存勇气”不成立。"}], "explanations": {"展现": "正确：展现表示清楚地表现出来，“一个人的勇气”是可以被表现出来的品质。", "购买": "搭配：购买的对象是商品，不能说“购买勇气”。", "参观": "配价：参观的宾语是地点或展览，“参观勇气”不通。", "寄存": "搭配：寄存的对象是行李或物品，“寄存勇气”不成立。"}, "sentence_index": 6, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仪表盘上展现了当前的温度。", "explanation": "这里应用“显示”。“展现”侧重人或事物的特点、面貌被清楚表现出来，温度、数据等信息要用“显示”。"}, {"text": "这个月的销售额展现了百分之二十。", "explanation": "这里应用“增长”。“展现”不用于数量的增减，销售额的变化要用“增长”。"}, {"text": "这座城市展现了一座公园。", "explanation": "这里应用“拥有”。“展现”的宾语是特点、面貌等抽象内容，不能是“一座公园”这样的具体事物；说城市有某个设施要用“拥有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在比赛中充分展现来了自己的能力。", "corrected_sentence": "他在比赛中充分展现了自己的能力。", "error_description": "错误形式：“展现来了”。“来”作趋向补语须跟在“出”之后（如“展现出来”），单独的“展现来”不成立。此处直接用体标“了”即可，改为“展现了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段历史的真相渐渐展现我们面前。", "corrected_sentence": "这段历史的真相渐渐展现在我们面前。", "error_description": "错误形式：“展现我们面前”。正确形式：“展现在我们面前”。表示“清楚显露在某人眼前”时，“在”不可省略，省去后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
