INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "完成复杂任务时展现的技术性动作或技能", "primary_collocate": null, "pronunciation": "cāo zuò", "ipa": "tsʰɑu̯˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他在比赛中的操作非常漂亮。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老选手的操作让大家很佩服。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏对操作的要求很高。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的操作太快了，我完全看不清。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为一次操作失误，我们输了比赛。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的手术操作又稳又准。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了很久，现在操作很熟练。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看高手的操作，我学到了不少东西。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一套操作真是太厉害了。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手的操作还不够稳定，要多练。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "操作员", "label": "复合词"}, {"form": "操作系统", "label": "复合词"}], "register": "中性", "sense_fingerprint": "操作|名词|比赛、手术等中展现的技术性动作或技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（名词）指完成任务时展现的技术性动作或技能，与“比赛中”和“漂亮”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高矮，不能用“漂亮”形容，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，与“比赛中”的语境不符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不能用“漂亮”形容，句意不通。"}], "explanations": {"操作": "正确：操作（名词）指完成任务时展现的技术性动作或技能，与“比赛中”和“漂亮”搭配。", "身高": "语义：身高是身体的高矮，不能用“漂亮”形容，句意不通。", "课本": "语义：课本是教学用书，与“比赛中”的语境不符。", "体重": "语义：体重是身体的重量，不能用“漂亮”形容，句意不通。"}, "sentence_index": 0, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她跳舞的操作很优美。", "explanation": "这里应用“动作”。“操作”指完成复杂任务时的技术性动作或技能，舞蹈的身体动作要说“动作”。"}, {"text": "这一只操作真是太厉害了。", "explanation": "量词错误：“操作”作名词时用量词“套”，“只”用于动物或成对事物中的一个，不能用于这里。"}, {"text": "他的操作去了超市买菜。", "explanation": "这里应用“厨师”。“操作”指完成任务时的技术动作或技能，不是能主动去超市的人，主语应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（名词）指技术性动作或技能，可以“很熟练”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“熟练”描述人的技能，饭菜不是技能，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“熟练”不修饰天气，“天气很熟练”不成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是技能，“现在书包很熟练”语义不通。"}], "explanations": {"操作": "正确：操作（名词）指技术性动作或技能，可以“很熟练”。", "饭菜": "语义：“熟练”描述人的技能，饭菜不是技能，句子不通。", "天气": "搭配：“熟练”不修饰天气，“天气很熟练”不成立。", "书包": "语义：“书包”不是技能，“现在书包很熟练”语义不通。"}, "sentence_index": 6, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的操作很新颖。", "explanation": "这里应用“设计”。“操作”指完成任务时的技术性动作，不用于形容建筑物的构思和样式，样式要说“设计”。"}, {"text": "这支乐队的操作很动听。", "explanation": "这里应用“演奏”。“动听”形容声音，乐队的表现要说“演奏”，“操作”不指乐队的演奏。"}, {"text": "这座山的操作很陡峭，我们爬吧。", "explanation": "这里应用“坡度”。“操作”指完成任务时的技术性动作或技能，不能用来形容山的陡峭；说山的陡峭要用“坡度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师示范了一只操作，大家都看得很认真。", "corrected_sentence": "老师示范了一套操作，大家都看得很认真。", "error_description": "错误形式：“一只操作”。正确形式：“一套操作”。“操作”作名词指一整套动作或技能，量词应用“套”，“只”不能用于它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学徒终于把这只操作练熟了。", "corrected_sentence": "学徒终于把这套操作练熟了。", "error_description": "错误形式：“这只操作”。正确形式：“这套操作”。“只”用于单个事物，“操作”作名词指一整套动作或技能，量词应用“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
