INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对事物未来发展趋势的预先判断能力。", "primary_collocate": null, "pronunciation": "yù jiàn xìng", "ipa": "y˥˩ tɕjɛn˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "玩家通过展现操作技巧、策略预见性或团队贡献度，在同侪评价体系中确立地位。", "target_word": "预见性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他做事很有预见性，早就准备好了。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老板要有预见性。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划缺乏预见性，所以问题很多。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的预见性很强，早知道价格会涨。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的预见性让公司少了很多麻烦。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做投资需要一定的预见性。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章对未来的判断很有预见性。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有预见性，结果什么都来不及做。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生的预见性让病人及时得到了治疗。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预见", "label": "词根"}], "register": "中性", "sense_fingerprint": "预见性|名词|对事物未来发展趋势的预先判断能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预见性", "is_correct": true, "explanation": "正确。“策略预见性”指对局势发展的预判能力，与并列的“操作技巧”等能力相合。"}, {"text": "颜值", "is_correct": false, "explanation": "体貌：“颜值”指外貌，不是游戏中可以展现的策略能力。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，与“展现策略”不相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是情绪，不是可以展现的策略能力。"}], "explanations": {"预见性": "正确。“策略预见性”指对局势发展的预判能力，与并列的“操作技巧”等能力相合。", "颜值": "体貌：“颜值”指外貌，不是游戏中可以展现的策略能力。", "价格": "语义：“价格”指钱数，与“展现策略”不相合。", "心情": "语义：“心情”是情绪，不是可以展现的策略能力。"}, "sentence_index": 0, "correct_answer": "预见性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的沟通预见性很强。", "explanation": "这里应该用〈能力〉。“预见性”指对未来变化的预判，不能用来修饰“沟通”这类能力。"}, {"text": "这首歌的预见性很好听。", "explanation": "这里应该用〈旋律〉。“旋律”指音乐的声音走向，可以说“好听”；“预见性”指对未来的判断，不能用来形容歌曲好听。"}, {"text": "他有一把好预见性。", "explanation": "这里应该用〈种〉。〈把〉用于有柄的物件，“预见性”是抽象名词，不能用〈把〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预见性", "is_correct": true, "explanation": "正确。“做投资需要预见性”指能预判未来走势，与投资的要求相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口味，与投资的要求无关。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，投资并不需要这样的条件。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，与做投资的要求无关。"}], "explanations": {"预见性": "正确。“做投资需要预见性”指能预判未来走势，与投资的要求相合。", "味道": "语义：“味道”指气味或口味，与投资的要求无关。", "长相": "体貌：“长相”指外貌，投资并不需要这样的条件。", "形状": "语义：“形状”指物体的外形，与做投资的要求无关。"}, "sentence_index": 6, "correct_answer": "预见性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的预见性很便宜。", "explanation": "这里应该用〈价格〉。“价格”可以说便宜，“预见性”指对未来的预判，不能用来形容考试便宜。"}, {"text": "这件衣服的预见性很好看。", "explanation": "这里应该用〈颜色〉。“颜色”指衣服的色彩，“预见性”不能用来形容衣服的样子。"}, {"text": "这道菜的预见性很好吃。", "explanation": "这里应该用〈味道〉。“味道”指食物的滋味，“预见性”不能用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很预见性，公司总能提前应对变化。", "corrected_sentence": "老板很有预见性，公司总能提前应对变化。", "error_description": "缺词错误：“预见性”是名词，前面要用动词“有”，应为“很有预见性”，漏掉“有”不成话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一位很强的预见性，每次都能提前准备。", "corrected_sentence": "他有一种很强的预见性，每次都能提前准备。", "error_description": "量词错误：“预见性”是抽象名词，应用量词“种”。“位”只用于人，不能修饰“预见性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
