INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "贡献度是指个人、组织或事物在某个领域或任务中所做出的贡献的大小或程度。", "primary_collocate": null, "pronunciation": "gòng xiàn dù", "ipa": "kʊŋ⁵¹ ɕjɛn⁵¹ tu⁵¹", "syllable_count": 3, "sentences": [{"text": "玩家通过展现操作技巧、策略预见性或团队贡献度，在同侪评价体系中确立地位。", "target_word": "贡献度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司按每个人的贡献度发奖金。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小组里的贡献度最高。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师会看每个同学的贡献度打分。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目里，小李的贡献度不大。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用数字来算每个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的贡献度越来越高，大家都很感谢他。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贡献度高的队员可以先选房间。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理给每位员工的贡献度排了名。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，你的贡献度比我大。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "个人或组织所做贡献的大小或程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。贡献度指个人或团队中贡献的大小，可以与“操作技巧”“策略预见性”并列，表示团队中的贡献程度。"}, {"text": "颜值", "is_correct": false, "explanation": "体貌：颜值指外貌，与操作技巧、策略预见性并列时不属于玩家的能力，句子不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不是玩家可以“展现”的能力，与前文的游戏语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能被“展现”来确立地位，与操作技巧、策略预见性并列也不成立。"}], "explanations": {"贡献度": "正确。贡献度指个人或团队中贡献的大小，可以与“操作技巧”“策略预见性”并列，表示团队中的贡献程度。", "颜值": "体貌：颜值指外貌，与操作技巧、策略预见性并列时不属于玩家的能力，句子不通。", "工资": "语义：工资是劳动报酬，不是玩家可以“展现”的能力，与前文的游戏语境不符。", "年龄": "语义：年龄不能被“展现”来确立地位，与操作技巧、策略预见性并列也不成立。"}, "sentence_index": 0, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为班级做了很多贡献度。", "explanation": "这里应该用〈贡献〉。贡献度是贡献大小的程度，“做”要搭配“贡献”，不能说“做贡献度”。"}, {"text": "他在比赛中取得了好贡献度。", "explanation": "这里应该用〈成绩〉。“取得”通常搭配成绩、结果，贡献度表示贡献的程度，不能被取得。"}, {"text": "他为公司立下了大贡献度。", "explanation": "这里应该用〈功劳〉。“立下”搭配功劳，贡献度是程度，不能说“立下大贡献度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。“他的贡献度越来越高”指他对团队的贡献在增加，与“大家都很感谢他”相符。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指群体的数量，不能指“他”一个人的数量，与“大家都很感谢他”的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，不能因为努力而变化并得到大家感谢，句子不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“越来越高”多用于水平、数量，形容脾气通常说“越来越大”。"}], "explanations": {"贡献度": "正确。“他的贡献度越来越高”指他对团队的贡献在增加，与“大家都很感谢他”相符。", "人数": "语义：人数指群体的数量，不能指“他”一个人的数量，与“大家都很感谢他”的语境不符。", "身高": "体貌：身高是身体特征，不能因为努力而变化并得到大家感谢，句子不通。", "脾气": "搭配：“越来越高”多用于水平、数量，形容脾气通常说“越来越大”。"}, "sentence_index": 6, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药起到了很大贡献度。", "explanation": "这里应该用〈作用〉。“起到”搭配作用、效果，贡献度是贡献的程度，不能说“起到贡献度”。"}, {"text": "他承担了很大贡献度。", "explanation": "这里应该用〈责任〉。“承担”搭配责任、任务，不能说“承担贡献度”。"}, {"text": "他学到了很多贡献度。", "explanation": "这里应该用〈知识〉。“学到”搭配知识、经验，贡献度不能被“学到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在团队里的贡献度很多。", "corrected_sentence": "他在团队里的贡献度很高。", "error_description": "错误在谓语“很多”。贡献度表示贡献的程度，应用“高”来形容，应说“贡献度很高”，不能说“贡献度很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动，你的贡献度比我很高。", "corrected_sentence": "这次活动，你的贡献度比我高。", "error_description": "“比”字句中不能再用程度副词“很”修饰，“比我很高”是错误的，应去掉“很”，说“你的贡献度比我高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
