INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同侪指与自己在年龄、地位、兴趣等方面相近的人，多用于同辈或同伴。", "primary_collocate": null, "pronunciation": "tóng chái", "ipa": "tʰʊŋ³⁵ ʈʂʰai³⁵", "syllable_count": 2, "sentences": [{"text": "玩家通过展现操作技巧、策略预见性或团队贡献度，在同侪评价体系中确立地位。", "target_word": "同侪", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他很在意同侪对他的看法。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年容易受同侪影响。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的成绩在同侪中很突出。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪之间常常互相比较。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同侪一起参加了比赛。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人喜欢得到同侪的认同。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在同侪面前有时很害羞。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新人很快赢得了同侪的尊重。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪的鼓励给了他很大信心。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "年龄、地位相近的同辈人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“同侪”指年龄、地位相近的人，可以作为“评价体系”中的评价对象，与句意相符。"}, {"text": "同伙", "is_correct": false, "explanation": "语义：同伙指一起做坏事的人，带有贬义，与正面的评价语境不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是人，不能构成“评价体系”的对象，与“确立地位”的语境不符。"}, {"text": "亲戚", "is_correct": false, "explanation": "搭配：“评价体系”通常指同行或同类人之间的评价，不说“亲戚评价体系”。"}], "explanations": {"同侪": "正确。“同侪”指年龄、地位相近的人，可以作为“评价体系”中的评价对象，与句意相符。", "同伙": "语义：同伙指一起做坏事的人，带有贬义，与正面的评价语境不符。", "颜色": "语义：颜色不是人，不能构成“评价体系”的对象，与“确立地位”的语境不符。", "亲戚": "搭配：“评价体系”通常指同行或同类人之间的评价，不说“亲戚评价体系”。"}, "sentence_index": 0, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一只同侪，经常一起打球。", "explanation": "这里应该用〈位〉。同侪指人，应用“位”或“个”，“只”多用于动物，不能用来量人。"}, {"text": "我认识一座同侪。", "explanation": "这里应该用〈位〉。同侪指人，“座”多用于山、桥等大型物体，不能用来量人。"}, {"text": "他是我的一本同侪。", "explanation": "这里应该用〈位〉。同侪指人，“本”多用于书籍，不能用来量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“年轻人喜欢得到同侪的认同”指年龄、地位相近的人给予的认可，与句意相符。"}, {"text": "证书", "is_correct": false, "explanation": "语义：证书是文件，不能给出“认同”，与“年轻人喜欢得到……的认同”的语境不符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能给出“认同”，句子不通。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”后面不能直接接“的认同”，与“认同”的搭配不自然。"}], "explanations": {"同侪": "正确。“年轻人喜欢得到同侪的认同”指年龄、地位相近的人给予的认可，与句意相符。", "证书": "语义：证书是文件，不能给出“认同”，与“年轻人喜欢得到……的认同”的语境不符。", "手机": "语义：手机是物品，不能给出“认同”，句子不通。", "赞美": "搭配：“赞美”后面不能直接接“的认同”，与“认同”的搭配不自然。"}, "sentence_index": 6, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同侪下令修建长城。", "explanation": "这里应该用〈皇帝〉。“下令”的人必须有更高的地位，同侪地位相近，不能发出命令。"}, {"text": "他很孝顺同侪。", "explanation": "这里应该用〈父母〉。“孝顺”的对象是父母或长辈，同侪地位相近，不能说“孝顺同侪”。"}, {"text": "这位同侪比我年长三十岁。", "explanation": "这里应该用〈长辈〉。同侪指年龄、地位相近的人，相差三十岁的人不能算同侪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位同侪们一起去了图书馆。", "corrected_sentence": "两位同侪一起去了图书馆。", "error_description": "“两位”已经表示人数，“同侪”前面有数量词时后面不能再加“们”，应为“两位同侪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在同侪上很受欢迎。", "corrected_sentence": "他在同侪中很受欢迎。", "error_description": "方位词用错：“同侪”之后应用“中”，表示在同侪之中；用“上”表示“在……上面”，与句意不符，应说“同侪中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
