INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11949, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示同意、肯定或承认某人的能力、价值或正确性。", "primary_collocate": null, "pronunciation": "rèn kě", "ipa": "ɻən⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这种基于绩效的认可机制，与现实社会的成就导向形成镜像。", "target_word": "认可", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老板很认可他的工作能力。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认可这个办法。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认可了这个新方法。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认可你的看法，但是有一点不同。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人认可了这家店的服务。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩让大家都认可他。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理认可过她的计划。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司认可他的学历。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认可这样的结果。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认可了", "label": "完成体"}, {"form": "认可过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "同意、肯定并承认能力、价值或正确性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”指承认某种机制或做法的价值，与“基于绩效”的评价方式相符，可以作定语修饰“机制”。"}, {"text": "慈善", "is_correct": false, "explanation": "语义：慈善指无偿帮助他人，与依据绩效评定的机制互相矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与绩效评定毫无关系，“基于绩效的天气机制”读不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”一般不用来修饰“机制”，没有这种搭配，且与绩效无关。"}], "explanations": {"认可": "“认可”指承认某种机制或做法的价值，与“基于绩效”的评价方式相符，可以作定语修饰“机制”。", "慈善": "语义：慈善指无偿帮助他人，与依据绩效评定的机制互相矛盾。", "天气": "语义：天气与绩效评定毫无关系，“基于绩效的天气机制”读不通。", "咖啡": "搭配：“咖啡”一般不用来修饰“机制”，没有这种搭配，且与绩效无关。"}, "sentence_index": 0, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认可了自己的错误，并向大家道了歉。", "explanation": "这里应该用〈承认〉。认可用于肯定别人的能力、价值或正确性，不用来承认自己的错误。"}, {"text": "法院认可他有罪，所以判了三年。", "explanation": "这里应该用〈认定〉。认可是对好的、对的事情表示肯定，不用于下有罪这类否定性的结论。"}, {"text": "我认可这个办法不太好。", "explanation": "这里应该用〈认为〉。认可表示肯定价值，不能与“不太好”这样的否定评价搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”指承认他的成绩与能力，与“大家都认可他”的语义相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "配价：“烹饪”要求以食物作宾语，不能以人作宾语。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指修整房屋或场所，与人的评价无关。"}, {"text": "调味", "is_correct": false, "explanation": "语义：“调味”指给食物加调料，用来形容大家对他的态度读不通。"}], "explanations": {"认可": "“认可”指承认他的成绩与能力，与“大家都认可他”的语义相符。", "烹饪": "配价：“烹饪”要求以食物作宾语，不能以人作宾语。", "装修": "语义：“装修”指修整房屋或场所，与人的评价无关。", "调味": "语义：“调味”指给食物加调料，用来形容大家对他的态度读不通。"}, "sentence_index": 6, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于认可了这次失败。", "explanation": "这里应该用〈接受〉。认可用于肯定别人的能力或价值，不能用于接受失败这类负面结果。"}, {"text": "面对别人的讽刺，他只能认可这些讽刺。", "explanation": "这里应该用〈忍受〉。认可表示肯定，不能用于指忍耐别人的讽刺。"}, {"text": "老师认可了他的粗心，没有批评他。", "explanation": "这里应该用〈原谅〉。认可表示觉得对而肯定，不能用来表示对粗心这类缺点的宽容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没认可了这种做法。", "corrected_sentence": "我从来没认可过这种做法。", "error_description": "“从来没”否定的是从未有过的经历，应与体标“过”搭配，说“从来没认可过”；“没”与“了”不能配合，“从来没认可了”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没认可了这种说法。", "corrected_sentence": "我从没认可过这种说法。", "error_description": "“从没”表示从未有过的经历，应与“过”搭配，说“从没认可过”；“了”表示已经完成，与“从没”矛盾，不能说“从没认可了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
