INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11951, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物纯净，没有杂质或别的成分。", "primary_collocate": null, "pronunciation": "chún cuì", "ipa": "ʈʂʰwən tsʰweɪ", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "纯粹", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一块纯粹的金子，一点杂质也没有。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对音乐的爱很纯粹，不是为了钱。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的笑容那么纯粹，让人心情很好。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说一口纯粹的北京话，没有一点口音。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶蜂蜜很纯粹，没有加糖。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们之间只有纯粹的友情，没有别的关系。", "target_word": "纯粹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢纯粹的咖啡，不加牛奶也不加糖。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画的颜色很纯粹，看不到杂色。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想过一种纯粹的生活，远离城市的吵闹。", "target_word": "纯粹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：事物纯净、不含杂质或别的成分（可指抽象的动机、感情）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纯粹", "is_correct": true, "explanation": "“纯粹”指没有掺杂其他因素，修饰“竞争”时表示竞争本身不掺别的东西，符合句意。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水等透明，不能用来形容竞争。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，与竞争的性质无关。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不能用来修饰竞争。"}], "explanations": {"纯粹": "“纯粹”指没有掺杂其他因素，修饰“竞争”时表示竞争本身不掺别的东西，符合句意。", "清澈": "语义：“清澈”形容水等透明，不能用来形容竞争。", "柔软": "语义：“柔软”形容质地，与竞争的性质无关。", "苗条": "体貌：“苗条”形容人的身材，不能用来修饰竞争。"}, "sentence_index": 0, "correct_answer": "纯粹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很纯粹，学东西特别快。", "explanation": "这里应该用〈聪明〉。纯粹指没有杂质，不用来形容智力高低；学东西快要说聪明。"}, {"text": "这套书很纯粹，少了第三册。", "explanation": "这里应该用〈完整〉。纯粹指没有杂质或别的成分，不表示书籍是否齐全；书少了一册，应说不完整。"}, {"text": "他的技术很纯粹，同事们都很佩服。", "explanation": "这里应该用〈纯熟〉。纯粹指没有杂质，不表示技术熟练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纯粹", "is_correct": true, "explanation": "“纯粹”形容友情没有掺杂别的关系，与句中“没有别的关系”相符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容食物的味道，不能用来形容友情。"}, {"text": "蓬松", "is_correct": false, "explanation": "语义：“蓬松”形容物体松软有空隙，不能用来形容友情。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人的身体状况，不能用来形容友情。"}], "explanations": {"纯粹": "“纯粹”形容友情没有掺杂别的关系，与句中“没有别的关系”相符。", "咸": "语义：“咸”形容食物的味道，不能用来形容友情。", "蓬松": "语义：“蓬松”形容物体松软有空隙，不能用来形容友情。", "瘦弱": "体貌：“瘦弱”形容人的身体状况，不能用来形容友情。"}, "sentence_index": 6, "correct_answer": "纯粹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法很纯粹，人人都能学会。", "explanation": "这里应该用〈简单〉。纯粹指没有杂质，不表示难度低、容易学。"}, {"text": "他讲得很纯粹，大家都明白了。", "explanation": "这里应该用〈清楚〉。纯粹指没有杂质，不用来形容讲述是否清楚。"}, {"text": "我的房间很纯粹，东西都整理好了。", "explanation": "这里应该用〈干净〉。纯粹指没有杂质，不用来形容房间是否整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块金子被纯粹，没有一点杂质。", "corrected_sentence": "这块金子很纯粹，没有一点杂质。", "error_description": "“被”不能放在形容词“纯粹”前，应说“很纯粹”，用副词“很”修饰形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他选择了一种纯粹地生活方式。", "corrected_sentence": "他选择了一种纯粹的生活方式。", "error_description": "修饰名词的形容词后应用结构助词“的”，应说“纯粹的生活方式”，不能用“地”；“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
