INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会或群体共同认可并用于衡量行为、语言或事物的标准。", "primary_collocate": null, "pronunciation": "guī fàn", "ipa": "kweɪ fan", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "规范", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "玩家自发形成 guild（公会）、clan（氏族），制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "规范", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校有一套规范，每个学生都要遵守。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写文章要符合语言规范。", "target_word": "规范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司制定了新的工作规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在图书馆大声说话不合社会规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了中文写作的规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生必须按照医疗规范做手术。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂网络上的行为规范，常常说错话。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个国家都有自己的交通规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範", "label": "繁体"}, {"form": "一套规范", "label": "量词"}, {"form": "规范化", "label": "复合"}], "register": "正式", "sense_fingerprint": "名词：群体公认、用来衡量行为、语言或事物的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规范", "is_correct": true, "explanation": "正确。“规范制衡”指用共同标准相互约束，与前文“排他性”“敌意文化”“生态恶化”的语境相符。"}, {"text": "资金", "is_correct": false, "explanation": "语义：资金指钱款，不能约束竞争行为，句中需要的是共同认可的标准。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指身体的重量，不能与“制衡”组合。"}, {"text": "跳绳", "is_correct": false, "explanation": "搭配：“跳绳”是体育活动，不能用来修饰“制衡”，句中需要共同标准。"}], "explanations": {"规范": "正确。“规范制衡”指用共同标准相互约束，与前文“排他性”“敌意文化”“生态恶化”的语境相符。", "资金": "语义：资金指钱款，不能约束竞争行为，句中需要的是共同认可的标准。", "体重": "搭配：“体重”指身体的重量，不能与“制衡”组合。", "跳绳": "搭配：“跳绳”是体育活动，不能用来修饰“制衡”，句中需要共同标准。"}, "sentence_index": 0, "correct_answer": "规范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是班里的规范，大家都向他学习。", "explanation": "这里应该用〈榜样〉。规范指共同认可的准则，指人时要说榜样，不能说成规范。"}, {"text": "这次失败给我留下了宝贵的规范。", "explanation": "这里应该用〈经验〉。规范指共同遵守的标准，个人从失败中总结的收获不说规范。"}, {"text": "他从小的规范是当一名医生。", "explanation": "这里应该用〈理想〉。规范指共同遵守的标准，个人的志向不能叫规范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规范", "is_correct": true, "explanation": "正确。“中文写作的规范”指写作要遵守的标准，与“这本书介绍了”相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱讲做菜的方法，不是写作的标准。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指外表，不能说写作的外貌。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“口音”属于说话，不属于书面的写作，搭配不当。"}], "explanations": {"规范": "正确。“中文写作的规范”指写作要遵守的标准，与“这本书介绍了”相符。", "食谱": "语义：食谱讲做菜的方法，不是写作的标准。", "外貌": "体貌：“外貌”指外表，不能说写作的外貌。", "口音": "搭配：“口音”属于说话，不属于书面的写作，搭配不当。"}, "sentence_index": 6, "correct_answer": "规范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台新机器的规范很高，运行起来比旧的快一倍。", "explanation": "这里应该用〈性能〉。规范指群体共同认可的准则，机器的运行能力要说性能，不能说规范。"}, {"text": "他今年的规范是考上大学。", "explanation": "这里应该用〈目标〉。规范指大家共同遵守的标准，个人想达成的方向要说目标。"}, {"text": "他找到了一个好规范，很快解决了问题。", "explanation": "这里应该用〈办法〉。规范指共同认可的标准，解决问题的具体做法要说办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校制定过一把新的规范。", "corrected_sentence": "学校制定过一套新的规范。", "error_description": "量词“把”多用于有柄的器物，规范应用量词“套”，应说“一套新的规范”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲解了一套基本地规范。", "corrected_sentence": "老师讲解了一套基本规范。", "error_description": "作定语的“基本”直接放在名词前，不加“地”，应说“一套基本规范”；“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过权力或力量的相互制约，达到平衡状态。", "primary_collocate": null, "pronunciation": "zhì héng", "ipa": "ʈʂɻ̩ xɤŋ", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "制衡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "三个部门互相制衡，谁也不能乱来。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律可以制衡政府的权力。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会用投票制衡经理的决定。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人制衡，权力就会越来越大。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个大国互相制衡，世界才能稳定。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒体的作用是制衡权力。", "target_word": "制衡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个班有两位班长，可以互相制衡。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国会和总统的权力互相制衡着。", "target_word": "制衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想制衡对手的力量，可是没有成功。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "制衡了", "label": "体标"}, {"form": "制衡着", "label": "体标"}, {"form": "制衡过", "label": "体标"}], "register": "正式", "sense_fingerprint": "动词：权力或力量互相制约，达到平衡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制衡", "is_correct": true, "explanation": "正确。“规范制衡”指用共同标准相互约束，与“排他性”“敌意文化”的语境相符。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖指生物增多，与社会竞争中的规范无关。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“规范”不修饰“歌唱”，两者不能组合。"}, {"text": "扯皮", "is_correct": false, "explanation": "语域：“扯皮”口语色彩强，与这句的正式书面语不合。"}], "explanations": {"制衡": "正确。“规范制衡”指用共同标准相互约束，与“排他性”“敌意文化”的语境相符。", "繁殖": "语义：繁殖指生物增多，与社会竞争中的规范无关。", "歌唱": "搭配：“规范”不修饰“歌唱”，两者不能组合。", "扯皮": "语域：“扯皮”口语色彩强，与这句的正式书面语不合。"}, "sentence_index": 0, "correct_answer": "制衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小红一直在制衡自己的情绪。", "explanation": "这里应该用〈控制〉。制衡需要两股力量互相约束，同一个人调节自己的情绪不能说制衡。"}, {"text": "公司由经理制衡日常事务。", "explanation": "这里应该用〈管理〉。制衡指双方的互相制约，经理对日常事务的组织要用管理。"}, {"text": "警察制衡了现场的局面。", "explanation": "这里应该用〈控制〉。制衡需要两股力量互相约束，警察单方面掌控局面要用控制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制衡", "is_correct": true, "explanation": "正确。“制衡权力”指用制约使权力平衡，与“媒体的作用”相符。"}, {"text": "制造", "is_correct": false, "explanation": "语义：制造指做出物品，不能指对权力的约束。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪的对象是食物，不能搭配“权力”。"}, {"text": "闲聊", "is_correct": false, "explanation": "配价：“闲聊”是不及物动词，不能带宾语“权力”。"}], "explanations": {"制衡": "正确。“制衡权力”指用制约使权力平衡，与“媒体的作用”相符。", "制造": "语义：制造指做出物品，不能指对权力的约束。", "烹饪": "搭配：烹饪的对象是食物，不能搭配“权力”。", "闲聊": "配价：“闲聊”是不及物动词，不能带宾语“权力”。"}, "sentence_index": 6, "correct_answer": "制衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生很快制衡了这场感冒。", "explanation": "这里应该用〈治好〉。制衡指双方互相约束，治愈疾病是单方面的行为，要用治好。"}, {"text": "小明很快制衡了那幅画。", "explanation": "这里应该用〈画好〉。制衡指双方互相约束，画画是单方面的创作，要用画好。"}, {"text": "我一个人制衡自己的作息。", "explanation": "这里不这么用。制衡需要两股力量互相制约，一个人安排自己的作息不能说制衡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司互相制衡得，市场才会稳定。", "corrected_sentence": "两家公司互相制衡，市场才会稳定。", "error_description": "补语标记“得”后面必须接补语，这里“制衡得”后面没有补语，应删去“得”，说“两家公司互相制衡，市场才会稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国曾经制衡着对方的势力。", "corrected_sentence": "两国曾经制衡过对方的势力。", "error_description": "“曾经”表示过去的经历，应与体标“过”搭配，说“制衡过对方的势力”；“着”表示动作正在持续，与“曾经”所指的过去经历矛盾，不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
