INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11954, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "表示某种情况很容易发生，多指不好的结果。", "primary_collocate": null, "pronunciation": "jí yì", "ipa": "tɕi˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "极易", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种水果极易坏，买回家要尽快吃。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天空气干燥，皮肤极易出现问题。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手开车时极易紧张，手心常常出汗。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这类玻璃很薄，搬的时候极易打碎。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子刚上学，极易生病，家长要多留意。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络上的消息极易传开，大家要小心。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路面结冰后，行人极易滑倒。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他性格急，遇到小事极易生气。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布极易燃烧，请远离火源。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "极易：副词，用在动词或形容词前，表示很容易发生某种情况，多指不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：极易 jí yì，书面副词，表示很容易。"}, {"text": "记忆", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记忆。"}, {"text": "技艺", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是技能和本领。"}, {"text": "奇异", "is_correct": false, "explanation": "qí 与 jí 声母不同（q / j），意思是奇特、不寻常。"}], "explanations": {"极易": "正确：极易 jí yì，书面副词，表示很容易。", "记忆": "jì（第四声）与 jí（第二声）声调不同，意思是记忆。", "技艺": "jì（第四声）与 jí（第二声）声调不同，意思是技能和本领。", "奇异": "qí 与 jí 声母不同（q / j），意思是奇特、不寻常。"}, "sentence_index": null, "correct_answer": "极易"}, "level_3": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：“极易”表示很容易，符合“若缺乏制衡就容易滑向……”的假设语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“若”表示假设，“已经”说明事情已经发生，与句中的假设语气冲突。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“滑向”指不自觉的趋势，不能说成“故意”所为。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰有意识的努力，不与“滑向”这种不自觉的变化搭配。"}], "explanations": {"极易": "正确：“极易”表示很容易，符合“若缺乏制衡就容易滑向……”的假设语境。", "已经": "语义：“若”表示假设，“已经”说明事情已经发生，与句中的假设语气冲突。", "故意": "语义：“滑向”指不自觉的趋势，不能说成“故意”所为。", "极力": "搭配：“极力”修饰有意识的努力，不与“滑向”这种不自觉的变化搭配。"}, "sentence_index": 0, "correct_answer": "极易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题我们讨论了一下午，极易做完了。", "explanation": "这里应该用〈不容易〉。极易表示很容易做成，与前句“讨论了一下午”矛盾；费了很多功夫的事要用“不容易”。"}, {"text": "这项工作要做整整三年，极易完成。", "explanation": "这里应该用〈需要很长时间〉。极易表示很容易做成，与“整整三年”矛盾；耗时很长的事不能用“极易”。"}, {"text": "他这次成绩很差，极易考上了好大学。", "explanation": "这里应该用〈难以〉。极易表示很容易做成，与前句“成绩很差”矛盾；说事情不容易做成时要用“难以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：“极易”表示很容易，说明消息容易扩散，与后文“大家要小心”相呼应。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”需要有意志的施事，“消息”不能亲自传开。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰有意的努力，“传开”是不自觉的扩散，二者不搭配。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此或从未如此，与“传开”这一具体事件不合。"}], "explanations": {"极易": "正确：“极易”表示很容易，说明消息容易扩散，与后文“大家要小心”相呼应。", "亲自": "语义：“亲自”需要有意志的施事，“消息”不能亲自传开。", "极力": "搭配：“极力”修饰有意的努力，“传开”是不自觉的扩散，二者不搭配。", "从来": "语义：“从来”表示一向如此或从未如此，与“传开”这一具体事件不合。"}, "sentence_index": 6, "correct_answer": "极易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事很难办，他极易就办成了。", "explanation": "这里应该用〈终于〉。极易表示很容易发生，与“很难办”矛盾；费了力才完成要用“终于”。"}, {"text": "他身体很好，极易生病。", "explanation": "这里应该用〈很少〉。极易表示很容易发生某种情况，与“身体很好”矛盾；说不常发生要用“很少”。"}, {"text": "这台机器很结实，极易坏。", "explanation": "这里应该用〈不容易〉。极易表示很容易发生，与“很结实”矛盾；说不容易发生要用“不容易”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种瓷器很薄，极易碎片。", "corrected_sentence": "这种瓷器很薄，极易碎。", "error_description": "错误：“极易”修饰动词，其后应接动词“碎”，此处多出名词“片”，“碎片”不能受“极易”修饰。正确应为“极易碎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨天路面很极易滑，要小心。", "corrected_sentence": "雨天路面极易滑，要小心。", "error_description": "错误：“极易”本身已表示“很容易”，前面不能再加“很”。正确应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逐渐朝着某个方向或状态移动，通常带有一种不自觉或难以阻止的趋势。", "primary_collocate": null, "pronunciation": "huá xiàng", "ipa": "xua˧˥ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "滑向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小船顺着水流，慢慢滑向湖中间。", "target_word": "滑向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面太斜，车不知不觉滑向路边。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不改变，会慢慢滑向失败。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国关系滑向紧张，大家很担心。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他越来越懒，生活正滑向混乱。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "争论没有结果，会议滑向争吵。", "target_word": "滑向", "complexity_tier": "T3", "furigana": "zhēng lùn méi yǒu jié guǒ, huì yì huá xiàng zhēng chǎo", "sentence_source": "generated"}, {"text": "社会失去信任，就会滑向冷漠。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不管学习，成绩慢慢滑向谷底。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济增长放缓，国家可能滑向衰退。", "target_word": "滑向", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滑向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "滑向：动词，事物不知不觉地朝某个方向或某种状态发展，难以阻止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：滑向 huá xiàng，动词，不自觉地朝某个方向发展。"}, {"text": "画像", "is_correct": false, "explanation": "huà（第四声）与 huá（第二声）声调不同，意思是画中的形象。"}, {"text": "华夏", "is_correct": false, "explanation": "xià 与 xiàng 韵母不同（少了 -ng），意思是中国的古称。"}, {"text": "滑下", "is_correct": false, "explanation": "xià 与 xiàng 韵母不同（少了 -ng），意思是从高处滑落。"}], "explanations": {"滑向": "正确：滑向 huá xiàng，动词，不自觉地朝某个方向发展。", "画像": "huà（第四声）与 huá（第二声）声调不同，意思是画中的形象。", "华夏": "xià 与 xiàng 韵母不同（少了 -ng），意思是中国的古称。", "滑下": "xià 与 xiàng 韵母不同（少了 -ng），意思是从高处滑落。"}, "sentence_index": null, "correct_answer": "滑向"}, "level_3": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：“滑向”表示不自觉地朝某方向发展，符合“缺乏制衡就容易陷入……”的语境。"}, {"text": "抵制", "is_correct": false, "explanation": "搭配：“抵制”需要有意志的主体主动反抗，竞争本身无法抵制。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是主动舍弃，与句中不自觉偏向的趋势相反。"}, {"text": "防止", "is_correct": false, "explanation": "语义：“防止”是主动阻止，与“若缺乏规范制衡”所假设的放任语境相反，句子说不通。"}], "explanations": {"滑向": "正确：“滑向”表示不自觉地朝某方向发展，符合“缺乏制衡就容易陷入……”的语境。", "抵制": "搭配：“抵制”需要有意志的主体主动反抗，竞争本身无法抵制。", "放弃": "语义：“放弃”是主动舍弃，与句中不自觉偏向的趋势相反。", "防止": "语义：“防止”是主动阻止，与“若缺乏规范制衡”所假设的放任语境相反，句子说不通。"}, "sentence_index": 0, "correct_answer": "滑向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要滑向改革的新阶段。", "explanation": "这里应该用〈推进〉。滑向指不自觉地朝某方向发展，有意推动改革时要用“推进”。"}, {"text": "他有意滑向失败，想要试试看。", "explanation": "“滑向”指不知不觉地朝某种状态发展，不能用于有意的选择。"}, {"text": "我们要滑向成功，不能停下来。", "explanation": "这里应该用〈迈向〉。滑向是不自觉的趋势，表示有意奋斗、走向目标时要用“迈向”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滑向", "is_correct": true, "explanation": "正确：“滑向”表示逐渐朝某方向发展，说明会议不自觉地走向争吵。"}, {"text": "推向", "is_correct": false, "explanation": "配价：“推向”需要施事和被推的对象，“会议推向争吵”缺少必要成分。"}, {"text": "转化", "is_correct": false, "explanation": "配价：“转化”单用不通，要说“转化为”才能接宾语。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，与“会议朝争吵发展”的意思相反。"}], "explanations": {"滑向": "正确：“滑向”表示逐渐朝某方向发展，说明会议不自觉地走向争吵。", "推向": "配价：“推向”需要施事和被推的对象，“会议推向争吵”缺少必要成分。", "转化": "配价：“转化”单用不通，要说“转化为”才能接宾语。", "驱赶": "语义：“驱赶”是赶走，与“会议朝争吵发展”的意思相反。"}, "sentence_index": 6, "correct_answer": "滑向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国很快滑向了友好关系。", "explanation": "这里应该用〈建立〉。建立关系是有意的行为，而滑向指不自觉的趋势，不能用于此处。"}, {"text": "他故意让局面滑向了混乱。", "explanation": "这里应该用〈推向〉。滑向是不自觉的趋势，“故意”说明是有意促成的，要用“推向”。"}, {"text": "这个小镇一夜之间滑向了繁荣。", "explanation": "这里应该用〈变成〉。滑向指逐渐朝某个方向发展，有一个缓慢的过程；“一夜之间”说的是突然的变化，要用“变成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司管理松散，慢慢滑向了了混乱。", "corrected_sentence": "公司管理松散，慢慢滑向了混乱。", "error_description": "错误：“滑向了”后面的“了”只能用一个，此句多出一个“了”。正确应为“滑向了混乱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谈判陷入僵局，局面渐渐滑向。", "corrected_sentence": "谈判陷入僵局，局面渐渐滑向失控。", "error_description": "错误：“滑向”后面必须带出去向（如“失控”），此句缺少去向成分，句子不完整。正确应为“滑向失控”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
