INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某事物或群体具有排斥其他同类事物的特性，比如某项权利或资源只能由一方拥有或使用。", "primary_collocate": null, "pronunciation": "pái tā xìng", "ipa": "pʰai˧˥ tʰa˥˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "排他性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这项权利有排他性，别人不能同时使用。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专利的排他性保护发明人的利益。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们小圈子的排他性很强，新人很难加入。", "target_word": "排他性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私人财产具有明显的排他性。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种合同的排他性让其他公司无法合作。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宗教若有太强的排他性，容易引起冲突。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "独家代理的排他性写在合同第二条。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土地使用权有排他性，别人不能占用。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "排他性太强的团队，很难接受新想法。", "target_word": "排他性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "排他性：名词，权利、资源或群体排斥同类其他事物的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包容性", "is_correct": false, "explanation": "语义：包容性指接纳他人，与“滑向……敌意文化”的消极趋势相反，句子说不通。"}, {"text": "排他性", "is_correct": true, "explanation": "排他性指排斥同类其他事物的特性，与“敌意文化”同属消极趋势，正好填入此处。"}, {"text": "竞争力", "is_correct": false, "explanation": "搭配：“滑向”后接消极趋势，“竞争力”是能力名词，不能作其宾语。"}, {"text": "亲和力", "is_correct": false, "explanation": "语义：亲和力指友好、易于接近，与“敌意文化”相悖。"}], "explanations": {"包容性": "语义：包容性指接纳他人，与“滑向……敌意文化”的消极趋势相反，句子说不通。", "排他性": "排他性指排斥同类其他事物的特性，与“敌意文化”同属消极趋势，正好填入此处。", "竞争力": "搭配：“滑向”后接消极趋势，“竞争力”是能力名词，不能作其宾语。", "亲和力": "语义：亲和力指友好、易于接近，与“敌意文化”相悖。"}, "sentence_index": 0, "correct_answer": "排他性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次项目的排他性很强，大家一起完成。", "explanation": "这里应该用〈合作性〉。排他性指排斥他人、不让他人参与，与“大家一起完成”矛盾。"}, {"text": "这所学校的排他性很强，接纳各种学生。", "explanation": "这里应该用〈包容性〉。排他性指排斥他人，“接纳各种学生”的语境要用包容性。"}, {"text": "这些设施的排他性很强，大家都能使用。", "explanation": "这里应该用〈共享性〉。排他性指不许他人共用，与“大家都能使用”相反；可供多人使用要用共享性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创造力", "is_correct": false, "explanation": "语义：创造力与“容易引起冲突”没有关联，句子说不通。"}, {"text": "排他性", "is_correct": true, "explanation": "排他性指排斥他人的特性，宗教若太强会引起冲突，正好填入此处。"}, {"text": "透明度", "is_correct": false, "explanation": "搭配：“透明度”多与“高”搭配，“太强的透明度”不是常用说法。"}, {"text": "幽默感", "is_correct": false, "explanation": "语义：幽默感与“容易引起冲突”语义不合，句子说不通。"}], "explanations": {"创造力": "语义：创造力与“容易引起冲突”没有关联，句子说不通。", "排他性": "排他性指排斥他人的特性，宗教若太强会引起冲突，正好填入此处。", "透明度": "搭配：“透明度”多与“高”搭配，“太强的透明度”不是常用说法。", "幽默感": "语义：幽默感与“容易引起冲突”语义不合，句子说不通。"}, "sentence_index": 6, "correct_answer": "排他性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的排他性很强，欢迎所有市民参观。", "explanation": "这里应该用〈开放性〉。排他性指排斥他人，与“欢迎所有市民参观”相悖。"}, {"text": "这份报告的排他性很强，任何人都能查阅。", "explanation": "这里应该用〈公开性〉。排他性指只许特定人使用，“任何人都能查阅”应说公开性。"}, {"text": "这种标准的排他性很强，各行业都能用。", "explanation": "这里应该用〈通用性〉。排他性指不许他人共用，“各行业都能用”应说通用性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项专利具有一只排他性，别人不能擅自使用。", "corrected_sentence": "这项专利具有一种排他性，别人不能擅自使用。", "error_description": "错误在量词：“一只排他性”应改为“一种排他性”。“只”用于动物或具体个体，抽象名词“排他性”应搭配量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种技术很排他性，别的公司很难仿造。", "corrected_sentence": "这种技术很有排他性，别的公司很难仿造。", "error_description": "错误在“有”的省略：“排他性”是名词，不能直接接“很”作谓语，应说“很有排他性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
