INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对他人或事物怀有的敌对、仇视或不满的情绪或态度。", "primary_collocate": null, "pronunciation": "dí yì", "ipa": "ti˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "敌意", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他看我的眼神里有一种敌意。", "target_word": "敌意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次见我，就表现出明显的敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人多年不说话，彼此都有敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这句话，他对我的敌意少了很多。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗对陌生人充满了敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望同学们不要对新同学有敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说话，我却感觉不到一点敌意。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家之间的敌意越来越深。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的敌意让大家觉得很不舒服。", "target_word": "敌意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一丝敌意", "label": "量词"}], "register": "中性", "sense_fingerprint": "对人或事物的敌对仇视情绪或态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信任", "is_correct": false, "explanation": "语义：信任是相互依靠的态度，与“滑向……敌意文化”的消极趋势相反。"}, {"text": "合作", "is_correct": false, "explanation": "语义：合作是积极的协作关系，与“滑向……敌意文化”的消极语境矛盾。"}, {"text": "善意", "is_correct": false, "explanation": "搭配：“善意文化”不成常用搭配，且与“滑向”后的消极趋势不符。"}, {"text": "敌意", "is_correct": true, "explanation": "敌意指对他人或事物的敌对、仇视态度，与“排他性”并列，描述竞争滑向的消极态度。"}], "explanations": {"信任": "语义：信任是相互依靠的态度，与“滑向……敌意文化”的消极趋势相反。", "合作": "语义：合作是积极的协作关系，与“滑向……敌意文化”的消极语境矛盾。", "善意": "搭配：“善意文化”不成常用搭配，且与“滑向”后的消极趋势不符。", "敌意": "敌意指对他人或事物的敌对、仇视态度，与“排他性”并列，描述竞争滑向的消极态度。"}, "sentence_index": 0, "correct_answer": "敌意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的敌意，我们多年不来往。", "explanation": "这里应该用〈敌人〉。敌意是对人或事物的敌对情绪，不能直接指人。"}, {"text": "他对我很有敌意，我们是多年的好朋友。", "explanation": "这里应该用〈好感〉。敌意指敌对、仇视的情绪，与“我们是多年的好朋友”相反；友好的感情要用好感。"}, {"text": "这篇文章充满了敌意，读起来很温暖。", "explanation": "这里应该用〈善意〉。敌意指敌对、仇视的态度，与“读起来很温暖”矛盾；友好的态度要用“善意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食欲", "is_correct": false, "explanation": "搭配：“食欲”不能与“对新同学有”搭配，句子说不通。"}, {"text": "礼貌", "is_correct": false, "explanation": "语义：“对新同学有礼貌”是老师希望的，与“不要”的要求相反。"}, {"text": "敌意", "is_correct": true, "explanation": "敌意是对他人的敌对态度，与“不要……”的劝诫语境一致，正好填入此处。"}, {"text": "耐心", "is_correct": false, "explanation": "语义：老师通常希望对新同学有耐心，与“不要”的要求相反。"}], "explanations": {"食欲": "搭配：“食欲”不能与“对新同学有”搭配，句子说不通。", "礼貌": "语义：“对新同学有礼貌”是老师希望的，与“不要”的要求相反。", "敌意": "敌意是对他人的敌对态度，与“不要……”的劝诫语境一致，正好填入此处。", "耐心": "语义：老师通常希望对新同学有耐心，与“不要”的要求相反。"}, "sentence_index": 6, "correct_answer": "敌意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的敌意，我们在比赛里经常见面。", "explanation": "这里应该用〈对手〉。敌意是情绪，不能直接指人。"}, {"text": "老师对学生充满了敌意，学生都很喜欢他。", "explanation": "这里应该用〈关爱〉。敌意指敌对、仇视的情绪，与“学生都很喜欢他”矛盾；对学生的情感要用“关爱”。"}, {"text": "他出于敌意，把所有的积蓄都捐给了孤儿院。", "explanation": "这里应该用〈善意〉。敌意指敌对、仇视的情绪，与“把积蓄捐给孤儿院”的动机相反；出于友好动机要用善意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对我敌意，说话时总是冷着脸。", "corrected_sentence": "他对我有敌意，说话时总是冷着脸。", "error_description": "错误在“有”的省略：“敌意”是名词，“对……有敌意”中间需要动词“有”，漏掉后不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种的敌意让我很难受。", "corrected_sentence": "这种敌意让我很难受。", "error_description": "错误在“的”：“这种”是指示词，后面直接接名词，不加“的”，应说“这种敌意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好转", "is_correct": true, "explanation": "反义：“好转”指情况向好的方向发展，与“恶化”相反。"}, {"text": "维持", "is_correct": false, "explanation": "无关：“维持”指保持原状，不表示与“恶化”相反的变化。"}, {"text": "扩大", "is_correct": false, "explanation": "无关：“扩大”指范围或规模变大，与“恶化”不构成反义。"}, {"text": "集中", "is_correct": false, "explanation": "无关：“集中”指聚在一起，与“恶化”不构成反义。"}], "correct_answer": "好转", "explanations": {"好转": "反义：“好转”指情况向好的方向发展，与“恶化”相反。", "维持": "无关：“维持”指保持原状，不表示与“恶化”相反的变化。", "扩大": "无关：“扩大”指范围或规模变大，与“恶化”不构成反义。", "集中": "无关：“集中”指聚在一起，与“恶化”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改善", "is_correct": true, "explanation": "反义：“改善”指情况变好，与“恶化”相反。"}, {"text": "增加", "is_correct": false, "explanation": "无关：“增加”指数量变多，不指情况变好或变坏，与“恶化”不构成反义。"}, {"text": "查明", "is_correct": false, "explanation": "无关：“查明”指弄清楚，与“恶化”不构成反义。"}, {"text": "推进", "is_correct": false, "explanation": "无关：“推进”指向前推动，不指情况的好坏变化。"}], "correct_answer": "改善", "explanations": {"改善": "反义：“改善”指情况变好，与“恶化”相反。", "增加": "无关：“增加”指数量变多，不指情况变好或变坏，与“恶化”不构成反义。", "查明": "无关：“查明”指弄清楚，与“恶化”不构成反义。", "推进": "无关：“推进”指向前推动，不指情况的好坏变化。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "情况或状态向更坏的方向发展。", "primary_collocate": null, "pronunciation": "è huà", "ipa": "ɤ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "然而，纯粹的竞争若缺乏规范制衡，极易滑向排他性与敌意文化，导致社区生态恶化。", "target_word": "恶化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气恶化了，飞机不能起飞。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的关系突然恶化了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气污染让城市环境恶化了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年河水的质量不断恶化。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架后，关系更加恶化了。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济形势恶化，很多人失去了工作。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不注意休息，病情会恶化。", "target_word": "恶化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他的情况没有恶化。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的治安这几年一直在恶化。", "target_word": "恶化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恶化了", "label": "体标"}, {"form": "恶化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "情况或状态向更坏的方向发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改善", "is_correct": false, "explanation": "语义：“改善”指向好的方向变化，与“滑向排他性与敌意文化”的负面趋势相反。"}, {"text": "恶化", "is_correct": true, "explanation": "正确：“恶化”指情况向更坏的方向发展，与“滑向敌意文化”“导致社区生态”的负面语境相符。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“恢复”指回到原来的良好状态，句中社区生态是向坏的方向变化，不能说恢复。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能说“生态提高”。"}], "explanations": {"改善": "语义：“改善”指向好的方向变化，与“滑向排他性与敌意文化”的负面趋势相反。", "恶化": "正确：“恶化”指情况向更坏的方向发展，与“滑向敌意文化”“导致社区生态”的负面语境相符。", "恢复": "语义：“恢复”指回到原来的良好状态，句中社区生态是向坏的方向变化，不能说恢复。", "提高": "搭配：“提高”用于水平、质量，不能说“生态提高”。"}, "sentence_index": 0, "correct_answer": "恶化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色恶化了。", "explanation": "这里应该用〈褪色〉。恶化说情况、局势变坏，颜色的深浅变化要用褪色。"}, {"text": "这家公司恶化了业务规模。", "explanation": "这里应该用〈扩大〉。恶化只用于情况、状态变坏，不能带“规模”作宾语；规模要用扩大或缩小。"}, {"text": "他这两年越来越恶化了。", "explanation": "这里应该用〈变坏〉。恶化用于情况、局势或病情，说人变坏时不用恶化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好转", "is_correct": false, "explanation": "语义：“好转”指情况变好，与后句“很多人失去了工作”的负面后果不相符。"}, {"text": "恶化", "is_correct": true, "explanation": "正确：“恶化”指经济形势向坏的方向发展，与“很多人失去了工作”的因果相符。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，经济形势不说提高。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”多用于数量，不用于形势。"}], "explanations": {"好转": "语义：“好转”指情况变好，与后句“很多人失去了工作”的负面后果不相符。", "恶化": "正确：“恶化”指经济形势向坏的方向发展，与“很多人失去了工作”的因果相符。", "提高": "搭配：“提高”用于水平、质量，经济形势不说提高。", "增长": "搭配：“增长”多用于数量，不用于形势。"}, "sentence_index": 6, "correct_answer": "恶化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的雨量恶化了。", "explanation": "这里应该用〈增加〉或〈减少〉。恶化说情况向坏的方向变化，雨量的多少变化要用增加或减少。"}, {"text": "他的责任这几年恶化了。", "explanation": "这里应该用〈加重〉。恶化用于情况、局势变坏，责任的轻重要用加重或减轻。"}, {"text": "他的身高这两年恶化了。", "explanation": "这里应该用〈增长〉。恶化说情况向坏的方向变化，身高是中性的数量变化，要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个月他的病情一直没有恶化了，我们都很放心。", "corrected_sentence": "这几个月他的病情一直没有恶化，我们都很放心。", "error_description": "错误：“没有恶化了”，正确：“没有恶化”。否定词“没有”表示变化尚未发生，句中不能再用表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的治安这两年恶化来了。", "corrected_sentence": "这个小区的治安这两年恶化起来了。", "error_description": "错误：“恶化来了”，正确：“恶化起来了”。“恶化”之后的趋向补语应为“起来”，表示变化开始并持续，不能用“来”代替。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗劣", "is_correct": true, "explanation": "反义：“粗劣”指质量差、做得粗陋，与“精良”相反。"}, {"text": "清澈", "is_correct": false, "explanation": "无关：“清澈”形容水或眼神清亮透明，与“精良”不构成反义。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：“宽敞”形容空间大，与“精良”不构成反义。"}, {"text": "灵活", "is_correct": false, "explanation": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。"}], "correct_answer": "粗劣", "explanations": {"粗劣": "反义：“粗劣”指质量差、做得粗陋，与“精良”相反。", "清澈": "无关：“清澈”形容水或眼神清亮透明，与“精良”不构成反义。", "宽敞": "无关：“宽敞”形容空间大，与“精良”不构成反义。", "灵活": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗劣", "is_correct": true, "explanation": "反义：“粗劣”指质量差，与“精良”相反。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与“精良”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容没有声音或很平和，与“精良”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}], "correct_answer": "粗劣", "explanations": {"粗劣": "反义：“粗劣”指质量差，与“精良”相反。", "迅速": "无关：“迅速”形容速度快，与“精良”不构成反义。", "安静": "无关：“安静”形容没有声音或很平和，与“精良”不构成反义。", "明亮": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物品质量很好，制作细致。", "primary_collocate": null, "pronunciation": "jīng liáng", "ipa": "tɕiŋ˥ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "因此，设计精良的游戏架构往往内嵌平衡机制，将对抗控制在激发活力而非摧毁联结的阈值之内。", "target_word": "精良", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂的设备十分精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一台制作精良的相机。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队装备精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套工具做工精良，用了十年也没坏。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅做的木桌工艺精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手表外形好看，做工也很精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用精良的材料造了这座桥。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀看起来很精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "精良的设备让工作快了很多。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物品质量好、制作细致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ca44288-1204-4ede-a46f-083eed1c9108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”表示做工不细，与“内嵌平衡机制”所暗示的精心设计相矛盾。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指设计和制作精细、质量好，与“内嵌平衡机制”的语境相符。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”指做事马虎匆忙，与“往往内嵌平衡机制”的精心设计相矛盾。"}, {"text": "廉价", "is_correct": false, "explanation": "搭配：“廉价”形容价格低，不用来形容游戏架构。"}], "explanations": {"粗糙": "语义：“粗糙”表示做工不细，与“内嵌平衡机制”所暗示的精心设计相矛盾。", "精良": "正确：“精良”指设计和制作精细、质量好，与“内嵌平衡机制”的语境相符。", "草率": "语义：“草率”指做事马虎匆忙，与“往往内嵌平衡机制”的精心设计相矛盾。", "廉价": "搭配：“廉价”形容价格低，不用来形容游戏架构。"}, "sentence_index": 0, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个精良的学生。", "explanation": "这里应该用〈优秀〉。精良形容物品质量好、制作细致，形容人要用优秀。"}, {"text": "今天天气很精良。", "explanation": "这里应该用〈晴朗〉。精良说物品的质量，天气的好坏要用晴朗。"}, {"text": "他有精良的经验。", "explanation": "这里应该用〈丰富〉。精良用于物品、器具的质量，经验的多少要用丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗劣", "is_correct": false, "explanation": "语义：“做工也很粗劣”与前句“外形好看”的正面评价不相容，“也”所引出的应是同样的好评。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指做工细致、质量好，与“外形好看”的正面评价相符。"}, {"text": "轻巧", "is_correct": false, "explanation": "搭配：“轻巧”形容重量小、灵便，不用来说做工。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不细心，与前句“外形好看”的正面评价以及“也”所引出的并列好评不相容。"}], "explanations": {"粗劣": "语义：“做工也很粗劣”与前句“外形好看”的正面评价不相容，“也”所引出的应是同样的好评。", "精良": "正确：“精良”指做工细致、质量好，与“外形好看”的正面评价相符。", "轻巧": "搭配：“轻巧”形容重量小、灵便，不用来说做工。", "马虎": "语义：“马虎”指做事不细心，与前句“外形好看”的正面评价以及“也”所引出的并列好评不相容。"}, "sentence_index": 6, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖水很精良。", "explanation": "这里应该用〈清澈〉。精良形容物品的制作质量，水的透明程度要用清澈。"}, {"text": "这个月的收入很精良。", "explanation": "这里应该用〈丰厚〉。精良形容物品的制作质量，收入的多少要用丰厚。"}, {"text": "她的声音很精良。", "explanation": "这里应该用〈响亮〉。精良形容物品的质量，声音的洪亮要用响亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂生产的零件做很精良。", "corrected_sentence": "这家工厂生产的零件做得很精良。", "error_description": "错误：“做很精良”，正确：“做得很精良”。“做”后接表示程度的补语时，要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师送我的显微镜是最很精良的。", "corrected_sentence": "这位老师送我的显微镜是最精良的。", "error_description": "错误：“最很精良”，正确：“最精良”。“最”和“很”都表示程度，不能同时修饰同一个形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cb12e7d-639a-44ff-b76c-a02f91b41442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
