INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个系统或组织的整体结构、框架或构成方式。", "primary_collocate": null, "pronunciation": "jià gòu", "ipa": "tɕja˥˩ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这个软件的架构很清楚。", "target_word": "架构", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司的组织架构已经改了。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新系统用了更简单的架构。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的架构能让程序更容易修改。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在黑板上画出了网站的架构。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络的架构分成三层。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在讨论新产品的技术架构。", "target_word": "架构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套系统的架构太复杂，新人很难看懂。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧系统的架构改成了新的。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司用过这种分层架构。", "target_word": "架构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "软件架构", "label": "复合"}, {"form": "系统架构", "label": "复合"}, {"form": "组织架构", "label": "复合"}], "register": "通用", "sense_fingerprint": "系统或组织的整体结构与框架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "架构", "is_correct": true, "explanation": "正确。“架构”指软件的整体结构，与“很清楚”相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：软件没有体重，“体重”只用于人或动物。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物或饮品，不能说“软件的口味很清楚”。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“气味”指物体散发的味道，“清楚”不能用来形容软件的气味。"}], "explanations": {"架构": "正确。“架构”指软件的整体结构，与“很清楚”相符。", "体重": "语义：软件没有体重，“体重”只用于人或动物。", "口味": "搭配：“口味”用于食物或饮品，不能说“软件的口味很清楚”。", "气味": "搭配：“气味”指物体散发的味道，“清楚”不能用来形容软件的气味。"}, "sentence_index": 0, "correct_answer": "架构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣的架构很新颖，穿起来很好看。", "explanation": "这里应该用〈设计〉。“架构”指系统或组织的整体框架，衣服的款式和样式要用〈设计〉。"}, {"text": "这种药的架构很简单。", "explanation": "这里应该用〈构成〉。“架构”指系统或组织的整体框架，药品的成分组成要用〈构成〉。"}, {"text": "他在黑板上画了一只架构。", "explanation": "这里量词用错。“架构”是抽象的框架，应该用〈个〉或〈套〉计量；“只”多用于动物，或成对物品中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "架构", "is_correct": true, "explanation": "正确。“架构”指产品的技术整体框架，与“讨论”和“技术”相符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：产品没有性格，不能讨论“技术性格”。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“嗓音”指人的声音，不能与“技术”搭配。"}, {"text": "零食", "is_correct": false, "explanation": "语义：讨论的是技术方案，与“零食”毫无关系。"}], "explanations": {"架构": "正确。“架构”指产品的技术整体框架，与“讨论”和“技术”相符。", "性格": "语义：产品没有性格，不能讨论“技术性格”。", "嗓音": "搭配：“嗓音”指人的声音，不能与“技术”搭配。", "零食": "语义：讨论的是技术方案，与“零食”毫无关系。"}, "sentence_index": 6, "correct_answer": "架构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的架构很高大，打篮球很占优势。", "explanation": "这里把“架构”误用于描述人的身材。本词指系统或组织的整体框架，并不指人的体格，与此处用法不符。"}, {"text": "他很有架构，说话总是摆着一副了不起的样子。", "explanation": "这里把“架构”误用为“架子”（摆派头）的意思。本词并不表示人的派头。"}, {"text": "这盘菜的架构很清淡，我很喜欢。", "explanation": "这里把“架构”误用于描述菜肴的口味。本词并不表示味道，与“系统或组织的整体框架”这一义项不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改版换了一件新的架构。", "corrected_sentence": "这次改版换了一套新的架构。", "error_description": "量词错误：“架构”指系统的整体框架，应该用“套”计量；“件”多用于具体物品或事情，不能用来数“架构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套新架构昨天已经改了过。", "corrected_sentence": "这套新架构昨天已经改过了。", "error_description": "错误：动词、“过”和“了”的顺序颠倒。“过”应紧跟动词，写作“改过了”，不能说“改了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
