INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "嵌入内部；放入内部。", "primary_collocate": null, "pronunciation": "nèi qiàn", "ipa": "nei˥˩ tɕʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "因此，设计精良的游戏架构往往内嵌平衡机制，将对抗控制在激发活力而非摧毁联结的阈值之内。", "target_word": "内嵌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款手机内嵌了一个小型电池。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件内嵌地图功能，用户不用另外下载。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电视内嵌喇叭，不需要再接音箱。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种桌子内嵌灯带，晚上很好看。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计师在墙里内嵌了一个小书架。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网页里内嵌着一段视频。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把芯片内嵌到手表里。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机内嵌过一个防抖装置。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司让每台机器都内嵌安全程序。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内嵌了", "label": "体标"}, {"form": "内嵌着", "label": "体标"}, {"form": "内嵌过", "label": "体标"}, {"form": "内嵌式", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把某物嵌入另一物内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内嵌", "is_correct": true, "explanation": "正确。“内嵌”指嵌入内部，与“往往……平衡机制”的句意相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：设计精良的架构不会去拆除平衡机制，与句意正好相反。"}, {"text": "搞掉", "is_correct": false, "explanation": "语域：“搞掉”是口语，与这句书面化的论述不相称。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”多用于纸张、合同等，不能用于“平衡机制”。"}], "explanations": {"内嵌": "正确。“内嵌”指嵌入内部，与“往往……平衡机制”的句意相符。", "拆除": "语义：设计精良的架构不会去拆除平衡机制，与句意正好相反。", "搞掉": "语域：“搞掉”是口语，与这句书面化的论述不相称。", "撕毁": "搭配：“撕毁”多用于纸张、合同等，不能用于“平衡机制”。"}, "sentence_index": 0, "correct_answer": "内嵌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把牛奶内嵌在冰箱外面。", "explanation": "这里用的是“内嵌”嵌入或放入内部的含义。牛奶放在冰箱外面，并不在内部，与此不符。"}, {"text": "书架上内嵌着一本词典。", "explanation": "这里应该用〈放置〉。“内嵌”表示嵌入物体内部、成为其一部分，词典只是放在书架上，要用〈放置〉。"}, {"text": "他把钥匙内嵌在门外的地上。", "explanation": "这里用的是“内嵌”放入内部的含义。钥匙落在门外的地上，并不在任何内部，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内嵌", "is_correct": true, "explanation": "正确。“内嵌”指嵌在网页内部，与“网页里……一段视频”相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "配价：“拍摄”需要有人或设备施动，网页本身不能拍摄视频。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”的对象应是可以移动的实物，网页里的视频无法被搬运。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”表示去掉，与表示持续存在的“着”不搭配。"}], "explanations": {"内嵌": "正确。“内嵌”指嵌在网页内部，与“网页里……一段视频”相符。", "拍摄": "配价：“拍摄”需要有人或设备施动，网页本身不能拍摄视频。", "搬运": "配价：“搬运”的对象应是可以移动的实物，网页里的视频无法被搬运。", "删除": "搭配：“删除”表示去掉，与表示持续存在的“着”不搭配。"}, "sentence_index": 6, "correct_answer": "内嵌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画内嵌在窗户的外侧。", "explanation": "这里用的是“内嵌”嵌入内部的含义。画在窗户外侧，并不在内部，与此不符。"}, {"text": "他在窗户上内嵌了一张贴纸。", "explanation": "这里应该用〈贴〉。“内嵌”指嵌在物体内部，贴纸只是贴在表面，要用〈贴〉。"}, {"text": "他用绳子把行李内嵌在车顶上。", "explanation": "这里应该用〈绑〉。“内嵌”指嵌入内部、固定为一体，行李只是绑在车顶外面，要用〈绑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款音箱内嵌了着一块小屏幕。", "corrected_sentence": "这款音箱内嵌着一块小屏幕。", "error_description": "体标重复：“着”已表示状态持续，不能再加“了”；应说“内嵌着”，不能说“内嵌了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把小磁铁内嵌耳机外壳里。", "corrected_sentence": "工人把小磁铁内嵌到耳机外壳里。", "error_description": "介词缺失：“内嵌”后缺少引出处所的介词，应说“内嵌到……里”或“内嵌在……里”，不能直接接处所名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
