INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彻底破坏或消灭，使不再存在。", "primary_collocate": null, "pronunciation": "cuī huǐ", "ipa": "tsʰuei˥ xuei˨˩˦", "syllable_count": 2, "sentences": [{"text": "地震摧毁了山里的小村子。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争摧毁了这座古老的城市。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大火摧毁了工厂里所有的机器。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次失败不会摧毁他的信心。", "target_word": "摧毁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "暴风雨摧毁过很多农民的房子。", "target_word": "摧毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队想摧毁对方的桥和路。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谎话会摧毁朋友之间的信任。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把敌人的基地彻底摧毁了。", "target_word": "摧毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水摧毁了河边的田地。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏消息差点摧毁了他的希望。", "target_word": "摧毁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "摧毁了", "label": "体标"}, {"form": "摧毁过", "label": "体标"}, {"form": "摧毁着", "label": "体标"}, {"form": "摧毁性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "彻底破坏使不复存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建造", "is_correct": false, "explanation": "语义：地震是破坏性的自然力，不会“建造”村子，与“摧毁”的破坏义正相反。"}, {"text": "摧毁", "is_correct": true, "explanation": "“摧毁”指彻底破坏，与地震毁坏村子的语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“摧毁”相反，地震不会保护村庄。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”多用于漏洞、衣物等小范围损坏，不说修补整座村子。"}], "explanations": {"建造": "语义：地震是破坏性的自然力，不会“建造”村子，与“摧毁”的破坏义正相反。", "摧毁": "“摧毁”指彻底破坏，与地震毁坏村子的语境相合。", "保护": "语义：“保护”与“摧毁”相反，地震不会保护村庄。", "修补": "搭配：“修补”多用于漏洞、衣物等小范围损坏，不说修补整座村子。"}, "sentence_index": 0, "correct_answer": "摧毁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把桌布摧毁了一小块。", "explanation": "这里应该用〈划破〉。“摧毁”指彻底毁掉，只毁掉一小块、布面其余部分仍在，应说划破。"}, {"text": "他把袜子摧毁了一个小洞。", "explanation": "这里应该用〈戳破〉。“摧毁”指彻底毁掉，只戳出一个小洞，应说戳破。"}, {"text": "医生摧毁了他的疼痛。", "explanation": "这里应该用〈消除〉。摧毁用于有形事物或系统的彻底毁灭，不用于疼痛这类感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增进", "is_correct": false, "explanation": "语义：“增进”是促进加深，谎话不能增进信任，与句意相反。"}, {"text": "维护", "is_correct": false, "explanation": "语义：“维护”是保持、守护，谎话不会维护朋友之间的信任。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：信任不能被“煮沸”，此搭配完全不通。"}, {"text": "摧毁", "is_correct": true, "explanation": "“摧毁”指彻底破坏，与谎话损害信任的语境相合。"}], "explanations": {"增进": "语义：“增进”是促进加深，谎话不能增进信任，与句意相反。", "维护": "语义：“维护”是保持、守护，谎话不会维护朋友之间的信任。", "煮沸": "语义：信任不能被“煮沸”，此搭配完全不通。", "摧毁": "“摧毁”指彻底破坏，与谎话损害信任的语境相合。"}, "sentence_index": 6, "correct_answer": "摧毁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那盏路灯被摧毁后，第二天又亮了。", "explanation": "“摧毁”指彻底毁掉、使不复存在，“第二天又亮了”与之矛盾；此处只是暂时坏了，不能用摧毁。"}, {"text": "他的衣服被摧毁了，洗一洗还能穿。", "explanation": "“摧毁”后不能再恢复，“洗一洗还能穿”与之矛盾；衣服只是弄脏，不能用摧毁。"}, {"text": "妈妈把面包摧毁成了两半。", "explanation": "“摧毁”指彻底消灭，切成两半后东西依然存在，二者矛盾；这里应说“切”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座老桥被台风把摧毁了。", "corrected_sentence": "那座老桥被台风摧毁了。", "error_description": "错误：“被”字句与“把”字句不能叠用；“被台风把摧毁了”应去掉“把”，说“被台风摧毁了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人昨天已经彻底摧毁着基地。", "corrected_sentence": "敌人昨天已经彻底摧毁了基地。", "error_description": "错误：“着”表示动作正在进行，与“已经”表示的已完成不协调；已完成的动作应用“了”，说“彻底摧毁了基地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "阈值是指某个系统或现象发生改变时的临界值，比如温度达到一定数值水就会沸腾，这个数值就是阈值。", "primary_collocate": null, "pronunciation": "yù zhí", "ipa": "y˥˩ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "因此，设计精良的游戏架构往往内嵌平衡机制，将对抗控制在激发活力而非摧毁联结的阈值之内。", "target_word": "阈值", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水温超过阈值，机器就会自动停止。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个报警器的阈值设得太低了。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度一到阈值，水就开始沸腾。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，每个人的疼痛阈值不一样。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把阈值调高了一点，误报就少了。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气污染一旦超过阈值，学校就停课。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电量低于阈值时，会自动省电。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音低于人耳的阈值，我们就听不见。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒数量超过阈值，系统就会自动隔离文件。", "target_word": "阈值", "complexity_tier": "T3", "furigana": "bìng dú shù liàng chāo guò yù zhí, xì tǒng jiù huì zì dòng gé lí wén jiàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "系统或现象发生改变时的临界值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作品", "is_correct": false, "explanation": "语义：“作品”不是临界数值，“将对抗控制在作品之内”文意不通。"}, {"text": "阈值", "is_correct": true, "explanation": "“阈值”指临界值，与“控制在……之内”的限度义相合。"}, {"text": "玩家", "is_correct": false, "explanation": "语义：对抗不能被控制在“玩家”之内，此处搭配与语境都不通。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语词，不宜用于这一书面语境。"}], "explanations": {"作品": "语义：“作品”不是临界数值，“将对抗控制在作品之内”文意不通。", "阈值": "“阈值”指临界值，与“控制在……之内”的限度义相合。", "玩家": "语义：对抗不能被控制在“玩家”之内，此处搭配与语境都不通。", "门道": "语域：“门道”是口语词，不宜用于这一书面语境。"}, "sentence_index": 0, "correct_answer": "阈值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器有一把阈值，超过它就会自动停止。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，阈值是数值界限，应说“一个阈值”。"}, {"text": "我们为报警器设定了一只阈值。", "explanation": "这里应该用〈个〉。“只”用于动物或成对物品中的一件，阈值应说“一个阈值”。"}, {"text": "医生量了三座阈值，结果都正常。", "explanation": "这里应该用〈个〉。“座”用于山、桥、楼等大型固定物，阈值应说“三个阈值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假期", "is_correct": false, "explanation": "语义：“假期”不是变化的界限，“空气污染一旦超过假期”不通。"}, {"text": "阈值", "is_correct": true, "explanation": "“阈值”指临界值，空气污染超过它时学校停课，与句意相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：污染不能“超过心情”，此处与句中的污染语境相反。"}, {"text": "夜色", "is_correct": false, "explanation": "语义：污染不能“超过夜色”，夜色不是可以比较的数量界限。"}], "explanations": {"假期": "语义：“假期”不是变化的界限，“空气污染一旦超过假期”不通。", "阈值": "“阈值”指临界值，空气污染超过它时学校停课，与句意相合。", "心情": "语义：污染不能“超过心情”，此处与句中的污染语境相反。", "夜色": "语义：污染不能“超过夜色”，夜色不是可以比较的数量界限。"}, "sentence_index": 6, "correct_answer": "阈值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人打开了机器的阈值，然后开始工作。", "explanation": "这里应该用〈设定〉。阈值是数值界限，不能被“打开”，应说设定或调整。"}, {"text": "他把阈值吃掉了一半，结果很满意。", "explanation": "这里应该用〈降低〉。阈值是数值界限，能被调高或调低，不能被“吃掉”。"}, {"text": "这个阈值很香，大家都爱闻。", "explanation": "阈值是数值界限，没有气味，不能用“香”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们设定了三股阈值，分别对应三个档位。", "corrected_sentence": "我们设定了三个阈值，分别对应三个档位。", "error_description": "错误：量词“股”多用于气味、力量、水流，阈值应用量词“个”，写作“三个阈值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些阈值们都需要重新检查。", "corrected_sentence": "这些阈值都需要重新检查。", "error_description": "错误：后缀“们”只用于指人的名词，阈值是抽象数值，不能加“们”；应说“这些阈值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
