INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同时进行，互不冲突。", "primary_collocate": null, "pronunciation": "bìng xíng bù bèi", "ipa": "piŋ˥˩ ɕiŋ˧˥ pu˥˩ pei˥˩", "syllable_count": 4, "sentences": [{"text": "与竞争并行不悖的，是日益复杂的团队合作范式。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工作和学习并行不悖，我都能做好。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得读书和运动并行不悖。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个计划并行不悖，可以一起做。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "散步和聊天并行不悖，我们边走边说。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱好和工作并行不悖，他过得很快乐。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学说话和学写字并行不悖，不用分先后。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两项研究并行不悖，可以同时推进。", "target_word": "并行不悖", "complexity_tier": "T3", "furigana": "zhè liǎng xiàng yán jiū bìng xíng bù bèi, kě yǐ tóng shí tuī jìn.", "sentence_source": "generated"}, {"text": "新旧办法并行不悖，大家可以自己选。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的两份兼职并行不悖，时间刚好够用。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "两件事同时进行而互不冲突", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简化", "is_correct": false, "explanation": "语义：“简化”是使事情变简单，与后文“日益复杂”相矛盾。"}, {"text": "并行不悖", "is_correct": true, "explanation": "正确：“并行不悖”指两件事同时进行、互不冲突，这里说与竞争不相冲突的范式。"}, {"text": "吵架", "is_correct": false, "explanation": "配价：“吵架”要求有人作施事，不能和“竞争”这类抽象名词搭配。"}, {"text": "打架", "is_correct": false, "explanation": "语域：“打架”是口语，与书面句式“与……的，是……”不协调。"}], "explanations": {"简化": "语义：“简化”是使事情变简单，与后文“日益复杂”相矛盾。", "并行不悖": "正确：“并行不悖”指两件事同时进行、互不冲突，这里说与竞争不相冲突的范式。", "吵架": "配价：“吵架”要求有人作施事，不能和“竞争”这类抽象名词搭配。", "打架": "语域：“打架”是口语，与书面句式“与……的，是……”不协调。"}, "sentence_index": 0, "correct_answer": "并行不悖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种说法并行不悖，无法同时成立。", "explanation": "这里应该用〈相悖〉。“并行不悖”表示两件事能同时进行、互不冲突，与“无法同时成立”的意思正相反。"}, {"text": "这两项任务并行不悖，所以只能二选一。", "explanation": "这里应该用〈不可兼得〉。“并行不悖”表示两件事能同时进行、互不妨碍，与“只能二选一”的意思相反。"}, {"text": "这两道工序并行不悖，必须先做完第一道，再做第二道。", "explanation": "这里应该用〈依次〉。“并行不悖”强调同时进行，与“先做完第一道，再做第二道”的先后顺序矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排序", "is_correct": false, "explanation": "语义：“排序”指按先后次序排列，与“不用分先后”相矛盾。"}, {"text": "并行不悖", "is_correct": true, "explanation": "正确：“并行不悖”指两件事能同时进行、互不妨碍，与“不用分先后”相合。"}, {"text": "争先", "is_correct": false, "explanation": "语义：“争先”指争着排在前面，与“不用分先后”相矛盾。"}, {"text": "扯皮", "is_correct": false, "explanation": "语域：“扯皮”是口语，含推诿之意，与这句的书面语气不合，也不表示同时进行。"}], "explanations": {"排序": "语义：“排序”指按先后次序排列，与“不用分先后”相矛盾。", "并行不悖": "正确：“并行不悖”指两件事能同时进行、互不妨碍，与“不用分先后”相合。", "争先": "语义：“争先”指争着排在前面，与“不用分先后”相矛盾。", "扯皮": "语域：“扯皮”是口语，含推诿之意，与这句的书面语气不合，也不表示同时进行。"}, "sentence_index": 6, "correct_answer": "并行不悖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的两种观点并行不悖，永远无法调和。", "explanation": "这里应该用〈水火不容〉。“并行不悖”表示互不冲突，与“永远无法调和”的意思矛盾。"}, {"text": "这两个项目要并行不悖地完成，一步一步来。", "explanation": "这里应该用〈循序渐进〉。“并行不悖”强调同时进行，与“一步一步来”的先后次序不符。"}, {"text": "两家公司并行不悖，只能有一家存活。", "explanation": "这里应该用〈势不两立〉。“并行不悖”表示两者能共存、互不冲突，与“只能有一家存活”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的两份工作很并行不悖，互不耽误。", "corrected_sentence": "我的两份工作并行不悖，互不耽误。", "error_description": "错误：“并行不悖”表示同时进行，一般不接程度副词“很”。正确：直接说“并行不悖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的画画课和跑步课并行不悖得进行，各不相扰。", "corrected_sentence": "她的画画课和跑步课并行不悖地进行，各不相扰。", "error_description": "“并行不悖”修饰动词“进行”时应用“地”，不能用“得”。应说“并行不悖地进行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
