INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "攻占（敌人的据点或堡垒）；比喻战胜困难、完成艰巨任务。", "primary_collocate": null, "pronunciation": "gōng kè", "ipa": "kʊŋ˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "攻克", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "攻克", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学家终于攻克了这个难题。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们用了三天，攻克了敌人的据点。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师们正在攻克技术难关。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院攻克了一种罕见的疾病。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须攻克这个最后的难关。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，想攻克语法难关。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队很快攻克了山上的城堡。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个难题很大，没有人攻克过。", "target_word": "攻克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻克了", "label": "体标"}, {"form": "攻克过", "label": "体标"}], "register": "中性", "sense_fingerprint": "攻占据点，或比喻战胜难题难关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻克", "is_correct": true, "explanation": "正确：指战胜高难度副本，符合句中“攻克高难度副本”的语境。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与句中“精密分工、统筹全局”以完成副本为目的的语境相悖。"}, {"text": "驱散", "is_correct": false, "explanation": "搭配：“驱散”用于人群、雾气等，不能用于副本或战役，句意不通。"}, {"text": "歼灭", "is_correct": false, "explanation": "搭配：“歼灭”的对象是敌人或敌军，不能说歼灭副本。"}], "explanations": {"攻克": "正确：指战胜高难度副本，符合句中“攻克高难度副本”的语境。", "放弃": "语义：“放弃”与句中“精密分工、统筹全局”以完成副本为目的的语境相悖。", "驱散": "搭配：“驱散”用于人群、雾气等，不能用于副本或战役，句意不通。", "歼灭": "搭配：“歼灭”的对象是敌人或敌军，不能说歼灭副本。"}, "sentence_index": 0, "correct_answer": "攻克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他攻克了一盘饺子。", "explanation": "这里应该用〈吃〉。攻克指攻下难关或堡垒，吃饺子要说吃，不能说攻克。"}, {"text": "他们平安攻克了这次旅行。", "explanation": "这里应该用〈度过〉。攻克指攻下难关或堡垒，旅行要说度过，不能说攻克。"}, {"text": "他攻克了一场雨。", "explanation": "这里应该用〈躲开〉。攻克指攻下难关或堡垒，躲避雨要说躲开，不能说攻克。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻克", "is_correct": true, "explanation": "正确：指战胜最后的难关，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”用于美好的事物，难关是需要克服的障碍，句意不通。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”只用于金钱、时间等，不能说挥霍难关。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”用于赞美人或事迹，不能用来形容要克服的难关。"}], "explanations": {"攻克": "正确：指战胜最后的难关，符合句意。", "欣赏": "语义：“欣赏”用于美好的事物，难关是需要克服的障碍，句意不通。", "挥霍": "搭配：“挥霍”只用于金钱、时间等，不能说挥霍难关。", "歌颂": "语义：“歌颂”用于赞美人或事迹，不能用来形容要克服的难关。"}, "sentence_index": 6, "correct_answer": "攻克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她攻克了这个邀请。", "explanation": "这里应该用〈拒绝〉。攻克的对象是堡垒、难题，邀请不能攻克，表示不接受要用拒绝。"}, {"text": "他攻克了热烈的掌声。", "explanation": "这里应该用〈赢得〉。掌声是别人给予的，要说赢得掌声，不能说攻克。"}, {"text": "他攻克了这次机会。", "explanation": "这里应该用〈放弃〉。机会不是需要攻下的难关，放弃机会要用放弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们攻克在这个难关。", "corrected_sentence": "我们攻克了这个难关。", "error_description": "介词误用：“攻克”是及物动词，后面直接带宾语，不能在动词与宾语之间插入介词“在”。把“在”换成体标“了”，即为正确形式“攻克了这个难关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天他不攻克这个难题。", "corrected_sentence": "昨天他没攻克这个难题。", "error_description": "否定词错误：叙述已经发生的动作要用“没”，不能用“不”。错误形式是“不攻克”，正确形式是“没攻克”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
