INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11967, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事情非常困难，需要付出很大努力才能完成。", "primary_collocate": null, "pronunciation": "gāo nán dù", "ipa": "kɑʊ˥ nan˧˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这个高难度副本，我们花了三天才通关。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一道高难度的数学题。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完成了一个高难度动作。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个关卡是高难度的，我试了三次都没成功。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么高难度的比赛，他一点也不怕。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是高难度的，小孩子看不懂。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一个高难度的任务。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳高对她来说是高难度运动。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高难度的手术，医生要先练习很多年。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子是高难度的，我练了一个月。", "target_word": "高难度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情非常困难，需要很大努力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c2bd5b-1259-421c-b750-220f4c66d70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空洞", "is_correct": false, "explanation": "语义：“空洞”指没有实际内容，不能用来说明副本的难度。"}, {"text": "高难度", "is_correct": true, "explanation": "正确：“高难度副本”指难度很大的副本，与“花了三天才通关”的语境相符。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”形容讨人喜欢的样子，不能说明副本的难度。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”形容感情或生活的愉快，不能用来修饰副本。"}], "explanations": {"空洞": "语义：“空洞”指没有实际内容，不能用来说明副本的难度。", "高难度": "正确：“高难度副本”指难度很大的副本，与“花了三天才通关”的语境相符。", "可爱": "搭配：“可爱”形容讨人喜欢的样子，不能说明副本的难度。", "甜蜜": "语义：“甜蜜”形容感情或生活的愉快，不能用来修饰副本。"}, "sentence_index": 0, "correct_answer": "高难度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的高难度是三千米。", "explanation": "这里应该用〈高度〉。“高难度”形容事情困难，说山的高低、海拔要用〈高度〉。"}, {"text": "他是一个高难度的人，大家都不敢靠近他。", "explanation": "这里应该用〈难相处〉。“高难度”只用来形容事情或任务，说人的性情难打交道要用“难相处”。"}, {"text": "这件衣服的价格高难度，我买不起。", "explanation": "这里应该用〈高价〉。“高难度”形容事情困难，不能用来说价格贵，要用“高价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物的个头低小，不能用来说任务的难度。"}, {"text": "高难度", "is_correct": true, "explanation": "正确：“高难度的任务”指难度很大的任务，与“老师给了我们”的语境相符。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能被看穿，不能用来修饰“任务”。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜的任务”说不通，任务不是甜蜜与否的事物，与“高难度”的语义无关。"}], "explanations": {"矮小": "体貌：“矮小”形容人或物的个头低小，不能用来说任务的难度。", "高难度": "正确：“高难度的任务”指难度很大的任务，与“老师给了我们”的语境相符。", "透明": "搭配：“透明”形容物体能被看穿，不能用来修饰“任务”。", "甜蜜": "语义：“甜蜜的任务”说不通，任务不是甜蜜与否的事物，与“高难度”的语义无关。"}, "sentence_index": 6, "correct_answer": "高难度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都吃高难度的饭，觉得很香。", "explanation": "这里应该用〈高档〉。“高难度”形容事情困难，不能用来形容饭菜的档次，说饭菜档次高要用“高档”。"}, {"text": "他们终于登上了高难度，站在山顶拍照。", "explanation": "这里应该用〈高峰〉。“高难度”指事情困难，不能指需要登上的地方。"}, {"text": "今天的天气高难度，我们去爬山吧。", "explanation": "这里应该用〈晴朗〉。“高难度”指事情难做，不能用来形容天气好坏，说天气好要用“晴朗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他弹完了一首高难度地曲子，大家都鼓掌了。", "corrected_sentence": "他弹完了一首高难度的曲子，大家都鼓掌了。", "error_description": "“高难度”修饰名词“曲子”时应用“的”，不能用“地”。应说“高难度的曲子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她完成了一个高难度地舞蹈，观众都鼓掌了。", "corrected_sentence": "她完成了一个高难度的舞蹈，观众都鼓掌了。", "error_description": "“高难度”修饰名词“舞蹈”时应用“的”，不能用“地”。应说“一个高难度的舞蹈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62039189-ca3b-4dd6-a66b-4c86db4284d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
