INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指同一内容或同一事物的再现版本，如文件、物品等的复制品。", "primary_collocate": null, "pronunciation": "fù běn", "ipa": "fu˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张照片的副本我已经洗好了。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份合同的副本发给我。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原件你留着，我只要一份副本。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张证件的副本不能代替原件。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件有两份副本，一份在公司。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用复印机做了一份副本。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把电子副本存在了电脑里。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办签证时，要交护照的副本。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你最好给重要文件留个副本，免得丢了。", "target_word": "副本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是副本，原件在银行的保险箱里。", "target_word": "副本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "电子副本", "label": "复合"}], "register": "中性", "sense_fingerprint": "副本：与原件内容相同的复制品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副本", "is_correct": true, "explanation": "正确。“这张照片的副本”指照片的复制件，可以“洗好”，与句意相合，是唯一能填入空格的词。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，“这张照片的蛋糕”说不通，也不能“洗好”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，“这张照片的手机”说不通，也不能“洗好”。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“这张照片的合同”说不通，合同不是可以“洗好”的东西。"}], "explanations": {"副本": "正确。“这张照片的副本”指照片的复制件，可以“洗好”，与句意相合，是唯一能填入空格的词。", "蛋糕": "语义：蛋糕是食物，“这张照片的蛋糕”说不通，也不能“洗好”。", "手机": "语义：手机是通讯工具，“这张照片的手机”说不通，也不能“洗好”。", "合同": "搭配：“这张照片的合同”说不通，合同不是可以“洗好”的东西。"}, "sentence_index": 0, "correct_answer": "副本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从病人身上取了一份组织副本化验。", "explanation": "这里应该用〈样本〉。副本是复制件，从人体取下用于化验的组织应称样本，不能说副本。"}, {"text": "我买了一只副本，放在书架上。", "explanation": "这里应该用〈份〉。副本是文件或物品的复制件，量词用“份”，“只”不能用于副本。"}, {"text": "这套房子是副本，供客户参观。", "explanation": "这里应该用〈样板〉。副本是复制件，供客户参观的示范房应称样板，不能说副本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副本", "is_correct": true, "explanation": "正确。“电子副本”指存在电脑里的数字复制件，与“存在了电脑里”相配。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，“电子椅子”说不通，也无法存进电脑。"}, {"text": "饭", "is_correct": false, "explanation": "配价：“存”的宾语须是文件或数据，饭不能存在电脑里。"}, {"text": "花", "is_correct": false, "explanation": "语义：花是植物，不能说“电子花”，也不能存进电脑。"}], "explanations": {"副本": "正确。“电子副本”指存在电脑里的数字复制件，与“存在了电脑里”相配。", "椅子": "语义：椅子是家具，“电子椅子”说不通，也无法存进电脑。", "饭": "配价：“存”的宾语须是文件或数据，饭不能存在电脑里。", "花": "语义：花是植物，不能说“电子花”，也不能存进电脑。"}, "sentence_index": 6, "correct_answer": "副本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场危险的戏由他的副本完成。", "explanation": "这里应该用〈替身〉。副本指复制的文件或物品，代替演员完成危险动作的人要用替身。"}, {"text": "我复印了一台副本，给了同事。", "explanation": "这里应该用〈份〉。副本计量用“份”，“台”用于机器等大型器具，不用于复印出来的文件。"}, {"text": "我把这份合同存成了一块副本，放进了档案柜。", "explanation": "这里应该用〈份〉。副本计量用“份”，“块”用于块状的东西，不能用于存档的文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给客户寄了一只副本。", "corrected_sentence": "我给客户寄了一份副本。", "error_description": "“副本”的量词应用“份”，不能用“只”。“只”用于动物或成对器物中的一个，不用于复制件。错误形式：一只副本；正确形式：一份副本。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给了他一只副本。", "corrected_sentence": "我给了他一份副本。", "error_description": "“副本”的量词应用“份”，不能用“只”。错误形式：一只副本；正确形式：一份副本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
