INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现一定战略目的，在统一指挥下进行的较大规模的作战行动。", "primary_collocate": null, "pronunciation": "zhàn yì", "ipa": "ʈʂan˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这场战役持续了三个月，双方损失很大。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官在战役开始前制定了详细计划。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次战役的胜利改变了战争的方向。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写了很多著名的战役。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在这场战役中牺牲了很多士兵。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了赢得这次战役，军队准备了一年。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军指挥过三次大型战役。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战役结束后，士兵们终于可以回家了。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战役的目的是夺回那座城市。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次战役动用了几十万军队。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "戰役", "label": "繁体"}], "register": "书面", "sense_fingerprint": "战役：统一指挥下为战略目的进行的大规模作战", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战役", "is_correct": true, "explanation": "正确。“战役”指统一指挥下的大规模作战，可以持续三个月并造成双方损失。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会一般只有几个小时，不可能持续三个月，也谈不上双方损失。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“双方损失很大”说的是交战双方，“电影”不能承担这种关系。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐只是一顿饭，无法持续三个月。"}], "explanations": {"战役": "正确。“战役”指统一指挥下的大规模作战，可以持续三个月并造成双方损失。", "晚会": "语义：晚会一般只有几个小时，不可能持续三个月，也谈不上双方损失。", "电影": "搭配：“双方损失很大”说的是交战双方，“电影”不能承担这种关系。", "午餐": "语义：午餐只是一顿饭，无法持续三个月。"}, "sentence_index": 0, "correct_answer": "战役"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战役没有统一指挥，只是几个人各自乱打了一通，十分钟就结束了。", "explanation": "这里应该用〈战斗〉。战役必须在统一指挥下进行，几个人各自乱打只能称战斗。"}, {"text": "他指挥了一只战役，取得了胜利。", "explanation": "这里应该用〈场〉。战役用“场”计量，“只”用于动物或成对器物中的一个，不能用于战役。"}, {"text": "这次战役是一场婚礼，宾客很多，大家都很开心。", "explanation": "这里应该用〈婚礼〉。战役是有战略目的的大规模作战，婚礼不能称为战役。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战役", "is_correct": true, "explanation": "正确。“指挥过三次大型战役”指将军指挥的军事作战，与“指挥”相配。"}, {"text": "舞会", "is_correct": false, "explanation": "搭配：“指挥”多用于军队或乐队，不能说指挥过三次舞会。"}, {"text": "论文", "is_correct": false, "explanation": "语义：论文是写成的文章，不是可以被指挥的活动。"}, {"text": "火锅", "is_correct": false, "explanation": "语义：火锅是食物，不能被大型“指挥”。"}], "explanations": {"战役": "正确。“指挥过三次大型战役”指将军指挥的军事作战，与“指挥”相配。", "舞会": "搭配：“指挥”多用于军队或乐队，不能说指挥过三次舞会。", "论文": "语义：论文是写成的文章，不是可以被指挥的活动。", "火锅": "语义：火锅是食物，不能被大型“指挥”。"}, "sentence_index": 6, "correct_answer": "战役"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "边境上的战役只是两方士兵互相瞪眼，没人开枪。", "explanation": "这里应该用〈对峙〉。战役是有战略目的的大规模作战，双方互相瞪眼的僵持应称对峙。"}, {"text": "他们打赢了一块战役，大家都很高兴。", "explanation": "这里应该用〈场〉。战役用“场”计量，“块”用于块状的东西，不能用于战役。"}, {"text": "这次战役只是几个人在院子里排练，动用的人不到十个。", "explanation": "这里应该用〈演练〉。战役须是大规模的实际作战，动用不到十人、只为排练的应称演练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只战役打了三天三夜。", "corrected_sentence": "这场战役打了三天三夜。", "error_description": "“战役”的量词应用“场”，不能用“只”。错误形式：这只战役；正确形式：这场战役。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那只战役中负了伤。", "corrected_sentence": "他在那场战役中负了伤。", "error_description": "“战役”的量词应用“场”，不能用“只”。错误形式：那只战役；正确形式：那场战役。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
