INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人、事物、机构所具有的特定职责和功能。", "primary_collocate": null, "pronunciation": "zhí néng", "ipa": "ʈʂɨ˧˥ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个部门的主要职能是管理资金。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要认真履行自己的职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的职能是治病救人。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把三个部门的职能分清楚了。", "target_word": "职能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务部的职能和人事部不同。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校除了教学，还有许多社会职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个机构的职能有些重复。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不清楚自己在团队中的职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改革以后，这个单位的职能变了。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院行使着审判的职能。", "target_word": "职能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "职能部门", "label": "复合"}, {"form": "職能", "label": "繁体"}], "register": "书面", "sense_fingerprint": "职能：人、事物、机构所具有的特定职责和功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职能", "is_correct": true, "explanation": "正确：“职能”指部门承担的职责和作用，与“这个部门的主要……是管理资金”相合。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”指人员的数量，不能说成“是管理资金”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不适合书面语的部门职责说明。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只描述人的身体特征，不能用来说部门。"}], "explanations": {"职能": "正确：“职能”指部门承担的职责和作用，与“这个部门的主要……是管理资金”相合。", "人数": "语义：“人数”指人员的数量，不能说成“是管理资金”。", "玩意儿": "语域：“玩意儿”是口语说法，不适合书面语的部门职责说明。", "身高": "体貌：“身高”只描述人的身体特征，不能用来说部门。"}, "sentence_index": 0, "correct_answer": "职能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被任命为部长，职能很高。", "explanation": "这里应该用〈职位〉。“职能”指职责和功能，不分高低；说职位高应用“职位”。"}, {"text": "他的职能是医生。", "explanation": "这里应该用〈职业〉。说一个人做什么工作要用“职业”，“职能”不指人的身份。"}, {"text": "他的职能是硕士。", "explanation": "这里应该用〈学历〉。硕士是学历，不是职能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职能", "is_correct": true, "explanation": "正确：“职能”指机构的职责和作用，与“这两个机构的……有些重复”相合。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说的是人或动物的身体，机构没有体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能说两个机构的年龄重复。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语，用来称呼人，不能用来指机构。"}], "explanations": {"职能": "正确：“职能”指机构的职责和作用，与“这两个机构的……有些重复”相合。", "体重": "体貌：“体重”说的是人或动物的身体，机构没有体重。", "年龄": "语义：“年龄”指岁数，不能说两个机构的年龄重复。", "哥们儿": "语域：“哥们儿”是口语，用来称呼人，不能用来指机构。"}, "sentence_index": 6, "correct_answer": "职能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他评上了高级职能。", "explanation": "这里应该用〈职称〉。评上的是专业技术职称，“职能”指职责和功能，不能说“评上”。"}, {"text": "他取得了律师职能。", "explanation": "这里应该用〈资格〉。取得的是执业资格，“职能”不能用来指资格。"}, {"text": "他的职能很好听。", "explanation": "这里应该用〈名字〉。好听的是名字，“职能”指职责和功能，不是人的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个部门有一台重要的职能，就是管理资金。", "corrected_sentence": "这个部门有一项重要的职能，就是管理资金。", "error_description": "量词错误：“职能”是抽象名词，计量用“项”；“台”是机器的量词，不能修饰“职能”。正确说法是“一项重要的职能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物馆除了展览，还有一朵重要的社会职能。", "corrected_sentence": "博物馆除了展览，还有一项重要的社会职能。", "error_description": "量词错误：“朵”用于花、云等，不能修饰“职能”。正确说法是“一项重要的社会职能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
