INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尽力保护，使不受损害或侵犯。", "primary_collocate": null, "pronunciation": "shǒu hù", "ipa": "ʂou˨˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "守护", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "战士们日夜守护着边境的安全。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们世世代代守护着这片森林。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直守护着祖先留下的老房子。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生日夜守护着病重的孩子。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用一生守护了这座古庙。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要守护好自己的家园。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员守护着图书馆里的古书。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古队员日夜守护着刚出土的文物。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员守护着国门的安全。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "守护了", "label": "体标（了）"}, {"form": "守护着", "label": "体标（着）"}, {"form": "守护过", "label": "体标（过）"}, {"form": "守护神", "label": "复合词"}, {"form": "守護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "守护：尽力保护某物或某地，使其不受损害或侵犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "守护", "is_correct": true, "explanation": "正确：“守护”指尽力保护，使不受损害，与“治疗者……生命线”相合。"}, {"text": "歼灭", "is_correct": false, "explanation": "语义：“歼灭”是消灭敌人，与治疗者保护生命线的职能相反。"}, {"text": "吃掉", "is_correct": false, "explanation": "语域：“吃掉”是口语，且意思是消灭，不适合这段书面的游戏说明。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”是心理动词，不能直接接“生命线”这类需要保护的对象。"}], "explanations": {"守护": "正确：“守护”指尽力保护，使不受损害，与“治疗者……生命线”相合。", "歼灭": "语义：“歼灭”是消灭敌人，与治疗者保护生命线的职能相反。", "吃掉": "语域：“吃掉”是口语，且意思是消灭，不适合这段书面的游戏说明。", "讨厌": "搭配：“讨厌”是心理动词，不能直接接“生命线”这类需要保护的对象。"}, "sentence_index": 0, "correct_answer": "守护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在网上守护了一部电影。", "explanation": "这里应该用〈下载〉。下载是把网上的内容存到自己的设备上，“守护”是保护使不受损害，不能用于存取内容。"}, {"text": "同学们都在守护他的口音，一直拿它开玩笑。", "explanation": "这里应该用〈取笑〉。拿口音开玩笑是取笑，“守护”是保护使不受损害，与之矛盾。"}, {"text": "他守护了那碗面，很快就吃完了。", "explanation": "这里应该用〈吃〉。“守护”是保护使不受损害，不表示吃掉东西，与“吃完”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "守护", "is_correct": true, "explanation": "正确：“守护好自己的家园”指好好保护家园，与语境相合。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“家园”。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖掉，与“要……好自己的家园”的保护之意相反。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语，不适合“守护家园”这种书面表达。"}], "explanations": {"守护": "正确：“守护好自己的家园”指好好保护家园，与语境相合。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“家园”。", "出售": "语义：“出售”是卖掉，与“要……好自己的家园”的保护之意相反。", "搞定": "语域：“搞定”是口语，不适合“守护家园”这种书面表达。"}, "sentence_index": 6, "correct_answer": "守护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于守护了那个难题。", "explanation": "这里应该用〈解决〉。难题要解决，不能说“守护”。"}, {"text": "他守护这种刺耳的噪音。", "explanation": "这里应该用〈讨厌〉。讨厌刺耳的噪音，“守护”是保护使不受损害，不能用于噪音。"}, {"text": "他不小心守护了钥匙。", "explanation": "这里应该用〈丢失〉。钥匙丢了是“丢失”，“守护”指保护，不能表示丢掉东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把年幼的弟弟守护了好。", "corrected_sentence": "他把年幼的弟弟守护好了。", "error_description": "补语位置错误：“守护好”中的“好”是结果补语，“了”应放在句尾，说“守护好了”，不能说“守护了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们日夜守护着了边境。", "corrected_sentence": "士兵们日夜守护着边境。", "error_description": "体标错误：“守护”后只用“着”表示持续，不能同时加“了”，“着了”重复体标。正确说法是“日夜守护着边境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
