INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻维持生存或发展的最根本的要素或途径。", "primary_collocate": null, "pronunciation": "shēng mìng xiàn", "ipa": "ʂɤŋ˥ miŋ˥˩ ɕi̯ɛn˥˩", "syllable_count": 3, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "生命线", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水是沙漠里的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路是山区的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "质量是一家工厂的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对公司来说，客户就是生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络是远程教育的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，土地就是他们的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河是整个城市的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚信是做生意的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鲜是这家菜店的生命线。", "target_word": "生命线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条生命线", "label": "量词（条）"}, {"form": "生命線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生命线：比喻事物生存或发展所依靠的最根本的要素或途径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不是需要守护的对象，“守护时间”搭配生硬，与治疗者守住根本要素的语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，治疗者无法守护它。"}, {"text": "生命线", "is_correct": true, "explanation": "“生命线”比喻治疗者必须守住的根本要素，与“守护”搭配自然，符合句中的职能分化语境。"}, {"text": "台词", "is_correct": false, "explanation": "语义：台词是说出的话，不能作为守护的对象。"}], "explanations": {"时间": "搭配：“时间”不是需要守护的对象，“守护时间”搭配生硬，与治疗者守住根本要素的语境不符。", "天气": "语义：天气是自然现象，治疗者无法守护它。", "生命线": "“生命线”比喻治疗者必须守住的根本要素，与“守护”搭配自然，符合句中的职能分化语境。", "台词": "语义：台词是说出的话，不能作为守护的对象。"}, "sentence_index": 0, "correct_answer": "生命线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这株小草的生命线很强。", "explanation": "这里应该用〈生命力〉。“生命力”指生物生存、繁殖的能力，可以说“很强”；“生命线”指维持发展的根本要素，不能用来形容强弱。"}, {"text": "春天一到，田野里到处是生命线。", "explanation": "这里应该用〈生机〉。“到处是生机”指充满生命的活力，“生命线”不指活力或景象。"}, {"text": "夕阳渐渐沉到了远方的生命线下。", "explanation": "这里应该用〈地平线〉。夕阳沉没在地平线下，“生命线”不是远处的界线或景观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，土地不能被说成手机。"}, {"text": "牙齿", "is_correct": false, "explanation": "体貌：牙齿是身体部位，不能用来比喻农民赖以生存的土地。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，与农民谈土地的语境不符。"}, {"text": "生命线", "is_correct": true, "explanation": "“生命线”比喻土地对农民的根本作用，符合句子的语境。"}], "explanations": {"手机": "语义：手机是通讯工具，土地不能被说成手机。", "牙齿": "体貌：牙齿是身体部位，不能用来比喻农民赖以生存的土地。", "课本": "语义：课本是学习用书，与农民谈土地的语境不符。", "生命线": "“生命线”比喻土地对农民的根本作用，符合句子的语境。"}, "sentence_index": 6, "correct_answer": "生命线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的生命线是十年。", "explanation": "这里应该用〈寿命〉。“生命线”不指使用年限，说机器可用的年限要用〈寿命〉。"}, {"text": "他为了救战友，差点搭上生命线。", "explanation": "这里应该用〈性命〉。“搭上”后接的是人的性命，“生命线”不能指性命本身。"}, {"text": "这幅画的生命线很流畅。", "explanation": "这里应该用〈线条〉。“流畅”形容线条，“生命线”指维持生存的根本要素，不指画中的线条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条铁路是这座城市的一只生命线。", "corrected_sentence": "这条铁路是这座城市的一条生命线。", "error_description": "量词错误：“生命线”的量词应为“条”，不能用“只”（“只”多用于动物或成对的物品）。错误形式为“一只生命线”，正确形式为“一条生命线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对这家人来说，这口井就是他们生命线。", "corrected_sentence": "对这家人来说，这口井就是他们的生命线。", "error_description": "“的”遗漏：代词“他们”作定语修饰“生命线”时要加“的”，应为“他们的生命线”，不能说“他们生命线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
