INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坦克是一种带有履带和装甲的军用战斗车辆，主要用于在战场上直接与敌人交火。", "primary_collocate": null, "pronunciation": "tǎn kè", "ipa": "tʰan˨˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "一辆坦克慢慢开过了桥。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克有厚厚的铁甲和履带。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆门口停着一辆旧坦克。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克开进了小城的广场。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵坐在坦克里等命令。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克的炮口对着前方。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆坦克在雪地里也能走。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争电影里有很多坦克。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克过河时需要一座结实的桥。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上了公园里的那辆坦克。", "target_word": "坦克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "坦克兵", "label": "复合词"}, {"form": "坦克部队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "坦克：带履带和装甲、在战场上直接作战的军用车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8034b76-f125-4129-9131-77cfab88eaca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手推车", "is_correct": false, "explanation": "搭配：手推车靠人推，不能说“开”过桥。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书本的袋子，不能作为慢慢开过桥的车辆。"}, {"text": "坦克", "is_correct": true, "explanation": "“坦克”是带履带和装甲的军用车辆，能够“慢慢开过了桥”。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是盛水的器皿，不能作为开过桥的车辆。"}], "explanations": {"手推车": "搭配：手推车靠人推，不能说“开”过桥。", "书包": "语义：书包是装书本的袋子，不能作为慢慢开过桥的车辆。", "坦克": "“坦克”是带履带和装甲的军用车辆，能够“慢慢开过了桥”。", "茶杯": "语义：茶杯是盛水的器皿，不能作为开过桥的车辆。"}, "sentence_index": 0, "correct_answer": "坦克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民开着坦克去田里干活。", "explanation": "这里应该用〈拖拉机〉。坦克是军用战斗车辆，不用于田间劳动，下地干活开的是拖拉机。"}, {"text": "坦克把货物吊上了楼。", "explanation": "这里应该用〈吊车〉。吊货上楼靠吊车，坦克没有起吊装置。"}, {"text": "赛车手驾驶坦克冲过了终点。", "explanation": "这里应该用〈赛车〉。赛车手驾驶的是赛车，坦克是履带式军用车辆，不能参赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能在雪地里自己行走。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不能在雪地里自己行走。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是家用电器，不能在雪地里自己行走。"}, {"text": "坦克", "is_correct": true, "explanation": "“坦克”带履带，能在雪地等复杂地形上行驶，符合“也能走”。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不能在雪地里自己行走。", "书桌": "语义：书桌是家具，不能在雪地里自己行走。", "洗衣机": "语义：洗衣机是家用电器，不能在雪地里自己行走。", "坦克": "“坦克”带履带，能在雪地等复杂地形上行驶，符合“也能走”。"}, "sentence_index": 6, "correct_answer": "坦克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵驾驶着坦克起飞了。", "explanation": "这里应该用〈飞机〉。坦克在陆地上靠履带行驶，不能起飞。"}, {"text": "老人推着坦克去买菜。", "explanation": "这里应该用〈手推车〉。坦克是军用车辆，不是买菜时推的车。"}, {"text": "坦克把病人送进了急诊室。", "explanation": "这里应该用〈救护车〉。坦克是军用车辆，不用来送病人，送病人进急诊室要用救护车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只坦克在演习中冲过了山坡。", "corrected_sentence": "这辆坦克在演习中冲过了山坡。", "error_description": "量词错误：“坦克”的量词应为“辆”，不能用“只”。错误形式为“这只坦克”，正确形式为“这辆坦克”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坦克冲了过山坡。", "corrected_sentence": "坦克冲过了山坡。", "error_description": "“了”与“过”的位置错误：“冲过”的“过”是补语，“了”表完成，应为“冲过了山坡”，不能说“冲了过山坡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '386cdea5-bdf8-4a73-a55f-82328e64a0c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
