INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受、承担（压力、痛苦、责任等）。", "primary_collocate": null, "pronunciation": "chéng shòu", "ipa": "tʂʰɤŋ˧˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他一个人承受着很大的压力。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重的责任，你一个人承受不了。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈默默承受了所有的痛苦。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了事，他得自己承受后果。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，她快承受不住了。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要学会承受失败带来的痛苦。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承受过很多别人想不到的苦。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息太突然，奶奶一时承受不了。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大家的批评，他只好低头承受。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，承受不了这么大的打击。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承受了", "label": "完成体"}, {"form": "承受着", "label": "持续体"}, {"form": "承受过", "label": "经历体"}, {"form": "承受力", "label": "复合词"}, {"form": "承受能力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "承受：接受并承担压力、痛苦、责任等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受并承担压力、痛苦、责任等。"}, {"text": "成熟", "is_correct": false, "explanation": "shú（第二声）与 shòu（第四声）声调不同，意思是发育完全、有经验。"}, {"text": "乘数", "is_correct": false, "explanation": "shù 与 shòu 的韵母不同（u 与 ou），意思是数学中的乘数。"}, {"text": "称手", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）、shǒu（第三声）与 shòu（第四声）声调都不同，意思是用起来顺手。"}], "explanations": {"承受": "承受：接受并承担压力、痛苦、责任等。", "成熟": "shú（第二声）与 shòu（第四声）声调不同，意思是发育完全、有经验。", "乘数": "shù 与 shòu 的韵母不同（u 与 ou），意思是数学中的乘数。", "称手": "chēng（第一声）与 chéng（第二声）、shǒu（第三声）与 shòu（第四声）声调都不同，意思是用起来顺手。"}, "sentence_index": null, "correct_answer": "承受"}, "level_3": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受并承担压力，与“一个人”“很大的压力”相合。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”是用力使物体移动，不能与“压力”搭配表示担负。"}, {"text": "散发", "is_correct": false, "explanation": "语义：“散发”指向外发出气味、光等，句意变成他在向外散发压力，与“承受”的含义不符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享用愉快的事物，与“压力”的含义相反，不能说“享受很大的压力”。"}], "explanations": {"承受": "承受：接受并承担压力，与“一个人”“很大的压力”相合。", "推": "搭配：“推”是用力使物体移动，不能与“压力”搭配表示担负。", "散发": "语义：“散发”指向外发出气味、光等，句意变成他在向外散发压力，与“承受”的含义不符。", "享受": "语义：“享受”指享用愉快的事物，与“压力”的含义相反，不能说“享受很大的压力”。"}, "sentence_index": 0, "correct_answer": "承受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承受了一块蛋糕。", "explanation": "这里应用〈得到〉。“承受”指接受压力、痛苦等不好的事，不能用于得到蛋糕这类具体的东西。"}, {"text": "老师提出的建议，他认真考虑后承受了。", "explanation": "这里应用〈接受〉。“承受”指承担压力、痛苦等不好的事，不用于接受建议。"}, {"text": "这个假期，我们好好承受了一下海边的阳光。", "explanation": "这里应用〈享受〉。“承受”只用于压力、痛苦等不好的事，不能用于享受愉快的阳光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受并承担痛苦，与“过”“很多别人想不到的苦”相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享用愉快的事物，与“苦”的含义相反。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能与“苦”搭配，不能说“打过很多苦”。"}, {"text": "赚", "is_correct": false, "explanation": "搭配：“赚”用于收入、利益，不能与“苦”搭配。"}], "explanations": {"承受": "承受：接受并承担痛苦，与“过”“很多别人想不到的苦”相合。", "享受": "语义：“享受”指享用愉快的事物，与“苦”的含义相反。", "打": "搭配：“打”不能与“苦”搭配，不能说“打过很多苦”。", "赚": "搭配：“赚”用于收入、利益，不能与“苦”搭配。"}, "sentence_index": 6, "correct_answer": "承受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他默默承受了一辆新车。", "explanation": "这里应用〈购买〉。“承受”指接受压力、痛苦等不好的事，不能用于购买汽车这类行为。"}, {"text": "他仔细承受着这座城市的夜景。", "explanation": "这里应用〈欣赏〉。“承受”的对象是压力、痛苦等，不能指欣赏美景。"}, {"text": "医生承受了受伤的工人。", "explanation": "这里应用〈慰问〉。“承受”的宾语是压力、痛苦等，不能是人，且表示承担，不表示安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她默默承受了着失业的压力。", "corrected_sentence": "她默默承受着失业的压力。", "error_description": "“承受”后不能同时用“了”和“着”。此句表示持续的状态，应使用“承受着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心理素质很好，承受了得这么大的压力。", "corrected_sentence": "他心理素质很好，承受得了这么大的压力。", "error_description": "错误：可能补语应为“V得了”，“了”不能放在“得”之前，应为“承受得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输入", "is_correct": true, "explanation": "输入：把数据或信号从外部送入设备，与“输出”构成反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存：把数据存放起来以备后用，与“输出”没有反义关系。"}, {"text": "查看", "is_correct": false, "explanation": "查看：看一看、检查，与“输出”没有反义关系。"}, {"text": "运行", "is_correct": false, "explanation": "运行：程序或设备开始工作，与“输出”没有反义关系。"}], "correct_answer": "输入", "explanations": {"输入": "输入：把数据或信号从外部送入设备，与“输出”构成反义关系。", "保存": "保存：把数据存放起来以备后用，与“输出”没有反义关系。", "查看": "查看：看一看、检查，与“输出”没有反义关系。", "运行": "运行：程序或设备开始工作，与“输出”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输入", "is_correct": true, "explanation": "输入：把数据送入设备，与“输出”构成反义关系。"}, {"text": "删除", "is_correct": false, "explanation": "删除：去掉已有的数据，与“输出”没有反义关系。"}, {"text": "备份", "is_correct": false, "explanation": "备份：复制一份数据以防丢失，与“输出”没有反义关系。"}, {"text": "更新", "is_correct": false, "explanation": "更新：换成新的内容或版本，与“输出”没有反义关系。"}], "correct_answer": "输入", "explanations": {"输入": "输入：把数据送入设备，与“输出”构成反义关系。", "删除": "删除：去掉已有的数据，与“输出”没有反义关系。", "备份": "备份：复制一份数据以防丢失，与“输出”没有反义关系。", "更新": "更新：换成新的内容或版本，与“输出”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从内部送到外部，特指计算机向外发送数据或信号。", "primary_collocate": null, "pronunciation": "shū chū", "ipa": "ʂu˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "虚拟世界中的声望，由持续的行为输出而非既定身份授予。", "target_word": "输出", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "电脑把结果输出到屏幕上。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器每天输出很多数据。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印机不能输出这个文件。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序运行完以后，会输出一个数字。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份表格输出成文件。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音从耳机输出，旁边的人听不到。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件输出的图片非常清楚。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统出了问题，没有输出任何结果。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先输入名字，电脑再输出成绩。", "target_word": "输出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输出了", "label": "完成体"}, {"form": "输出过", "label": "经历体"}, {"form": "输出量", "label": "复合词"}, {"form": "输出设备", "label": "复合词"}, {"form": "輸出", "label": "繁体"}], "register": "中性", "sense_fingerprint": "输出：从内部向外送出，尤指计算机发送数据或信号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输出", "is_correct": true, "explanation": "正确：“输出”指把行为的成果送出，与“行为”搭配，符合游戏语境。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是人的悠闲动作，不能作为声望的来源，句子说不通。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与“声望”的正面含义相反，不能作为声望的来源。"}, {"text": "提出", "is_correct": false, "explanation": "搭配：“提出”后接意见、问题，不说“行为提出”，句中搭配不通。"}], "explanations": {"输出": "正确：“输出”指把行为的成果送出，与“行为”搭配，符合游戏语境。", "散步": "语义：“散步”是人的悠闲动作，不能作为声望的来源，句子说不通。", "撒谎": "语义：“撒谎”与“声望”的正面含义相反，不能作为声望的来源。", "提出": "搭配：“提出”后接意见、问题，不说“行为提出”，句中搭配不通。"}, "sentence_index": 0, "correct_answer": "输出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先把名字输出电脑。", "explanation": "这里应该用〈输入〉。输出是从电脑向外送出，把名字送进电脑要用输入。"}, {"text": "这次比赛我们输出了两局。", "explanation": "这里应该用〈输〉。输出表示从内部送到外部，比赛失败要用输（输了两局），二者不能互换。"}, {"text": "秘书把客户资料输出了电脑。", "explanation": "这里应该用〈录入〉。输出指从电脑向外发送，把资料录进电脑要用录入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输出", "is_correct": true, "explanation": "正确：“输出”指声音从耳机送出，与“声音”“耳机”搭配自然。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指降温，不能用来描述声音的发出。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼、成果，不说“收割声音”。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”指物体着火，声音不会燃烧，句子说不通。"}], "explanations": {"输出": "正确：“输出”指声音从耳机送出，与“声音”“耳机”搭配自然。", "冷却": "语义：“冷却”指降温，不能用来描述声音的发出。", "收割": "搭配：“收割”用于庄稼、成果，不说“收割声音”。", "燃烧": "语义：“燃烧”指物体着火，声音不会燃烧，句子说不通。"}, "sentence_index": 6, "correct_answer": "输出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为这次成功输出了很多代价。", "explanation": "这里应该用〈付出〉。输出用于数据、信号等，不用于代价、精力的投入。"}, {"text": "他的眼神里输出了一丝悲伤。", "explanation": "这里应该用〈流露〉。输出指从内部送到外部，多用于数据、信号；表达情绪要用流露，「输出悲伤」不成立。"}, {"text": "我把生日礼物输出给了妈妈。", "explanation": "这里应该用〈送〉。输出用于数据、信号，不用于礼物等实物的赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "程序把数据输出文件里。", "corrected_sentence": "程序把数据输出到文件里。", "error_description": "错误：“输出”后面缺少介词“到”，表示送往的地点要说“输出到……”。应为“程序把数据输出到文件里。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑把图片输出了来。", "corrected_sentence": "电脑把图片输出来了。", "error_description": "错误：趋向补语“来”要紧跟在动词“输出”之后，“了”放在句末，应为“电脑把图片输出来了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
