INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消灭敌人。", "primary_collocate": null, "pronunciation": "jiān dí", "ipa": "tɕjɛn˥ ti˧˥", "syllable_count": 2, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "歼敌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们的任务是歼敌，不是撤退。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们勇敢地冲上去歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次战斗，我军歼敌三千人。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人歼敌五名。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里，输出者的工作就是歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老将军说，要想办法快点歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士用机枪歼敌，保护了村子。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以前，部队必须歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在战斗中歼敌二十人。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "作战中消灭敌人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歼敌", "is_correct": true, "explanation": "正确：“歼敌”指消灭敌人，与“输出者”的职责和“精准”搭配。"}, {"text": "守护", "is_correct": false, "explanation": "语义：“守护”是治疗者的职责（句中已有“治疗者守护生命线”），输出者不应守护，语境不通。"}, {"text": "承受", "is_correct": false, "explanation": "语义：“承受”是坦克的职责（句中已有“坦克承受攻击”），与输出者的职责冲突。"}, {"text": "统筹", "is_correct": false, "explanation": "搭配：“统筹”的对象是全局、计划，句末已有“统筹全局”，此处重复且不搭配。"}], "explanations": {"歼敌": "正确：“歼敌”指消灭敌人，与“输出者”的职责和“精准”搭配。", "守护": "语义：“守护”是治疗者的职责（句中已有“治疗者守护生命线”），输出者不应守护，语境不通。", "承受": "语义：“承受”是坦克的职责（句中已有“坦克承受攻击”），与输出者的职责冲突。", "统筹": "搭配：“统筹”的对象是全局、计划，句末已有“统筹全局”，此处重复且不搭配。"}, "sentence_index": 0, "correct_answer": "歼敌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生终于歼敌了病毒。", "explanation": "这里应该用〈消灭〉。歼敌专指消灭敌人，病毒不是敌人，不能用“歼敌”。"}, {"text": "消防员歼敌了被困的三千名居民。", "explanation": "这里应该用〈救援〉。歼敌的对象只能是敌人，不能用于救出被困的居民。"}, {"text": "农民歼敌了一头猪。", "explanation": "这里应该用〈杀〉。歼敌专指消灭敌人，不用于宰杀牲畜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歼敌", "is_correct": true, "explanation": "正确：“歼敌”指消灭敌人，与“老将军”的作战语境相符。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与“快点”的意思相矛盾，句子说不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与作战语境不符，老将军不会这样吩咐。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业、试卷，与作战语境不符。"}], "explanations": {"歼敌": "正确：“歼敌”指消灭敌人，与“老将军”的作战语境相符。", "迟到": "语义：“迟到”与“快点”的意思相矛盾，句子说不通。", "哭": "语义：“哭”与作战语境不符，老将军不会这样吩咐。", "批改": "搭配：“批改”的对象是作业、试卷，与作战语境不符。"}, "sentence_index": 6, "correct_answer": "歼敌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把信歼敌给了朋友。", "explanation": "这里应该用〈送〉。歼敌只表示消灭敌人，信件是送出的物品。"}, {"text": "园丁在院子里歼敌了一棵树。", "explanation": "这里应该用〈种植〉。歼敌只能用于敌人，树木要说种植。"}, {"text": "渔夫歼敌了一条大鱼。", "explanation": "这里应该用〈捕获〉。歼敌专指消灭敌人，抓鱼要用捕获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战士们在天亮前被歼敌一百人。", "corrected_sentence": "战士们在天亮前歼敌一百人。", "error_description": "错误：“歼敌”是主动动词，不能直接加“被”构成被动句，应为“歼敌一百人”。被动的说法要用“歼灭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支小队半天内歼敌三十只。", "corrected_sentence": "这支小队半天内歼敌三十名。", "error_description": "错误：“敌”指敌人，计量应用“名”，“只”用于动物等，不能用于敌人。正确应为“歼敌三十名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
