INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责发号施令、领导或管理他人的人。", "primary_collocate": null, "pronunciation": "zhǐ huī zhě", "ipa": "tʂɻ̩˨˩ xweɪ˥ tʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "指挥者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "乐队的指挥者站在最前面。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这次行动的指挥者。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的指挥者要听大家的话。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥者举起手，大家马上停下来。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次搜救行动的指挥者是一位退役军官。", "target_word": "指挥者", "complexity_tier": "T3", "furigana": "zhè cì sōujiù xíngdòng de zhǐhuīzhě shì yí wèi tuìyì jūnguān", "sentence_source": "generated"}, {"text": "火灾现场的指挥者让大家先离开。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥者要看清全局，才能做对决定。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这个队的指挥者？", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当过指挥者，知道责任很重。", "target_word": "指挥者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位指挥者", "label": "量词"}], "register": "中性", "sense_fingerprint": "负责发号施令、带领众人行动的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa9dc1-b16c-4823-8c0d-d506d16883a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治疗者", "is_correct": false, "explanation": "语义：句中“治疗者”负责守护生命线，不能统筹全局，与前文的职能分工矛盾。"}, {"text": "指挥者", "is_correct": true, "explanation": "“指挥者”指负责统筹全局的人，与前文“职能分化”的语境相符。"}, {"text": "坦克", "is_correct": false, "explanation": "配价：“统筹全局”要求人作主语，“坦克”是器械，不能统筹。"}, {"text": "副本", "is_correct": false, "explanation": "搭配：“统筹全局”不能以“副本”作主语，副本是游戏场景。"}], "explanations": {"治疗者": "语义：句中“治疗者”负责守护生命线，不能统筹全局，与前文的职能分工矛盾。", "指挥者": "“指挥者”指负责统筹全局的人，与前文“职能分化”的语境相符。", "坦克": "配价：“统筹全局”要求人作主语，“坦克”是器械，不能统筹。", "副本": "搭配：“统筹全局”不能以“副本”作主语，副本是游戏场景。"}, "sentence_index": 0, "correct_answer": "指挥者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位指挥者开车很稳。", "explanation": "这里应该用〈司机〉。“指挥者”指发号施令、带领他人的人，不指驾驶车辆的人。"}, {"text": "这位指挥者修好了水管。", "explanation": "这里应该用〈水管工〉。“指挥者”指领导他人的人，不指修理水管的人。"}, {"text": "这位指挥者把文件译成了英文。", "explanation": "这里应该用〈翻译〉。“指挥者”指领导他人的人，不指做翻译工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不会行动，不能“让大家先离开”。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“让”的主语须是能发出指令的人，“窗户”不能作主语。"}, {"text": "指挥者", "is_correct": true, "explanation": "“指挥者”能发号施令，“让大家先离开”符合火灾现场的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能指挥人行动，与“让大家先离开”的意思不符。"}], "explanations": {"课本": "语义：课本不会行动，不能“让大家先离开”。", "窗户": "配价：“让”的主语须是能发出指令的人，“窗户”不能作主语。", "指挥者": "“指挥者”能发号施令，“让大家先离开”符合火灾现场的语境。", "天气": "语义：天气不能指挥人行动，与“让大家先离开”的意思不符。"}, "sentence_index": 6, "correct_answer": "指挥者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位指挥者每天给花浇水。", "explanation": "这里应该用〈园丁〉。“指挥者”指领导他人的人，不指浇花养护植物的人。"}, {"text": "这位指挥者每天核对账目。", "explanation": "这里应该用〈会计〉。“指挥者”指发号施令的人，不指核对账目的工作。"}, {"text": "这位指挥者做的饺子很好吃。", "explanation": "这里应该用〈厨师〉。“指挥者”指领导他人的人，不指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三位指挥者们都很有经验。", "corrected_sentence": "三位指挥者都很有经验。", "error_description": "错误：“三位”已表示数量，“指挥者”后不能再加“们”。正确：“三位指挥者都很有经验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很有经验指挥者带领大家完成了任务。", "corrected_sentence": "这位很有经验的指挥者带领大家完成了任务。", "error_description": "错误：修饰语“很有经验”与“指挥者”之间漏掉了“的”。正确：“很有经验的指挥者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4fd29c-2289-4e96-96ae-fe634b805df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
