INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "统一筹划，指全面安排和协调各方面工作。", "primary_collocate": null, "pronunciation": "tǒng chóu", "ipa": "tʰʊŋ˨˩˦ ʈʂʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "统筹", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经理全面统筹公司的工作。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长要统筹城市的交通和教育。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动由小王统筹，大家都听他的。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他统筹了整个项目的人员和资金。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长统筹着学校各个部门的工作。", "target_word": "统筹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府需要统筹各地区的发展。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她负责统筹这次会议的所有事情。", "target_word": "统筹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理把各部门的工作统筹起来。", "target_word": "统筹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要统筹城乡的发展。", "target_word": "统筹", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "统筹了", "label": "体标"}, {"form": "统筹过", "label": "体标"}, {"form": "统筹安排", "label": "复合"}, {"form": "統籌", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从全局出发，统一安排并协调各方面的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统筹", "is_correct": true, "explanation": "统筹：统一筹划，与「指挥者」「全局」搭配，符合句意。"}, {"text": "承受", "is_correct": false, "explanation": "搭配：「承受」多接压力、攻击、损失等，不能带「全局」作宾语，且句中坦克已是承受攻击。"}, {"text": "歼灭", "is_correct": false, "explanation": "语义：「歼灭」指消灭敌人，指挥者并非消灭「全局」，句中输出者「歼敌」已表达此义。"}, {"text": "攻击", "is_correct": false, "explanation": "语义：「攻击」针对敌人或目标，「指挥者攻击全局」语义不通，也与句中坦克承受攻击的角色重复。"}], "explanations": {"统筹": "统筹：统一筹划，与「指挥者」「全局」搭配，符合句意。", "承受": "搭配：「承受」多接压力、攻击、损失等，不能带「全局」作宾语，且句中坦克已是承受攻击。", "歼灭": "语义：「歼灭」指消灭敌人，指挥者并非消灭「全局」，句中输出者「歼敌」已表达此义。", "攻击": "语义：「攻击」针对敌人或目标，「指挥者攻击全局」语义不通，也与句中坦克承受攻击的角色重复。"}, "sentence_index": 0, "correct_answer": "统筹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师统筹了这次考试的成绩。", "explanation": "这里应该用〈统计〉。统计指汇总数字，统筹指统一安排工作，不用于成绩等数据。"}, {"text": "妈妈统筹了一锅汤。", "explanation": "这里应该用〈煮〉。煮指加水加热做熟食物，统筹指统一安排工作，不用于烹饪。"}, {"text": "他统筹了一根香蕉。", "explanation": "这里应该用〈吃〉。吃指把食物放进口中咽下，统筹指统一安排工作，不能用于吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统筹", "is_correct": true, "explanation": "统筹：统一安排，与「政府」「发展」搭配，符合句意。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：「阻碍」与句中「需要」的意愿相反，「政府需要阻碍发展」语义矛盾。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：「破坏」造成损害，与政府「需要」推动发展的意图相矛盾。"}, {"text": "拖延", "is_correct": false, "explanation": "搭配：「拖延」多用于时间、任务、进度，不说拖延「各地区的发展」。"}], "explanations": {"统筹": "统筹：统一安排，与「政府」「发展」搭配，符合句意。", "阻碍": "语义：「阻碍」与句中「需要」的意愿相反，「政府需要阻碍发展」语义矛盾。", "破坏": "语义：「破坏」造成损害，与政府「需要」推动发展的意图相矛盾。", "拖延": "搭配：「拖延」多用于时间、任务、进度，不说拖延「各地区的发展」。"}, "sentence_index": 6, "correct_answer": "统筹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他统筹了一幅画。", "explanation": "这里应该用〈绘制〉。绘制指画出图画，统筹指统一安排工作，不用于作画。"}, {"text": "他统筹了一块抹布。", "explanation": "这里应该用〈擦〉。擦指用布来回抹去污物，统筹指统一安排工作，不指具体的擦拭动作。"}, {"text": "他统筹了一台电脑。", "explanation": "这里应该用〈维修〉。维修指修理具体物品，统筹指统一安排工作，不用于修理机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长把全校的后勤工作统筹。", "corrected_sentence": "校长把全校的后勤工作统筹起来。", "error_description": "「统筹」在把字句中作谓语时，后面须带补语（如「起来」「好」），不能只说「把……统筹」。应改为「统筹起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他统筹了着三个部门的预算。", "corrected_sentence": "他统筹着三个部门的预算。", "error_description": "「统筹」后已用「着」表示进行中，不能再加「了」。应只用「着」，改为「统筹着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "反义：「局部」指事物的一部分，与「全局」整体局面相对，句中「影响了全局」对应的正是整体。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与「全局」所指的整体局面没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是具体的地理事物，与「全局」没有反义关系。"}, {"text": "步骤", "is_correct": false, "explanation": "语义：「步骤」指做事的先后环节，不是「全局」的反义词。"}], "correct_answer": "局部", "explanations": {"局部": "反义：「局部」指事物的一部分，与「全局」整体局面相对，句中「影响了全局」对应的正是整体。", "颜色": "语义：「颜色」与「全局」所指的整体局面没有反义关系。", "河流": "语义：「河流」是具体的地理事物，与「全局」没有反义关系。", "步骤": "语义：「步骤」指做事的先后环节，不是「全局」的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "反义：「局部」指部分范围，与「全局」相对，句中「小事」与「全局」正是一对照。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」与「全局」所指的局面没有反义关系。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：「歌曲」是艺术作品，与「全局」没有反义关系。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：「餐桌」是具体的家具，与「全局」没有反义关系。"}], "correct_answer": "局部", "explanations": {"局部": "反义：「局部」指部分范围，与「全局」相对，句中「小事」与「全局」正是一对照。", "天气": "语义：「天气」与「全局」所指的局面没有反义关系。", "歌曲": "语义：「歌曲」是艺术作品，与「全局」没有反义关系。", "餐桌": "语义：「餐桌」是具体的家具，与「全局」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指整个局面或整体范围。", "primary_collocate": null, "pronunciation": "quán jú", "ipa": "tɕʰɥɛn˧˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "在攻克高难度副本或组织大规模战役时，玩家必须进行精密的职能分化：治疗者守护生命线，坦克承受攻击，输出者精准歼敌，指挥者统筹全局。", "target_word": "全局", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好队长要看清全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只看小事，不看全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这一步棋影响了全局。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练站在场边，观察着比赛的全局。", "target_word": "全局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，要先考虑全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的一个错误，让全局都乱了。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从全局来看，这个办法最好。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这名球员能控制全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小事要服从全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "全局观", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情或比赛的整个局面、整体范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全局", "is_correct": true, "explanation": "全局：整体局面，是「统筹」的对象，句意通顺。"}, {"text": "生命线", "is_correct": false, "explanation": "搭配：「统筹」的对象是工作、事务，不说统筹「生命线」，且句中「守护生命线」已是另一角色的职能。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「统筹」的对象是工作、事务、资源，不说统筹「颜色」。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：「统筹」指安排工作，「统筹敌人」与句中「输出者精准歼敌」的分工矛盾。"}], "explanations": {"全局": "全局：整体局面，是「统筹」的对象，句意通顺。", "生命线": "搭配：「统筹」的对象是工作、事务，不说统筹「生命线」，且句中「守护生命线」已是另一角色的职能。", "颜色": "搭配：「统筹」的对象是工作、事务、资源，不说统筹「颜色」。", "敌人": "语义：「统筹」指安排工作，「统筹敌人」与句中「输出者精准歼敌」的分工矛盾。"}, "sentence_index": 0, "correct_answer": "全局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全局同学都来了。", "explanation": "这里应该用〈全部〉。全部指所有的人或物，全局指整个局面，不能用来修饰人。"}, {"text": "他全局都湿了。", "explanation": "这里应该用〈全身〉。全身指从头到脚，全局指整个局面或整体范围，不能指人的身体。"}, {"text": "我买了全局的西瓜。", "explanation": "这里应该用〈整个〉。整个可修饰具体事物表示全部，全局指抽象的整体局面，不能用来修饰西瓜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全局", "is_correct": true, "explanation": "全局：整体局面，与「错误」造成的「乱」相合，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「乱」多用于局面、秩序、计划等，「体重乱了」搭配不当。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不会因一个错误而乱，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不受人的错误影响而「乱」，与句中的因果关系矛盾。"}], "explanations": {"全局": "全局：整体局面，与「错误」造成的「乱」相合，符合句意。", "体重": "搭配：「乱」多用于局面、秩序、计划等，「体重乱了」搭配不当。", "生日": "语义：生日不会因一个错误而乱，句意不通。", "天气": "语义：天气不受人的错误影响而「乱」，与句中的因果关系矛盾。"}, "sentence_index": 6, "correct_answer": "全局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全局观众都站起来了。", "explanation": "这里应该用〈全场〉。全场指在场的全部人，全局指整个局面，不指观众。"}, {"text": "他全局支持我的决定。", "explanation": "这里应该用〈全力〉。全力是副词，表示用尽力量，全局是名词，不能作状语。"}, {"text": "全局人民都很关心这件事。", "explanation": "这里应该用〈全国〉。全国指整个国家，全局指整体局面，不指人民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一决定关系很全局。", "corrected_sentence": "这一决定关系全局。", "error_description": "「全局」是名词，不能受程度副词「很」修饰；去掉「很」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事关系很全局。", "corrected_sentence": "这件事关系全局。", "error_description": "「全局」是名词，不能受程度副词「很」修饰，应去掉「很」，说「关系全局」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
