INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11984, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示把数量合在一起计算，相当于“总共”，用于总括全部数量。", "primary_collocate": null, "pronunciation": "gòng", "ipa": "kʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我家共有五口人。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书共十章。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个星期共有七天。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班共有二十八个学生。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买苹果和香蕉共花了三十块。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛共来了十个队。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从北京到上海，我们共坐了五个小时的车。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学校共有两千个学生。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三个月我共学了三百个汉字。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这个月共借了五本书。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一共", "label": "复合"}, {"form": "总共", "label": "复合"}, {"form": "共计", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，把数量合在一起总括，相当于“总共”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共", "is_correct": true, "explanation": "共（gòng）：副词，表示总计，“我家共有五口人”中指全家加起来的总数。"}, {"text": "工", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是工作。"}, {"text": "公", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是公共、公平。"}, {"text": "功", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是功劳、成功。"}, {"text": "更", "is_correct": false, "explanation": "gèng 与 gòng 韵母不同（eng 与 ong），意思是更加。"}], "explanations": {"共": "共（gòng）：副词，表示总计，“我家共有五口人”中指全家加起来的总数。", "工": "gōng（第一声）与 gòng（第四声）声调不同，意思是工作。", "公": "gōng（第一声）与 gòng（第四声）声调不同，意思是公共、公平。", "功": "gōng（第一声）与 gòng（第四声）声调不同，意思是功劳、成功。", "更": "gèng 与 gòng 韵母不同（eng 与 ong），意思是更加。"}, "sentence_index": null, "correct_answer": "共"}, "level_3": {"options": [{"text": "共", "is_correct": true, "explanation": "共：表示总括，全家加起来一共五口人，符合句意。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样、并列，句子成了“我家也有五口人”，没有总括全部的意思。"}, {"text": "各", "is_correct": false, "explanation": "语义：「各」指分别、每个，需要多个主体；「我家」是一个整体，不能说「各有五口人」。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”要求复数的所有者，“我家”作为一个整体不能说“都有”。"}], "explanations": {"共": "共：表示总括，全家加起来一共五口人，符合句意。", "也": "语义：“也”表示同样、并列，句子成了“我家也有五口人”，没有总括全部的意思。", "各": "语义：「各」指分别、每个，需要多个主体；「我家」是一个整体，不能说「各有五口人」。", "都": "搭配：“都”要求复数的所有者，“我家”作为一个整体不能说“都有”。"}, "sentence_index": 0, "correct_answer": "共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人共去了北京。", "explanation": "这里的〈共〉表示“一起”，要求几个人共同做同一件事，句中只有“我一个人”，与该义项矛盾。"}, {"text": "他共出生在北京。", "explanation": "这里的〈共〉表示“一起”，而“出生”是个人只发生一次的事，不能与他人一起完成。"}, {"text": "他们三人各自共买了一台电脑。", "explanation": "这里的〈共〉表示“一起”，与“各自”（分别、单独）相矛盾，不能说各自一起买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11984, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "共", "is_correct": true, "explanation": "共（gòng）：副词，表示总计，与听到的音相符。"}, {"text": "控", "is_correct": false, "explanation": "k 与 g 声母不同（kòng 与 gòng），意思是控制。"}, {"text": "攻", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是攻打。"}, {"text": "杠", "is_correct": false, "explanation": "ong 与 ang 韵母不同（gàng 与 gòng），意思是杠杆。"}], "explanations": {"共": "共（gòng）：副词，表示总计，与听到的音相符。", "控": "k 与 g 声母不同（kòng 与 gòng），意思是控制。", "攻": "gōng（第一声）与 gòng（第四声）声调不同，意思是攻打。", "杠": "ong 与 ang 韵母不同（gàng 与 gòng），意思是杠杆。"}, "sentence_index": null, "correct_answer": "共"}, "level_3": {"options": [{"text": "共", "is_correct": true, "explanation": "共：表示总括或一起，此处指几人一起坐了五个小时的车，符合句意。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：“差点”后接未发生的动作，不能与“坐了”这类已经完成的动作搭配。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”表示徒劳，句中没有白费的意思。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有前后对比的语境。"}], "explanations": {"共": "共：表示总括或一起，此处指几人一起坐了五个小时的车，符合句意。", "差点": "搭配：“差点”后接未发生的动作，不能与“坐了”这类已经完成的动作搭配。", "白": "语义：“白”表示徒劳，句中没有白费的意思。", "却": "语义：“却”表示转折，句中没有前后对比的语境。"}, "sentence_index": 6, "correct_answer": "共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们轮流共用一台电脑。", "explanation": "这里的〈共〉表示“一起”，与“轮流”（先后交替）相矛盾，轮流使用就不能说共用。"}, {"text": "他们分别共去了北京。", "explanation": "这里的〈共〉表示“一起”，与“分别”（各自）相矛盾，分别去不能说共去。"}, {"text": "他独自共完成了任务。", "explanation": "这里的〈共〉表示“一起”，与“独自”（一个人）相矛盾，一个人完成不能说共同完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本字典有共三千个词。", "corrected_sentence": "这本字典共有三千个词。", "error_description": "错误在“共”的位置。“共”是副词，应放在“有”前，说“共有”，不能放在“有”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班共同有三十个学生。", "corrected_sentence": "这个班共有三十个学生。", "error_description": "错误在于在“共”后多加了“同”。“共同”表示一起做某事，不表示总数；表示总人数应说“共有”，不能说“共同有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
