INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11987, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使两个或多个目标、想法、标准等抽象事物保持一致。", "primary_collocate": null, "pronunciation": "duì qí", "ipa": "tweɪ˥˩ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这一过程要求实时沟通、风险共担与目标对齐，其组织复杂度堪比现实中的项目管理。", "target_word": "对齐", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "开会前，我们先对齐一下目标。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部门的计划还没有对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想让大家对齐想法再做决定。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目开始前，团队要对齐时间表。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对齐了需求，就可以开始写了。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和同事先对齐了口径，才发给客户。", "target_word": "对齐", "complexity_tier": "T3", "furigana": "tā hé tóngshì xiān duìqí le kǒujìng, cái fā gěi kèhù.", "sentence_source": "generated"}, {"text": "买房前，我和家人对齐过预算。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把大家的标准对齐，再比较结果。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目标不对齐，工作就容易出错。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对齐了", "label": "完成体"}, {"form": "对齐过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使目标、想法、标准等抽象事物保持一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对齐", "is_correct": true, "explanation": "对齐：使多方的目标保持一致，与前文“风险共担”的协作语境相符。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与前文“风险共担”的协作义相反，不能与“共担”同时成立。"}, {"text": "偏离", "is_correct": false, "explanation": "语义：“偏离”指偏离目标，与“目标对齐”的句意相反。"}, {"text": "瞄准", "is_correct": false, "explanation": "搭配：“瞄准”直接接目标，要说“瞄准目标”，不能说“与目标瞄准”。"}], "explanations": {"对齐": "对齐：使多方的目标保持一致，与前文“风险共担”的协作语境相符。", "分开": "语义：“分开”与前文“风险共担”的协作义相反，不能与“共担”同时成立。", "偏离": "语义：“偏离”指偏离目标，与“目标对齐”的句意相反。", "瞄准": "搭配：“瞄准”直接接目标，要说“瞄准目标”，不能说“与目标瞄准”。"}, "sentence_index": 0, "correct_answer": "对齐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对齐了那场雨。", "explanation": "这里应该用〈淋〉。淋指被雨水浇到，“对齐”指使多个想法、标准或计划保持一致，不能用于“雨”。"}, {"text": "我们对齐了昨天的天气。", "explanation": "这里的〈对齐〉指使多个事物或标准保持一致，“昨天的天气”不能与他人或标准对齐，应说〈记录〉。"}, {"text": "我对齐了那个笑话。", "explanation": "这里应该用〈讲〉。讲指说出或叙述，“对齐”指使多方的想法或标准保持一致，不用于讲笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对齐", "is_correct": true, "explanation": "对齐：使口径一致，才能发给客户，符合“先……才……”的句意。"}, {"text": "泄露", "is_correct": false, "explanation": "语义：“泄露”指不该说出去的内容被说出，与“先对齐口径”的协调义不符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“发给客户”的交付语境相反，口径不能隐藏后再发。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”后接文件、内容，“口径”是抽象标准，不能说“删除口径”。"}], "explanations": {"对齐": "对齐：使口径一致，才能发给客户，符合“先……才……”的句意。", "泄露": "语义：“泄露”指不该说出去的内容被说出，与“先对齐口径”的协调义不符。", "隐藏": "语义：“隐藏”与“发给客户”的交付语境相反，口径不能隐藏后再发。", "删除": "搭配：“删除”后接文件、内容，“口径”是抽象标准，不能说“删除口径”。"}, "sentence_index": 6, "correct_answer": "对齐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对齐了那个晚上。", "explanation": "这里的〈对齐〉指使多个事物或标准保持一致，“那个晚上”不能对齐，应说〈度过〉。"}, {"text": "老师对齐了她。", "explanation": "对齐的对象是想法、标准，不能用于指人，这里应说〈表扬〉或〈帮助〉。"}, {"text": "她对齐了那场电影。", "explanation": "这里应该用〈看〉。看指用眼睛接收影像，“对齐”指使多个想法、标准或计划保持一致，不用于观看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们没对齐了预算，才签了合同。", "corrected_sentence": "他们对齐了预算，才签了合同。", "error_description": "否定句中不能同时用「没」和「了」；「没对齐了」不成立，应去掉「没」，说「对齐了预算」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把对齐需求，再开始写。", "corrected_sentence": "我们先对齐需求，再开始写。", "error_description": "错误在于把“先”误写成“把”。“把”引出处置对象，此处不需要；“对齐需求”应改为“先对齐需求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
