INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或系统的复杂程度。", "primary_collocate": null, "pronunciation": "fù zá dù", "ipa": "fu˥˩ tsa˧˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这一过程要求实时沟通、风险共担与目标对齐，其组织复杂度堪比现实中的项目管理。", "target_word": "复杂度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个系统的复杂度很高。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件越大，复杂度就越高。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想降低流程的复杂度。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的复杂度超过了我的想象。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师先评估项目的复杂度，再定计划。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规则太多，会增加管理的复杂度。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司制度的复杂度太高，新员工看不懂。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市地铁网络的复杂度让游客头疼。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代码的复杂度低，别人才容易看懂。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "復雜度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "系统、流程、组织等事物的复杂程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复杂度", "is_correct": true, "explanation": "正确：“复杂度”指组织的繁复程度，可以与“项目管理”相比。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”说快慢，不能与“项目管理”比较繁复程度。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“组织”不与“价格”搭配，价格也无法堪比项目管理。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”说冷热，与组织的繁复无关。"}], "explanations": {"复杂度": "正确：“复杂度”指组织的繁复程度，可以与“项目管理”相比。", "速度": "语义：“速度”说快慢，不能与“项目管理”比较繁复程度。", "价格": "搭配：“组织”不与“价格”搭配，价格也无法堪比项目管理。", "温度": "语义：“温度”说冷热，与组织的繁复无关。"}, "sentence_index": 0, "correct_answer": "复杂度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这列火车的复杂度很快。", "explanation": "这里应该用〈速度〉。“快”说的是速度，复杂度指系统的繁复程度，不能描述快慢。"}, {"text": "热水的复杂度降了。", "explanation": "这里应该用〈水温〉。热水会降温，但复杂度不指水的冷热，不能说“降了”。"}, {"text": "这碗汤的复杂度很鲜。", "explanation": "这里应该用〈味道〉。“鲜”形容味道，复杂度不能用来形容汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复杂度", "is_correct": true, "explanation": "正确：“增加管理的复杂度”是常用说法，指规则越多，管理越繁复。"}, {"text": "效率", "is_correct": false, "explanation": "语义：规则太多应使效率降低，与“增加”的语境相悖。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”说外形，不能用来指管理的繁复。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“管理的颜色”不成立，“颜色”不与“管理”搭配。"}], "explanations": {"复杂度": "正确：“增加管理的复杂度”是常用说法，指规则越多，管理越繁复。", "效率": "语义：规则太多应使效率降低，与“增加”的语境相悖。", "形状": "语义：“形状”说外形，不能用来指管理的繁复。", "颜色": "搭配：“管理的颜色”不成立，“颜色”不与“管理”搭配。"}, "sentence_index": 6, "correct_answer": "复杂度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的复杂度很高。", "explanation": "这里应该用〈新鲜度〉。复杂度指事物的繁复程度，不能用来说水果新不新鲜。"}, {"text": "这块石头的复杂度很重，搬不动。", "explanation": "搭配：复杂度说高低，不说“重”；“重”用于重量。"}, {"text": "这件衣服的复杂度很便宜。", "explanation": "这里应该用〈价格〉。“便宜”形容价钱，复杂度不指价钱，不能说“便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套软件很复杂度比较低，团队很容易上手。", "corrected_sentence": "这套软件的复杂度比较低，团队很容易上手。", "error_description": "错误在于“的”被误写成“很”。“复杂度”是名词，不能被“很”修饰，名词前应用“的”，说“软件的复杂度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案有一只复杂度，需要仔细评估。", "corrected_sentence": "这个方案有一定的复杂度，需要仔细评估。", "error_description": "错误形式：“一只”，是用于动物或小物件的量词。正确形式：“一定的”，用于抽象的程度。“复杂度”是抽象名词，不能用“只”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
