INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "比得上；可以相比。", "primary_collocate": null, "pronunciation": "kān bǐ", "ipa": "kʰan˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这一过程要求实时沟通、风险共担与目标对齐，其组织复杂度堪比现实中的项目管理。", "target_word": "堪比", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家小店的咖啡，品质堪比大品牌的产品。", "target_word": "堪比", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo diàn de kāfēi, pǐnzhì kānbǐ dà pǐnpái de chǎnpǐn.", "sentence_source": "generated"}, {"text": "他的画堪比专业画家。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的夜景堪比巴黎。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的歌声堪比专业歌手。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新人的表现堪比老选手。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司的服务，堪比五星级酒店。", "target_word": "堪比", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo gōngsī de fúwù, kānbǐ wǔxīngjí jiǔdiàn.", "sentence_source": "generated"}, {"text": "这台手机拍的照片，效果堪比相机。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他的字堪比书法家。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景堪比画里的山水。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "水平、效果等能与更好的对象相比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79c4ad0b-1d06-4255-be99-3a41444b55b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堪比", "is_correct": true, "explanation": "正确：“堪比”表示相当，可以把组织复杂度与项目管理相比。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”需要有感情的主语，复杂度不能讨厌项目管理。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求有生命的施事和可吃的宾语，不能吃“项目管理”。"}, {"text": "颁布", "is_correct": false, "explanation": "配价：“颁布”只用于法令、政策，不能颁布“项目管理”。"}], "explanations": {"堪比": "正确：“堪比”表示相当，可以把组织复杂度与项目管理相比。", "讨厌": "语义：“讨厌”需要有感情的主语，复杂度不能讨厌项目管理。", "吃": "配价：“吃”要求有生命的施事和可吃的宾语，不能吃“项目管理”。", "颁布": "配价：“颁布”只用于法令、政策，不能颁布“项目管理”。"}, "sentence_index": 0, "correct_answer": "堪比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一小时堪比六十分钟。", "explanation": "这里应该用〈等于〉。“堪比”表示大致相当、可以相比，不用于精确的换算。"}, {"text": "他跑得快，堪比超过所有人。", "explanation": "这里应该用〈超过〉。“堪比”表示相当，不能直接表示超越。"}, {"text": "我喜欢各种运动，堪比跑步和游泳。", "explanation": "这里应该用〈比如〉。“堪比”表示相当，不能用来举例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堪比", "is_correct": true, "explanation": "正确：“堪比”表示相当，可以比较服务与五星级酒店。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要有意愿的主语，“服务”不能欢迎“五星级酒店”。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是厌恶的态度，与服务的比较无关。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”指空间上的离开，与两者的程度比较不符。"}], "explanations": {"堪比": "正确：“堪比”表示相当，可以比较服务与五星级酒店。", "欢迎": "配价：“欢迎”需要有意愿的主语，“服务”不能欢迎“五星级酒店”。", "嫌弃": "语义：“嫌弃”是厌恶的态度，与服务的比较无关。", "远离": "语义：“远离”指空间上的离开，与两者的程度比较不符。"}, "sentence_index": 6, "correct_answer": "堪比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影堪比一看。", "explanation": "这里应该用〈值得〉。“堪比”表示相当，不表示“值得”。"}, {"text": "这份报告按标准堪比审核。", "explanation": "这里应该用〈比照〉。“堪比”表示相当，不表示“依照”。"}, {"text": "这个人堪比好的待遇。", "explanation": "这里应该用〈配得上〉。“堪比”表示相当，不能用来说某人配不配得上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小店的咖啡堪比了大品牌。", "corrected_sentence": "这家小店的咖啡堪比大品牌。", "error_description": "错误形式：“堪比了”，多了“了”。正确形式：“堪比大品牌”，“堪比”是表示相当的动词，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新电脑的速度堪比了高端机型。", "corrected_sentence": "这台新电脑的速度堪比高端机型。", "error_description": "错误形式：“堪比了”，多了“了”。正确形式：“堪比”，是表示状态的动词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04dcf9d6-09f4-4224-a53c-706c8d64bfa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
