INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对项目从开始到结束进行计划、组织、领导和控制的过程。", "primary_collocate": null, "pronunciation": "xiàng mù guǎn lǐ", "ipa": "ɕiɑŋ⁵¹ mu⁵¹ kuan²¹⁴ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "这一过程要求实时沟通、风险共担与目标对齐，其组织复杂度堪比现实中的项目管理。", "target_word": "项目管理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在公司负责项目管理。", "target_word": "项目管理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想学习项目管理的方法。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的项目管理能节省时间和钱。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司需要一位懂项目管理的经理。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "项目管理要求计划、组织和控制。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学学的是项目管理专业。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为项目管理做得好，工程按时完成。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "项目管理软件可以帮我们安排任务。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理开会讨论了项目管理的问题。", "target_word": "项目管理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "項目管理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对项目全过程进行计划、组织、领导和控制的管理活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”是休息，与句中“实时沟通、风险共担”的复杂组织工作无关。"}, {"text": "项目管理", "is_correct": true, "explanation": "正确：“项目管理”指对项目全过程的计划与组织，与句中“组织复杂度”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能用来比喻组织的复杂程度，与句意不合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不能用来比喻组织复杂度，句子说的是现实中的管理活动。"}], "explanations": {"午睡": "语义：“午睡”是休息，与句中“实时沟通、风险共担”的复杂组织工作无关。", "项目管理": "正确：“项目管理”指对项目全过程的计划与组织，与句中“组织复杂度”相合。", "冰箱": "语义：“冰箱”是家用电器，不能用来比喻组织的复杂程度，与句意不合。", "小猫": "语义：“小猫”不能用来比喻组织复杂度，句子说的是现实中的管理活动。"}, "sentence_index": 0, "correct_answer": "项目管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的项目管理越来越好。", "explanation": "这里应该用〈经营〉。项目管理指对有明确目标和期限的项目进行计划与控制，餐厅的日常营运要说经营。"}, {"text": "这位老师的项目管理很严格，学生都怕他。", "explanation": "这里应该用〈班级管理〉。项目管理指对有明确目标和期限的项目进行计划与控制，课堂秩序和学生纪律要说班级管理。"}, {"text": "这支乐团的项目管理很有名。", "explanation": "这里应该用〈指挥〉。项目管理是管理项目的工作，带领乐团演奏的人要说指挥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大象", "is_correct": false, "explanation": "语义：“大象”不是学科名称，“学的是……专业”需要一个学科名词。"}, {"text": "项目管理", "is_correct": true, "explanation": "正确：“项目管理”是一门学科，可以说“学的是项目管理专业”。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一餐饭，不是学科，与“专业”不搭。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“学的是……专业”要用学科名词，“铅笔”不能与“专业”搭配。"}], "explanations": {"大象": "语义：“大象”不是学科名称，“学的是……专业”需要一个学科名词。", "项目管理": "正确：“项目管理”是一门学科，可以说“学的是项目管理专业”。", "午饭": "语义：“午饭”是一餐饭，不是学科，与“专业”不搭。", "铅笔": "搭配：“学的是……专业”要用学科名词，“铅笔”不能与“专业”搭配。"}, "sentence_index": 6, "correct_answer": "项目管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理在墙上挂了一幅项目管理。", "explanation": "这里把〈项目管理〉当成了〈画〉。项目管理是抽象的管理活动，不是字画，不能挂在墙上，“幅”只用于字画。"}, {"text": "公司新来了一位项目管理。", "explanation": "这里把〈项目管理〉当成了一个人。项目管理是活动，担任这一工作的人应说〈项目经理〉。"}, {"text": "车间里养着一头项目管理。", "explanation": "这里把〈项目管理〉当成了〈牲口〉。项目管理是抽象的管理活动，不是动物，不能说养一头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在大学里学了一个项目管理。", "corrected_sentence": "她在大学里学了一门项目管理。", "error_description": "“项目管理”作为学科，量词应用“门”，不用“个”。错误：一个项目管理；正确：一门项目管理；原因：学科类名词用“门”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的项目管理做的非常好。", "corrected_sentence": "他的项目管理做得非常好。", "error_description": "动词“做”后的程度补语要用“得”连接，不用“的”。错误：做的非常好；正确：做得非常好；原因：“得”引出补语，“的”不能用在此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
