INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指社会或群体中系统化的思想观念，如政治、法律、艺术等方面的看法。", "primary_collocate": null, "pronunciation": "yì shí xíng tài", "ipa": "i˥˩ ʂɻ̩˧˥ ɕiŋ˧˥ tʰaɪ˥˩", "syllable_count": 4, "sentences": [{"text": "值得注意的是，这种协作常跨越地理、语言乃至意识形态的断层线。", "target_word": "意识形态", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一恶性循环的背后，是消费主义意识形态的深度驱动。", "target_word": "意识形态", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "不同国家的意识形态常常不一样。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讨论了政治意识形态的变化。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不应该只教一种意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影有时会传播某种意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的意识形态对立，但贸易往来很多。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究法律和艺术中的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会变化会影响人们的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸常常带着一定的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "意識形態", "label": "繁体"}], "register": "书面", "sense_fingerprint": "社会或群体系统化的思想观念体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意识形态", "is_correct": true, "explanation": "正确：指系统化的思想观念，符合“跨越地理、语言乃至……的断层线”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是社会或群体之间的分界，不能与地理、语言并列构成断层线。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语词，不适用于这种书面语的论述。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具不是人群之间的分界，不能构成断层线。"}], "explanations": {"意识形态": "正确：指系统化的思想观念，符合“跨越地理、语言乃至……的断层线”的语境。", "天气": "语义：天气不是社会或群体之间的分界，不能与地理、语言并列构成断层线。", "饭碗": "语域：“饭碗”是口语词，不适用于这种书面语的论述。", "工具": "语义：工具不是人群之间的分界，不能构成断层线。"}, "sentence_index": 0, "correct_answer": "意识形态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种昆虫的意识形态很特别。", "explanation": "这里应该用〈外形〉。意识形态指社会的思想体系，描述昆虫的样子要说外形，不能用意识形态。"}, {"text": "他有早起的意识形态。", "explanation": "这里应该用〈习惯〉。意识形态指思想体系，个人的生活习惯要用习惯。"}, {"text": "她的意识形态很开朗。", "explanation": "这里应该用〈性格〉。开朗用来形容性格，意识形态不能用来形容性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意识形态", "is_correct": true, "explanation": "正确：指系统化的思想观念，符合“两国思想不同”的语境。"}, {"text": "个人", "is_correct": false, "explanation": "语义：“个人”指单一的人，不能用于比较两个国家。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人或生物的体型属性，不能与“对立”搭配，“两国的身高对立”不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是人或生物的体型属性，不能与“对立”搭配，“两国的体重对立”不通。"}], "explanations": {"意识形态": "正确：指系统化的思想观念，符合“两国思想不同”的语境。", "个人": "语义：“个人”指单一的人，不能用于比较两个国家。", "身高": "搭配：“身高”是人或生物的体型属性，不能与“对立”搭配，“两国的身高对立”不通。", "体重": "搭配：“体重”是人或生物的体型属性，不能与“对立”搭配，“两国的体重对立”不通。"}, "sentence_index": 6, "correct_answer": "意识形态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的意识形态很高。", "explanation": "这里应该用〈价格〉。衣服的贵贱要用价格，意识形态是抽象的思想，不能说高低。"}, {"text": "这把椅子的意识形态很结实。", "explanation": "这里应该用〈质量〉。椅子结不结实要说质量，意识形态是抽象的思想，不能指物品的质量。"}, {"text": "这块石头的意识形态很重。", "explanation": "这里应该用〈重量〉。石头的轻重要说重量，意识形态是抽象的思想，没有重量可言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有一只意识形态。", "corrected_sentence": "这个国家有一种意识形态。", "error_description": "量词错误：“意识形态”是抽象概念，应使用量词“种”，“只”多用于动物。错误形式是“一只意识形态”，正确形式是“一种意识形态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人有一颗意识形态。", "corrected_sentence": "这个人有一种意识形态。", "error_description": "量词错误：“意识形态”是抽象概念，应使用量词“种”，“颗”用于小而圆的东西。错误形式是“一颗意识形态”，正确形式是“一种意识形态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
