INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地壳岩层因受力发生破裂并产生相对移动的构造现象，也可指事物发展中的中断或缺失。", "primary_collocate": null, "pronunciation": "duàn céng", "ipa": "tuan⁵¹ tsʰəŋ³⁵", "syllable_count": 2, "sentences": [{"text": "两国在技术标准上出现了断层，合作因此停滞。", "target_word": "断层", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "地震常常发生在断层附近。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下有一条很大的断层。", "target_word": "断层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家正在研究这个断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震让山边出现了新的断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市建在断层上，很危险。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人和老人之间有文化断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争以后，这门手艺出现了断层。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的人才出现断层，没人接班。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上能看到这条断层的位置。", "target_word": "断层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "斷層", "label": "繁体"}, {"form": "断层线", "label": "复合"}], "register": "中性", "sense_fingerprint": "地壳岩层破裂错动的构造；引申指事物发展中的中断或缺失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电", "is_correct": false, "explanation": "语义：“电”是能源或导线，不能指技术标准上的中断或缺失，“出现了电”不成立。"}, {"text": "断层", "is_correct": true, "explanation": "正确：“断层”引申指事物发展中的中断或缺失，与句中技术标准上的脱节相合。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“出现了……”不能接“鱼”，鱼不表示事物发展中的中断或缺失。"}, {"text": "水", "is_correct": false, "explanation": "语义：“水”不能表示技术标准上的中断或缺失，“出现了水”与句意不合。"}], "explanations": {"电": "语义：“电”是能源或导线，不能指技术标准上的中断或缺失，“出现了电”不成立。", "断层": "正确：“断层”引申指事物发展中的中断或缺失，与句中技术标准上的脱节相合。", "鱼": "搭配：“出现了……”不能接“鱼”，鱼不表示事物发展中的中断或缺失。", "水": "语义：“水”不能表示技术标准上的中断或缺失，“出现了水”与句意不合。"}, "sentence_index": 0, "correct_answer": "断层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上出现了一条断层。", "explanation": "这里应该用〈裂缝〉。断层指地壳岩层断裂错动，墙面的缝隙要说裂缝。"}, {"text": "他的手上有一道断层。", "explanation": "这里应该用〈伤口〉。断层是地质术语，皮肤上的创口要说伤口。"}, {"text": "桥的栏杆上有一处断层。", "explanation": "这里应该用〈缺口〉。断层指地壳岩层断裂错动，栏杆上的豁口要说缺口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "搭配：“文化”不能与“蛋糕”搭配，句子说的是两代人之间的文化差异。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”与两代人之间的文化差异无关。"}, {"text": "断层", "is_correct": true, "explanation": "正确：“文化断层”指不同代人之间的文化隔阂，与句意相合。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：“冰块”无法指代两代人之间的隔阂。"}], "explanations": {"蛋糕": "搭配：“文化”不能与“蛋糕”搭配，句子说的是两代人之间的文化差异。", "水果": "语义：“水果”与两代人之间的文化差异无关。", "断层": "正确：“文化断层”指不同代人之间的文化隔阂，与句意相合。", "冰块": "语义：“冰块”无法指代两代人之间的隔阂。"}, "sentence_index": 6, "correct_answer": "断层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的额头上有一道断层。", "explanation": "这里应该用〈皱纹〉。断层指地壳岩层断裂错动，额头上的纹路要说皱纹。"}, {"text": "山脚下有一头断层。", "explanation": "这里把〈断层〉当成了〈牲口〉。断层是长条形的地质构造，不是动物，不能用头计量。"}, {"text": "草地上有一朵断层。", "explanation": "这里把〈断层〉当成了〈花〉。断层是长条形的地质构造，不是花，不能用朵计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在河边发现了一只断层。", "corrected_sentence": "他们在河边发现了一条断层。", "error_description": "“断层”是长条状的地质构造，量词用“条”，不用“只”（“只”用于动物）。错误：一只断层；正确：一条断层。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在黑板上画出了一只断层。", "corrected_sentence": "老师在黑板上画出了一条断层。", "error_description": "错误：量词用错。“断层”是长条状的地质构造，应用“条”，不能用“只”（“只”多用于动物）。改为“一条断层”即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
