INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用丝、棉、金属等制成的细长的东西；也指细长如线的界限或赖以维系的途径，如“生命线”。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn⁵¹", "syllable_count": 1, "sentences": [{"text": "两国之间有一条看不见的线，谁也不愿跨过。", "target_word": "线", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "我需要一根线来缝衣服。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这条线后面等。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈用线缝好了扣子。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风筝的线断了。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条线太细了，很容易断。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要走过这条线。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线是用金属做的。", "target_word": "线", "complexity_tier": "T3", "furigana": "zhè gēn xiàn shì yòng jīn shǔ zuò de", "sentence_source": "generated"}, {"text": "路边画着一条线。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到这条线就停下来。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "根", "label": "量词"}, {"form": "線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "丝、棉、金属等制成的细长物；引申指界限或途径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指用丝、棉、金属等制成的细长的东西，正确。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}], "explanations": {"线": "线 xiàn，指用丝、棉、金属等制成的细长的东西，正确。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。", "见": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。", "向": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确：“一条看不见的线”指无形的界限，与句中两国之间的隔阂相合。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”是植物，不能比作无形的界限，与“谁也不愿跨过”不合。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“鱼”是动物，不能比作无形的界限，与“谁也不愿跨过”不合。"}, {"text": "脸", "is_correct": false, "explanation": "语义：“脸”是身体部位，不能表示两国之间无形的界限。"}], "explanations": {"线": "正确：“一条看不见的线”指无形的界限，与句中两国之间的隔阂相合。", "树": "语义：“树”是植物，不能比作无形的界限，与“谁也不愿跨过”不合。", "鱼": "语义：“鱼”是动物，不能比作无形的界限，与“谁也不愿跨过”不合。", "脸": "语义：“脸”是身体部位，不能表示两国之间无形的界限。"}, "sentence_index": 0, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上摆着一排线。", "explanation": "这里应该用〈书〉。书架上摆的是书，线不能用来指书。"}, {"text": "冬天的早上，窗户上结了一层线。", "explanation": "这里应该用〈霜〉。窗上结成的是霜，不是细长的线。"}, {"text": "妈妈买了一只线。", "explanation": "量词用错。线应用“根”“条”“团”等，不用“只”（“只”多用于动物或成对的器官）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11993, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指用丝、棉、金属等制成的细长的东西，正确。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。"}, {"text": "建", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}], "explanations": {"线": "线 xiàn，指用丝、棉、金属等制成的细长的东西，正确。", "闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。", "建": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确。“这条线”指地面上不能越过的界线，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“走过”的对象应是路径或界线，鱼不是可以走过的东西。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：蛇是动物，不能作为可以“走过”的界线。"}, {"text": "裙子", "is_correct": false, "explanation": "配价：“走过”需要表示路径或界限的宾语，“裙子”不能被走过。"}], "explanations": {"线": "正确。“这条线”指地面上不能越过的界线，符合句意。", "鱼": "语义：“走过”的对象应是路径或界线，鱼不是可以走过的东西。", "蛇": "语义：蛇是动物，不能作为可以“走过”的界线。", "裙子": "配价：“走过”需要表示路径或界限的宾语，“裙子”不能被走过。"}, "sentence_index": 6, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一座线。", "explanation": "量词用错。“座”用于山、桥、房屋等大型固定物，线不用“座”。"}, {"text": "孩子在操场上跳线。", "explanation": "这里应该用〈绳〉。跳的是绳，线太细，不能说“跳线”。"}, {"text": "他端起碗，喝了一条线的汤。", "explanation": "这里把〈线〉当成了计量汤的单位。线是细长物，不能用来计量液体，应说“一碗汤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用一只红线把两块布缝在一起。", "corrected_sentence": "妈妈用一根红线把两块布缝在一起。", "error_description": "错误：“线”的量词用错。“只”多用于动物或成对的器官，线应用“根”（或“条”“团”）。改为“一根红线”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他沿着那线跑到了终点。", "corrected_sentence": "他沿着那条线跑到了终点。", "error_description": "错误：指示代词“那”后漏了量词。“线”前应为“那条线”，不能说“那线”。改为“那条线”即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
