INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11995, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某个团队或组织中的成员。", "primary_collocate": null, "pronunciation": "duì yuán", "ipa": "twei˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这支球队有十五名队员。", "target_word": "队员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新队员今天第一次来训练。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练让所有队员先休息一下。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每位队员都要遵守队里的规定。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这名队员跑得比别人快。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救援队的队员已经出发了。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们队最年轻的队员。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们一起走进了体育馆。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，队员们互相握手。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "所有队员的名字都写在这张表上。", "target_word": "队员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "队员：团队或组织中的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11995, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队员", "is_correct": true, "explanation": "正确。“队员”指球队中的成员，符合“十五名”的数量。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不属于球队成员，不能计入“十五名队员”。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练是指导者，不属于队员，句子说的是球员人数。"}, {"text": "队长", "is_correct": false, "explanation": "搭配：一支球队通常只设一名队长，不能说“十五名队长”。"}], "explanations": {"队员": "正确。“队员”指球队中的成员，符合“十五名”的数量。", "观众": "语义：观众不属于球队成员，不能计入“十五名队员”。", "教练": "语义：教练是指导者，不属于队员，句子说的是球员人数。", "队长": "搭配：一支球队通常只设一名队长，不能说“十五名队长”。"}, "sentence_index": 0, "correct_answer": "队员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "董事会的队员每年都开一次会。", "explanation": "这里应该用〈成员〉。队员多指体育队或团队中参加活动的人，董事会的人应说“成员”。"}, {"text": "驾校的队员每天都要练车。", "explanation": "这里应该用〈学员〉。队员指团队中的成员，驾校里学车的人应说“学员”。"}, {"text": "我们班来了一只队员。", "explanation": "量词用错。“队员”指人，应用“名”或“位”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队员", "is_correct": true, "explanation": "正确。“最年轻的”修饰人，队员符合句意。"}, {"text": "设备", "is_correct": false, "explanation": "语义：设备是器材，不是人，不能说“最年轻的设备”。"}, {"text": "球鞋", "is_correct": false, "explanation": "搭配：“年轻”修饰人的年龄，球鞋不能说“最年轻的”。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是人，与“我们队最年轻的”不符。"}], "explanations": {"队员": "正确。“最年轻的”修饰人，队员符合句意。", "设备": "语义：设备是器材，不是人，不能说“最年轻的设备”。", "球鞋": "搭配：“年轻”修饰人的年龄，球鞋不能说“最年轻的”。", "饮料": "语义：饮料不是人，与“我们队最年轻的”不符。"}, "sentence_index": 6, "correct_answer": "队员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的队员每天都很忙。", "explanation": "这里应该用〈员工〉。队员指队伍中的人，公司职员应说“员工”。"}, {"text": "我们班来了一头队员。", "explanation": "量词用错。“头”用于牛、猪等大型牲畜，队员不用“头”。"}, {"text": "医院里的队员很多。", "explanation": "这里应该用〈病人〉。队员指团队中的成员，医院里的人应说“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们队里的一只队员。", "corrected_sentence": "他是我们队里的一名队员。", "error_description": "错误：“队员”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。改为“一名队员”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队有一名新队员们。", "corrected_sentence": "我们队有一名新队员。", "error_description": "错误：“们”不能跟在数量短语后面。“一名新队员”之后不能加“们”，应说“一名新队员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
