INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11996, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们在共同条件或共同目标下结成的集体。", "primary_collocate": null, "pronunciation": "gòng tóng tǐ", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "共同体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "虚拟世界因而成为理解21世纪社会性的一把密钥，其启示或许终将反哺现实世界的组织哲学与共同体构建。", "target_word": "共同体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们在同一个目标下组成了一个小共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网络共同体里，大家互相帮助。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了完成任务，他们结成了临时共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同体的成员要遵守共同的规则。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者们为了同一个目标，结成了共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学习共同体每周都有一次讨论。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家目标一致，慢慢形成了一个共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在游戏里，我们是一个互相信任的共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "命运共同体", "label": "复合"}, {"form": "共同體", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "人们在共同条件或目标下结成的集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“形成临时共同体”指在共同目标下结成的集体，“临时”“形成”与之搭配。"}, {"text": "家族", "is_correct": false, "explanation": "语义：家族以血缘为基础，前文说凝聚力不依赖血缘，“临时家族”与之相悖。"}, {"text": "国家", "is_correct": false, "explanation": "搭配：“临时”不能修饰“国家”，国家是长期的主权实体，不能临时形成。"}, {"text": "亲属", "is_correct": false, "explanation": "语义：亲属由血缘或婚姻而来，不能临时形成，与“不依赖血缘”相悖。"}], "explanations": {"共同体": "正确：“形成临时共同体”指在共同目标下结成的集体，“临时”“形成”与之搭配。", "家族": "语义：家族以血缘为基础，前文说凝聚力不依赖血缘，“临时家族”与之相悖。", "国家": "搭配：“临时”不能修饰“国家”，国家是长期的主权实体，不能临时形成。", "亲属": "语义：亲属由血缘或婚姻而来，不能临时形成，与“不依赖血缘”相悖。"}, "sentence_index": 0, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个共同体在城市的东边，交通很方便。", "explanation": "这里应该用〈社区〉。社区指居住的区域，共同体指因共同条件或目标结成的人群，不指地理位置。"}, {"text": "这个共同体的气候又干燥又寒冷。", "explanation": "这里应该用〈地区〉。气候属于地域，共同体指人群，不能用来描述气候。"}, {"text": "这个共同体有很多树，夏天特别凉快。", "explanation": "这里应该用〈公园〉。树木和凉快描述的是绿地，共同体不指公共场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“结成了共同体”指为了同一个目标结合成的集体，与“志愿者们”“同一个目标”相符。"}, {"text": "宗族", "is_correct": false, "explanation": "语义：宗族以血缘为纽带，志愿者之间没有血缘关系，不能因同一个目标结成宗族。"}, {"text": "部族", "is_correct": false, "explanation": "语义：部族以血缘和部落为纽带，与“为了同一个目标”的志愿者不符。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“结成”的宾语应是组织或关系，“结成冰”不能用于人，志愿者不能结成冰。"}], "explanations": {"共同体": "正确：“结成了共同体”指为了同一个目标结合成的集体，与“志愿者们”“同一个目标”相符。", "宗族": "语义：宗族以血缘为纽带，志愿者之间没有血缘关系，不能因同一个目标结成宗族。", "部族": "语义：部族以血缘和部落为纽带，与“为了同一个目标”的志愿者不符。", "冰": "搭配：“结成”的宾语应是组织或关系，“结成冰”不能用于人，志愿者不能结成冰。"}, "sentence_index": 6, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个共同体的油箱是空的。", "explanation": "这里应该用〈汽车〉。汽车有油箱，共同体指人的集体，没有油箱，不能这样说。"}, {"text": "他把这个共同体打印了五份。", "explanation": "这里应该用〈文件〉。文件可以打印，共同体指人的集体，不能被打印。"}, {"text": "这个共同体的屏幕很大。", "explanation": "这里应该用〈电脑〉。电脑有屏幕，共同体指人的集体，没有屏幕，不能用大小来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "志愿者们为了同一个目标，很快结了一个共同体。", "corrected_sentence": "志愿者们为了同一个目标，很快结成了一个共同体。", "error_description": "错误在“结”。“结了一个共同体”不自然，表示结合成集体通常说复合动词“结成”，“结成了一个共同体”才是通常说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在线上组成了一只共同体。", "corrected_sentence": "他们在线上组成了一个共同体。", "error_description": "量词错误：“只”多用于动物或某些器物，“共同体”应用量词“个”，应说“一个共同体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
