INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指使人或事物聚集、结合并保持为一个整体的力量。", "primary_collocate": null, "pronunciation": "níng jù lì", "ipa": "niŋ˧˥ tɕy˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "凝聚力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这支队伍很有凝聚力。", "target_word": "凝聚力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的领导能提高团队的凝聚力。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一起吃饭可以增强大家的凝聚力。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的凝聚力很强，没人想走。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了以后，队里的凝聚力反而更强了。", "target_word": "凝聚力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的目标让全班有了凝聚力。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家的凝聚力来自互相信任。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有凝聚力的小组很难完成任务。", "target_word": "凝聚力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师组织活动，是为了培养班级的凝聚力。", "target_word": "凝聚力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "书面", "sense_fingerprint": "凝聚力：使人或事物结合为整体的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物身体的重量，不能描述共同体的结合状况，「其体重不依赖血缘或国籍」说不通。"}, {"text": "凝聚力", "is_correct": true, "explanation": "正确：凝聚力指使人或事物结合为整体的力量，句中说它「不依赖血缘或国籍」而「根植于角色互补性与互信契约」，与句意完全吻合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的价值，与共同体内部的结合无关，「其价格根植于角色互补性与互信契约」不成立。"}, {"text": "电力", "is_correct": false, "explanation": "搭配：电力指电能，不能说「根植于角色互补性与互信契约」；此处描述的是队员之间的结合力。"}], "explanations": {"体重": "语义：体重指人或动物身体的重量，不能描述共同体的结合状况，「其体重不依赖血缘或国籍」说不通。", "凝聚力": "正确：凝聚力指使人或事物结合为整体的力量，句中说它「不依赖血缘或国籍」而「根植于角色互补性与互信契约」，与句意完全吻合。", "价格": "语义：价格是商品的价值，与共同体内部的结合无关，「其价格根植于角色互补性与互信契约」不成立。", "电力": "搭配：电力指电能，不能说「根植于角色互补性与互信契约」；此处描述的是队员之间的结合力。"}, "sentence_index": 0, "correct_answer": "凝聚力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完马拉松，凝聚力还很强。", "explanation": "这里应该用〈体力〉。凝聚力指人或团体结合为整体的力量，不指个人的身体能量；跑步后仍然有的身体能量要用体力。"}, {"text": "我们班有一只很强的凝聚力。", "explanation": "这里量词应该用〈股〉，说「一股凝聚力」。凝聚力是抽象的力量，量词「只」用于动物、手等具体事物，不能用于它。"}, {"text": "他的凝聚力很强，一顿能吃三碗饭。", "explanation": "这里应该用〈食量〉。凝聚力指聚集、结合成整体的力量，吃东西的饭量要用食量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人存在的年数，目标不能让全班「有了年龄」，句意不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命指生物存活的时间，与团体的结合无关，「让全班有了寿命」不成立。"}, {"text": "凝聚力", "is_correct": true, "explanation": "正确：「有了凝聚力」指全班形成了团结的力量，与「共同的目标」这一原因搭配自然。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：「有了」后接字数不自然，字数是文字的数量，不会因目标而产生。"}], "explanations": {"年龄": "语义：年龄指人存在的年数，目标不能让全班「有了年龄」，句意不通。", "寿命": "语义：寿命指生物存活的时间，与团体的结合无关，「让全班有了寿命」不成立。", "凝聚力": "正确：「有了凝聚力」指全班形成了团结的力量，与「共同的目标」这一原因搭配自然。", "字数": "搭配：「有了」后接字数不自然，字数是文字的数量，不会因目标而产生。"}, "sentence_index": 6, "correct_answer": "凝聚力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的凝聚力很强，每小时能开一百公里。", "explanation": "这里应该用〈速度〉。凝聚力指聚集、结合成整体的力量，车子行驶的快慢要用速度。"}, {"text": "她的笑容很有凝聚力，让人印象深刻。", "explanation": "这里应该用〈吸引力〉。凝聚力指聚集、结合成整体的力量，笑容令人喜爱、引人注意的力量要用吸引力。"}, {"text": "老人的凝聚力很强，能一口气吹灭十根蜡烛。", "explanation": "这里应该用〈肺活量〉。凝聚力指人或事物结合成整体的力量，呼气的能力要用肺活量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班很凝聚力，大家互相帮助。", "corrected_sentence": "这个班很有凝聚力，大家互相帮助。", "error_description": "错误：「很凝聚力」，漏掉了动词「有」。正确：「很有凝聚力」。凝聚力是名词，前面用程度副词修饰时要说「很有凝聚力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支队伍有一条很强的凝聚力。", "corrected_sentence": "这支队伍有一股很强的凝聚力。", "error_description": "错误：量词「条」多用于细长的东西，不能用于抽象的凝聚力。改为量词「股」，说「一股很强的凝聚力」即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
