INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "血缘指因出生而自然形成的亲属关系，如父母与子女之间的血统联系。", "primary_collocate": null, "pronunciation": "xuè yuán", "ipa": "ɕɥe˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "血缘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他们没有血缘关系，但像亲兄弟一样。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里的人大多有血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领养的孩子和养父母没有血缘。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生通过检查，确认了两人的血缘关系。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代社会的家族常常以血缘为纽带。", "target_word": "血缘", "complexity_tier": "T3", "furigana": "gǔ dài shè huì de jiā zú cháng cháng yǐ xuè yuán wéi niǔ dài", "sentence_source": "generated"}, {"text": "血缘把这一家人连在一起。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们虽然血缘不同，却互相照顾。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血缘相近的人，长得常常很像。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个部落里，血缘决定一个人的地位。", "target_word": "血缘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血缘关系", "label": "复合"}, {"form": "血緣", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "因出生而形成的亲属关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确：血缘（xuè yuán）指因出生形成的亲属关系。"}, {"text": "学员", "is_correct": false, "explanation": "xué（第二声）与 xuè（第四声）声调不同，意思是学习的人。"}, {"text": "雪原", "is_correct": false, "explanation": "xuě（第三声）与 xuè（第四声）声调不同，意思是积雪覆盖的原野。"}, {"text": "学院", "is_correct": false, "explanation": "两个音节的声调都与血缘不同（xué 与 yuàn），意思是高等教育机构。"}], "explanations": {"血缘": "正确：血缘（xuè yuán）指因出生形成的亲属关系。", "学员": "xué（第二声）与 xuè（第四声）声调不同，意思是学习的人。", "雪原": "xuě（第三声）与 xuè（第四声）声调不同，意思是积雪覆盖的原野。", "学院": "两个音节的声调都与血缘不同（xué 与 yuàn），意思是高等教育机构。"}, "sentence_index": null, "correct_answer": "血缘"}, "level_3": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确：“不依赖血缘或国籍”与“凝聚力根植于……”形成对照，血缘指因出生形成的亲属关系。"}, {"text": "互信", "is_correct": false, "explanation": "语义：前文说凝聚力根植于互信契约，不能说凝聚力不依赖互信。"}, {"text": "角色", "is_correct": false, "explanation": "语义：前文说凝聚力根植于角色互补性，与“不依赖角色”相悖。"}, {"text": "契约", "is_correct": false, "explanation": "搭配：“契约”与“国籍”并列作凝聚力的来源不当，且与“根植于……互信契约”矛盾。"}], "explanations": {"血缘": "正确：“不依赖血缘或国籍”与“凝聚力根植于……”形成对照，血缘指因出生形成的亲属关系。", "互信": "语义：前文说凝聚力根植于互信契约，不能说凝聚力不依赖互信。", "角色": "语义：前文说凝聚力根植于角色互补性，与“不依赖角色”相悖。", "契约": "搭配：“契约”与“国籍”并列作凝聚力的来源不当，且与“根植于……互信契约”矛盾。"}, "sentence_index": 0, "correct_answer": "血缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的血缘都住在乡下，平时很少见面。", "explanation": "这里应该用〈亲属〉。血缘是抽象的关系，不指具体的人，不能说“血缘住在乡下”。"}, {"text": "这个古老的血缘有上百人，都姓李。", "explanation": "这里应该用〈家族〉。家族是同一血缘的人群，血缘本身不能计人数。"}, {"text": "我们家的血缘有五口人。", "explanation": "这里应该用〈家庭〉。家庭可以计人口，血缘是关系，不能计人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血缘", "is_correct": true, "explanation": "正确：血缘指因出生形成的亲属关系，能够把一家人连在一起。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人与“一家人”相对，不能把一家人连在一起。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”多用于拉开事物，不说“距离把……连在一起”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，不能把人连在一起。"}], "explanations": {"血缘": "正确：血缘指因出生形成的亲属关系，能够把一家人连在一起。", "陌生人": "语义：陌生人与“一家人”相对，不能把一家人连在一起。", "距离": "搭配：“距离”多用于拉开事物，不说“距离把……连在一起”。", "空气": "语义：空气是无形的物质，不能把人连在一起。"}, "sentence_index": 6, "correct_answer": "血缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的血缘是O型，很少见。", "explanation": "这里应该用〈血型〉。血型指血液的类型，血缘指亲属关系，不能说“血缘是O型”。"}, {"text": "爷爷的血缘有点高，要多注意。", "explanation": "这里应该用〈血压〉。血压可以高，血缘不能用高低来描述。"}, {"text": "医生给我抽了血缘。", "explanation": "这里应该用〈血液〉。抽取的是血液，血缘是亲属关系，不能被抽取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人不有血缘关系，却像朋友一样。", "corrected_sentence": "这两个人没有血缘关系，却像朋友一样。", "error_description": "错误在否定词。“有”的否定要用“没有”，不能说“不有”。正确说法是“没有血缘关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家人之间带血缘关系。", "corrected_sentence": "这两家人之间有血缘关系。", "error_description": "错误在动词。“有”不能换成“带”。“带”不能直接以“血缘关系”作宾语，应说“有血缘关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
