INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国籍指一个人依法属于某个国家的公民身份。", "primary_collocate": null, "pronunciation": "guó jí", "ipa": "kwo˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "请在表格里写上你的国籍。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在中国，国籍却是美国。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友想申请中国国籍。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国籍不同，也可以成为好朋友。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员已经改了国籍。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的国籍和父母一样。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护照上写着持有人的国籍。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入境时，工作人员问了我的国籍。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的国籍是什么？", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃原来的国籍，换了新的。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "双重国籍", "label": "复合"}, {"form": "國籍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人依法属于某国的公民身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11999, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。国籍指一个人依法属于某国的公民身份。"}, {"text": "国际", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是国际。"}, {"text": "国旗", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），意思是国旗。"}, {"text": "过季", "is_correct": false, "explanation": "guò 与 guó、jì 与 jí 声调都不同，意思是过季。"}], "explanations": {"国籍": "正确答案。国籍指一个人依法属于某国的公民身份。", "国际": "jì（第四声）与 jí（第二声）声调不同，意思是国际。", "国旗": "qí 与 jí 声母不同（q 与 j），意思是国旗。", "过季": "guò 与 guó、jì 与 jí 声调都不同，意思是过季。"}, "sentence_index": null, "correct_answer": "国籍"}, "level_3": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。表格里要求填写的是国籍，与“写上你的……”相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性格特点，不是表格里要填写的内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能用来指人的身份信息。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气描述气象状况，不是表格里要填写的个人信息。"}], "explanations": {"国籍": "正确答案。表格里要求填写的是国籍，与“写上你的……”相符。", "脾气": "语义：“脾气”是性格特点，不是表格里要填写的内容。", "颜色": "语义：“颜色”指事物的色彩，不能用来指人的身份信息。", "天气": "语义：天气描述气象状况，不是表格里要填写的个人信息。"}, "sentence_index": 0, "correct_answer": "国籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国籍在北京。", "explanation": "这里应该用〈户口〉。户口是居住地登记，北京是城市，国籍指国家归属，不能说“国籍在北京”。"}, {"text": "他的国籍是山东。", "explanation": "这里应该用〈籍贯〉。籍贯指出生或祖籍的地方，山东是省份，不能用作国籍。"}, {"text": "他拿着国籍出了境。", "explanation": "这里应该用〈护照〉。国籍是身份归属，不是可以拿着的证件，“拿着国籍”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。护照上写的是持有人的国籍，与“护照上写着持有人的……”相符。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：“爱好”是兴趣，护照上不记录这类信息。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”指生活方式，不是护照上会写的内容。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”是身体活动，不能用“写着”来表示护照上记载它。"}], "explanations": {"国籍": "正确答案。护照上写的是持有人的国籍，与“护照上写着持有人的……”相符。", "爱好": "语义：“爱好”是兴趣，护照上不记录这类信息。", "习惯": "语义：“习惯”指生活方式，不是护照上会写的内容。", "心跳": "搭配：“心跳”是身体活动，不能用“写着”来表示护照上记载它。"}, "sentence_index": 6, "correct_answer": "国籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去过很多国籍，见过很多风景。", "explanation": "这里应该用〈国家〉。国籍是身份归属，不是可以去的地方。"}, {"text": "中国的国籍很勤劳。", "explanation": "这里应该用〈国民〉。国籍是身份归属，不能用来描述人的勤劳程度。"}, {"text": "他是少数国籍，有自己的语言。", "explanation": "这里应该用〈民族〉。少数民族指人群的划分，不指国籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经拿到了一只新的法国国籍。", "corrected_sentence": "他已经拿到了一个新的法国国籍。", "error_description": "量词错误：“只”多用于动物等，“国籍”应用量词“个”，应说“一个新的法国国籍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她十年前就放弃了原来地国籍。", "corrected_sentence": "她十年前就放弃了原来的国籍。", "error_description": "助词错误：修饰名词“国籍”时应用“的”，不能用“地”（“地”用于修饰动词），应说“原来的国籍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
