INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个事物或方面相互补充、相互依存，通过结合能够形成更完整或更有效的整体。", "primary_collocate": null, "pronunciation": "hù bǔ xìng", "ipa": "xu˥˩ pu˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "互补性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两种食物的互补性很强。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的性格有互补性，所以合作很顺利。", "target_word": "互补性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩的技能有很强的互补性。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "团队里的人需要互补性，不能都一样。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两家公司的产品互补性很高。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻之间的互补性让家庭更稳定。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，米饭和豆类在营养上有互补性。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选队友时，我最看重能力的互补性。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个方案没有互补性，只能选一个。", "target_word": "互补性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "事物之间相互补充、结合后更完整的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互补性", "is_correct": true, "explanation": "正确答案。“角色互补性”与“互信契约”相符，指角色之间相互补充。"}, {"text": "竞争性", "is_correct": false, "explanation": "语义：“竞争性”与“共同目标”“互信契约”的合作语境相矛盾。"}, {"text": "排他性", "is_correct": false, "explanation": "语义：“排他性”指排斥他人，与“共同体”和“互信”相冲突。"}, {"text": "单向性", "is_correct": false, "explanation": "搭配：“单向性”通常修饰联系或流程，不能与“角色”“互信契约”搭配。"}], "explanations": {"互补性": "正确答案。“角色互补性”与“互信契约”相符，指角色之间相互补充。", "竞争性": "语义：“竞争性”与“共同目标”“互信契约”的合作语境相矛盾。", "排他性": "语义：“排他性”指排斥他人，与“共同体”和“互信”相冲突。", "单向性": "搭配：“单向性”通常修饰联系或流程，不能与“角色”“互信契约”搭配。"}, "sentence_index": 0, "correct_answer": "互补性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对父母的互补性很强，离不开他们。", "explanation": "这里应该用〈依赖性〉。互补性指两方相互补充，不指一方对另一方的依赖。"}, {"text": "这对双胞胎的长相完全一样，互补性很高。", "explanation": "这里应该用〈相似性〉。互补性指两方相互补充，长相完全一样时不存在互补，应说“相似性很高”。"}, {"text": "这两家公司之间有激烈的互补性。", "explanation": "这里应该用〈竞争性〉。“激烈”形容对抗，与“互补性”搭配不当；互补性指相互补充。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互补性", "is_correct": true, "explanation": "正确答案。“夫妻之间的互补性”让家庭更稳定，与后半句相符。"}, {"text": "对立性", "is_correct": false, "explanation": "语义：“对立”与“让家庭更稳定”相矛盾。"}, {"text": "偶然性", "is_correct": false, "explanation": "搭配：“偶然性”一般不修饰夫妻之间的长期关系，“夫妻之间的偶然性”不成立。"}, {"text": "脆弱性", "is_correct": false, "explanation": "语义：“脆弱”与“让家庭更稳定”相矛盾。"}], "explanations": {"互补性": "正确答案。“夫妻之间的互补性”让家庭更稳定，与后半句相符。", "对立性": "语义：“对立”与“让家庭更稳定”相矛盾。", "偶然性": "搭配：“偶然性”一般不修饰夫妻之间的长期关系，“夫妻之间的偶然性”不成立。", "脆弱性": "语义：“脆弱”与“让家庭更稳定”相矛盾。"}, "sentence_index": 6, "correct_answer": "互补性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人完成了所有工作，互补性很强。", "explanation": "这里应该用〈效率〉。互补性指两方或多方相互补充，一个人独自完成工作谈不上互补，应说“效率很高”。"}, {"text": "这台机器自己运行，没有任何配合，互补性很高。", "explanation": "这里应该用〈独立性〉。互补性指相互补充，机器独自运行没有配合，应说“独立性很高”。"}, {"text": "这本书只有一个作者，互补性很强。", "explanation": "这里应该用〈完整性〉。互补性指相互补充，只有一个作者时谈不上互补，应说“完整性很强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的技能很有的互补性。", "corrected_sentence": "他们的技能很有互补性。", "error_description": "多余的“的”：“有”后直接接名词“互补性”，中间不加“的”，应说“很有互补性”，不能说“很有的互补性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种搭配地互补性很强。", "corrected_sentence": "这种搭配的互补性很强。", "error_description": "助词错误：修饰名词“互补性”的“搭配”是名词，应用“的”，不能用“地”（“地”用于修饰动词或形容词），应说“这种搭配的互补性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
