INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指彼此之间相互信任的关系。", "primary_collocate": null, "pronunciation": "hù xìn", "ipa": "xu˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "一个中国玩家可能与北欧、南美队员在共同目标下形成临时共同体，其凝聚力不依赖血缘或国籍，而根植于角色互补性与互信契约。", "target_word": "互信", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国之间需要建立互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间的互信很重要。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有互信，合作就很难继续。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们花了很多年才有今天的互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "互信是好团队的基础。", "target_word": "互信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经常沟通能增加双方的互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次谎言就会破坏我们的互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻之间有互信，家里就很安定。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司和客户之间已经形成了互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "双方彼此信任所形成的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97b7304-e68a-4de4-b193-807fb56c347d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互信", "is_correct": true, "explanation": "正确：「互信契约」指双方彼此信任的契约，与「互补性」并列，符合语境。"}, {"text": "血缘", "is_correct": false, "explanation": "语义：前文说凝聚力不依赖血缘，「血缘契约」与之矛盾。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：前文说凝聚力不依赖国籍，「国籍契约」与之矛盾。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：「哥们儿」是口语词，与这段书面论述的风格不协调。"}], "explanations": {"互信": "正确：「互信契约」指双方彼此信任的契约，与「互补性」并列，符合语境。", "血缘": "语义：前文说凝聚力不依赖血缘，「血缘契约」与之矛盾。", "国籍": "语义：前文说凝聚力不依赖国籍，「国籍契约」与之矛盾。", "哥们儿": "语域：「哥们儿」是口语词，与这段书面论述的风格不协调。"}, "sentence_index": 0, "correct_answer": "互信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很感谢老板对我的互信。", "explanation": "这里应该用〈信任〉。互信指双方彼此相信，老板只对我一方的信任应说信任。"}, {"text": "我对这家公司很有互信。", "explanation": "这里应该用〈信心〉。互信是双方之间的关系，「对这家公司有信心」只是我一方的想法。"}, {"text": "她对自己的判断有很强的互信。", "explanation": "这里应该用〈自信〉。互信指双方彼此相信的关系，只涉及一个人对自己的判断时应说自信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互信", "is_correct": true, "explanation": "正确：「增加双方的互信」指双方之间彼此信任的程度提高，符合句意。"}, {"text": "误会", "is_correct": false, "explanation": "语义：经常沟通的作用是减少误会，「增加双方的误会」与句意相反。"}, {"text": "摩擦", "is_correct": false, "explanation": "语义：经常沟通能减少摩擦，说「增加摩擦」与常理相反。"}, {"text": "隔阂", "is_correct": false, "explanation": "语义：经常沟通应当减少隔阂，「增加双方的隔阂」与句意相反。"}], "explanations": {"互信": "正确：「增加双方的互信」指双方之间彼此信任的程度提高，符合句意。", "误会": "语义：经常沟通的作用是减少误会，「增加双方的误会」与句意相反。", "摩擦": "语义：经常沟通能减少摩擦，说「增加摩擦」与常理相反。", "隔阂": "语义：经常沟通应当减少隔阂，「增加双方的隔阂」与句意相反。"}, "sentence_index": 6, "correct_answer": "互信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的互信很高，顾客都很放心。", "explanation": "这里应该用〈口碑〉。互信指双方之间的相互信任，一家店的好名声应说口碑。"}, {"text": "两家公司之间的互信很激烈，每天都在抢客户。", "explanation": "这里应该用〈竞争〉。互信指彼此相信的关系，两家公司互相抢客户、局势激烈应说竞争。"}, {"text": "这个人的互信很好，说话算数。", "explanation": "这里应该用〈信用〉。互信指双方互相信任，只涉及一个人时应说信用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们之间有一颗很深的互信。", "corrected_sentence": "我们之间有一种很深的互信。", "error_description": "量词错误：「互信」是抽象名词，应用量词「种」，不能用「颗」（「颗」用于粒状小物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要两家公司之间有互信地，合作就能顺利进行。", "corrected_sentence": "只要两家公司之间有互信，合作就能顺利进行。", "error_description": "助词错误：「地」用于修饰动词或形容词作状语，「互信」是名词，其后不能用「地」。应删去「地」，说「有互信，合作就能顺利进行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aac0e3e9-ed14-4a49-a8fb-6c93994fbbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
