INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进行科学实验或研究的专用场所。", "primary_collocate": null, "pronunciation": "shí yàn shì", "ipa": "ʂɻ̩˧˥ jɛn˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "虚拟世界因而成为社会性研究的天然实验室。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小王每天都在实验室里做实验。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们穿上白大褂，去学校的实验室做化学实验。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室的桌子上放着很多瓶子和仪器。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验的时候，实验室里不能吃东西。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司新建了一间大实验室，专门做研究。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一股刺鼻的药品味。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后，在一家药厂的实验室工作。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有危险的药品，学生不能随便进。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚实验室的灯一直亮着，他在做实验。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一间实验室", "label": "量词"}, {"form": "化学实验室", "label": "复合"}, {"form": "實驗室", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进行科学实验或研究的专用场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实验室", "is_correct": true, "explanation": "“实验室”指进行科学研究的场所，与句中的“社会性研究”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是进行社会性研究的场所。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场用于体育活动，与“社会性研究”无关。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“天然”多指自然形成的场所，银行是人造的金融机构，不说“天然银行”。"}], "explanations": {"实验室": "“实验室”指进行科学研究的场所，与句中的“社会性研究”相符。", "厨房": "语义：厨房是做饭的地方，不是进行社会性研究的场所。", "操场": "语义：操场用于体育活动，与“社会性研究”无关。", "银行": "搭配：“天然”多指自然形成的场所，银行是人造的金融机构，不说“天然银行”。"}, "sentence_index": 0, "correct_answer": "实验室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天下午都做实验室。", "explanation": "这里“做”后面要接动作或事情，应说“在实验室做实验”。实验室表示场所，不能直接作“做”的宾语，把场所误当成动作来用。"}, {"text": "这家实验室每天生产上千台电视。", "explanation": "这里应该用〈工厂〉。实验室用于科学研究，大批量生产要用工厂。"}, {"text": "她感冒了，就去实验室看病。", "explanation": "这里应该用〈医院〉。看病要去医院，实验室是做科学研究的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验室", "is_correct": true, "explanation": "“实验室”可以有药品味，“里有一股刺鼻的药品味”符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音，不会有刺鼻的气味。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是叙述内容，不能有气味。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“里有一股……味”通常指有封闭空间的地方，不说“天空里”。"}], "explanations": {"实验室": "“实验室”可以有药品味，“里有一股刺鼻的药品味”符合句意。", "音乐": "语义：音乐是声音，不会有刺鼻的气味。", "故事": "语义：故事是叙述内容，不能有气味。", "天空": "搭配：“里有一股……味”通常指有封闭空间的地方，不说“天空里”。"}, "sentence_index": 6, "correct_answer": "实验室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们新建了一张实验室，就在三楼。", "explanation": "这里应该用〈间〉。“张”用于桌子、纸张等平面的东西，房间要用“间”。"}, {"text": "他们新建了一只实验室，就在三楼。", "explanation": "这里应该用〈间〉。“只”多用于动物或成对的器官，不能修饰房间。"}, {"text": "他们新建了一台实验室，就在三楼。", "explanation": "这里应该用〈间〉。“台”用于机器、设备，实验室是房间，不能用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校新建了一所实验室，大家都很高兴。", "corrected_sentence": "这所学校新建了一间实验室，大家都很高兴。", "error_description": "量词错误：“实验室”指房间，数房间应用“间”，应说“一间实验室”。“所”多用于学校、医院等建筑机构，这里用在“实验室”上不合适。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们实验室里认真地记录数据。", "corrected_sentence": "同学们在实验室里认真地记录数据。", "error_description": "介词错误：处所要用“在”引出，应说“在实验室里”。漏掉“在”，直接说“实验室里”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "统一", "is_correct": true, "explanation": "“统一”与“对立”在“互相排斥、矛盾”的义项上构成反义关系（对立统一）。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“对立”无反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”指付钱取得物品，与“对立”无反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指慢慢走着放松，与“对立”无反义关系。"}], "correct_answer": "统一", "explanations": {"统一": "“统一”与“对立”在“互相排斥、矛盾”的义项上构成反义关系（对立统一）。", "观察": "“观察”指仔细看，与“对立”无反义关系。", "购买": "“购买”指付钱取得物品，与“对立”无反义关系。", "散步": "“散步”指慢慢走着放松，与“对立”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "统一", "is_correct": true, "explanation": "“统一”与“对立”在“互相排斥、矛盾”的义项上构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子考虑问题，与“对立”无反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指把坏了的东西弄好，与“对立”无反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“对立”无反义关系。"}], "correct_answer": "统一", "explanations": {"统一": "“统一”与“对立”在“互相排斥、矛盾”的义项上构成反义关系。", "思考": "“思考”指用脑子考虑问题，与“对立”无反义关系。", "修理": "“修理”指把坏了的东西弄好，与“对立”无反义关系。", "参加": "“参加”指加入某项活动，与“对立”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指两种事物或力量互相排斥、矛盾。", "primary_collocate": null, "pronunciation": "duì lì", "ipa": "twei˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "协作与竞争并非二元对立，而是通过游戏机制被编织成动态张力网络。", "target_word": "对立", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这两个国家的立场长期对立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲和儿子的看法完全对立，谁也说服不了谁。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的两派意见对立，会议开了很久。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这件事上，我们的利益并不对立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人和老板的矛盾越来越大，双方严重对立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种观点互相对立，很难同时成立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两党在这个问题上始终对立，谈不到一起。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩的想法对立，常常吵起来。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去人们把工作和生活看成对立的两面。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对立着", "label": "体标"}, {"form": "对立了", "label": "体标"}, {"form": "对立面", "label": "复合"}, {"form": "對立", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两种事物或力量互相排斥、矛盾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“二元对立”指两种互相排斥的关系，与句中的“协作与竞争”对举相符。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：句中“竞争”已与“协作”对举，再说“二元竞争”不构成对立关系。"}, {"text": "协作", "is_correct": false, "explanation": "语义：“协作”已在句中作为一方出现，不能再作“二元”的替换词。"}, {"text": "合作", "is_correct": false, "explanation": "搭配：“二元”后接对立类词语，“合作”不能与“二元”搭配。"}], "explanations": {"对立": "“二元对立”指两种互相排斥的关系，与句中的“协作与竞争”对举相符。", "竞争": "语义：句中“竞争”已与“协作”对举，再说“二元竞争”不构成对立关系。", "协作": "语义：“协作”已在句中作为一方出现，不能再作“二元”的替换词。", "合作": "搭配：“二元”后接对立类词语，“合作”不能与“二元”搭配。"}, "sentence_index": 0, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家在1950年对立。", "explanation": "这里应该用〈独立〉。对立指双方互相排斥，只有一方时不能说“对立”。"}, {"text": "两派为了共同目标对立起来，一起解决了难题。", "explanation": "这里应该用〈团结〉。“对立”指互相排斥、矛盾，不能用来说双方为共同目标一起努力。"}, {"text": "两家公司决定对立，共同开发新产品。", "explanation": "这里应该用〈合作〉。对立指双方互相排斥，不能用来说双方一起做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“两种观点互相对立”，“对立”表示互相排斥，符合“很难同时成立”。"}, {"text": "配合", "is_correct": false, "explanation": "语义：观点“配合”则易于并存，与“很难同时成立”相矛盾。"}, {"text": "补充", "is_correct": false, "explanation": "语义：观点“补充”则可以并存，与“很难同时成立”相悖。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“互相讨论”指人之间交流，观点不能“互相讨论”。"}], "explanations": {"对立": "“两种观点互相对立”，“对立”表示互相排斥，符合“很难同时成立”。", "配合": "语义：观点“配合”则易于并存，与“很难同时成立”相矛盾。", "补充": "语义：观点“补充”则可以并存，与“很难同时成立”相悖。", "讨论": "搭配：“互相讨论”指人之间交流，观点不能“互相讨论”。"}, "sentence_index": 6, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的看法高度对立，很快就达成了共识。", "explanation": "这里应该用〈一致〉。对立指互相排斥、矛盾，与“很快就达成共识”的语义相反。"}, {"text": "两位同事对立得很默契，工作很顺利。", "explanation": "这里应该用〈配合〉。对立表示互相排斥，不能说“对立得很默契”。"}, {"text": "他和我的脾气对立，我们却相处得很融洽。", "explanation": "这里应该用〈融洽〉。对立指互相排斥、矛盾，不能说脾气对立却相处融洽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两派长期对立面，谁也不让步。", "corrected_sentence": "两派长期对立，谁也不让步。", "error_description": "词形错误：此处应用动词“对立”，不能用名词“对立面”（对立的一方）。多了“面”，句子变成指一方，不再表示双方互相排斥。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两派已经对立三年。", "corrected_sentence": "两派已经对立了三年。", "error_description": "缺少“了”：“已经”后叙述已发生并持续的情况，动词后须加“了”，应说“对立了三年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
