INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用线、绳、带子等材料通过交叉、缠绕等方法制作成物品。", "primary_collocate": null, "pronunciation": "biān zhī chéng", "ipa": "pjɛn˥ ʈʂɻ̩˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "协作与竞争并非二元对立，而是通过游戏机制被编织成动态张力网络。", "target_word": "编织成", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "奶奶把毛线编织成一条长围巾。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把竹子编织成漂亮的篮子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用红绳编织成了一个小手链。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草可以编织成帽子，夏天戴很凉快。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民把细线编织成一张大渔网。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用彩色的带子编织成一块小地毯。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧布条编织成一双拖鞋。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用麦秆编织成小动物，送给孩子们。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的女人们把羊毛编织成厚厚的毛衣。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编织", "label": "原形"}, {"form": "编织成了", "label": "体标"}, {"form": "編織成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用线绳带子等交叉缠绕制作成物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：此处“编织成”为比喻用法，指多个要素交错组成网络，与“动态张力网络”相合，并非本义的用线绳制作物品。"}, {"text": "拆解成", "is_correct": false, "explanation": "语义：“拆解”是拆开、分解，与句中“网络”被构建出来的意思相反。"}, {"text": "切割成", "is_correct": false, "explanation": "语义：“切割”是把东西切开，无法形成网络结构，与“通过游戏机制”的构建义不符。"}, {"text": "烧制成", "is_correct": false, "explanation": "搭配：“烧制”用于陶瓷、砖瓦等，不说烧制成网络。"}], "explanations": {"编织成": "正确：此处“编织成”为比喻用法，指多个要素交错组成网络，与“动态张力网络”相合，并非本义的用线绳制作物品。", "拆解成": "语义：“拆解”是拆开、分解，与句中“网络”被构建出来的意思相反。", "切割成": "语义：“切割”是把东西切开，无法形成网络结构，与“通过游戏机制”的构建义不符。", "烧制成": "搭配：“烧制”用于陶瓷、砖瓦等，不说烧制成网络。"}, "sentence_index": 0, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这团黏土编织成了一只碗。", "explanation": "这里应该用〈烧成〉。黏土要经过烧制才能成为器物，编织只适用于线、绳、条等可以交叉的材料。"}, {"text": "几块玻璃编织成了一扇窗。", "explanation": "这里应该用〈拼成〉。玻璃是硬块，要拼接组合而成，不能用编织的方式制作。"}, {"text": "这块木头编织成了一张桌子。", "explanation": "这里应该用〈做成〉。木头是硬材料，要锯、刨、榫接加工才能做成桌子，编织只适用于线、绳等可以交叉缠绕的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：用彩色的带子交叉编织，可以做成小地毯，符合句意。"}, {"text": "剪成", "is_correct": false, "explanation": "语义：“剪”是用剪刀裁断，带子剪开后无法交叉编成地毯，与句中“编织”的做法不符。"}, {"text": "画成", "is_correct": false, "explanation": "搭配：“画成”用于颜料绘图，不能用带子画成地毯。"}, {"text": "雕成", "is_correct": false, "explanation": "搭配：“雕成”用于木材、石头等硬材料，不用于带子。"}], "explanations": {"编织成": "正确：用彩色的带子交叉编织，可以做成小地毯，符合句意。", "剪成": "语义：“剪”是用剪刀裁断，带子剪开后无法交叉编成地毯，与句中“编织”的做法不符。", "画成": "搭配：“画成”用于颜料绘图，不能用带子画成地毯。", "雕成": "搭配：“雕成”用于木材、石头等硬材料，不用于带子。"}, "sentence_index": 6, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把石头编织成了一个佛像。", "explanation": "这里应该用〈凿成〉。石头是硬材料，要用凿刻的方式雕成佛像，不能编织。"}, {"text": "他把小麦编织成了面粉。", "explanation": "这里应该用〈磨成〉。小麦要经过磨制才能变成面粉，编织的对象必须是线、绳等材料。"}, {"text": "她把橡皮泥编织成了一只小猪。", "explanation": "这里应该用〈捏成〉。橡皮泥是可塑材料，用手捏出造型，不能用编织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明用红绳编织到一个手环。", "corrected_sentence": "小明用红绳编织成一个手环。", "error_description": "错误：“编织到”。正确：“编织成”。结果补语应用“成”表示编织出来的结果，“到”不能表示编织成的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把草绳编织了成一个草垫。", "corrected_sentence": "奶奶把草绳编织成了一个草垫。", "error_description": "错误：“编织了成”。正确：“编织成了”。“了”表示完成，应放在结果补语“成”之后，不能插在“编织”和“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "友好", "is_correct": true, "explanation": "正确：“友好”与“敌对”互为反义，指双方和睦相处、不互相对立。"}, {"text": "高大", "is_correct": false, "explanation": "与“敌对”无反义关系，“高大”只描述体形或规模。"}, {"text": "明亮", "is_correct": false, "explanation": "与“敌对”无反义关系，“明亮”描述光线或颜色。"}, {"text": "安静", "is_correct": false, "explanation": "与“敌对”无反义关系，“安静”描述声音或环境的状态。"}], "correct_answer": "友好", "explanations": {"友好": "正确：“友好”与“敌对”互为反义，指双方和睦相处、不互相对立。", "高大": "与“敌对”无反义关系，“高大”只描述体形或规模。", "明亮": "与“敌对”无反义关系，“明亮”描述光线或颜色。", "安静": "与“敌对”无反义关系，“安静”描述声音或环境的状态。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指双方因利益、立场等不同而相互对立、仇视。", "primary_collocate": null, "pronunciation": "dí duì", "ipa": "ti˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "敌对", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国的关系一直很敌对。", "target_word": "敌对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两家公司立场不同，态度很敌对。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是敌对的两派，从不来往。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌对的双方终于坐下来谈判了。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对新来的同事很敌对，总是不理他。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个敌对的国家都不想先开口说话。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板和员工不应该这么敌对。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌对的两队球迷在街上吵了起来。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家和邻国的敌对状态已经结束了。", "target_word": "敌对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵對", "label": "繁体"}, {"form": "敌对势力", "label": "复合"}, {"form": "敌对状态", "label": "复合"}], "register": "中性", "sense_fingerprint": "敌对：双方因利益立场不同而对立仇视（形容状态或关系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敌对", "is_correct": true, "explanation": "正确：“敌对公会”指互相仇视、对立的公会，与“厮杀”的语境一致。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好公会”与后文“竞技场厮杀”相矛盾，友好的团体不会厮杀。"}, {"text": "中立", "is_correct": false, "explanation": "语义：“中立”指不偏向任何一方，与“厮杀”的对立关系不符。"}, {"text": "和睦", "is_correct": false, "explanation": "语义：“和睦”指彼此和气，与“竞技场厮杀”的敌对语境相矛盾。"}], "explanations": {"敌对": "正确：“敌对公会”指互相仇视、对立的公会，与“厮杀”的语境一致。", "友好": "语义：“友好公会”与后文“竞技场厮杀”相矛盾，友好的团体不会厮杀。", "中立": "语义：“中立”指不偏向任何一方，与“厮杀”的对立关系不符。", "和睦": "语义：“和睦”指彼此和气，与“竞技场厮杀”的敌对语境相矛盾。"}, "sentence_index": 0, "correct_answer": "敌对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种理论完全敌对，不能同时成立。", "explanation": "这里应该用〈对立〉。敌对多指人、国家、团体之间的仇视关系，理论或观点之间应说对立。"}, {"text": "两家超市在价格上敌对，谁也不肯让步。", "explanation": "这里应该用〈竞争〉。价格上的较量是竞争，敌对强调双方仇视对立的关系。"}, {"text": "两队在决赛中敌对，但赛后关系一直很友好。", "explanation": "这里应该用〈对抗〉。比赛中的较量叫对抗，敌对指长期仇视，与“关系一直很友好”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敌对", "is_correct": true, "explanation": "正确：“敌对的国家”指双方对立、不想交往，与“都不想先开口说话”一致。"}, {"text": "融洽", "is_correct": false, "explanation": "语义：“融洽”指关系和睦，与“都不想先开口说话”的冷淡语境相矛盾。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”指关系密切，与“都不想先开口说话”的冷淡语境相矛盾。"}, {"text": "和谐", "is_correct": false, "explanation": "语义：“和谐”指协调融洽，双方都不愿开口的状况与之不符。"}], "explanations": {"敌对": "正确：“敌对的国家”指双方对立、不想交往，与“都不想先开口说话”一致。", "融洽": "语义：“融洽”指关系和睦，与“都不想先开口说话”的冷淡语境相矛盾。", "亲近": "语义：“亲近”指关系密切，与“都不想先开口说话”的冷淡语境相矛盾。", "和谐": "语义：“和谐”指协调融洽，双方都不愿开口的状况与之不符。"}, "sentence_index": 6, "correct_answer": "敌对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司正在敌对，共同开发新产品。", "explanation": "这里应该用〈合作〉。共同开发是合作行为，敌对表示双方对立，两者语义相反。"}, {"text": "两人在会议上为一个小问题敌对，很快就平息了。", "explanation": "这里应该用〈争执〉。一时的小争吵用争执，敌对指长期的对立关系。"}, {"text": "两位同事在项目上敌对，可是关系一直很好。", "explanation": "这里应该用〈分歧〉。敌对指仇视的对立关系，意见不合不能说敌对，且与“关系一直很好”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个敌对地公司正在打官司。", "corrected_sentence": "两个敌对的公司正在打官司。", "error_description": "错误：“敌对地”。正确：“敌对的”。“敌对”修饰名词时要用“的”，不用“地”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个邻国之间的敌对地状态终于结束了。", "corrected_sentence": "两个邻国之间的敌对状态终于结束了。", "error_description": "错误：“敌对地状态”。正确：“敌对状态”。“敌对”修饰名词时不加“地”，“地”用于修饰动词；“敌对状态”是复合词，中间不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由相同职业或兴趣的人组成的组织。", "primary_collocate": null, "pronunciation": "gōng huì", "ipa": "kʊŋ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "公会", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "玩家自发形成 guild（公会）、clan（氏族），制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "公会", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他加入了一个作家公会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行业公会帮会员争取更高的收入。", "target_word": "公会", "complexity_tier": "T3", "furigana": "zhè ge háng yè gōng huì bāng huì yuán zhēng qǔ gèng gāo de shōu rù", "sentence_source": "generated"}, {"text": "老李是木匠公会的会长。", "target_word": "公会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个月公会都会开一次会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想做这一行，先要加入当地的公会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公会给会员提供培训和帮助。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐家公会今天办了一场音乐会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人们成立公会，保护自己的生意。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "公會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公会：同行业或同兴趣的人组成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公会", "is_correct": true, "explanation": "正确：“敌对公会”指游戏中互相对抗的玩家团体，与“竞技场厮杀”“合作采矿”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“敌对”说的是立场对立的人或势力，天气没有立场，不能被“敌对”修饰。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：“敌对”修饰的是团体或势力，不能修饰“饭馆”这类场所。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，与“竞技场厮杀”的语境毫不相干。"}], "explanations": {"公会": "正确：“敌对公会”指游戏中互相对抗的玩家团体，与“竞技场厮杀”“合作采矿”的语境相符。", "天气": "语义：“敌对”说的是立场对立的人或势力，天气没有立场，不能被“敌对”修饰。", "饭馆": "搭配：“敌对”修饰的是团体或势力，不能修饰“饭馆”这类场所。", "书包": "语义：书包是装东西的袋子，与“竞技场厮杀”的语境毫不相干。"}, "sentence_index": 0, "correct_answer": "公会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几个国家为了共同的利益结成了公会。", "explanation": "这里应该用〈联盟〉。国家之间结成的组织叫联盟；公会指同行业或同兴趣的人组成的组织，不能用于国家。"}, {"text": "我每周末去健身公会洗衣服。", "explanation": "这里应该用〈洗衣店〉。洗衣服要去洗衣店；公会指同兴趣的人组成的组织，不是洗衣的地方。"}, {"text": "草原上的公会每天一起捕猎。", "explanation": "这里应该用〈狼群〉。狼群是动物结成的群体；公会指同行业或同兴趣的人组成的组织，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公会", "is_correct": true, "explanation": "正确：“加入当地的公会”指加入同行业的团体，与“想做这一行”的语境相符。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“加入”要搭配组织或团体，宿舍是居住的房子，不能被“加入”。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“加入”不能用于考试，应说“参加考试”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用的器具，不是团体，不能被“加入”。"}], "explanations": {"公会": "正确：“加入当地的公会”指加入同行业的团体，与“想做这一行”的语境相符。", "宿舍": "搭配：“加入”要搭配组织或团体，宿舍是居住的房子，不能被“加入”。", "考试": "搭配：“加入”不能用于考试，应说“参加考试”。", "乐器": "语义：乐器是演奏用的器具，不是团体，不能被“加入”。"}, "sentence_index": 6, "correct_answer": "公会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公会每年生产十万台电脑。", "explanation": "这里应该用〈公司〉。生产产品是公司的业务；公会是同行业或同兴趣的人组成的团体，不从事生产。"}, {"text": "工人们在公会里搬运水泥。", "explanation": "这里应该用〈工地〉。搬运水泥要在工地进行；公会是同行业或同兴趣的人组成的组织，不是施工场所。"}, {"text": "公会上大家回忆了小学时的老师。", "explanation": "这里应该用〈同学会〉。回忆小学老师是同学之间的事；公会指同行业或同兴趣的人组成的组织，不指同学关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "木匠们组成了一只公会，互相交流手艺。", "corrected_sentence": "木匠们组成了一个公会，互相交流手艺。", "error_description": "错误：公会的量词应为“个”，“只”用于动物或成对物品之一。正确形式：“一个公会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于成立了一个的公会。", "corrected_sentence": "他们终于成立了一个公会。", "error_description": "错误：数量短语“一个”后多加了“的”。正确形式：“一个公会”。数量短语直接修饰名词，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
