INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指进行比赛、竞争或表演的专用场地。", "primary_collocate": null, "pronunciation": "jìng jì chǎng", "ipa": "tɕiŋ˥˩ tɕi˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "竞技场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座竞技场可以坐五万个观众。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古罗马的竞技场到现在还在。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员走进竞技场，观众都站起来了。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末竞技场里有一场篮球比赛。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "竞技场的灯一亮，比赛就要开始了。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐地铁去市中心的竞技场看比赛。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次站在竞技场中间，非常紧张。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新竞技场花了三年才建好。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在竞技场里准备明天的表演。", "target_word": "竞技场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "競技場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "竞技场：比赛、竞争或表演的专用场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd87c58c-09f6-4d3a-99ac-19363ee6c39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞技场", "is_correct": true, "explanation": "正确：“竞技场厮杀”指在专用场地里的战斗，与“敌对公会”“排行榜”的语境相符。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是吃饭用的桌子，不能用来厮杀。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与厮杀无关。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“厮杀”不能在图书馆里发生，图书馆与之不搭配。"}], "explanations": {"竞技场": "正确：“竞技场厮杀”指在专用场地里的战斗，与“敌对公会”“排行榜”的语境相符。", "饭桌": "语义：饭桌是吃饭用的桌子，不能用来厮杀。", "厨房": "语义：厨房是做饭的地方，与厮杀无关。", "图书馆": "搭配：“厮杀”不能在图书馆里发生，图书馆与之不搭配。"}, "sentence_index": 0, "correct_answer": "竞技场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "竞技场里摆着一张大床。", "explanation": "这里应该用〈卧室〉。床要放在卧室里；竞技场是专用于比赛或表演的场地，不放床。"}, {"text": "竞技场的书架上摆满了小说。", "explanation": "这里应该用〈图书馆〉。书架和小说是图书馆里的东西；竞技场是专用于比赛或表演的场地。"}, {"text": "竞技场里挂着很多锅碗。", "explanation": "这里应该用〈厨房〉。锅碗挂在厨房里；竞技场是专用于比赛或表演的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞技场", "is_correct": true, "explanation": "正确：竞技场是专用于比赛的场地，“去市中心的竞技场看比赛”符合语境。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买菜的地方，不是看比赛的场所。"}, {"text": "加油站", "is_correct": false, "explanation": "搭配：“看比赛”的地点应是比赛场馆，加油站不能与之搭配。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不是比赛场所，无法用来看比赛。"}], "explanations": {"竞技场": "正确：竞技场是专用于比赛的场地，“去市中心的竞技场看比赛”符合语境。", "菜市场": "语义：菜市场是买菜的地方，不是看比赛的场所。", "加油站": "搭配：“看比赛”的地点应是比赛场馆，加油站不能与之搭配。", "厕所": "语义：厕所不是比赛场所，无法用来看比赛。"}, "sentence_index": 6, "correct_answer": "竞技场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在竞技场里洗衣服。", "explanation": "这里应该用〈洗衣房〉。洗衣服要去洗衣房；竞技场是专用于比赛或表演的场地。"}, {"text": "老师在竞技场里讲课。", "explanation": "这里应该用〈教室〉。讲课要在教室里进行；竞技场是专用于比赛或表演的场地。"}, {"text": "他们在竞技场里养了一群鸡。", "explanation": "这里应该用〈农场〉。养鸡要在农场；竞技场是专用于比赛或表演的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里新建了一只大型竞技场。", "corrected_sentence": "城里新建了一座大型竞技场。", "error_description": "错误：“竞技场”的量词应用“座”，不能用“只”（“只”多用于动物等）。正确形式：“一座大型竞技场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们终于把竞技场打扫干净。", "corrected_sentence": "工人们终于把竞技场打扫干净了。", "error_description": "错误：缺少“了”。把字句表示已完成的动作，句末应加“了”，应说“把竞技场打扫干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fa3d241-5fec-4a1a-b457-3365b82e151e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
