INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方激烈地互相攻击、拼杀，常指战斗或竞争中的激烈对抗。", "primary_collocate": null, "pronunciation": "sī shā", "ipa": "sɹ̩˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "厮杀", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两家公司在市场上厮杀了三年。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了抢第一名，选手们在赛场上拼命厮杀。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机行业的价格战让各品牌厮杀得很激烈。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队在决赛中厮杀到最后一分钟。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了抢客人，这些小店在街上拼命厮杀。", "target_word": "厮杀", "complexity_tier": "T3", "furigana": "wèi le qiǎng kè rén, zhè xiē xiǎo diàn zài jiē shang pīn mìng sī shā.", "sentence_source": "generated"}, {"text": "好多人抢一个工作，面试像在厮杀。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个电商平台在节日大促中厮杀了一整天。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司不想和大企业在低价市场厮杀。", "target_word": "厮杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战场上，两军厮杀了一整夜。", "target_word": "厮杀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "厮杀了", "label": "体标：了"}, {"form": "厮杀着", "label": "体标：着"}, {"form": "厮杀过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "双方在战斗或竞争中激烈对抗、拼杀", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结盟", "is_correct": false, "explanation": "语义：“结盟”是联合，与“敌对公会”的对立关系相反。"}, {"text": "厮杀", "is_correct": true, "explanation": "正确：“厮杀”表示激烈对抗，与“敌对公会”的竞技场语境相符。"}, {"text": "合作", "is_correct": false, "explanation": "语义：“合作”与“敌对公会”的对立关系矛盾，且后文已用“合作采矿”，重复且语义冲突。"}, {"text": "散步", "is_correct": false, "explanation": "语义：竞技场是对抗场所，“散步”悠闲，与“敌对公会”的竞技对抗不符。"}], "explanations": {"结盟": "语义：“结盟”是联合，与“敌对公会”的对立关系相反。", "厮杀": "正确：“厮杀”表示激烈对抗，与“敌对公会”的竞技场语境相符。", "合作": "语义：“合作”与“敌对公会”的对立关系矛盾，且后文已用“合作采矿”，重复且语义冲突。", "散步": "语义：竞技场是对抗场所，“散步”悠闲，与“敌对公会”的竞技对抗不符。"}, "sentence_index": 0, "correct_answer": "厮杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夫妻俩在厨房里互相厮杀，又互相夸对方的厨艺。", "explanation": "这里应该用〈互相夸奖〉。“厮杀”表示激烈对抗，与互相夸奖的场面矛盾。"}, {"text": "顾客和摊主热情寒暄，厮杀了半天。", "explanation": "这里应该用〈寒暄〉。“厮杀”表示激烈对抗，与热情寒暄的气氛相反。"}, {"text": "两位同事在会议室里厮杀，一起完成了报告。", "explanation": "这里应该用〈配合〉。“厮杀”表示激烈对抗，同事共同完成报告时要用“配合”，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合唱", "is_correct": false, "explanation": "语义：“合唱”是和谐的集体活动，与“好多人抢一个工作”的竞争气氛冲突。"}, {"text": "厮杀", "is_correct": true, "explanation": "正确：“厮杀”表示激烈对抗，与抢工作的竞争场面相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”悠闲，与“好多人抢一个工作”的紧张气氛不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：用“唱歌”来比喻面试不自然，与“抢一个工作”的语境不搭配。"}], "explanations": {"合唱": "语义：“合唱”是和谐的集体活动，与“好多人抢一个工作”的竞争气氛冲突。", "厮杀": "正确：“厮杀”表示激烈对抗，与抢工作的竞争场面相符。", "散步": "语义：“散步”悠闲，与“好多人抢一个工作”的紧张气氛不符。", "唱歌": "搭配：用“唱歌”来比喻面试不自然，与“抢一个工作”的语境不搭配。"}, "sentence_index": 6, "correct_answer": "厮杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位老教授在书房里共同撰写论文，厮杀了三个月。", "explanation": "这里应该用〈合著〉。“厮杀”表示激烈对抗，两人共同撰写论文时要用“合著”，两者语义相反。"}, {"text": "几位朋友在咖啡馆里聊得很开心，厮杀了一下午。", "explanation": "这里应该用〈聊天〉。“厮杀”表示激烈对抗，与开心闲聊的气氛相反。"}, {"text": "老朋友久别重逢，在车站厮杀起来。", "explanation": "这里应该用〈拥抱〉。“厮杀”表示互相攻击，久别重逢的老友之间不用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两支队伍厮杀异常激烈。", "corrected_sentence": "两支队伍厮杀得异常激烈。", "error_description": "“厮杀”后面带补语“异常激烈”时要用“得”连接，应说“厮杀得异常激烈”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在市场上厮杀着两次。", "corrected_sentence": "我们在市场上厮杀过两次。", "error_description": "体标“着”表示动作持续，不能用于计次；表示次数时要用“过”，应说“厮杀过两次”，把“着”改为“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
