INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12009, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开采地下埋藏的矿物。", "primary_collocate": null, "pronunciation": "cǎi kuàng", "ipa": "tsʰai˨˩ kʰwaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "采矿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他爸爸在山里的矿区采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山上不许采矿。", "target_word": "采矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们戴着帽子进洞采矿。", "target_word": "采矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "采矿会破坏山上的树和水。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方的煤很多，很多人来这里采矿。", "target_word": "采矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们用手工具采矿，现在用大机器。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家要求公司采矿时保护环境。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打算明年在北方山区采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天太危险，工人们今天不去采矿。", "target_word": "采矿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采了矿", "label": "体标：了"}, {"form": "采着矿", "label": "体标：着"}, {"form": "采过矿", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "开采地下埋藏的矿物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝茶", "is_correct": false, "explanation": "语义：资源区里开采的是矿，“喝茶”与开采的场景完全不符，合作喝茶不成立。"}, {"text": "采矿", "is_correct": true, "explanation": "正确：“采矿”与资源区和游戏中的开采语境相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“合作烹饪”不能用于资源区的采集活动，搭配不当。"}, {"text": "读书", "is_correct": false, "explanation": "语义：“读书”与资源区的矿产开采毫不相关，语境冲突。"}], "explanations": {"喝茶": "语义：资源区里开采的是矿，“喝茶”与开采的场景完全不符，合作喝茶不成立。", "采矿": "正确：“采矿”与资源区和游戏中的开采语境相符。", "烹饪": "搭配：“合作烹饪”不能用于资源区的采集活动，搭配不当。", "读书": "语义：“读书”与资源区的矿产开采毫不相关，语境冲突。"}, "sentence_index": 0, "correct_answer": "采矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石油公司在海上采矿石油。", "explanation": "这里应该用〈开采〉。“采矿”专指挖掘固体矿物，石油、天然气等要用“开采”。"}, {"text": "孩子们在树林里采矿蘑菇。", "explanation": "这里应该用〈采集〉。“采矿”指从地下挖掘矿物，采蘑菇、草药要用“采集”。"}, {"text": "考古队在遗址里采矿文物。", "explanation": "这里应该用〈挖掘〉。“采矿”的对象是矿物，出土文物要用“挖掘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：用手工具唱歌不成立，与“用手工具”的生产语境不符。"}, {"text": "采矿", "is_correct": true, "explanation": "正确：“采矿”指用工具挖掘矿物，与“用手工具”和“现在用大机器”的对比相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步不借助手工具，与“以前人们用……，现在用大机器”的生产语境不符。"}, {"text": "下棋", "is_correct": false, "explanation": "配价：“下棋”的对象是棋，单独说“用手工具下棋”不完整，也不成立。"}], "explanations": {"唱歌": "语义：用手工具唱歌不成立，与“用手工具”的生产语境不符。", "采矿": "正确：“采矿”指用工具挖掘矿物，与“用手工具”和“现在用大机器”的对比相符。", "散步": "语义：散步不借助手工具，与“以前人们用……，现在用大机器”的生产语境不符。", "下棋": "配价：“下棋”的对象是棋，单独说“用手工具下棋”不完整，也不成立。"}, "sentence_index": 6, "correct_answer": "采矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民们在田里采矿玉米，忙了一早上。", "explanation": "这里应该用〈收割〉。“采矿”指开采地下埋藏的矿物，从田里收玉米要用“收割”。"}, {"text": "渔民们在海上采矿，收获很多。", "explanation": "这里应该用〈捕捞〉。“采矿”的对象是地下矿物，在海里捞鱼要用“捕捞”。"}, {"text": "村民们在井边采矿，装满了水桶。", "explanation": "这里应该用〈取水〉。“采矿”指挖掘矿物，从井里打水要用“取水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "矿工们每天在深井里采矿了。", "corrected_sentence": "矿工们每天在深井里采矿。", "error_description": "“每天”表示习惯性动作，要说“每天在深井里采矿”，动词后不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们今天在井下采了次矿。", "corrected_sentence": "工人们今天在井下采了一次矿。", "error_description": "次数短语的“次”前必须有数词，应说“采了一次矿”；“采了次矿”缺少数词“一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
