INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在同一领域或活动中相互竞争的人或组织。", "primary_collocate": null, "pronunciation": "jìng zhēng duì shǒu", "ipa": "tɕiŋ˥˩ tʂɤŋ˥ tweɪ˥˩ ʂoʊ˨˩", "syllable_count": 4, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "竞争对手", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司最大的竞争对手是谁？", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家饭店是多年的竞争对手。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了打败竞争对手，他们降低了价格。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王和我做同一行，是竞争对手。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先了解竞争对手，再做新计划。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的竞争对手也是一家大公司。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "竞争对手推出了新手机，我们的压力很大。", "target_word": "竞争对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生意场上，竞争对手有时也能合作。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板常说，不要小看任何竞争对手。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个竞争对手", "label": "量词：个"}, {"form": "一位竞争对手", "label": "量词：位"}, {"form": "一家竞争对手", "label": "量词：家"}], "register": "中性", "sense_fingerprint": "同一领域中相互竞争的人或组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": true, "explanation": "正确：句中指在排行榜上剑拔弩张、相互争胜的对象，与前半句的厮杀和后半句的对立相符。"}, {"text": "合作伙伴", "is_correct": false, "explanation": "语义：“合作伙伴”指一起合作的人，与“剑拔弩张”的对立情绪矛盾。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判负责评判，不参与争胜，与“剑拔弩张”的对立情绪不符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众只看不比，不会在排行榜上互相争胜，与句意不符。"}], "explanations": {"竞争对手": "正确：句中指在排行榜上剑拔弩张、相互争胜的对象，与前半句的厮杀和后半句的对立相符。", "合作伙伴": "语义：“合作伙伴”指一起合作的人，与“剑拔弩张”的对立情绪矛盾。", "裁判": "语义：裁判负责评判，不参与争胜，与“剑拔弩张”的对立情绪不符。", "观众": "语义：观众只看不比，不会在排行榜上互相争胜，与句意不符。"}, "sentence_index": 0, "correct_answer": "竞争对手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的竞争对手，每天给我安排工作。", "explanation": "这里应该用〈老板〉。竞争对手是在同一领域争取同一目标的一方，不会给我安排工作；管理下属、安排工作的是〈老板〉。"}, {"text": "这位竞争对手负责判案，大家都很信任他。", "explanation": "这里应该用〈法官〉。竞争对手是在同一领域争取同一目标的一方，不负责判案；负责判案的是〈法官〉。"}, {"text": "我的竞争对手每天检查我的作业。", "explanation": "这里应该用〈家长〉。竞争对手与我争取同一目标，不会检查我的作业；检查作业的是〈家长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": true, "explanation": "正确：句中指与她的公司同行、相互竞争的对象，与“也是一家大公司”相符。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：女儿是家人，不是公司，不能说她“也是一家大公司”。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“一家”只搭配公司、饭店等机构，不搭配老师。"}, {"text": "同事", "is_correct": false, "explanation": "语义：同事是人，句中说的是公司之间的关系，同事不能是一家公司。"}], "explanations": {"竞争对手": "正确：句中指与她的公司同行、相互竞争的对象，与“也是一家大公司”相符。", "女儿": "语义：女儿是家人，不是公司，不能说她“也是一家大公司”。", "老师": "搭配：“一家”只搭配公司、饭店等机构，不搭配老师。", "同事": "语义：同事是人，句中说的是公司之间的关系，同事不能是一家公司。"}, "sentence_index": 6, "correct_answer": "竞争对手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一条竞争对手实力很强。", "explanation": "量词：〈条〉用于长条形的东西。竞争对手指人或组织，这里应该用〈个〉或〈家〉。"}, {"text": "那只竞争对手很厉害。", "explanation": "量词：〈只〉多用于动物或成对的东西。竞争对手指人或组织，这里应该用〈个〉。"}, {"text": "这块竞争对手很强大。", "explanation": "量词：〈块〉用于块状的东西。竞争对手指人或组织，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们有三个竞争对手们。", "corrected_sentence": "我们有三个竞争对手。", "error_description": "错误：“竞争对手”前有数量词“三个”，后面不能再加“们”。应说“三个竞争对手”，不说“三个竞争对手们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有三本竞争对手。", "corrected_sentence": "我们班有三个竞争对手。", "error_description": "量词错误：“竞争对手”指人或组织，量词应用“个”，不用“本”（“本”用于书籍等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
