INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "排行榜是用于展示事物按照某种标准（如销量、热度、成绩等）排列顺序的名单。", "primary_collocate": null, "pronunciation": "pái háng bǎng", "ipa": "pʰai˧˥ xɑŋ˧˥ pɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "排行榜", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌上周排在排行榜第一名。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字出现在排行榜的前三名。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期，网站都会更新游戏排行榜。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看今年的电影票房排行榜。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书进了畅销书排行榜。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排行榜上的第一名是一个新玩家。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都看排行榜，想知道自己排第几。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，排行榜马上就变了。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排行榜按销量排列，卖得最多的在最前面。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "按销量、热度、成绩等标准排序展示的名单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排行榜", "is_correct": true, "explanation": "正确：句中指竞争对手在上面较量名次的名单，与“剑拔弩张”相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板只是书写板，不是按成绩排列名次的名单，与竞争对手在上面争胜的语境不符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录做法，不记录对手的排名。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“剑拔弩张”形容对峙的紧张，不能与墙壁搭配。"}], "explanations": {"排行榜": "正确：句中指竞争对手在上面较量名次的名单，与“剑拔弩张”相符。", "黑板": "语义：黑板只是书写板，不是按成绩排列名次的名单，与竞争对手在上面争胜的语境不符。", "菜谱": "语义：菜谱记录做法，不记录对手的排名。", "墙壁": "搭配：“剑拔弩张”形容对峙的紧张，不能与墙壁搭配。"}, "sentence_index": 0, "correct_answer": "排行榜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个星期，网站都会更新游戏排行榜的价格。", "explanation": "这里应该用〈价目表〉。排行榜按成绩排名，不标价格；标价格的是〈价目表〉。"}, {"text": "每个星期，网站都会更新这座游戏排行榜。", "explanation": "量词：〈座〉用于山、楼房等大型固定物，排行榜是名单，这里应该用〈个〉。"}, {"text": "每个星期，网站都会更新那块游戏排行榜。", "explanation": "量词：〈块〉用于块状的东西，排行榜是名单，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排行榜", "is_correct": true, "explanation": "正确：句中指新玩家排在首位的名单，与“第一名”相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包用来装东西，不能显示名次。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不能排列名次，句中也没有名单的意思。"}, {"text": "水杯", "is_correct": false, "explanation": "搭配：“上的第一名”要求能排列名次的载体，“水杯”不能与之搭配。"}], "explanations": {"排行榜": "正确：句中指新玩家排在首位的名单，与“第一名”相符。", "书包": "语义：书包用来装东西，不能显示名次。", "鞋子": "语义：鞋子不能排列名次，句中也没有名单的意思。", "水杯": "搭配：“上的第一名”要求能排列名次的载体，“水杯”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "排行榜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是这个月的水费排行榜，我要按时付钱。", "explanation": "这里应该用〈账单〉。账单是要按时付钱的单据，排行榜只是按标准排列顺序的名单，不能用来付钱。"}, {"text": "这次比赛他拿了一个好排行榜。", "explanation": "这里应该用〈名次〉。“拿到”搭配的是名次；排行榜是名单，不能说“拿了一个排行榜”。"}, {"text": "这本书的排行榜告诉我们每一章的页码。", "explanation": "这里应该用〈目录〉。目录按顺序列出章节和页码；排行榜按标准排列名次，不列章节和页码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网站每个星期发布三条排行榜。", "corrected_sentence": "网站每个星期发布三个排行榜。", "error_description": "量词错误：“排行榜”是名单，量词应用“个”，不用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的名字出现在排行榜的上。", "corrected_sentence": "他的名字出现在排行榜上。", "error_description": "位置错误：方位词“上”应直接接在“排行榜”后，说“排行榜上”，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
