INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12012, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容双方冲突或紧张对峙，一触即发的状态。", "primary_collocate": null, "pronunciation": "jiàn bá nǔ zhāng", "ipa": "tɕjɛn˥˩ pa˧˥ nu˨˩˦ ʈʂɑŋ˥˥", "syllable_count": 4, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "剑拔弩张", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "开会时，两个人剑拔弩张，谁也不说话。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队比赛前，现场的气氛剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了钱吵架，场面剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，双方的关系变得剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室里剑拔弩张，大家都不敢出声。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国边境的局势一度剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理一来，剑拔弩张的气氛才慢慢缓和。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，两支球队就剑拔弩张。", "target_word": "剑拔弩张", "complexity_tier": "T3", "furigana": "bǐ sài yī kāi shǐ , liǎng zhī qiú duì jiù jiàn bá nǔ zhāng .", "sentence_source": "generated"}, {"text": "他们见面时总是剑拔弩张，像要打架。", "target_word": "剑拔弩张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劍拔弩張", "label": "繁体"}], "register": "书面", "sense_fingerprint": "双方对峙、冲突一触即发的紧张状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剑拔弩张", "is_correct": true, "explanation": "剑拔弩张形容双方紧张对峙，与排行榜上竞争对手的关系相符。"}, {"text": "亲密无间", "is_correct": false, "explanation": "语义：“亲密无间”形容关系非常密切，与“竞争对手”的身份矛盾。"}, {"text": "风和日丽", "is_correct": false, "explanation": "搭配：“风和日丽”形容天气，不能用来形容排行榜上竞争者的状态。"}, {"text": "悠然自得", "is_correct": false, "explanation": "语义：“悠然自得”形容从容安闲，与前文“竞争”的紧张关系不合。"}], "explanations": {"剑拔弩张": "剑拔弩张形容双方紧张对峙，与排行榜上竞争对手的关系相符。", "亲密无间": "语义：“亲密无间”形容关系非常密切，与“竞争对手”的身份矛盾。", "风和日丽": "搭配：“风和日丽”形容天气，不能用来形容排行榜上竞争者的状态。", "悠然自得": "语义：“悠然自得”形容从容安闲，与前文“竞争”的紧张关系不合。"}, "sentence_index": 0, "correct_answer": "剑拔弩张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们在公园野餐，大家剑拔弩张地聊着天。", "explanation": "“剑拔弩张”指双方紧张对峙、一触即发，用在轻松的野餐场合与词义相反。"}, {"text": "得知考试成绩的那天，我一个人心里剑拔弩张。", "explanation": "这里应该用〈紧张〉。剑拔弩张描述双方之间的对峙，不用来形容一个人心里的紧张。"}, {"text": "湖面剑拔弩张，映着天空。", "explanation": "这里应该用〈平静〉。剑拔弩张只描述人与人之间的对峙，不能用来形容湖面这样的自然景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剑拔弩张", "is_correct": true, "explanation": "剑拔弩张形容双方对峙、一触即发，与“一度”所描述的紧张局势相符。"}, {"text": "心平气和", "is_correct": false, "explanation": "搭配：“心平气和”形容人的态度，不能用来形容两国边境的局势。"}, {"text": "无忧无虑", "is_correct": false, "explanation": "搭配：“无忧无虑”形容人的心境，不能用于描写局势。"}, {"text": "和风细雨", "is_correct": false, "explanation": "语义：“和风细雨”比喻温和的做法，与边境局势的紧张相矛盾。"}], "explanations": {"剑拔弩张": "剑拔弩张形容双方对峙、一触即发，与“一度”所描述的紧张局势相符。", "心平气和": "搭配：“心平气和”形容人的态度，不能用来形容两国边境的局势。", "无忧无虑": "搭配：“无忧无虑”形容人的心境，不能用于描写局势。", "和风细雨": "语义：“和风细雨”比喻温和的做法，与边境局势的紧张相矛盾。"}, "sentence_index": 6, "correct_answer": "剑拔弩张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位老师在讲台上剑拔弩张地讲解课文。", "explanation": "这里应该用〈从容〉。剑拔弩张指双方紧张对峙、一触即发，不能用来形容老师平和地讲课。"}, {"text": "两位老人聊天时剑拔弩张。", "explanation": "这里应该用〈和气〉。剑拔弩张描述冲突对峙，老人聊天的温和场面与词义相反。"}, {"text": "两个老朋友见面，剑拔弩张地拥抱在一起。", "explanation": "剑拔弩张描述对峙冲突，老朋友见面拥抱表示亲近，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司的谈判一度剑拔弩张地，后来才慢慢缓和。", "corrected_sentence": "两家公司的谈判一度剑拔弩张，后来才慢慢缓和。", "error_description": "错误：“剑拔弩张”作谓语时后面不能加“地”，“地”只用在动词前作状语。正确说法是“谈判一度剑拔弩张，后来才慢慢缓和”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "剑拔弩张地会场里，没有人说话。", "corrected_sentence": "剑拔弩张的会场里，没有人说话。", "error_description": "错误：“剑拔弩张”修饰名词“会场”时要用“的”，不能用“地”。正确应为“剑拔弩张的会场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
