INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12013, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互联网上供用户围绕特定话题发布信息、交流讨论的虚拟平台。", "primary_collocate": null, "pronunciation": "shè qū lùn tán", "ipa": "ʂɤ˥˩ tɕʰy˥˥ lwən˥˩ tʰan˧˥", "syllable_count": 4, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "社区论坛", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我常在社区论坛上回答新手的问题。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区有自己的社区论坛。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在社区论坛发了一个帖子。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区论坛里的网友都很热心。", "target_word": "社区论坛", "complexity_tier": "T3", "furigana": "shèqū lùntán lǐ de wǎngyǒu dōu hěn rèxīn .", "sentence_source": "generated"}, {"text": "想找二手家具，可以先看社区论坛。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员删除了社区论坛里的广告。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在社区论坛认识了很多朋友。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区论坛每天都有新话题。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在社区论坛讨论停车的问题。", "target_word": "社区论坛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "社區論壇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "网上围绕话题发帖交流的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ce11b3-a076-4ef4-a0b4-1773df363eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社区论坛", "is_correct": true, "explanation": "社区论坛是网上供人交流的平台，正适合共享战术心得。"}, {"text": "竞技场", "is_correct": false, "explanation": "语义：竞技场是厮杀对战的地方，与“共享心得”的合作语境相反。"}, {"text": "排行榜", "is_correct": false, "explanation": "搭配：排行榜只显示名次，不能作为共享心得的场所。"}, {"text": "矿区", "is_correct": false, "explanation": "语义：矿区是采矿的地方，不是交流心得的平台。"}], "explanations": {"社区论坛": "社区论坛是网上供人交流的平台，正适合共享战术心得。", "竞技场": "语义：竞技场是厮杀对战的地方，与“共享心得”的合作语境相反。", "排行榜": "搭配：排行榜只显示名次，不能作为共享心得的场所。", "矿区": "语义：矿区是采矿的地方，不是交流心得的平台。"}, "sentence_index": 0, "correct_answer": "社区论坛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在社区论坛养了一只猫。", "explanation": "这里应该用〈小区〉。社区论坛是网上的交流平台，不是居住的地方，不能在里面养猫。"}, {"text": "他下班后去社区论坛上班。", "explanation": "社区论坛是网络平台，不是工作单位，不能去那里上班。"}, {"text": "他在一把社区论坛上发了一个帖子。", "explanation": "这里应该用〈个〉。社区论坛用“个”作量词，“把”用于椅子、伞等物体，不能修饰论坛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社区论坛", "is_correct": true, "explanation": "社区论坛是网络平台，可以发布广告，符合“删除广告”的语境。"}, {"text": "心理学", "is_correct": false, "explanation": "语义：心理学是一门学科，不是可以放广告的平台。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：应说“黑板上的广告”，“里”一般不用于黑板。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是放广告的地方，“水果里的广告”说不通。"}], "explanations": {"社区论坛": "社区论坛是网络平台，可以发布广告，符合“删除广告”的语境。", "心理学": "语义：心理学是一门学科，不是可以放广告的平台。", "黑板": "搭配：应说“黑板上的广告”，“里”一般不用于黑板。", "水果": "语义：水果不是放广告的地方，“水果里的广告”说不通。"}, "sentence_index": 6, "correct_answer": "社区论坛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在社区论坛排队交停车费。", "explanation": "社区论坛是网络平台，不能排队缴费，把它当成缴费场所是用错了。"}, {"text": "大家坐社区论坛回家。", "explanation": "社区论坛不是交通工具，不能乘坐，这里的用法与词义不符。"}, {"text": "大家在社区论坛的停车场里修车。", "explanation": "这里应该用〈维修厂〉。社区论坛是网上的平台，不是实体场所，不能在里面修车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我社区论坛里跟网友聊了很久。", "corrected_sentence": "我在社区论坛里跟网友聊了很久。", "error_description": "错误：“社区论坛”前漏掉介词“在”。正确说法是“在社区论坛里跟网友聊了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把社区论坛很热闹。", "corrected_sentence": "这个社区论坛很热闹。", "error_description": "错误：“社区论坛”应用量词“个”，“把”用于椅子、伞等有柄的物体，不能修饰论坛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1890f7-5960-4d2d-be19-63d94ee74132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
