INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在战斗或比赛中，为了达到目的而采用的具体方法和策略。", "primary_collocate": null, "pronunciation": "zhàn shù", "ipa": "ʈʂan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "战术", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "教练在黑板上画出了新的战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛，我们的战术很成功。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对手改变战术后，我们很难进球。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们踢球时常用快攻战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练让大家先记住这个战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏需要好的战术，不能只靠运气。", "target_word": "战术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长把比赛的战术讲给大家听。", "target_word": "战术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打篮球时，每个人都要懂战术。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出一种新战术，赢了这场比赛。", "target_word": "战术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "戰術", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "战术板", "label": "复合词"}], "register": "中性", "sense_fingerprint": "比赛或对抗中为取胜而采用的具体方法和策略", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术（zhàn shù）指比赛或对抗中为取胜而采用的具体打法。"}, {"text": "站住", "is_correct": false, "explanation": "zhù 与 shù 声母不同（zh 与 sh），声调相同（第四声），意思是站稳、停下来不动。"}, {"text": "战士", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），声调相同（第四声），意思是士兵。"}, {"text": "战时", "is_correct": false, "explanation": "shí（第二声）与 shù（第四声）韵母和声调都不同，意思是战争时期。"}, {"text": "展示", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，shì 与 shù 韵母不同，意思是展现给别人看。"}], "explanations": {"战术": "正确：战术（zhàn shù）指比赛或对抗中为取胜而采用的具体打法。", "站住": "zhù 与 shù 声母不同（zh 与 sh），声调相同（第四声），意思是站稳、停下来不动。", "战士": "shì 与 shù 韵母不同（i 与 u），声调相同（第四声），意思是士兵。", "战时": "shí（第二声）与 shù（第四声）韵母和声调都不同，意思是战争时期。", "展示": "zhǎn（第三声）与 zhàn（第四声）声调不同，shì 与 shù 韵母不同，意思是展现给别人看。"}, "sentence_index": null, "correct_answer": "战术"}, "level_3": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术指比赛中为取胜采用的具体方法，与“共享……心得”搭配，指交流打法上的经验。"}, {"text": "财富", "is_correct": false, "explanation": "搭配：“财富心得”不成立，心得指经验体会，不能与“财富”搭配，句中也无法成立。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人的医疗记录，与竞技场和排行榜的游戏语境无关。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是可以共享的打法或经验。"}], "explanations": {"战术": "正确：战术指比赛中为取胜采用的具体方法，与“共享……心得”搭配，指交流打法上的经验。", "财富": "搭配：“财富心得”不成立，心得指经验体会，不能与“财富”搭配，句中也无法成立。", "病历": "语义：病历是病人的医疗记录，与竞技场和排行榜的游戏语境无关。", "体温": "语义：体温是身体的温度，不是可以共享的打法或经验。"}, "sentence_index": 0, "correct_answer": "战术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司制定了长远的战术，计划五年内占领东南亚市场。", "explanation": "这里应该用〈战略〉。战术指比赛或作战中的具体打法，长远的总体规划要用战略。"}, {"text": "这位球员的传球战术一脚能踢出三十米。", "explanation": "这里应该用〈力量〉。战术是作战的具体打法，不能用来说踢得多远，这要靠力量。"}, {"text": "我们的战术是拿到冠军。", "explanation": "这里应该用〈目标〉。战术指取胜的具体方法，要达到的结果应说目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战术", "is_correct": true, "explanation": "正确：战术指比赛中为取胜采用的具体方法，与“需要好的……，不能只靠运气”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：游戏的胜负取决于方法而不是天气，“好的天气”不是游戏需要的条件。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物与游戏所需的条件无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“好的颜色”不能作为游戏所需的条件，与“需要”搭配不当。"}], "explanations": {"战术": "正确：战术指比赛中为取胜采用的具体方法，与“需要好的……，不能只靠运气”相符。", "天气": "语义：游戏的胜负取决于方法而不是天气，“好的天气”不是游戏需要的条件。", "食物": "语义：食物与游戏所需的条件无关，句意不通。", "颜色": "搭配：“好的颜色”不能作为游戏所需的条件，与“需要”搭配不当。"}, "sentence_index": 6, "correct_answer": "战术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个角色的战术数值很高，一次能打掉对手一半血。", "explanation": "这里应该用〈攻击力〉。战术是打法和安排，不是可以量化的数值；角色攻击的高低要用攻击力。"}, {"text": "他在游戏里吃掉了战术，血量很快回满了。", "explanation": "这里应该用〈药剂〉。战术是打法和安排，不能吃；能用来补血的是药剂。"}, {"text": "我们的战术领先三分，比赛还剩五分钟。", "explanation": "这里应该用〈比分〉。战术不能用来表示领先几分，比赛中的得分多少要用比分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队这场比赛用了新战术的，很快就赢了。", "corrected_sentence": "我们队这场比赛用了新战术，很快就赢了。", "error_description": "结构错误：句中的「新战术」后面多加了「的」，「战术的」不能直接接逗号，应去掉多余的「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赛前，他们想出了一本新战术。", "corrected_sentence": "赛前，他们想出了一套新战术。", "error_description": "量词错误：“战术”应用量词“套”或“种”计量，“本”用于书册，不能用来计量战术。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
