INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学习和实践中获得的体会、认识。", "primary_collocate": null, "pronunciation": "xīn dé", "ipa": "ɕin˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "玩家在“敌对公会”的竞技场厮杀后，可能在同一资源区合作采矿；竞争对手在排行榜上剑拔弩张，却又在社区论坛共享战术心得。", "target_word": "心得", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "读完这本书，我写了一篇心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把学习汉语的心得告诉了大家。", "target_word": "心得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们交流学习心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想听听你的工作心得。", "target_word": "心得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是我做饭多年的一点心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在网上分享了自己的跑步心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次旅行后，她都会写下心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习心得不用太长，写清楚就行。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了他的心得，我也学到了很多。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "点", "label": "量词"}, {"form": "篇", "label": "量词"}, {"form": "学习心得", "label": "复合词"}, {"form": "心得体会", "label": "复合词"}], "register": "中性", "sense_fingerprint": "学习或做事之后得到的体会和认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心得", "is_correct": true, "explanation": "正确：心得指学习或实践后得到的体会，“共享……心得”指交流打法上的体会。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”是入场凭证，不能与“心得”构成可以共享的体会，“门票心得”不成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是可以共享的体会。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人的医疗记录，与竞技场和排行榜的游戏语境无关。"}], "explanations": {"心得": "正确：心得指学习或实践后得到的体会，“共享……心得”指交流打法上的体会。", "门票": "搭配：“门票”是入场凭证，不能与“心得”构成可以共享的体会，“门票心得”不成立。", "体温": "语义：体温是身体的温度，不是可以共享的体会。", "病历": "语义：病历是病人的医疗记录，与竞技场和排行榜的游戏语境无关。"}, "sentence_index": 0, "correct_answer": "心得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天早上他的心得很好。", "explanation": "这里应该用〈心情〉。心得指学习或实践后得到的体会，不用来形容情绪。"}, {"text": "他在草原上度过的心得很特别，我们都很羡慕。", "explanation": "这里应该用〈经历〉。心得是对学习或实践的认识，不能说“在草原上度过”；亲身经过的事要用经历。"}, {"text": "他的心得很积极，遇到困难也不放弃。", "explanation": "这里应该用〈心态〉。心得是学习或实践后的体会，描述一个人对事情的态度要用心态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心得", "is_correct": true, "explanation": "正确：心得指学习或实践后得到的体会，“分享了自己的跑步……”指分享跑步的体会。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：大衣是衣物，不是可以分享的跑步体会，句意不通。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是身体的血液类别，不是可以分享的跑步体会，句意不通。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“跑步饼干”不是可以说的说法，与“分享”搭配不当。"}], "explanations": {"心得": "正确：心得指学习或实践后得到的体会，“分享了自己的跑步……”指分享跑步的体会。", "大衣": "语义：大衣是衣物，不是可以分享的跑步体会，句意不通。", "血型": "语义：血型是身体的血液类别，不是可以分享的跑步体会，句意不通。", "饼干": "搭配：“跑步饼干”不是可以说的说法，与“分享”搭配不当。"}, "sentence_index": 6, "correct_answer": "心得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里有一个心得，希望能去西藏看看。", "explanation": "这里应该用〈心愿〉。心得指学习或实践后得到的体会，不能表示希望；心里想实现的愿望要用心愿。"}, {"text": "他每个月的心得很高。", "explanation": "这里应该用〈工资〉。心得是学习后得到的认识，不是收入；每月拿到的钱要用工资。"}, {"text": "这件衣服的心得很合理。", "explanation": "这里应该用〈价格〉。心得是学习后的认识，不能用来说衣服的价钱；售价的高低要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我心得很有用，大家都来看看。", "corrected_sentence": "我的心得很有用，大家都来看看。", "error_description": "结构错误：表示领属的“我的心得”需要加“的”，“我心得”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛后，他写了一条心得。", "corrected_sentence": "这次比赛后，他写了一点心得。", "error_description": "量词错误：「条」用于细长的东西，不能用来计量心得；心得可用「点」计量，如「一点心得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
