INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物整体中各个部分保持一致、没有矛盾的状态。", "primary_collocate": null, "pronunciation": "tǒng yī xìng", "ipa": "tʰʊŋ˨˩ i˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这套理论体系的各个部分相互印证，整体的统一性使它显得十分严密。", "target_word": "统一性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这篇文章的统一性很好，每段都讲同一件事。", "target_word": "统一性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套家具的颜色缺少统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的作文缺少统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里的校服有统一性，看起来很整齐。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些规定的统一性，让大家都容易遵守。", "target_word": "统一性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好的计划，要有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要保持全书风格的统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的装修很有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份报告的各部分缺乏统一性，读起来很混乱。", "target_word": "统一性", "complexity_tier": "T3", "furigana": "tǒng yī xìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "統一性", "label": "繁体"}, {"form": "统一", "label": "词根"}, {"form": "统一体", "label": "复合词"}], "register": "书面", "sense_fingerprint": "整体各部分一致、没有矛盾的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“整体的统一性”指各部分保持一致、没有矛盾，与“相互印证”“十分严密”的语境相合。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律、由偶然决定，与“十分严密”的意思相反。"}, {"text": "分裂性", "is_correct": false, "explanation": "语义：“分裂性”指各部分相互离散，与“相互印证”的意思相反。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指由偶然因素决定，与“整体……严密”的意思相悖。"}], "explanations": {"统一性": "正确。“整体的统一性”指各部分保持一致、没有矛盾，与“相互印证”“十分严密”的语境相合。", "随机性": "语义：“随机性”指无规律、由偶然决定，与“十分严密”的意思相反。", "分裂性": "语义：“分裂性”指各部分相互离散，与“相互印证”的意思相反。", "偶然性": "语义：“偶然性”指由偶然因素决定，与“整体……严密”的意思相悖。"}, "sentence_index": 0, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份计划的各环节有一把统一性。", "explanation": "量词用错。“把”用于有柄的器具，不能计量“统一性”这类抽象名词，这里应该用〈种〉：“一种统一性”。"}, {"text": "大家的看法很统一性。", "explanation": "这里应该用形容词〈一致〉。“统一性”是名词，不能直接用“很”修饰作谓语，“看法很一致”才自然。"}, {"text": "这家超市的商品很有统一性，什么都能买到。", "explanation": "这里应该用〈齐全〉。“统一性”指各部分保持一致、没有矛盾，不指种类完整；说商品种类多、什么都有，应用〈齐全〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“要有统一性”指计划各部分协调一致，符合句意。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指无规划、任意而为，与“好的计划”的要求相反。"}, {"text": "范儿", "is_correct": false, "explanation": "语域：“范儿”是口语说法，与书面化的计划说明语体不合。"}, {"text": "惰性", "is_correct": false, "explanation": "语义：“惰性”指懒散、不愿行动，与好计划所需的严谨相反。"}], "explanations": {"统一性": "正确。“要有统一性”指计划各部分协调一致，符合句意。", "随意性": "语义：“随意性”指无规划、任意而为，与“好的计划”的要求相反。", "范儿": "语域：“范儿”是口语说法，与书面化的计划说明语体不合。", "惰性": "语义：“惰性”指懒散、不愿行动，与好计划所需的严谨相反。"}, "sentence_index": 6, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议要把大家的意见统一性起来。", "explanation": "这里应该用动词〈统一〉。“统一性”是名词，不能接“起来”作补语，“把意见统一起来”才正确。"}, {"text": "这套书的内容有很高的统一性，一本都没少。", "explanation": "这里应该用〈完整性〉。“统一性”指各部分保持一致、没有矛盾，不指内容齐全；“一本都没少”说的是完整，应用〈完整性〉。"}, {"text": "警察很快疏散了现场的统一性。", "explanation": "这里应该用〈人群〉。〈疏散〉的对象是人群、车辆等具体事物，“统一性”是抽象特征，不能被疏散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告各章都统一性了，前后用词一致。", "corrected_sentence": "这份报告各章都统一了，前后用词一致。", "error_description": "词性错误：“统一性”是名词，不能当动词用，“统一性了”不成立；表示变得一致应说“统一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本教材有一位统一性，各单元的体例完全一致。", "corrected_sentence": "这本教材有一种统一性，各单元的体例完全一致。", "error_description": "量词错误：“位”用于人，不能计量抽象的“统一性”；应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
