INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一群人或动物共同表现出的行动或活动模式。", "primary_collocate": null, "pronunciation": "qún tǐ xíng wéi", "ipa": "tɕʰyn˧˥ tʰi˨˩˦ ɕiŋ˧˥ weɪ˧˥", "syllable_count": 4, "sentences": [{"text": "这种矛盾统一性揭示了人类群体行为的本质弹性——社会联结既在对抗中淬炼强度，亦在协作中拓展深度。", "target_word": "群体行为", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "心理学家研究人群在紧急时的群体行为。", "target_word": "群体行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队上车是一种常见的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家分析了网络上的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家同时鼓掌，这是典型的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到火灾时，群体行为常常会影响逃生。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生观察动物的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟类迁徙是自然界的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司研究顾客的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个人的想法有时会随着群体行为改变。", "target_word": "群体行为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "群體行為", "label": "繁体"}], "register": "书面", "sense_fingerprint": "社会学、心理学及生态学中指一群人或动物共同表现出的行动模式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体行为", "is_correct": true, "explanation": "正确。“人类群体行为”指一群人共同表现出的行动模式，与“社会联结”“协作”的语境相合。"}, {"text": "孤独感", "is_correct": false, "explanation": "语义：“孤独感”是个人的心理感受，与句中社会联结、协作所体现的群体性相悖。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语词，与句子的书面语体不合。"}, {"text": "饮食习惯", "is_correct": false, "explanation": "语义：“饮食习惯”属于个人生活方式，与句中强调的群体联结不符。"}], "explanations": {"群体行为": "正确。“人类群体行为”指一群人共同表现出的行动模式，与“社会联结”“协作”的语境相合。", "孤独感": "语义：“孤独感”是个人的心理感受，与句中社会联结、协作所体现的群体性相悖。", "八卦": "语域：“八卦”是口语词，与句子的书面语体不合。", "饮食习惯": "语义：“饮食习惯”属于个人生活方式，与句中强调的群体联结不符。"}, "sentence_index": 0, "correct_answer": "群体行为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察疏散了现场的群体行为。", "explanation": "这里应该用〈群众〉。〈群体行为〉指共同的行动模式，不能被疏散；疏散的对象是人群，应说“疏散群众”。"}, {"text": "专家分析了网络上的一只群体行为。", "explanation": "量词用错。〈只〉用于动物或成对的物品，不能计量抽象的行为；这里应该用〈种〉。"}, {"text": "这个群体行为有五十名成员。", "explanation": "这里应该用〈团体〉。〈群体行为〉是行为模式，不能说有多少成员；指有组织的人群才说“有多少成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体行为", "is_correct": true, "explanation": "正确。“动物的群体行为”指动物群体的行动模式，与“观察”的对象相合。"}, {"text": "数学公式", "is_correct": false, "explanation": "语义：“数学公式”与观察动物无关，句意不通。"}, {"text": "入学手续", "is_correct": false, "explanation": "搭配：“观察”不能搭配“手续”，“观察”的对象应是动物的行为或现象。"}, {"text": "高考真题", "is_correct": false, "explanation": "语义：“高考真题”不是观察的对象，与动物无关。"}], "explanations": {"群体行为": "正确。“动物的群体行为”指动物群体的行动模式，与“观察”的对象相合。", "数学公式": "语义：“数学公式”与观察动物无关，句意不通。", "入学手续": "搭配：“观察”不能搭配“手续”，“观察”的对象应是动物的行为或现象。", "高考真题": "语义：“高考真题”不是观察的对象，与动物无关。"}, "sentence_index": 6, "correct_answer": "群体行为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动很群体行为，大家都参加了。", "explanation": "这里应该用形容词〈集体〉。〈群体行为〉是名词，不能用“很”修饰作谓语。"}, {"text": "我们明天一起群体行为，去公园散步。", "explanation": "这里应该用动词〈行动〉。〈群体行为〉是名词，不能直接用在“一起”之后充当动词。"}, {"text": "我的个人习惯是早睡，这也是一种群体行为。", "explanation": "指代错误。〈群体行为〉指一群人共同表现的行动模式，“个人习惯”属于个人行为，不能称作群体行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "心理学家分析了人群在突发情况下的群体行为们。", "corrected_sentence": "心理学家分析了人群在突发情况下的群体行为。", "error_description": "“们”只用于指人的复数，不能加在抽象名词“群体行为”后面；应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "动物学家记录了一只群体行为，即鸟群同时转向。", "corrected_sentence": "动物学家记录了一种群体行为，即鸟群同时转向。", "error_description": "“只”用于动物或成对的物品，不能计量抽象的“群体行为”；这里应该用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
