INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "淬炼原指金属热处理工艺，将金属加热到一定温度后迅速冷却，以提高硬度和强度；比喻在艰苦环境中锻炼、磨砺。", "primary_collocate": null, "pronunciation": "cuì liàn", "ipa": "tsʰweɪ˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种矛盾统一性揭示了人类群体行为的本质弹性——社会联结既在对抗中淬炼强度，亦在协作中拓展深度。", "target_word": "淬炼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "艰苦的生活淬炼了他的意志。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长期的训练淬炼出了强壮的身体。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争淬炼了一代年轻人。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在困难中不断淬炼自己。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年的工作经历淬炼了她的耐心。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛就是淬炼球员的好机会。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败一次次淬炼着他，他终于成熟了。", "target_word": "淬炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍在比赛中淬炼出了团队精神。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队用严格的纪律淬炼士兵。", "target_word": "淬炼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淬炼了", "label": "完成体"}, {"form": "淬炼着", "label": "持续体"}, {"form": "淬炼过", "label": "经历体"}, {"form": "淬煉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "比喻在艰苦环境中锻炼、磨砺意志或品格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确答案：淬炼（cuì liàn），指在艰苦环境中磨砺意志或品格。"}, {"text": "脆片", "is_correct": false, "explanation": "piàn（第四声）与 liàn 声母不同（p/l），意思是薯片等脆的零食。"}, {"text": "脆面", "is_correct": false, "explanation": "miàn（第四声）与 liàn 声母不同（m/l），意思是一种脆口的方便面零食。"}, {"text": "脆亮", "is_correct": false, "explanation": "liàng（第四声）与 liàn 韵尾不同（-ng/-n），意思是声音清脆响亮。"}, {"text": "对练", "is_correct": false, "explanation": "duì（第四声）与 cuì 声母不同（d/c），意思是两人配合进行的练习。"}], "explanations": {"淬炼": "正确答案：淬炼（cuì liàn），指在艰苦环境中磨砺意志或品格。", "脆片": "piàn（第四声）与 liàn 声母不同（p/l），意思是薯片等脆的零食。", "脆面": "miàn（第四声）与 liàn 声母不同（m/l），意思是一种脆口的方便面零食。", "脆亮": "liàng（第四声）与 liàn 韵尾不同（-ng/-n），意思是声音清脆响亮。", "对练": "duì（第四声）与 cuì 声母不同（d/c），意思是两人配合进行的练习。"}, "sentence_index": null, "correct_answer": "淬炼"}, "level_3": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确：“淬炼强度”指在对抗中锤炼出强度，与句中的比喻义和语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”的主体须是能感受快乐的人，社会联结不能“享受强度”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”需要有意识的主体，社会联结不能遗忘强度，句意不通。"}, {"text": "冷却", "is_correct": false, "explanation": "搭配：“冷却”多用于物体降温，“强度”不能被冷却，与“在对抗中”的比喻不搭。"}], "explanations": {"淬炼": "正确：“淬炼强度”指在对抗中锤炼出强度，与句中的比喻义和语境相符。", "享受": "语义：“享受”的主体须是能感受快乐的人，社会联结不能“享受强度”。", "忘记": "语义：“忘记”需要有意识的主体，社会联结不能遗忘强度，句意不通。", "冷却": "搭配：“冷却”多用于物体降温，“强度”不能被冷却，与“在对抗中”的比喻不搭。"}, "sentence_index": 0, "correct_answer": "淬炼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上去公园淬炼太极拳。", "explanation": "这里应该用〈练习〉。淬炼指在艰苦环境中磨砺意志或品格，早晨练习太极拳要用练习。"}, {"text": "这只小狗经过一周的淬炼，学会了握手。", "explanation": "这里应该用〈训练〉。淬炼强调在艰苦环境中磨砺，教动物学技能要用训练。"}, {"text": "工人把墙壁淬炼得很干净。", "explanation": "这里应该用〈擦洗〉。淬炼不用于清洁墙面，擦净墙面要用擦洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淬炼", "is_correct": true, "explanation": "正确：“淬炼球员”指通过比赛磨砺球员，与“好机会”搭配，句意通顺。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”是怠慢、不理睬，比赛不可能是“冷落球员的好机会”。"}, {"text": "掩盖", "is_correct": false, "explanation": "搭配：“掩盖”一般用于真相或问题，不能与“球员”搭配。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，比赛不能把球员的好机会赶走，句意相悖。"}], "explanations": {"淬炼": "正确：“淬炼球员”指通过比赛磨砺球员，与“好机会”搭配，句意通顺。", "冷落": "语义：“冷落”是怠慢、不理睬，比赛不可能是“冷落球员的好机会”。", "掩盖": "搭配：“掩盖”一般用于真相或问题，不能与“球员”搭配。", "驱赶": "语义：“驱赶”是赶走，比赛不能把球员的好机会赶走，句意相悖。"}, "sentence_index": 6, "correct_answer": "淬炼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里淬炼晚饭。", "explanation": "这里应该用〈烹饪〉。淬炼是在艰苦环境中磨砺人，不用于做饭。"}, {"text": "工人正在淬炼坏掉的电梯。", "explanation": "这里应该用〈维修〉。淬炼是磨砺人的意志，不用于修理机器。"}, {"text": "园丁淬炼了花园里的树枝。", "explanation": "这里应该用〈修剪〉。淬炼不用于整理花木，修整树枝要说修剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次挫折淬炼了出他坚韧的性格。", "corrected_sentence": "这次挫折淬炼出了他坚韧的性格。", "error_description": "错误在于“出”和“了”的顺序：结果补语“出”应紧跟动词“淬炼”，之后再接“了”，说“淬炼出了”；“淬炼了出”的顺序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的比赛会淬炼了球员的意志。", "corrected_sentence": "明天的比赛会淬炼球员的意志。", "error_description": "错误在于“淬炼”后多加了“了”。句中有“明天”和“会”，说的是将来，将来的动作不能带“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
