INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "作用力或某种性质、程度的强弱大小。", "primary_collocate": null, "pronunciation": "qiáng dù", "ipa": "tɕʰjɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "今天阳光的强度很大。", "target_word": "强度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，运动的强度不要太大。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次地震的强度有多大？", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "噪音的强度超过了标准。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天工作强度很高，非常累。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯光的强度可以慢慢调整。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风的强度越来越大，我们回家吧。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "训练强度太低，效果不好。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机信号的强度只有一格。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的强度很大，球员都跑得很累。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "光、声、运动、工作等性质或作用的强弱大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确答案：强度，qiáng dù，指作用力或性质的强弱大小。"}, {"text": "强大", "is_correct": false, "explanation": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。"}, {"text": "强盗", "is_correct": false, "explanation": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。"}, {"text": "强固", "is_correct": false, "explanation": "gù（第四声）与 dù 声母不同（g 与 d），意思是坚固、稳固。"}], "explanations": {"强度": "正确答案：强度，qiáng dù，指作用力或性质的强弱大小。", "强大": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。", "强盗": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。", "强固": "gù（第四声）与 dù 声母不同（g 与 d），意思是坚固、稳固。"}, "sentence_index": null, "correct_answer": "强度"}, "level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「很大」修饰光的强弱，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很大”不修饰颜色，颜色说深浅。"}, {"text": "性格", "is_correct": false, "explanation": "语义：阳光没有性格，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：阳光没有气味，“味道很大”只用于有气味的东西。"}], "explanations": {"强度": "正确：「很大」修饰光的强弱，符合句意。", "颜色": "搭配：“很大”不修饰颜色，颜色说深浅。", "性格": "语义：阳光没有性格，句子说不通。", "味道": "语义：阳光没有气味，“味道很大”只用于有气味的东西。"}, "sentence_index": 0, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "室内的强度超过了标准，空调要开小一点。", "explanation": "这里应该用〈温度〉。强度说光、声、力的强弱，室内的冷热要用温度。"}, {"text": "这块地的强度很大，可以种很多树。", "explanation": "这里应该用〈面积〉。强度指作用力或性质的强弱，土地有多大要用面积。"}, {"text": "这个水池的强度是两米，比我还深。", "explanation": "这里应该用〈深度〉。强度指力量的强弱，不用米来计量；水池的深浅要说深度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「越来越大」说强弱程度，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：风没有身高，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：风没有体重，句子说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“越来越大”说大小，寿命要说“越来越长”。"}], "explanations": {"强度": "正确：「越来越大」说强弱程度，符合句意。", "身高": "语义：风没有身高，句子说不通。", "体重": "语义：风没有体重，句子说不通。", "寿命": "搭配：“越来越大”说大小，寿命要说“越来越长”。"}, "sentence_index": 6, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的强度超过了限速，警察把他拦下了。", "explanation": "这里应该用〈速度〉。强度说力量的强弱，车的快慢要用速度。"}, {"text": "这根绳子的强度是十米，够用了。", "explanation": "这里应该用〈长度〉。强度不能用来说明长短，绳子的长短要说长度。"}, {"text": "这场比赛的强度是两个小时，大家都很累。", "explanation": "这里应该用〈时长〉。强度指力量的强弱，比赛持续多久要说时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "训练的一强度太大了，要注意休息。", "corrected_sentence": "训练的强度太大了，要注意休息。", "error_description": "“一”不能直接修饰名词“强度”，应去掉“一”，说“训练的强度太大了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风地强度增大了，我们先回家吧。", "corrected_sentence": "风的强度增大了，我们先回家吧。", "error_description": "结构助词误用：「地」接在名词「强度」前，修饰名词应用「的」，应改为「风的强度增大了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
