INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指资金、资源等可以快速移动或转换的能力。", "primary_collocate": null, "pronunciation": "liú dòng xìng", "ipa": "ljou̯˧˥ tʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更深刻的变革在于身份的流动性与去中心化权威的兴起。", "target_word": "流动性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "值得注意的是，口头传统的韧性恰恰源于其流动性。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "资金的流动性越高，企业越灵活。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市吸引人才，增强了劳动力的流动性。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络提高了信息的流动性。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场缺乏流动性，资源很难及时调配。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动力的流动性影响着各地的经济发展。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市人口的流动性很大。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的流动性比老人高，常常换城市工作。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际合作加强了科研人员的流动性。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動性", "label": "繁体"}, {"form": "流动", "label": "词根"}], "register": "书面", "sense_fingerprint": "资金、人员、信息等快速移动或转换的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "搭配：“面积”只用于平面或场地的大小，不能说身份的面积。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”指身份、资金等可以快速移动或转换的能力，与“变革”和“兴起”的语境相合。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指立体物体所占空间的大小，不能用于身份。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指运动的快慢，身份不是会运动的东西，与此处语境不符。"}], "explanations": {"面积": "搭配：“面积”只用于平面或场地的大小，不能说身份的面积。", "流动性": "“流动性”指身份、资金等可以快速移动或转换的能力，与“变革”和“兴起”的语境相合。", "体积": "搭配：“体积”指立体物体所占空间的大小，不能用于身份。", "速度": "语义：“速度”指运动的快慢，身份不是会运动的东西，与此处语境不符。"}, "sentence_index": 0, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这堵墙的流动性很高，颜色非常漂亮。", "explanation": "这里应该用〈颜色〉。流动性指资金、资源快速移动或转换的能力，墙的外观要说“颜色”。"}, {"text": "这座山的流动性很强，爬起来很累。", "explanation": "这里应该用〈高度〉。流动性指资金、资源快速移动的能力，山的高低要说“高度”。"}, {"text": "这个问题的流动性很高，很难解释清楚。", "explanation": "这里应该用〈复杂性〉。流动性指资源快速转移的能力，形容问题难懂要说“复杂性”，问题本身不会流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”描述事物的外观，不能用来说劳动力的颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与劳动力和经济发展无关。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”指劳动力在地区之间迁移的能力，会影响各地的经济发展，语境相合。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“形状”描述有形之物的外形，不能用于劳动力。"}], "explanations": {"颜色": "搭配：“颜色”描述事物的外观，不能用来说劳动力的颜色。", "味道": "语义：“味道”指气味或滋味，与劳动力和经济发展无关。", "流动性": "“流动性”指劳动力在地区之间迁移的能力，会影响各地的经济发展，语境相合。", "形状": "搭配：“形状”描述有形之物的外形，不能用于劳动力。"}, "sentence_index": 6, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片的流动性很高，看起来很清楚。", "explanation": "这里应该用〈清晰度〉。流动性指资金、资源快速移动的能力，照片清楚的程度要说“清晰度”。"}, {"text": "这把椅子的流动性很高，坐起来很舒服。", "explanation": "这里应该用〈舒适度〉。流动性指资金、资源快速移动的能力，椅子舒适的程度要说“舒适度”。"}, {"text": "这块石头的流动性很强，很快就碎了。", "explanation": "这里应该用〈脆性〉。流动性指资金、资源快速移动的能力，石头易碎要说“脆性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "改革后，资金的流动性强很，企业融资更方便。", "corrected_sentence": "改革后，资金的流动性很强，企业融资更方便。", "error_description": "语序错误：程度副词“很”要放在形容词前面，应说“流动性很强”，不能说“流动性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政策放宽后，这只流动性让企业融资更灵活。", "corrected_sentence": "政策放宽后，这种流动性让企业融资更灵活。", "error_description": "量词错误：“流动性”的量词应用“种”，说“这种流动性”；“只”多用于动物或单件物品，不能用来计量这个抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
