INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12025, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先设定或准备。", "primary_collocate": null, "pronunciation": "yù shè", "ipa": "y˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "游戏开发者预设了一套等级规则，使新晋玩家凭借策略天赋迅速晋级。", "target_word": "预设", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "我们把闹钟预设在六点半。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件已经预设好了三种语言。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预设了几个问题，等学生回答。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台空调预设的温度是二十六度。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机的铃声预设成了一首老歌。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游预设了两条路线，可以随时换。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先预设一个密码，以后再改。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电饭煲预设了煮粥的时间。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预设过几种方案，应对涨价。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预设了", "label": "体标"}, {"form": "预设过", "label": "体标"}, {"form": "预设值", "label": "复合"}, {"form": "預設", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事先设定好或准备好某种内容、参数或安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12025, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指事先设定或准备。"}, {"text": "预热", "is_correct": false, "explanation": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。"}, {"text": "预示", "is_correct": false, "explanation": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。"}, {"text": "预测", "is_correct": false, "explanation": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}], "explanations": {"预设": "正确。预设 yù shè，指事先设定或准备。", "预热": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。", "预示": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。", "预测": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指游戏开发者预先设定的一套等级规则。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：开发者不会“忘记”自己设定的规则，与句意相悖。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“规则”搭配，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“规则”搭配，句子不通。"}], "explanations": {"预设": "正确。此处指游戏开发者预先设定的一套等级规则。", "忘记": "语义：开发者不会“忘记”自己设定的规则，与句意相悖。", "唱": "搭配：“唱”不能与“规则”搭配，句子不通。", "吃": "搭配：“吃”不能与“规则”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "气象台预设明天会下雨。", "explanation": "这里应该用〈预测〉。预设指事先定好做法或参数，不用于推断天气等将要发生的情况。"}, {"text": "学生们每天晚上都预设第二天的课文。", "explanation": "这里应该用〈预习〉。预设指事先定好做法或参数，不用于学生提前学习课文，预习才用于此。"}, {"text": "我们提前预设了酒店。", "explanation": "这里应该用〈预订〉。预设多指设定好的程序、方案或参数，订酒店要用预订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12025, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指事先设定或准备。"}, {"text": "遇事", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。"}, {"text": "预售", "is_correct": false, "explanation": "shòu 与 shè 韵母不同（ou 与 ê），都是第四声，意思是提前销售。"}, {"text": "预热", "is_correct": false, "explanation": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。"}], "explanations": {"预设": "正确。预设 yù shè，指事先设定或准备。", "遇事": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。", "预售": "shòu 与 shè 韵母不同（ou 与 ê），都是第四声，意思是提前销售。", "预热": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指导游预先定好的路线方案。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”是不及物动词，不能带“路线”作宾语，句子不通。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多与纪录、规则搭配，不说“打破路线”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“路线”搭配，句子不通。"}], "explanations": {"预设": "正确。此处指导游预先定好的路线方案。", "哭": "搭配：“哭”是不及物动词，不能带“路线”作宾语，句子不通。", "打破": "搭配：“打破”多与纪录、规则搭配，不说“打破路线”。", "喝": "搭配：“喝”不能与“路线”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天预设了周六的餐厅包间。", "explanation": "这里应该用〈预约〉。预设指事先定好做法或参数，不用于为餐厅留位，预约才用于此。"}, {"text": "这本书下周开始预设，现在就能买。", "explanation": "这里应该用〈预售〉。预设用于设定做法或参数，不用于商品的提前销售。"}, {"text": "这位老人预设了今年的末日。", "explanation": "这里应该用〈预言〉。预设指事先定好做法或参数，不用于推断未来的事件，预言才用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把空调的温度预设成二十四个。", "corrected_sentence": "我把空调的温度预设成二十四度。", "error_description": "错误在于量词：温度以“度”计量，不能用量词“个”。应说“预设成二十四度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们预设了过两种办法，应对变化。", "corrected_sentence": "我们预设过两种办法，应对变化。", "error_description": "错误在于“预设”后同时用了“了”和“过”。“预设过”表示曾经预先定过，两个体标不能同时出现，应去掉“了”，说“预设过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
