INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人天生就有的才能或资质。", "primary_collocate": null, "pronunciation": "tiān fù", "ipa": "tʰjɛn˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "互联网解构了现实社会的等级预设，使新晋玩家凭借策略天赋迅速成为意见领袖。", "target_word": "天赋", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她从小就有唱歌的天赋。", "target_word": "天赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子在画画上很有天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "努力比天赋更重要。", "target_word": "天赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的数学天赋让老师很吃惊。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有天赋的人也需要每天练习。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师发现了这个孩子的音乐天赋。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有天赋，只靠努力也能进步。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的运动天赋是爸爸给的。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有语言天赋，学外语特别快。", "target_word": "天赋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "天賦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人天生具有的才能或资质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '549d97fa-a22a-48f3-802f-0d64c12db3ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确答案：天赋（tiān fù），指人天生就有的才能或资质。"}, {"text": "颠覆", "is_correct": false, "explanation": "diān（第一声）与 tiān 声母不同（d/t），意思是推翻、打倒。"}, {"text": "肩负", "is_correct": false, "explanation": "jiān（第一声）与 tiān 声母不同（j/t），意思是承担责任。"}, {"text": "担负", "is_correct": false, "explanation": "dān（第一声）与 tiān 声母不同（d/t），意思是承担（任务、责任）。"}, {"text": "天路", "is_correct": false, "explanation": "lù（第四声）与 fù 声母不同（l/f），意思是通往高原或天上的道路。"}], "explanations": {"天赋": "正确答案：天赋（tiān fù），指人天生就有的才能或资质。", "颠覆": "diān（第一声）与 tiān 声母不同（d/t），意思是推翻、打倒。", "肩负": "jiān（第一声）与 tiān 声母不同（j/t），意思是承担责任。", "担负": "dān（第一声）与 tiān 声母不同（d/t），意思是承担（任务、责任）。", "天路": "lù（第四声）与 fù 声母不同（l/f），意思是通往高原或天上的道路。"}, "sentence_index": null, "correct_answer": "天赋"}, "level_3": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确：“凭借天赋”指依靠生来的才能，与句意相符，句子通顺。"}, {"text": "体力", "is_correct": false, "explanation": "语义：“体力”指身体的力量，与“凭借策略”的语义不相容，不能借它成为意见领袖。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“凭借”后面要接能力或条件，“口音”不能用作凭借。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体特征，与“策略”并列作凭借，句意不通。"}], "explanations": {"天赋": "正确：“凭借天赋”指依靠生来的才能，与句意相符，句子通顺。", "体力": "语义：“体力”指身体的力量，与“凭借策略”的语义不相容，不能借它成为意见领袖。", "口音": "搭配：“凭借”后面要接能力或条件，“口音”不能用作凭借。", "身高": "语义：“身高”是身体特征，与“策略”并列作凭借，句意不通。"}, "sentence_index": 0, "correct_answer": "天赋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有多年的工作天赋。", "explanation": "这里应该用〈经验〉。天赋指生来的才能，不指后天积累的工作经历，此处应该用经验。"}, {"text": "他的天赋是每天喝三杯咖啡。", "explanation": "这里应该用〈习惯〉。天赋指生来的才能，每天喝咖啡是后天养成的生活习惯，应说习惯。"}, {"text": "他通过训练掌握了绘画的天赋。", "explanation": "这里应该用〈技能〉。天赋是生来就有的才能，不能通过训练掌握，绘画技能才可以掌握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天赋", "is_correct": true, "explanation": "正确：“音乐天赋”指生来的音乐才能，与“发现”搭配，句意通顺。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”是座椅的位置，不是可以被“发现”的才能或资质。"}, {"text": "病史", "is_correct": false, "explanation": "语义：“病史”是病情记录，与“音乐”无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“音乐”不能修饰“体重”，搭配不当。"}], "explanations": {"天赋": "正确：“音乐天赋”指生来的音乐才能，与“发现”搭配，句意通顺。", "座位": "语义：“座位”是座椅的位置，不是可以被“发现”的才能或资质。", "病史": "语义：“病史”是病情记录，与“音乐”无关，句意不通。", "体重": "搭配：“音乐”不能修饰“体重”，搭配不当。"}, "sentence_index": 6, "correct_answer": "天赋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段天赋让他明白了很多道理。", "explanation": "这里应该用〈经历〉。天赋指生来的才能，不指亲身经过的事情，此处应该用经历。"}, {"text": "他的天赋很急躁，常常发火。", "explanation": "这里应该用〈脾气〉。天赋指才能，不能用来形容性情，此处应该用脾气。"}, {"text": "这块布料的天赋很柔软。", "explanation": "这里应该用〈质地〉。天赋指人生来的才能，不能用来形容布料，此处应该用质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子很天赋。", "corrected_sentence": "这个孩子很有天赋。", "error_description": "错误在于漏掉了动词“有”。“天赋”是名词，说一个人很有才能时要说“很有天赋”，不能直接说“很天赋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只数学天赋。", "corrected_sentence": "他有一种数学天赋。", "error_description": "错误在于量词：“天赋”的量词是“种”，“只”多用于动物，不能用来修饰天赋，应改为“一种数学天赋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaf93011-0e90-41ac-ab22-ff49726bb7fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
