INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指国家、政党、团体等的最高领导人。", "primary_collocate": null, "pronunciation": "lǐng xiù", "ipa": "liŋ˨˩˦ ɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他凭借出色的口才，很快成为工会的领袖。", "target_word": "领袖", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他是这个国家受人尊敬的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领袖带领人民走向了新的生活。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党的领袖今天在大会上发表了讲话。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民都很爱戴这位伟大的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党的新领袖是一位女士。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领袖的话让全国人民都充满了信心。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国领袖明天要在北京开会。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就梦想成为国家的领袖。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老领袖退休后，新领袖接替了他的工作。", "target_word": "领袖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "領袖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家、政党、团体的最高领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领袖", "is_correct": true, "explanation": "正确。领袖指团体的最高领导人，此处指工会的领导人，句意通顺。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能成为工会的领导人，句子不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物品，不能成为工会的领导人，句子不通。"}, {"text": "货车", "is_correct": false, "explanation": "语义：货车是运输工具，不能成为工会的领导人，句子不通。"}], "explanations": {"领袖": "正确。领袖指团体的最高领导人，此处指工会的领导人，句意通顺。", "饼干": "语义：饼干是食品，不能成为工会的领导人，句子不通。", "闹钟": "语义：闹钟是物品，不能成为工会的领导人，句子不通。", "货车": "语义：货车是运输工具，不能成为工会的领导人，句子不通。"}, "sentence_index": 0, "correct_answer": "领袖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的领袖很大，人口也很多。", "explanation": "这里应该用〈领土〉。领土指国家管辖的土地，领袖指国家或政党的最高领导人，不能用来说国家的大小。"}, {"text": "他今天系了一条很漂亮的领袖。", "explanation": "这里应该用〈领带〉。领带是系在衣领下的服饰，领袖指国家或政党的最高领导人，不能用来指衣饰。"}, {"text": "这家饭店的领袖很高级，客人都说环境好。", "explanation": "这里应该用〈档次〉。领袖指国家、政党、团体的最高领导人，不能用来形容饭店的水准，应说“档次很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领袖", "is_correct": true, "explanation": "领袖：国家或政党的最高领导人，“领袖的话”让全国人民充满信心，句意通顺。"}, {"text": "狗", "is_correct": false, "explanation": "语义：“狗的话”与让全国人民充满信心无关，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不会说话，“石头的话”句意不通。"}, {"text": "服务员", "is_correct": false, "explanation": "搭配：“服务员”的话一般不会让全国人民都充满信心，二者不搭配。"}], "explanations": {"领袖": "领袖：国家或政党的最高领导人，“领袖的话”让全国人民充满信心，句意通顺。", "狗": "语义：“狗的话”与让全国人民充满信心无关，句子不通。", "石头": "语义：“石头”不会说话，“石头的话”句意不通。", "服务员": "搭配：“服务员”的话一般不会让全国人民都充满信心，二者不搭配。"}, "sentence_index": 6, "correct_answer": "领袖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天在菜市场买了领袖，回家炒着吃。", "explanation": "这里应该用〈青菜〉。领袖指国家、政党、团体的最高领导人，是人，不能买来炒着吃。"}, {"text": "这台冰箱的领袖坏了，需要修理。", "explanation": "这里应该用〈压缩机〉。领袖指人，不能用来指冰箱的部件，应说压缩机。"}, {"text": "我每天早上都会给领袖浇水。", "explanation": "这里应该用〈花〉。领袖指人，不能浇水，应说“给花浇水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只领袖在会上握手致意。", "corrected_sentence": "两位领袖在会上握手致意。", "error_description": "量词错误：“领袖”指人，应用量词“位”计数，“只”多用于动物，应改为“两位领袖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在电视上见了过这位领袖。", "corrected_sentence": "我在电视上见过这位领袖。", "error_description": "体标错误：“过”表示经历，已紧跟动词“见”，“了”与“过”不能并列，应删去“了”，说“见过这位领袖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
