INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12029, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给予（荣誉、称号、奖项等）。", "primary_collocate": null, "pronunciation": "shòu yǔ", "ipa": "ʂoʊ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "虚拟世界中的声望，由持续的行为输出而非既定身份授予。", "target_word": "授予", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "学校授予他“优秀学生”的称号。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家授予这位科学家一枚金质奖章。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学今天授予她博士学位。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长授予老人“荣誉市民”称号。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府授予他们集体一等功。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司授予小李“最佳员工”奖。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王授予了他一个爵位。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院授予他名誉教授的称号。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统在仪式上授予她一枚勋章。", "target_word": "授予", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授予了", "label": "体标"}, {"form": "授予过", "label": "体标"}], "register": "书面", "sense_fingerprint": "正式给予荣誉、称号、奖项或学位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "授予", "is_correct": true, "explanation": "授予 shòu yǔ：正式给予荣誉、称号、奖项等，是本词条的目标词。"}, {"text": "手语", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手语指用手势交流的语言。"}, {"text": "术语", "is_correct": false, "explanation": "shù 与 shòu 的韵母不同（u 与 ou），术语指专业领域的固定词语。"}, {"text": "受辱", "is_correct": false, "explanation": "rǔ 与 yǔ 声母不同（r 与 y），意思是遭受侮辱。"}], "explanations": {"授予": "授予 shòu yǔ：正式给予荣誉、称号、奖项等，是本词条的目标词。", "手语": "shǒu（第三声）与 shòu（第四声）声调不同，手语指用手势交流的语言。", "术语": "shù 与 shòu 的韵母不同（u 与 ou），术语指专业领域的固定词语。", "受辱": "rǔ 与 yǔ 声母不同（r 与 y），意思是遭受侮辱。"}, "sentence_index": null, "correct_answer": "授予"}, "level_3": {"options": [{"text": "授予", "is_correct": true, "explanation": "正确：“授予”指正式赋予，与“由……授予”的被动结构相合。"}, {"text": "丧失", "is_correct": false, "explanation": "语义：“丧失”是失去，与“由持续的行为输出而得”的声望相反。"}, {"text": "购买", "is_correct": false, "explanation": "语义：声望不能用“购买”获得，与句中“由行为而非身份”获得的意思相悖。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”是撤回已给出的东西，与“授予”的给予方向相反。"}], "explanations": {"授予": "正确：“授予”指正式赋予，与“由……授予”的被动结构相合。", "丧失": "语义：“丧失”是失去，与“由持续的行为输出而得”的声望相反。", "购买": "语义：声望不能用“购买”获得，与句中“由行为而非身份”获得的意思相悖。", "收回": "语义：“收回”是撤回已给出的东西，与“授予”的给予方向相反。"}, "sentence_index": 0, "correct_answer": "授予"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我授予了朋友一束花。", "explanation": "这里应该用〈送〉。“授予”多指机构或上级向个人颁发荣誉、称号，朋友之间送花要用“送”。"}, {"text": "学校授予了她的申请。", "explanation": "这里应该用〈批准〉。“授予”的对象是荣誉、称号、学位，申请要用“批准”。"}, {"text": "政府授予了新的法律。", "explanation": "这里应该用〈颁布〉。“授予”的对象是荣誉、称号、学位等，法律要用“颁布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授予", "is_correct": true, "explanation": "正确：“授予”指正式把奖项赋予他人，与“公司……小李‘最佳员工’奖”相合。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”用于法令、政策，不说“颁布奖”。"}, {"text": "扣", "is_correct": false, "explanation": "语义：“扣”是扣除，与公司颁授奖项的语境相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与公司把奖项授予员工的语境冲突。"}], "explanations": {"授予": "正确：“授予”指正式把奖项赋予他人，与“公司……小李‘最佳员工’奖”相合。", "颁布": "搭配：“颁布”用于法令、政策，不说“颁布奖”。", "扣": "语义：“扣”是扣除，与公司颁授奖项的语境相反。", "拒绝": "语义：“拒绝”是不接受，与公司把奖项授予员工的语境冲突。"}, "sentence_index": 6, "correct_answer": "授予"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈授予了我一个假期。", "explanation": "这里应该用〈奖励〉。“授予”只用于荣誉、称号、学位等，“假期”属于奖励，不能说“授予假期”。"}, {"text": "老师授予了他的努力。", "explanation": "这里应该用〈称赞〉。“授予”的对象是荣誉、称号，“努力”是品质，要说“称赞他的努力”。"}, {"text": "李教授授予了我们三节物理课。", "explanation": "这里应该用〈授课〉。“授予”用于荣誉、称号、学位等，给学生讲课要用“授课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教育局授予她一张荣誉称号。", "corrected_sentence": "教育局授予她一个荣誉称号。", "error_description": "量词错误：“称号”应搭配量词“个”，不能用“张”（“张”用于纸张、桌子等平面或扁平的事物）。应说“教育局授予她一个荣誉称号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府授予她了荣誉称号。", "corrected_sentence": "市政府授予了她荣誉称号。", "error_description": "“了”位置错误：完成体“了”应紧跟动词“授予”，应说“授予了她”，不能放在“她”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
