INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种设计或管理方式，去掉多余的装饰和级别，让事情更简单直接。", "primary_collocate": null, "pronunciation": "biǎn píng huà", "ipa": "pjɛn˨˩˦ pʰiŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这种以绩效为导向的文化，催生出扁平化、自组织的社群结构。", "target_word": "扁平化", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "公司管理扁平化后，工作更快了。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扁平化让老板和员工更容易沟通。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在推进组织扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扁平化的管理减少了很多层级。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机图标的设计越来越扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这个网站扁平化的设计。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扁平化的公司没有太多部门经理。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的改革目标就是扁平化。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扁平化管理让信息传得更快。", "target_word": "扁平化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扁平化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "设计或管理去掉装饰和层级，变得简单直接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1c9b64-cfef-45a7-8659-93a59137a1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扁平化", "is_correct": true, "explanation": "正确：“扁平化”指去掉层级，与“催生出……自组织的社群结构”的语境相合。"}, {"text": "层级化", "is_correct": false, "explanation": "语义：“层级化”指层层分级，与“扁平化”的去层级方向相反，也与“自组织”的语境冲突。"}, {"text": "官僚化", "is_correct": false, "explanation": "语义：“官僚化”指科层臃肿、层层审批，与“自组织的社群结构”相反。"}, {"text": "工业化", "is_correct": false, "explanation": "语义：“工业化”指大规模工业生产，与“自组织的社群结构”的语境不合。"}], "explanations": {"扁平化": "正确：“扁平化”指去掉层级，与“催生出……自组织的社群结构”的语境相合。", "层级化": "语义：“层级化”指层层分级，与“扁平化”的去层级方向相反，也与“自组织”的语境冲突。", "官僚化": "语义：“官僚化”指科层臃肿、层层审批，与“自组织的社群结构”相反。", "工业化": "语义：“工业化”指大规模工业生产，与“自组织的社群结构”的语境不合。"}, "sentence_index": 0, "correct_answer": "扁平化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们扁平化了这份合同。", "explanation": "这里应该用〈签署〉。“扁平化”指组织、管理或设计方式去掉层级和装饰，合同要用“签署”。"}, {"text": "医生扁平化了病人的血压。", "explanation": "这里应该用〈测量〉。“扁平化”指组织、管理或设计方式去掉层级和装饰，血压要用“测量”。"}, {"text": "这台机器扁平化了电压。", "explanation": "这里应该用〈稳定〉。“扁平化”指组织、管理或设计方式，电压要用“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扁平化", "is_correct": true, "explanation": "正确：“扁平化”指去掉装饰和层次的设计风格，可以修饰“设计”。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：网站的设计不会用“纸张”来描述，与“网站”的语境冲突。"}, {"text": "石材", "is_correct": false, "explanation": "语义：“石材”是材料，与网站界面设计的语境不符。"}, {"text": "木料", "is_correct": false, "explanation": "搭配：“木料”多用于描述家具、建材，不用来修饰“网站的设计”。"}], "explanations": {"扁平化": "正确：“扁平化”指去掉装饰和层次的设计风格，可以修饰“设计”。", "纸张": "语义：网站的设计不会用“纸张”来描述，与“网站”的语境冲突。", "石材": "语义：“石材”是材料，与网站界面设计的语境不符。", "木料": "搭配：“木料”多用于描述家具、建材，不用来修饰“网站的设计”。"}, "sentence_index": 6, "correct_answer": "扁平化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机扁平化了油箱。", "explanation": "这里应该用〈加满〉。“扁平化”指组织、管理或设计方式去掉层级和装饰，油箱要用“加满”。"}, {"text": "政府扁平化了物价。", "explanation": "这里应该用〈调节〉。“扁平化”用于组织和管理，不能用于物价，调控价格要用“调节”。"}, {"text": "工人扁平化了文件大小。", "explanation": "这里应该用〈压缩〉。“扁平化”不能指减小文件体积，压缩文件要用“压缩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司采用了扁平化了管理。", "corrected_sentence": "这家公司采用了扁平化管理。", "error_description": "多余的“了”：完成体“了”已放在动词“采用”后面，“扁平化”后不能再加“了”。应说“这家公司采用了扁平化管理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队采用了扁平化地结构。", "corrected_sentence": "这个团队采用了扁平化结构。", "error_description": "“地”误用：“扁平化”修饰名词“结构”时直接相接，不能加“地”（“地”用于修饰动词、形容词）。应说“这个团队采用了扁平化结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b036a8f5-9068-4757-82b6-347580cf1231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由一定数量的成员组成的、具有共同特征或共同利益的社会群体。", "primary_collocate": null, "pronunciation": "shè qún", "ipa": "ʂɤ˥˩ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "这种绩效导向的文化，催生出扁平化、自组织的社群结构。", "target_word": "社群", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "自远古以来，干旱地区的农业社群便发展出一系列复杂的资源管理体系，这些体系不仅是对自然制约的回应，更深刻体现了本土知识与生态伦理的融合。", "target_word": "社群", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "社群", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个社群有三百多名成员。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱好摄影的人组成了一个线上社群。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社群里的成员互相帮助，也分享经验。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个社群都有自己的规则和习惯。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师常在社群里回答新手的问题。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小区业主建立了社群，方便交流和互助。", "target_word": "社群", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山村里的少数民族社群，仍然保留着传统节日。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "社群媒体", "label": "复合"}, {"form": "社群网络", "label": "复合"}], "register": "书面", "sense_fingerprint": "有共同特征或利益的成员组成的社会群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”描述外观，不能说“自组织的颜色结构”。"}, {"text": "社群", "is_correct": true, "explanation": "“社群”指由成员组成、有共同特征的群体，与“自组织的……结构”的语境相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与社会结构的组织方式无关。"}, {"text": "电压", "is_correct": false, "explanation": "语义：“电压”指电路中的电势差，与人群的组织结构无关。"}], "explanations": {"颜色": "搭配：“颜色”描述外观，不能说“自组织的颜色结构”。", "社群": "“社群”指由成员组成、有共同特征的群体，与“自组织的……结构”的语境相合。", "味道": "语义：“味道”指气味或滋味，与社会结构的组织方式无关。", "电压": "语义：“电压”指电路中的电势差，与人群的组织结构无关。"}, "sentence_index": 0, "correct_answer": "社群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个社群有三百多名员工。", "explanation": "这里应该用〈公司〉。“员工”指受雇于单位的人，社群的人叫成员，不能说员工。"}, {"text": "这个社群有三百多张病床。", "explanation": "这里应该用〈医院〉。社群指由成员组成的群体，病床是医院的设施，社群不能说有病床。"}, {"text": "这个社群有三百多台机器。", "explanation": "这里应该用〈工厂〉。社群指由成员组成的群体，机器属于工厂，这里不能用社群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "搭配：“规则和习惯”的主体需要是人或群体，不能说桌子有规则和习惯。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是器物，不具备规则与习惯。"}, {"text": "社群", "is_correct": true, "explanation": "“社群”由成员组成，有共同的规则和习惯，语境相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不会有自己的规则和习惯。"}], "explanations": {"桌子": "搭配：“规则和习惯”的主体需要是人或群体，不能说桌子有规则和习惯。", "灯泡": "语义：灯泡是器物，不具备规则与习惯。", "社群": "“社群”由成员组成，有共同的规则和习惯，语境相合。", "窗户": "语义：窗户是建筑部件，不会有自己的规则和习惯。"}, "sentence_index": 6, "correct_answer": "社群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山村里的一只少数民族社群，仍然保留着传统节日。", "explanation": "这里不用“只”。“只”多用于动物或单件器物，社群是人的群体，应说“一个社群”。"}, {"text": "山村里的一座少数民族社群，仍然保留着传统节日。", "explanation": "这里不用“座”。“座”计量山、楼等大型固定物体，社群是人的群体，应说“一个社群”。"}, {"text": "山村里的一棵少数民族社群，仍然保留着传统节日。", "explanation": "这里不用“棵”。“棵”计量树木等植物，社群是人的群体，应说“一个社群”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社群们每周都组织一次线下活动。", "corrected_sentence": "这个社群每周都组织一次线下活动。", "error_description": "复数错误：“这个”指一个群体，“社群”本身已指群体，不能再加“们”，应说“这个社群”，不能说“这个社群们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只社群的规则很简单，新人一学就会。", "corrected_sentence": "这个社群的规则很简单，新人一学就会。", "error_description": "量词错误：“社群”指人的群体，应用量词“个”，说“这个社群”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
