INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "氏族是以血缘关系为基础形成的社会群体，通常拥有共同的祖先、姓氏或图腾。", "primary_collocate": null, "pronunciation": "shì zú", "ipa": "ʂʐ̩˥˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "玩家自发形成 guild（公会）、clan（氏族），制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "氏族", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古代的每个氏族都有自己的图腾。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氏族由有共同祖先的人组成。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个氏族的成员都姓李。", "target_word": "氏族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "历史书里说，原始社会的人按氏族生活。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氏族首领带着族人搬到了河边。", "target_word": "氏族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氏族成员要共同保护自己的土地。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的氏族之间有时会结盟。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古学家找到了一个古老氏族的墓地。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会发展以后，氏族慢慢变成了部落。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "氏族社会", "label": "复合"}, {"form": "氏族制度", "label": "复合"}], "register": "书面", "sense_fingerprint": "氏族：以血缘为基础、有共同祖先的社会群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确答案：氏族（shì zú），指以血缘为基础、有共同祖先的社会群体。"}, {"text": "十足", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，十足意思是十分充足。"}, {"text": "失足", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，失足意思是不慎跌倒或误入歧途。"}, {"text": "始祖", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，zǔ（第三声）与 zú（第二声）声调也不同，始祖意思是最早的祖先。"}], "explanations": {"氏族": "正确答案：氏族（shì zú），指以血缘为基础、有共同祖先的社会群体。", "十足": "shí（第二声）与 shì（第四声）声调不同，十足意思是十分充足。", "失足": "shī（第一声）与 shì（第四声）声调不同，失足意思是不慎跌倒或误入歧途。", "始祖": "shǐ（第三声）与 shì（第四声）声调不同，zǔ（第三声）与 zú（第二声）声调也不同，始祖意思是最早的祖先。"}, "sentence_index": null, "correct_answer": "氏族"}, "level_3": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确：氏族是以血缘为基础的群体，此处指原始社会中共同生产、分配的血缘群体。"}, {"text": "武器", "is_correct": false, "explanation": "语义：武器不是人群组织，没有“成员”。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币是交换媒介，不是人群组织，没有“成员”。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：饮料不是人群组织，不说“饮料成员”。"}], "explanations": {"氏族": "正确：氏族是以血缘为基础的群体，此处指原始社会中共同生产、分配的血缘群体。", "武器": "语义：武器不是人群组织，没有“成员”。", "货币": "语义：货币是交换媒介，不是人群组织，没有“成员”。", "饮料": "搭配：饮料不是人群组织，不说“饮料成员”。"}, "sentence_index": 0, "correct_answer": "氏族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们氏族的员工都在上海工作。", "explanation": "这里应该用〈公司〉。氏族是以血缘为基础的群体，公司员工是按职业聚集的，要说公司。"}, {"text": "我们村有一个氏族，专门负责组织春节晚会。", "explanation": "这里应该用〈委员会〉。氏族是以血缘为基础的群体，负责组织活动的机构要用委员会。"}, {"text": "我们国家有五十六个氏族。", "explanation": "这里应该用〈民族〉。氏族是较小的血缘群体，国家里的多个民族要用民族。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12033, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确答案：氏族（shì zú），指以血缘为基础、有共同祖先的社会群体。"}, {"text": "赤足", "is_correct": false, "explanation": "chì（第四声）与 shì（第四声）声母不同（ch 与 sh），赤足意思是光着脚。"}, {"text": "四足", "is_correct": false, "explanation": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），四足意思是有四条腿。"}, {"text": "实足", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，实足意思是实际的、足额的，如“实足年龄”。"}], "explanations": {"氏族": "正确答案：氏族（shì zú），指以血缘为基础、有共同祖先的社会群体。", "赤足": "chì（第四声）与 shì（第四声）声母不同（ch 与 sh），赤足意思是光着脚。", "四足": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），四足意思是有四条腿。", "实足": "shí（第二声）与 shì（第四声）声调不同，实足意思是实际的、足额的，如“实足年龄”。"}, "sentence_index": null, "correct_answer": "氏族"}, "level_3": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确：氏族是以血缘为基础的群体，可以作为“成员”的主语，共同保护土地。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流没有成员，也不会保护土地。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不是社会群体，不能有“成员”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不与“成员”搭配，也不能作为共同保护土地的主体。"}], "explanations": {"氏族": "正确：氏族是以血缘为基础的群体，可以作为“成员”的主语，共同保护土地。", "河流": "语义：河流没有成员，也不会保护土地。", "树木": "语义：树木不是社会群体，不能有“成员”。", "颜色": "搭配：“颜色”不与“成员”搭配，也不能作为共同保护土地的主体。"}, "sentence_index": 6, "correct_answer": "氏族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们氏族的球队是一个团体，大家都很努力。", "explanation": "这里应该用〈队伍〉。氏族指以血缘为基础的群体，比赛组成的队伍不是血缘群体，不能用氏族。"}, {"text": "这个氏族有很多党员。", "explanation": "这里应该用〈政党〉。氏族是血缘群体，有党员的政治组织要用政党。"}, {"text": "这个氏族的护士每天给病人打针。", "explanation": "这里应该用〈医院〉。氏族是血缘群体，给病人打针的地方要说医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子里有三只氏族。", "corrected_sentence": "这个村子里有三个氏族。", "error_description": "量词错误：“只”用于动物，氏族是群体，应说“三个氏族”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的两只氏族常常争夺水源。", "corrected_sentence": "这个地区的两个氏族常常争夺水源。", "error_description": "量词错误：“只”用于动物，氏族是群体，应说“两个氏族”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
