INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12035, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "劝说双方消除矛盾，达成一致。", "primary_collocate": null, "pronunciation": "tiáo jiě", "ipa": "tʰjɑʊ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "玩家自发形成 guild（公会）、clan（氏族），制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "调解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警察来调解邻居之间的矛盾。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师调解了两个同学的争吵。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村干部出面调解，两家和好了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方请法院调解这起纠纷。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师出面调解后，他们不再打官司了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司请专家来调解劳资矛盾。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "居委会常常帮邻居调解纠纷。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国请第三方调解边境冲突。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从中调解，哥哥和姐姐不吵了。", "target_word": "调解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调解了", "label": "体标"}, {"form": "调解过", "label": "体标"}, {"form": "调解员", "label": "复合"}], "register": "中性", "sense_fingerprint": "调解：居中劝说双方消除矛盾、达成一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确答案：调解（tiáo jiě），指居中劝说双方消除矛盾、达成一致。"}, {"text": "调节", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，调节意思是调整使其适当。"}, {"text": "条街", "is_correct": false, "explanation": "声调混淆：jiē（第一声）与 jiě（第三声）声调不同，条街指一条街道。"}, {"text": "条件", "is_correct": false, "explanation": "jiàn（第四声）与 jiě（第三声）韵母与声调不同，条件意思是情况或前提。"}], "explanations": {"调解": "正确答案：调解（tiáo jiě），指居中劝说双方消除矛盾、达成一致。", "调节": "jiě（第三声）与 jié（第二声）声调不同，调节意思是调整使其适当。", "条街": "声调混淆：jiē（第一声）与 jiě（第三声）声调不同，条街指一条街道。", "条件": "jiàn（第四声）与 jiě（第三声）韵母与声调不同，条件意思是情况或前提。"}, "sentence_index": null, "correct_answer": "调解"}, "level_3": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确：前文“调解冲突”与“制定规范”并列，指居中化解矛盾。"}, {"text": "挑起", "is_correct": false, "explanation": "语义：“挑起冲突”与前文“制定内部规范”“组织慈善活动”的积极语境相反。"}, {"text": "策划", "is_correct": false, "explanation": "搭配：“策划”的对象是活动或方案，不说“策划冲突”。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视冲突与前文组织管理、化解矛盾的语境不合。"}], "explanations": {"调解": "正确：前文“调解冲突”与“制定规范”并列，指居中化解矛盾。", "挑起": "语义：“挑起冲突”与前文“制定内部规范”“组织慈善活动”的积极语境相反。", "策划": "搭配：“策划”的对象是活动或方案，不说“策划冲突”。", "忽视": "语义：忽视冲突与前文组织管理、化解矛盾的语境不合。"}, "sentence_index": 0, "correct_answer": "调解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学难题终于调解了。", "explanation": "这里应该用〈解决〉。调解针对双方的争执，数学难题要用解决。"}, {"text": "我调解他戒烟了。", "explanation": "这里应该用〈劝说〉。调解需要双方的矛盾，只针对一个人劝他戒烟要用劝说。"}, {"text": "这场示威活动终于调解了。", "explanation": "这里应该用〈平息〉。调解是双方经协商达成一致，群体骚乱要用平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12035, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确答案：调解（tiáo jiě），指居中劝说双方消除矛盾、达成一致。"}, {"text": "题解", "is_correct": false, "explanation": "tí（第二声）与 tiáo 声母相同、韵母不同，题解指题目的解答，与调解意思不同。"}, {"text": "理解", "is_correct": false, "explanation": "lǐ（第三声）与 tiáo 声母韵母均不同，理解意思是懂得、明白。"}, {"text": "调减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiě（第三声）韵母不同，调减意思是下调、减少。"}], "explanations": {"调解": "正确答案：调解（tiáo jiě），指居中劝说双方消除矛盾、达成一致。", "题解": "tí（第二声）与 tiáo 声母相同、韵母不同，题解指题目的解答，与调解意思不同。", "理解": "lǐ（第三声）与 tiáo 声母韵母均不同，理解意思是懂得、明白。", "调减": "jiǎn（第三声）与 jiě（第三声）韵母不同，调减意思是下调、减少。"}, "sentence_index": null, "correct_answer": "调解"}, "level_3": {"options": [{"text": "调解", "is_correct": true, "explanation": "正确：请专家来处理劳资矛盾，与“调解”的居中劝和意义相符。"}, {"text": "激化", "is_correct": false, "explanation": "语义：“激化”使矛盾加深，与“请专家来”的处理意图相反。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”的对象是数字或费用，不说“计算矛盾”。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”矛盾与请专家来处理的目的相反。"}], "explanations": {"调解": "正确：请专家来处理劳资矛盾，与“调解”的居中劝和意义相符。", "激化": "语义：“激化”使矛盾加深，与“请专家来”的处理意图相反。", "计算": "搭配：“计算”的对象是数字或费用，不说“计算矛盾”。", "扩大": "语义：“扩大”矛盾与请专家来处理的目的相反。"}, "sentence_index": 6, "correct_answer": "调解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他调解了孩子玩火。", "explanation": "这里应该用〈阻止〉。调解需要双方的矛盾，孩子玩火是单方面的行为，应说阻止。"}, {"text": "妈妈调解了哭泣的女儿。", "explanation": "这里应该用〈安慰〉。调解是帮双方和好，单纯安慰伤心的人要用安慰。"}, {"text": "他调解了我改变主意。", "explanation": "这里应该用〈说服〉。调解是居中促成双方和好，让一方改变主意要用说服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区干部成功调解着两家的纠纷。", "corrected_sentence": "社区干部成功调解了两家的纠纷。", "error_description": "体标错误：“成功调解”是已完成的动作，应用“了”；“着”表示持续状态，与已完成的动作不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的纠纷已经调解过着。", "corrected_sentence": "他们的纠纷已经调解过了。", "error_description": "体标错误：“过了”表示动作已完成，“过着”表示持续状态，与“调解”搭配应说“调解过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
