INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对人关怀，富有同情心，愿意帮助他人的品质或行为。", "primary_collocate": null, "pronunciation": "cí shàn", "ipa": "tsʰɨ˧˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "玩家自发形成公会、氏族，制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "慈善", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "她每年都参加慈善活动。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把一半利润用于慈善。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直热心慈善，帮助了很多孩子。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个慈善机构为老人提供免费午饭。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捐钱给慈善组织，却不想让人知道。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慈善不只是捐钱，也是关心别人。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举办了一场慈善义卖，同学们都来了。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做慈善已经十年了。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星们为山区学校办了慈善晚会。", "target_word": "慈善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慈善机构", "label": "复合"}, {"form": "慈善家", "label": "复合"}], "register": "中性", "sense_fingerprint": "关怀并帮助他人的善行，如捐款、公益活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慈善", "is_correct": true, "explanation": "正确：慈善指关怀、救助他人的公益行为，可以组织成跨国活动，符合句中语境。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠是人或动物的生理状态，不能被组织成跨国活动。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于感官感受，不能被组织成跨国活动。"}, {"text": "嘴炮", "is_correct": false, "explanation": "语域：嘴炮是网络俚语，指空谈，与这句书面的描述语体不合，也不能与“组织跨国活动”搭配。"}], "explanations": {"慈善": "正确：慈善指关怀、救助他人的公益行为，可以组织成跨国活动，符合句中语境。", "睡眠": "语义：睡眠是人或动物的生理状态，不能被组织成跨国活动。", "味道": "语义：味道属于感官感受，不能被组织成跨国活动。", "嘴炮": "语域：嘴炮是网络俚语，指空谈，与这句书面的描述语体不合，也不能与“组织跨国活动”搭配。"}, "sentence_index": 0, "correct_answer": "慈善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的慈善，帮助了很多孩子。", "explanation": "这里应该用〈慈善家〉。慈善指行为或活动，指人要用“慈善家”，不能直接说“慈善”。"}, {"text": "她在一家慈善工作，帮助老人。", "explanation": "这里应该用〈慈善机构〉。“一家”指的是机构，慈善只指关怀、救助的行为，不能作为工作的单位。"}, {"text": "这把椅子很慈善，坐上去很舒服。", "explanation": "这里应该用〈舒适〉。慈善用来形容人的关怀与助人，不用来形容椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慈善", "is_correct": true, "explanation": "正确：句中在给慈善下定义，慈善可以是捐钱，也可以是关心别人。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能捐钱，也不是关心别人的行为，用来定义慈善讲不通。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：长相指人的外貌，与捐钱、关心别人都无关，不能用来定义慈善。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能捐钱，也不是关心他人的行为。"}], "explanations": {"慈善": "正确：句中在给慈善下定义，慈善可以是捐钱，也可以是关心别人。", "手机": "语义：手机不能捐钱，也不是关心别人的行为，用来定义慈善讲不通。", "长相": "体貌：长相指人的外貌，与捐钱、关心别人都无关，不能用来定义慈善。", "数学": "语义：数学是学科，不能捐钱，也不是关心他人的行为。"}, "sentence_index": 6, "correct_answer": "慈善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明星们去年办了一台慈善，为山区学校筹了不少款。", "explanation": "这里应该用〈场〉。“台”多用于演出、机器等，慈善是活动，应用“场”计量。"}, {"text": "她组织了一辆慈善，帮助了很多孩子。", "explanation": "这里应该用〈次〉。“辆”用于车辆，慈善不能用“辆”计量。"}, {"text": "学校去年办了一张慈善，同学们都来了。", "explanation": "这里应该用〈场〉。“张”用于平面的东西，慈善活动应用“场”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把慈善很有意义，大家都应该参与。", "corrected_sentence": "这种慈善很有意义，大家都应该参与。", "error_description": "量词错误：慈善是抽象的行为，应搭配“种”，“把”用于有柄的物件，不能用于慈善。正确说法是“这种慈善”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台慈善让很多孩子有了上学的机会。", "corrected_sentence": "这种慈善让很多孩子有了上学的机会。", "error_description": "量词错误：慈善是抽象的行为，应搭配“种”，“台”用于机器、演出等，不能用于慈善。正确说法是“这种慈善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶意", "is_correct": true, "explanation": "恶意：与“善意”相对，指怀有不好的用意。"}, {"text": "压力", "is_correct": false, "explanation": "压力：指外界施加的负担或紧迫感，与“善意”没有反义关系。"}, {"text": "秘密", "is_correct": false, "explanation": "秘密：指不让人知道的事情，与“善意”没有反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙：开锁用的工具，与“善意”没有反义关系。"}], "correct_answer": "恶意", "explanations": {"恶意": "恶意：与“善意”相对，指怀有不好的用意。", "压力": "压力：指外界施加的负担或紧迫感，与“善意”没有反义关系。", "秘密": "秘密：指不让人知道的事情，与“善意”没有反义关系。", "钥匙": "钥匙：开锁用的工具，与“善意”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶意", "is_correct": true, "explanation": "恶意：与“善意”相对，指怀有不好的用意。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸：定期出版的印刷品，与“善意”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞：挡雨用的器具，与“善意”没有反义关系。"}, {"text": "镜子", "is_correct": false, "explanation": "镜子：照人用的器具，与“善意”没有反义关系。"}], "correct_answer": "恶意", "explanations": {"恶意": "恶意：与“善意”相对，指怀有不好的用意。", "报纸": "报纸：定期出版的印刷品，与“善意”没有反义关系。", "雨伞": "雨伞：挡雨用的器具，与“善意”没有反义关系。", "镜子": "镜子：照人用的器具，与“善意”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指好心、好意，即对他人的友善和关怀。", "primary_collocate": null, "pronunciation": "shàn yì", "ipa": "ʂan˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "玩家自发形成 guild（公会）、clan（氏族），制定内部规范，调解冲突，甚至组织跨国慈善活动，将虚拟资本转化为现实善意。", "target_word": "善意", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我感受到了他的善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你的善意，我真的很感动。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "陌生人对我笑了笑，我知道那是善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用善意的话安慰了朋友。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对学生总是充满善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的批评虽然严格，但是出于善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居送来一碗热汤，让我感到了善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要误会，我只是想表达善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小小的善意也能让人觉得温暖。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "善意：对他人的好心、友善与关怀", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "善意", "is_correct": true, "explanation": "善意（shàn yì）：对别人友善的好心。"}, {"text": "战役", "is_correct": false, "explanation": "战役（zhàn yì）与善意声母不同，zh 与 sh 对立，意思是规模较大的作战行动。"}, {"text": "现役", "is_correct": false, "explanation": "现役（xiàn yì）与善意声母不同，x 与 sh 对立，意思是正在服役。"}, {"text": "善于", "is_correct": false, "explanation": "善于（shàn yú）与善意韵母不同（yú 与 yì），意思是擅长。"}, {"text": "审议", "is_correct": false, "explanation": "审议（shěn yì）与善意韵母不同（en 与 an），声调也不同，意思是仔细讨论。"}], "explanations": {"善意": "善意（shàn yì）：对别人友善的好心。", "战役": "战役（zhàn yì）与善意声母不同，zh 与 sh 对立，意思是规模较大的作战行动。", "现役": "现役（xiàn yì）与善意声母不同，x 与 sh 对立，意思是正在服役。", "善于": "善于（shàn yú）与善意韵母不同（yú 与 yì），意思是擅长。", "审议": "审议（shěn yì）与善意韵母不同（en 与 an），声调也不同，意思是仔细讨论。"}, "sentence_index": null, "correct_answer": "善意"}, "level_3": {"options": [{"text": "善意", "is_correct": true, "explanation": "善意：指好心、友善的心意，与“将虚拟资本转化为现实……”的语境相合。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“机器”是工具，不能作为“转化为”的结果。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，不能作为“转化为”的结果。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指体型，不能作为资本转化的结果。"}], "explanations": {"善意": "善意：指好心、友善的心意，与“将虚拟资本转化为现实……”的语境相合。", "机器": "语义：“机器”是工具，不能作为“转化为”的结果。", "冰箱": "语义：“冰箱”是电器，不能作为“转化为”的结果。", "身高": "体貌：“身高”指体型，不能作为资本转化的结果。"}, "sentence_index": 0, "correct_answer": "善意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司经常做善意。", "explanation": "这里应该用〈善事〉。善意指好心、心意，不是可以去做的事；做好事要说“善事”。"}, {"text": "这部电影的善意很精彩。", "explanation": "这里应该用〈情节〉。善意是好心，不能用“精彩”来评价影片；故事好看要说“情节精彩”。"}, {"text": "他的善意很整齐。", "explanation": "这里应该用〈摆放〉。善意是好心，不是可以摆放整齐的东西；物品排列整齐才说“摆放整齐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善意", "is_correct": true, "explanation": "善意：出于好心，与“他的批评虽然严格，但是出于……”相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的货币价值，不能作为“出于”的动因，句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的语体不合，且句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能作为“出于”的动因。"}], "explanations": {"善意": "善意：出于好心，与“他的批评虽然严格，但是出于……”相合。", "价格": "语义：“价格”指商品的货币价值，不能作为“出于”的动因，句意不通。", "玩意儿": "语域：“玩意儿”是口语，与书面的语体不合，且句意不通。", "窗户": "语义：“窗户”是建筑部件，不能作为“出于”的动因。"}, "sentence_index": 6, "correct_answer": "善意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的善意很大声。", "explanation": "这里应该用〈音量〉。善意是好心，没有音量高低；说话声音大要用“音量”。"}, {"text": "两国之间的善意很紧张。", "explanation": "这里应该用〈关系〉。善意是好心，不能用“紧张”形容两国的状态；两国的状态要说“关系紧张”。"}, {"text": "她的善意很潮湿。", "explanation": "这里应该用〈空气〉。善意是好心，不能用“潮湿”形容；形容空气状态才用“潮湿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个善意人。", "corrected_sentence": "他是一个善意的人。", "error_description": "结构错误：“善意”修饰名词时要加“的”，应说“善意的人”，不能说“善意人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天会感受过他的善意。", "corrected_sentence": "我明天会感受他的善意。", "error_description": "体标错误：“过”表示已经发生的经历，不能与“明天”这样的将来时间词连用；说将来要用“会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
