INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "指根据前面所说的情况或道理，可以得出后面的结论。", "primary_collocate": null, "pronunciation": "yóu cǐ guān zhī", "ipa": "joʊ˧˥ tsʰɹ̩˨˩˦ kwan˥ ʈʂɹ̩˥", "syllable_count": 4, "sentences": [{"text": "由此观之，这些看似消遣的数字空间，实则是社会演化逻辑的加速器。", "target_word": "由此观之", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "由此观之", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他每天坚持跑步，身体越来越好。由此观之，运动很重要。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店客人很多，天天排队。由此观之，菜一定不错。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每次考试都得第一，由此观之，他学习很努力。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的人都带了伞，由此观之，今天可能会下雨。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水一年比一年清，由此观之，环保工作有了效果。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王三次都迟到了，由此观之，他不太守时。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的书店越来越多，由此观之，读书的人没有少。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的树都死了，由此观之，这里很久没人浇水了。", "target_word": "由此观之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "由此觀之", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由此观之：根据前面的情况或道理得出后面的结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，而这里后文是推断出的结论，不是原因。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不然时的后果，与“看似消遣”的判断无关，句意不通。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”需要与“也”“仍”等呼应，这里后面没有对应的结构。"}, {"text": "由此观之", "is_correct": true, "explanation": "由此观之：表示根据前面的情况得出后面的结论，与“实则是……”的判断相符。"}], "explanations": {"因为": "语义：“因为”引出原因，而这里后文是推断出的结论，不是原因。", "否则": "语义：“否则”表示不然时的后果，与“看似消遣”的判断无关，句意不通。", "即使": "搭配：“即使”需要与“也”“仍”等呼应，这里后面没有对应的结构。", "由此观之": "由此观之：表示根据前面的情况得出后面的结论，与“实则是……”的判断相符。"}, "sentence_index": 0, "correct_answer": "由此观之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，由此观之，成绩还是不好。", "explanation": "这里应该用〈然而〉。由此观之表示从前文推出结论，不能用来引出转折。"}, {"text": "我们要做三件事，由此观之，先去看电影。", "explanation": "这里应该用〈首先〉。由此观之表示根据前文推出结论，不能用来列出先做的事。"}, {"text": "他吃完饭，由此观之，去看电影。", "explanation": "这里应该用〈然后〉。由此观之表示推论，不能用来表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“河水越来越清”推出的结论相反，句意不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示假设相反的后果，与前文的因果推断不符。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：“不过”需要与前文形成对立，而这里前后并无对立。"}, {"text": "由此观之", "is_correct": true, "explanation": "由此观之：根据“河水一年比一年清”推出“环保工作有了效果”，与句意相符。"}], "explanations": {"然而": "语义：“然而”表示转折，与“河水越来越清”推出的结论相反，句意不通。", "否则": "语义：“否则”表示假设相反的后果，与前文的因果推断不符。", "不过": "搭配：“不过”需要与前文形成对立，而这里前后并无对立。", "由此观之": "由此观之：根据“河水一年比一年清”推出“环保工作有了效果”，与句意相符。"}, "sentence_index": 6, "correct_answer": "由此观之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们已经买了牛奶，由此观之，我还想买些水果。", "explanation": "这里应该用〈另外〉。由此观之表示推论，不能用来补充一件并列的事。"}, {"text": "大家吃完了晚饭，由此观之，我们一起拍了照。", "explanation": "这里应该用〈最后〉。由此观之表示推论，不能用来表示事情的最后一步。"}, {"text": "由此观之，我们吃饭时，看了看天气。", "explanation": "这里应该用〈顺便〉。由此观之表示根据前文推出结论，不能用来表示顺带做的另一件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天按时吃药，由此观之了，他的身体一定在好转。", "corrected_sentence": "他每天按时吃药，由此观之，他的身体一定在好转。", "error_description": "“由此观之”后加了“了”：该词是连词，不能带体标记，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续几年的考试成绩都进步了，由此观之，所以他的努力有了成效。", "corrected_sentence": "连续几年的考试成绩都进步了，由此观之，他的努力有了成效。", "error_description": "“由此观之”已经表示结论，后面不应再加“所以”；两者重复，应去掉“所以”，说“由此观之，他的努力有了成效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用自己感兴趣的活动来打发空闲时间。", "primary_collocate": null, "pronunciation": "xiāo qiǎn", "ipa": "ɕjɑʊ˥ tɕʰjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "由此观之，这些用来消遣的数字空间，实则是社会演化逻辑的加速器。", "target_word": "消遣", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "周末没事，我在家看电影消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢下棋，用它来消遣晚上的时间。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "退休以后，爷爷常常钓鱼消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等车的时候，她玩手机消遣了一会儿。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨不能出门，孩子们在屋里画画消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不工作的时候，一般怎么消遣？", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想找点事消遣一下，就去公园走了走。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶坐在窗前织着毛衣消遣时间。", "target_word": "消遣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有朋友陪我，我只好看书消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "消遣了", "label": "体标"}, {"form": "消遣着", "label": "体标"}, {"form": "消遣消遣", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用感兴趣的活动打发空闲时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消遣", "is_correct": true, "explanation": "“消遣”指用感兴趣的活动打发空闲时间，修饰“数字空间”，与“用来……的”结构及“实则”的转折相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：数字空间不能拿来睡觉，“用来睡觉的数字空间”与句意不符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：数字空间不能用来吃饭，与“社会演化逻辑的加速器”的论述无关，句子不成立。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”需要具体的器物作宾语，不能修理“数字空间”这类抽象概念。"}], "explanations": {"消遣": "“消遣”指用感兴趣的活动打发空闲时间，修饰“数字空间”，与“用来……的”结构及“实则”的转折相符。", "睡觉": "语义：数字空间不能拿来睡觉，“用来睡觉的数字空间”与句意不符。", "吃饭": "语义：数字空间不能用来吃饭，与“社会演化逻辑的加速器”的论述无关，句子不成立。", "修理": "搭配：“修理”需要具体的器物作宾语，不能修理“数字空间”这类抽象概念。"}, "sentence_index": 0, "correct_answer": "消遣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天早上，我去公园消遣身体。", "explanation": "这里应该用〈锻炼〉。消遣指拿感兴趣的活动打发空闲时间，锻炼身体才用“锻炼”，不能说“消遣身体”。"}, {"text": "我非常消遣这次旅行。", "explanation": "这里应该用〈享受〉。消遣表示用活动打发时间，不用来表达对一次经历的喜爱。"}, {"text": "这份单调的工作消遣了他的意志，他终于辞职了。", "explanation": "这里应该用〈消磨〉。消遣指用有趣的活动打发时间，逐渐耗损意志要用“消磨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消遣", "is_correct": true, "explanation": "“消遣”指做让自己开心的事来打发时间，用于询问休闲方式，与“不工作的时候”的语境相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：前文说“不工作的时候”，此处再问“怎么工作”，前后自相矛盾。"}, {"text": "上班", "is_correct": false, "explanation": "语义：与前文“不工作”的条件冲突，“不工作的时候怎么上班”不成立。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”要求带具体的受事宾语，单独用在“一般怎么…”中缺少宾语，搭配不成立。"}], "explanations": {"消遣": "“消遣”指做让自己开心的事来打发时间，用于询问休闲方式，与“不工作的时候”的语境相符。", "工作": "语义：前文说“不工作的时候”，此处再问“怎么工作”，前后自相矛盾。", "上班": "语义：与前文“不工作”的条件冲突，“不工作的时候怎么上班”不成立。", "修理": "搭配：“修理”要求带具体的受事宾语，单独用在“一般怎么…”中缺少宾语，搭配不成立。"}, "sentence_index": 6, "correct_answer": "消遣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天在厨房消遣衣服。", "explanation": "这里应该用〈清洗〉。消遣的对象是时间或自己，不能用来指洗衣服这类家务。"}, {"text": "工人们用卡车消遣货物。", "explanation": "这里应该用〈运送〉。消遣是打发空闲时间的活动，不用来指搬运货物。"}, {"text": "医生用针灸消遣他的腰伤。", "explanation": "这里应该用〈治疗〉。消遣指做开心的事打发时间，不能用来处理疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在阳台上消遣很开心。", "corrected_sentence": "他在阳台上消遣得很开心。", "error_description": "错误：“消遣很开心”，漏掉了补语的“得”；正确：“消遣得很开心”。表示程度的状态补语必须用“得”连接动词与形容词短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天在家写字消遣了。", "corrected_sentence": "她每天在家写字消遣。", "error_description": "错误：“每天”表示习惯，却用了完成态的“消遣了”，“了”多余；正确：“每天在家写字消遣。”去掉“了”，“消遣”表示习惯性的活动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
