INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加速器是使物体速度增加的装置或设备。", "primary_collocate": null, "pronunciation": "jiā sù qì", "ipa": "tɕja˥ su˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "由此观之，这些看似消遣的数字空间，实则是社会演化逻辑的加速器。", "target_word": "加速器", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "科学家用加速器研究很小的粒子。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台加速器长二十七公里。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加速器能让粒子跑得非常快。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家建了一台新的加速器。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的加速器正在工作。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师检查了加速器的电源。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加速器里的粒子几乎和光一样快。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院用小型加速器治疗病人。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学里研究加速器的原理。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "粒子加速器", "label": "复合"}, {"form": "回旋加速器", "label": "复合"}], "register": "中性", "sense_fingerprint": "加速器：使物体速度增加的装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加速器", "is_correct": true, "explanation": "加速器：此处指把粒子加速的装置，与“实验”“推到接近光速”相合。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不能用来把粒子推到接近光速。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不是能加速粒子的装置。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能用来把粒子推到接近光速。"}], "explanations": {"加速器": "加速器：此处指把粒子加速的装置，与“实验”“推到接近光速”相合。", "公园": "语义：公园是供人游玩的场所，不能用来把粒子推到接近光速。", "字典": "语义：字典是工具书，不是能加速粒子的装置。", "蛋糕": "语义：蛋糕是食物，不能用来把粒子推到接近光速。"}, "sentence_index": 0, "correct_answer": "加速器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的加速器很大，三秒就能到一百公里。", "explanation": "这里应该用〈加速度〉。加速度指速度变化的快慢，是数值概念；加速器是使速度增加的装置，不能用来表示这一数值。"}, {"text": "房间太干燥，我打开了加速器。", "explanation": "这里应该用〈加湿器〉。加湿器用来增加空气湿度，加速器与湿度无关，房间干燥时不会用它。"}, {"text": "冬天的晚上，屋里的加速器一直开着。", "explanation": "这里应该用〈加热器〉。加热器用来取暖，加速器用来加快物体的速度，不能用来取暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加速器", "is_correct": true, "explanation": "加速器：检查的对象是一台设备，与“电源”搭配。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕没有电源，“检查……的电源”只能用于带电的设备。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不是机器，不存在可以检查的电源。"}, {"text": "演讲", "is_correct": false, "explanation": "搭配：“电源”属于设备，“演讲”不能带“电源”。"}], "explanations": {"加速器": "加速器：检查的对象是一台设备，与“电源”搭配。", "蛋糕": "语义：蛋糕没有电源，“检查……的电源”只能用于带电的设备。", "诗歌": "语义：诗歌不是机器，不存在可以检查的电源。", "演讲": "搭配：“电源”属于设备，“演讲”不能带“电源”。"}, "sentence_index": 6, "correct_answer": "加速器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车装了加速器，最高时速被限制在一百公里。", "explanation": "这里应该用〈限速器〉。限速器用来限制最高速度，加速器的作用是提高速度，两者正好相反，装了加速器不会限制时速。"}, {"text": "房间里的加速器一直在运行，空气变干净了。", "explanation": "这里应该用〈净化器〉。净化器用来净化空气，加速器用于加快物体速度，与空气质量无关。"}, {"text": "这台电视的加速器很大。", "explanation": "这里应该用〈显示屏〉。显示屏是电视的画面部件，加速器是加快速度的装置，电视上并没有它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家在实验室里用只加速器做实验。", "corrected_sentence": "科学家在实验室里用加速器做实验。", "error_description": "量词错误。加速器是机器，不能用量词“只”（“只”多用于动物等）。此处直接说“用加速器做实验”即可，去掉“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前用着过这台加速器。", "corrected_sentence": "我们以前用过这台加速器。", "error_description": "体貌错误。“着”与“过”不能同时使用；“以前”的经历应直接用“过”，说“用过这台加速器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
