INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12041, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "表示达到最高程度，无法再超越。", "primary_collocate": null, "pronunciation": "jí zhì", "ipa": "tɕi˧˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "它们以极致情境暴露人类互动的核心机制：在规则明确的边界内，竞争激发个体潜能，协作构筑集体韧性。", "target_word": "极致", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家餐厅给客人极致的服务。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这道菜做到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手机的设计简约到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢极致简单的生活。", "target_word": "极致", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "登上山顶，我们看到了极致的美景。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工匠们追求产品的极致。", "target_word": "极致", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动员把速度发挥到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种极致的安静让人有点害怕。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对工作的认真，已经到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "极致的", "label": "定语形式"}, {"form": "极致体验", "label": "复合"}], "register": "书面语", "sense_fingerprint": "极致|达到最高程度、无法再超越", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到最高程度、无法再超越。"}, {"text": "机制", "is_correct": false, "explanation": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。"}, {"text": "集市", "is_correct": false, "explanation": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。"}, {"text": "极值", "is_correct": false, "explanation": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到最高程度、无法再超越。", "机制": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。", "集市": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。", "极值": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“极致情境”指达到极端程度的情境，与“竞争”“协作”的描述相合。"}, {"text": "随意", "is_correct": false, "explanation": "语义：句中强调“规则明确的边界内”，“随意”与明确规则相矛盾。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与句中“规则明确”“边界”相矛盾，不能描述用来暴露核心机制的情境。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”多用于物质，不能修饰“情境”。"}], "explanations": {"极致": "与上下文相符：“极致情境”指达到极端程度的情境，与“竞争”“协作”的描述相合。", "随意": "语义：句中强调“规则明确的边界内”，“随意”与明确规则相矛盾。", "模糊": "语义：“模糊”与句中“规则明确”“边界”相矛盾，不能描述用来暴露核心机制的情境。", "坚硬": "搭配：“坚硬”多用于物质，不能修饰“情境”。"}, "sentence_index": 0, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想极致一下自己的成绩。", "explanation": "这里应该用〈提高〉。极致是名词，不能作动词带宾语。"}, {"text": "这次比赛的进步已经超过了极致。", "explanation": "极致指已达最高程度、无法再超越，不能说“超过了极致”。"}, {"text": "这个方案还有很大的极致空间。", "explanation": "这里应该用〈提升〉。极致表示已达最高、无法再超越，不能说“极致空间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12041, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到最高程度、无法再超越。"}, {"text": "直至", "is_correct": false, "explanation": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。"}, {"text": "节制", "is_correct": false, "explanation": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。"}, {"text": "基质", "is_correct": false, "explanation": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到最高程度、无法再超越。", "直至": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。", "节制": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。", "基质": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“追求产品的极致”指追求最高的完美境界。"}, {"text": "成本", "is_correct": false, "explanation": "语义：工匠追求的是品质，不是成本，句意与“追求成本”不符。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“追求”的对象多为抽象的品质或境界，“噪音”不能被追求。"}, {"text": "字数", "is_correct": false, "explanation": "语义：“字数”与产品品质无关，不能说“追求产品的字数”。"}], "explanations": {"极致": "与上下文相符：“追求产品的极致”指追求最高的完美境界。", "成本": "语义：工匠追求的是品质，不是成本，句意与“追求成本”不符。", "噪音": "搭配：“追求”的对象多为抽象的品质或境界，“噪音”不能被追求。", "字数": "语义：“字数”与产品品质无关，不能说“追求产品的字数”。"}, "sentence_index": 6, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩已经比极致还要高了。", "explanation": "极致本身已是最高程度，不能说“比极致还要高”。"}, {"text": "他的兴趣已经变成了极致的三倍。", "explanation": "极致是程度的顶点，不能用倍数来计量。"}, {"text": "这家店的服务极致了，但还有很大的极致空间。", "explanation": "这里应该用〈提升〉。极致指已达最高、无法再超越，既然已是极致，就不能说“极致空间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次演出的舞台设计达了极致。", "corrected_sentence": "这次演出的舞台设计达到了极致。", "error_description": "错误在于动词“达到”被误写为“达”，少了“到”。“到”是“达到”这个动词的组成部分，不是补语；应说“达到了极致”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的努力已经了极致。", "corrected_sentence": "他的努力已经到了极致。", "error_description": "错误在于“到”被省略。“到了极致”中的“到”不能省，应说“已经到了极致”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种能凸显人类行为本质的典型或极端场景", "primary_collocate": null, "pronunciation": "qíng jìng", "ipa": "tɕʰiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "它们以极致情境暴露人类互动的核心机制：在规则明确的边界内，竞争激发个体潜能，协作构筑集体韧性。", "target_word": "情境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "极端情境最能看出一个人的本性。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在危险的情境中，人才会露出真实的一面。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验设计了一个很极端的情境，看大家怎么选择。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争是考验人性的极端情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影把主角放进了一个生死情境里。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家用特殊情境研究人的行为。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这种两难情境，很多人都不知道怎么办。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难情境让人看清什么是真正的合作。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师设计了竞争情境，观察学生如何合作。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在极端情境下，普通人也可能做出英雄的事。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "书面语", "sense_fingerprint": "能暴露人性与行为本质的典型或极端场景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情境", "is_correct": true, "explanation": "情境：指极致、典型的场景，与“以……暴露”的搭配相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能用来“暴露人类互动的核心机制”。"}, {"text": "骨头", "is_correct": false, "explanation": "语义：骨头是人体组织，不能作为场景来“暴露人类互动的核心机制”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“极致”多修饰情境、状态等，不说“极致天气”，天气也难以暴露人的本性。"}], "explanations": {"情境": "情境：指极致、典型的场景，与“以……暴露”的搭配相合。", "咖啡": "语义：咖啡是饮品，不能用来“暴露人类互动的核心机制”。", "骨头": "语义：骨头是人体组织，不能作为场景来“暴露人类互动的核心机制”。", "天气": "搭配：“极致”多修饰情境、状态等，不说“极致天气”，天气也难以暴露人的本性。"}, "sentence_index": 0, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行后，我的情境很平静。", "explanation": "这里应该用〈心境〉。心境指内心的状态，情境指典型或极端的场景，不能用来形容一个人的心情是否平静。"}, {"text": "这个城市的情境很干净。", "explanation": "这里应该用〈环境〉。环境指周围的自然或社会条件，能“干净”的是地方，情境不能用来形容地方是否干净。"}, {"text": "这间房子的情境很合理。", "explanation": "这里应该用〈布局〉。布局指空间的安排方式，情境指典型或极端的场景，不能用来说房间的安排是否合理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情境", "is_correct": true, "explanation": "情境：此处指研究所依托的特定条件，与“用……研究”相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能用来研究人的行为。"}, {"text": "语气", "is_correct": false, "explanation": "搭配：“语气”是说话的口气，不能作为“用……研究”的工具。"}, {"text": "烧饼", "is_correct": false, "explanation": "语义：烧饼是食物，不能用来研究人的行为。"}], "explanations": {"情境": "情境：此处指研究所依托的特定条件，与“用……研究”相合。", "钢琴": "语义：钢琴是乐器，不能用来研究人的行为。", "语气": "搭配：“语气”是说话的口气，不能作为“用……研究”的工具。", "烧饼": "语义：烧饼是食物，不能用来研究人的行为。"}, "sentence_index": 6, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的情境定在北京。", "explanation": "这里应该用〈地点〉。地点指具体位置，情境指人所处的条件，不能用来指会议的位置。"}, {"text": "这道菜的情境很咸。", "explanation": "这里应该用〈味道〉。味道指食物的咸淡和口感，情境指人所处的场景，不能用来形容菜的咸淡。"}, {"text": "这个情境很舒服，我想坐一会儿。", "explanation": "这里应该用〈座位〉。座位指供人坐的位置，情境不能用来指可以坐的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一场很特殊的情境。", "corrected_sentence": "这是一种很特殊的情境。", "error_description": "量词错误。“情境”应与量词“种”搭配，“场”多用于比赛、演出等事件，不能用来修饰“情境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前经历着这种情境。", "corrected_sentence": "我们以前经历过这种情境。", "error_description": "体貌错误。“以前”指已经完成的经历，应用“过”，说“经历过这种情境”；“着”表示动作持续，与“以前”不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
