INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "潜在的能力或才能，尚未完全显现出来的天赋。", "primary_collocate": null, "pronunciation": "qián néng", "ipa": "tɕʰjɛn˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "它们以极致情境暴露人类互动的核心机制：在规则明确的边界内，竞争激发个体潜能，协作构筑集体韧性。", "target_word": "潜能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个孩子都有自己的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会帮学生发现潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛让他发挥了全部潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力有时能激发人的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的音乐潜能很大，只是还没人发现。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员要不断挖掘自己的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想给年轻人更多发挥潜能的机会。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以为自己没有潜能，其实只是不够努力。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习新技能能开发大脑的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别小看自己，你的潜能比你想的大。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "尚未完全显现的潜在能力或天赋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“激发”可以接能力、情绪，不能接颜色，“激发个体颜色”不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是人的体貌数据，不能被竞争激发，“激发个体身高”不成立。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是植物纤维，不能被竞争激发，“激发个体棉花”文意不通。"}, {"text": "潜能", "is_correct": true, "explanation": "潜能指潜在的能力或天赋，尚未显现，这里指竞争激发出的个体潜在能力，符合语境。"}], "explanations": {"颜色": "搭配：“激发”可以接能力、情绪，不能接颜色，“激发个体颜色”不通。", "身高": "搭配：身高是人的体貌数据，不能被竞争激发，“激发个体身高”不成立。", "棉花": "语义：棉花是植物纤维，不能被竞争激发，“激发个体棉花”文意不通。", "潜能": "潜能指潜在的能力或天赋，尚未显现，这里指竞争激发出的个体潜在能力，符合语境。"}, "sentence_index": 0, "correct_answer": "潜能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了一个小时，潜能还很好。", "explanation": "这里应该用〈体力〉。说现在的体力状况要用体力；潜能只指尚未显现的能力，不说现在的身体状况。"}, {"text": "这次考试他取得了很好的潜能。", "explanation": "这里应该用〈成绩〉。取得的是成绩；潜能是尚未显现的能力，不能被“取得”。"}, {"text": "他每个月的潜能是三千元。", "explanation": "这里应该用〈工资〉。每月拿到的三千元是工资；潜能指尚未显现的才能，不能用来说金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑容", "is_correct": false, "explanation": "搭配：“挖掘”可以接资源、潜力，不能接笑容，“挖掘笑容”不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“挖掘自己的口味”不成立，口味不能用“挖掘”来说。"}, {"text": "煤", "is_correct": false, "explanation": "语义：煤是矿物，不是运动员内在的东西，“挖掘自己的煤”文意不通。"}, {"text": "潜能", "is_correct": true, "explanation": "潜能指尚未显现的能力，运动员挖掘自己的潜能，符合语境。"}], "explanations": {"笑容": "搭配：“挖掘”可以接资源、潜力，不能接笑容，“挖掘笑容”不通。", "口味": "搭配：“挖掘自己的口味”不成立，口味不能用“挖掘”来说。", "煤": "语义：煤是矿物，不是运动员内在的东西，“挖掘自己的煤”文意不通。", "潜能": "潜能指尚未显现的能力，运动员挖掘自己的潜能，符合语境。"}, "sentence_index": 6, "correct_answer": "潜能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的游泳潜能已经很熟练了。", "explanation": "这里应该用〈技能〉。熟练说的是已经掌握的技能；潜能指尚未显现的能力，不能说熟练。"}, {"text": "她瘦了五公斤，潜能变得很苗条。", "explanation": "这里应该用〈身材〉。苗条形容人的身材；潜能不能用来形容人的体型。"}, {"text": "这次旅行是我最难忘的潜能。", "explanation": "这里应该用〈经历〉。最难忘的是经历；潜能不能用来指一段难忘的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都有一件值得开发的潜能。", "corrected_sentence": "每个人都有一种值得开发的潜能。", "error_description": "量词错误：“潜能”应用量词“种”，不能用“件”（件多用于事情、物品）。正确说法是“一种值得开发的潜能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把潜能发挥下来了。", "corrected_sentence": "他终于把潜能发挥出来了。", "error_description": "补语错误：“发挥”后应接“出来”，表示潜能显现出来；“下来”不能用于此，应说“发挥出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上层", "is_correct": true, "explanation": "上层与底层相对，指堆叠结构中位于上面的层次，如“上层应用”。"}, {"text": "核心", "is_correct": false, "explanation": "语义：核心指事物最重要的部分，与底层不构成反义关系。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，与底层的层次关系无关。"}, {"text": "功能", "is_correct": false, "explanation": "语义：功能指事物的作用，与底层的层次关系无关。"}], "correct_answer": "上层", "explanations": {"上层": "上层与底层相对，指堆叠结构中位于上面的层次，如“上层应用”。", "核心": "语义：核心指事物最重要的部分，与底层不构成反义关系。", "沙发": "语义：沙发是家具，与底层的层次关系无关。", "功能": "语义：功能指事物的作用，与底层的层次关系无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上层", "is_correct": true, "explanation": "上层与底层相对，指堆叠结构中位于上面的层次，如“上层应用”。"}, {"text": "文档", "is_correct": false, "explanation": "语义：文档指记录文字的材料，与底层没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩的属性，与底层没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是艺术形式，与底层没有反义关系。"}], "correct_answer": "上层", "explanations": {"上层": "上层与底层相对，指堆叠结构中位于上面的层次，如“上层应用”。", "文档": "语义：文档指记录文字的材料，与底层没有反义关系。", "颜色": "语义：颜色指色彩的属性，与底层没有反义关系。", "音乐": "语义：音乐是艺术形式，与底层没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "支撑整个系统运作的基础结构或层次", "primary_collocate": null, "pronunciation": "dǐ céng", "ipa": "ti˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这意味着，同一代理可在不同计算平台间无缝迁移，其长期记忆与行为模式不受底层模型更迭的影响。", "target_word": "底层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "手机的底层系统是公司自己做的。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查软件的底层代码。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题出在底层，不在界面上。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学电脑要先了解底层的原理。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层技术好，上面的应用才稳定。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们重新设计了网站的底层结构。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层出了错，整个系统都会停。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序的底层是用简单的语言写的。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想改进速度，得先改底层。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "底層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "系统或技术中支撑上层运作的基础层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层：dǐ céng，指支撑整个系统运作的基础层。"}, {"text": "地层", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。"}, {"text": "顶层", "is_correct": false, "explanation": "dǐng（第三声）与 dǐ 韵母不同（多一个 -ng），意思是顶部的一层，与底层相反。"}, {"text": "里层", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}], "explanations": {"底层": "底层：dǐ céng，指支撑整个系统运作的基础层。", "地层": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。", "顶层": "dǐng（第三声）与 dǐ 韵母不同（多一个 -ng），意思是顶部的一层，与底层相反。", "里层": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}, "sentence_index": null, "correct_answer": "底层"}, "level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指作为基础的层次，这里指支撑上层模型的基础层。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以更迭的模型层，句意说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不指可以更迭的技术层，句意说不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡模型”不成立，“模型更迭”要求技术层级的名词。"}], "explanations": {"底层": "底层指作为基础的层次，这里指支撑上层模型的基础层。", "天空": "语义：天空不是可以更迭的模型层，句意说不通。", "石头": "语义：石头是物体，不指可以更迭的技术层，句意说不通。", "咖啡": "搭配：“咖啡模型”不成立，“模型更迭”要求技术层级的名词。"}, "sentence_index": 0, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用户点击了底层，页面就打开了。", "explanation": "这里应该用〈按钮〉。按钮可以被点击，点击后打开页面；底层是支撑系统运作的基础结构，不能被点击。"}, {"text": "用户通过底层欣赏电影。", "explanation": "这里应该用〈屏幕〉。屏幕是用户观看内容的部分；底层是支撑系统运作的基础结构，不用来观看。"}, {"text": "他按下了底层，灯就亮了。", "explanation": "这里应该用〈开关〉。开关可以按下，按下后灯会亮；底层是支撑系统运作的基础结构，不能按下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指网站的基础构造，与“结构”搭配，符合“重新设计”的语境。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一餐饭，不能作为网站的构造。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“结构”前的修饰语要指系统或组织的构造，“窗帘”不能修饰“结构”。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓是水果，不指网站的组成部分。"}], "explanations": {"底层": "底层指网站的基础构造，与“结构”搭配，符合“重新设计”的语境。", "早餐": "语义：早餐是一餐饭，不能作为网站的构造。", "窗帘": "搭配：“结构”前的修饰语要指系统或组织的构造，“窗帘”不能修饰“结构”。", "草莓": "语义：草莓是水果，不指网站的组成部分。"}, "sentence_index": 6, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把底层打开了，屋里很亮。", "explanation": "这里应该用〈窗户〉。窗户可以打开，打开后屋里变亮；底层是支撑系统的基础结构，不能打开。"}, {"text": "他把底层装进了口袋。", "explanation": "这里应该用〈硬币〉。硬币可以装进口袋；底层指支撑系统运作的基础结构，不能装进口袋。"}, {"text": "底层程序直接面向用户。", "explanation": "这里应该用〈应用〉。应用是直接面向用户的程序；底层是支撑它们运行的基础层，不直接面向用户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次故障出底层。", "corrected_sentence": "这次故障出在底层。", "error_description": "介词漏用：“出”后表示处所要加介词“在”，应说“出在底层”，不能说“出底层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个程序的底层写很好。", "corrected_sentence": "这个程序的底层写得很好。", "error_description": "补语漏“得”：“写”后要加“得”，说“写得很好”，不能说“写很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
