INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物赖以存在和发展的基本框架或底层基础", "primary_collocate": null, "pronunciation": "jī zhì", "ipa": "tɕi˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "而互联网作为底层基质，不仅连接设备，更重构了归属感的生成路径——归属不再源于地缘或血缘的宿命，而诞生于共同叙事与目标驱动的瞬时共鸣。", "target_word": "基质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "信任是社会关系的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言是文化最重要的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭是孩子性格形成的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络成了现代生活的底层基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的历史是民族认同的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有诚信这个基质，市场就无法运行。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据是人工智能发展的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种价值观是整个制度的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育是国家发展的底层基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "底层基质", "label": "复合"}, {"form": "基質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物存在和发展所依赖的底层基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指事物赖以存在和发展的底层基础。"}, {"text": "极致", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。"}, {"text": "几只", "is_correct": false, "explanation": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。"}, {"text": "寄至", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}], "explanations": {"基质": "正确。基质指事物赖以存在和发展的底层基础。", "极致": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。", "几只": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。", "寄至": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。此处指互联网作为底层的基础结构，与“底层”搭配。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：互联网不能作为“花朵”式的底层基础，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“底层”不与“颜色”组合，它表示基础层，不是颜色。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不能作为连接设备的底层基础，句意不通。"}], "explanations": {"基质": "正确。此处指互联网作为底层的基础结构，与“底层”搭配。", "花朵": "语义：互联网不能作为“花朵”式的底层基础，句意不通。", "颜色": "搭配：“底层”不与“颜色”组合，它表示基础层，不是颜色。", "乐器": "语义：乐器不能作为连接设备的底层基础，句意不通。"}, "sentence_index": 0, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用基质织了一件毛衣。", "explanation": "这里应该用〈毛线〉。基质指事物赖以存在的底层基础，不是织衣的材料。"}, {"text": "他把这个基质涂成了红色。", "explanation": "这里应该用〈油漆〉。基质指抽象的底层基础，不能涂抹上色。"}, {"text": "我们给这个基质配了一个漂亮的相框。", "explanation": "这里应该用〈照片〉。基质是抽象的底层基础，不能装进相框。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指事物赖以存在和发展的底层基础。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。"}, {"text": "精致", "is_correct": false, "explanation": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。"}, {"text": "鸡只", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}], "explanations": {"基质": "正确。基质指事物赖以存在和发展的底层基础。", "资质": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。", "精致": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。", "鸡只": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。此处指市场运行所依赖的底层基础，与“没有……就无法运行”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是市场运行的底层基础，句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不能作为市场运行的底层条件，句子不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“诚信这个”后接的应是抽象的基础条件，不能与“颜色”组合。"}], "explanations": {"基质": "正确。此处指市场运行所依赖的底层基础，与“没有……就无法运行”相符。", "天气": "语义：天气不是市场运行的底层基础，句意不通。", "音乐": "语义：音乐不能作为市场运行的底层条件，句子不成立。", "颜色": "搭配：“诚信这个”后接的应是抽象的基础条件，不能与“颜色”组合。"}, "sentence_index": 6, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上用基质刷牙。", "explanation": "这里应该用〈牙膏〉。基质指抽象的底层基础，不能用来刷牙。"}, {"text": "他的基质跑得很快。", "explanation": "这里应该用〈速度〉。基质指抽象的底层基础，不能形容跑步的快慢。"}, {"text": "妈妈用基质给花浇水。", "explanation": "这里应该用〈清水〉。基质指抽象的底层基础，不能用来浇花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "信任是社会关系地重要基质。", "corrected_sentence": "信任是社会关系的重要基质。", "error_description": "结构助词错误：“社会关系”与“重要基质”之间应用“的”，此处误用“地”；“地”用于动词前作状语，不能修饰名词。应说“社会关系的重要基质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法治是社会秩序赖以存在的基质们。", "corrected_sentence": "法治是社会秩序赖以存在的基质。", "error_description": "“们”不能加在抽象物质名词“基质”后表示复数，句中应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
