INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指个体对某个群体或环境产生的心理认同和情感依赖，觉得自己是其中一部分。", "primary_collocate": null, "pronunciation": "guī shǔ gǎn", "ipa": "kweɪ˥ ʂu˨˩˦ kan˨˩˦", "syllable_count": 3, "sentences": [{"text": "而互联网作为底层基质，不仅连接设备，更重构了归属感的生成路径——归属不再源于地缘或血缘的宿命，而诞生于共同叙事与目标驱动的瞬时共鸣。", "target_word": "归属感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "住了三年，我对这个城市有了归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在新公司，同事们都很热情，他很快有了归属感。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人坐在一起吃饭，让人很有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚搬来的时候，我没有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加入球队以后，他找到了归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师常常组织活动，让学生有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对留学生来说，归属感很重要。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个社区很小，邻居们互相帮忙，居民的归属感很强。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的欢迎让我第一次感到了归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种归属感", "label": "量词"}, {"form": "一份归属感", "label": "量词"}], "register": "中性", "sense_fingerprint": "对群体或环境的心理认同与情感依赖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指个体对群体的心理认同，“重构”的正是这种认同的生成路径，与语境相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不是心理认同，不能作为被“重构”的生成路径的对象，句子不成立。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是器物，与“重构…生成路径”的抽象论述不相容。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“重构”多与体系、结构、认同等抽象对象搭配，不说“重构窗户”。"}], "explanations": {"归属感": "“归属感”指个体对群体的心理认同，“重构”的正是这种认同的生成路径，与语境相符。", "温度": "语义：“温度”不是心理认同，不能作为被“重构”的生成路径的对象，句子不成立。", "螺丝": "语义：螺丝是器物，与“重构…生成路径”的抽象论述不相容。", "窗户": "搭配：“重构”多与体系、结构、认同等抽象对象搭配，不说“重构窗户”。"}, "sentence_index": 0, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的分数让他很有归属感。", "explanation": "这里应该用〈失望〉。归属感指觉得属于某群体的心理认同，考试分数带来的情绪要用“失望”。"}, {"text": "他终于解出了那道难题，心里充满了归属感。", "explanation": "这里应该用〈成就感〉。归属感指觉得属于某群体的心理认同，解题后的满足要用“成就感”。"}, {"text": "听到雷声，他心里很有归属感。", "explanation": "这里应该用〈害怕〉。归属感指觉得属于某群体的心理认同，突然的雷声带来的恐惧要用“害怕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指觉得属于某群体的心理认同，与“让学生有…”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“有”给学生的心理感受，句子不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，与“老师组织活动”带来的感受无关。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“有螺丝”不构成表示心理感受的常见搭配。"}], "explanations": {"归属感": "“归属感”指觉得属于某群体的心理认同，与“让学生有…”的语境相符。", "天气": "语义：天气不是可以“有”给学生的心理感受，句子不成立。", "颜色": "语义：颜色是事物的属性，与“老师组织活动”带来的感受无关。", "螺丝": "搭配：“有螺丝”不构成表示心理感受的常见搭配。"}, "sentence_index": 6, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在大家面前说错了话，脸上很有归属感。", "explanation": "这里应该用〈尴尬〉。归属感指心理认同，不能用来形容脸上的神情；说错话后的难堪要用“尴尬”。"}, {"text": "考试让他感到了很大的归属感。", "explanation": "这里应该用〈压力〉。归属感指对群体的认同，不用来形容考试带来的负担。"}, {"text": "他把这首歌背得很有归属感。", "explanation": "这里应该用〈熟〉。归属感指心理认同，不能用来形容背歌的程度；要说“背得很熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇让我产生了一颗归属感。", "corrected_sentence": "这个小镇让我产生了一种归属感。", "error_description": "错误：“一颗归属感”，量词“颗”用于小而圆的东西，不能修饰抽象的心理感受；正确：“一种归属感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的活动让学生增强了很归属感。", "corrected_sentence": "学校的活动让学生增强了归属感。", "error_description": "错误：“很归属感”，程度副词“很”不能直接修饰名词“归属感”；正确：“增强了归属感”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
