INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某事物或某人属于某个群体、地方或某人的范围。", "primary_collocate": null, "pronunciation": "guī shǔ", "ipa": "kweɪ˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座古城的管辖权最终归属于中央政府。", "target_word": "归属", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这片森林归属于国家。", "target_word": "归属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这幅画归属于谁，大家还在争论。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛的奖杯归属于三班。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小岛归属于哪个国家？", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这类工作归属于人事部门。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "按照合同，这辆车归属于公司。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书归属于学校图书馆，不能带走。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包归属于谁，你知道吗？", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些作品归属于同一个作者。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "归属于", "label": "搭配"}], "register": "中性", "sense_fingerprint": "事物或人属于某个群体、地方或某人的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属”在此指管辖权归于某一方，与“最终……于中央政府”的所属语境相符。"}, {"text": "隔绝", "is_correct": false, "explanation": "语义：“隔绝”指阻断联系，与“管辖权最终……于中央政府”的所属关系不相容，句子不成立。"}, {"text": "解散", "is_correct": false, "explanation": "语义：“解散”指团体分散，不适用于管辖权的归向，句子不成立。"}, {"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容声音嘈杂，不能与管辖权的归向搭配，“喧闹于中央政府”不成立。"}], "explanations": {"归属": "正确：“归属”在此指管辖权归于某一方，与“最终……于中央政府”的所属语境相符。", "隔绝": "语义：“隔绝”指阻断联系，与“管辖权最终……于中央政府”的所属关系不相容，句子不成立。", "解散": "语义：“解散”指团体分散，不适用于管辖权的归向，句子不成立。", "喧闹": "搭配：“喧闹”形容声音嘈杂，不能与管辖权的归向搭配，“喧闹于中央政府”不成立。"}, "sentence_index": 0, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场争论最终归属于平静。", "explanation": "这里应该用〈归于〉。归属表示所属，不能表示争论最终变成平静的状态。"}, {"text": "这些资料最终归属于一个结论。", "explanation": "这里应该用〈归纳〉。归属表示所属，不能表示从资料中概括出结论。"}, {"text": "他伤好以后终于归属于那张病床。", "explanation": "这里应该用〈归队〉。归属表示所属，不能表示伤愈后回到原来的部队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属于公司”表示车辆归公司所有，与“按照合同”一致。"}, {"text": "忠于", "is_correct": false, "explanation": "语义：“忠于”的对象须是人或事业，车辆不能忠于公司。"}, {"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示相等，与表示所属的语境无关。"}, {"text": "依赖于", "is_correct": false, "explanation": "语义：车辆不能“依赖于”公司，这里的“依赖”表示依靠，与“按照合同”的所属语境不符。"}], "explanations": {"归属": "正确：“归属于公司”表示车辆归公司所有，与“按照合同”一致。", "忠于": "语义：“忠于”的对象须是人或事业，车辆不能忠于公司。", "等于": "语义：“等于”表示相等，与表示所属的语境无关。", "依赖于": "语义：车辆不能“依赖于”公司，这里的“依赖”表示依靠，与“按照合同”的所属语境不符。"}, "sentence_index": 6, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个部门的工作将归属于一个。", "explanation": "这里应该用〈归并〉。归属表示所属，不表示把两个部门合并成一个。"}, {"text": "玩完游戏后，棋子终于归属于原位了。", "explanation": "这里应该用〈归位〉。归属表示所属，不能表示把棋子放回原位。"}, {"text": "一切都归属于平静。", "explanation": "这里应该用〈归于〉。归属只表示所属，不能表示最终变成某种状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座房子归属王先生。", "corrected_sentence": "这座房子归属于王先生。", "error_description": "错误在于“归属”后漏掉了介词“于”。作动词时，所属方要用“归属于”引出，应为“归属于王先生”；直接接名词不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔奖金已经归属于我们过。", "corrected_sentence": "这笔奖金已经归属于我们了。", "error_description": "错误在于动态助词。表示动作已经完成并产生结果，应用“了”；“过”表示曾经有过的经历，与“已经”的完成语气相矛盾。正确为“归属于我们了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宿命指一种认为人的命运由某种超越力量事先决定、无法改变的观念。", "primary_collocate": null, "pronunciation": "sù mìng", "ipa": "su˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "而互联网作为底层基质，不仅连接设备，更重构了归属感的生成路径——归属不再源于地缘或血缘的宿命，而诞生于共同叙事与目标驱动的瞬时共鸣。", "target_word": "宿命", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他相信宿命，觉得努力没有用。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是人和宿命的斗争。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿接受宿命，决定自己改变生活。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多古老的故事都谈到宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把失败看成宿命，不再尝试。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿命让人觉得一切都是天意。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说，这是宿命，没办法。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说写了一个家族的宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不太相信宿命，更相信努力。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿命论", "label": "复合"}], "register": "书面", "sense_fingerprint": "相信命运早已注定、无法改变的观念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宿命", "is_correct": true, "explanation": "宿命（sù mìng）：指命运早已注定、无法改变的观念。"}, {"text": "续命", "is_correct": false, "explanation": "续命（xù mìng）与宿命声母不同，x 与 s 对立，意思是延续生命。"}, {"text": "署名", "is_correct": false, "explanation": "署名（shǔ míng）与宿命声母不同（sh 与 s），第二音节声调也变了，意思是在文件上签名。"}, {"text": "书名", "is_correct": false, "explanation": "书名（shū míng）与宿命声母不同（sh 与 s），声调也不同，意思是书的名称。"}], "explanations": {"宿命": "宿命（sù mìng）：指命运早已注定、无法改变的观念。", "续命": "续命（xù mìng）与宿命声母不同，x 与 s 对立，意思是延续生命。", "署名": "署名（shǔ míng）与宿命声母不同（sh 与 s），第二音节声调也变了，意思是在文件上签名。", "书名": "书名（shū míng）与宿命声母不同（sh 与 s），声调也不同，意思是书的名称。"}, "sentence_index": null, "correct_answer": "宿命"}, "level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "宿命：指命运早已注定、无法改变的观念，与“归属不再源于……”的语境相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能作为“归属”的来源，句意不通。"}, {"text": "老天爷", "is_correct": false, "explanation": "语域：“老天爷”是口语，与本句的书面语体不合，且句意不通。"}, {"text": "公寓", "is_correct": false, "explanation": "语义：“公寓”是住所，不能作为“归属”的来源。"}], "explanations": {"宿命": "宿命：指命运早已注定、无法改变的观念，与“归属不再源于……”的语境相合。", "天气": "语义：“天气”不能作为“归属”的来源，句意不通。", "老天爷": "语域：“老天爷”是口语，与本句的书面语体不合，且句意不通。", "公寓": "语义：“公寓”是住所，不能作为“归属”的来源。"}, "sentence_index": 0, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我的宿命很好。", "explanation": "这里应该用〈运气〉。宿命指命运早已注定的观念，不能用来形容好坏；说“运气很好”才自然。"}, {"text": "他的宿命每天都在变化，他可以自己选择。", "explanation": "这里应该用〈命运〉。宿命指命运早已注定、无法改变；每天变化、可以自己选择的是命运，不能用“宿命”。"}, {"text": "这次宿命很难忘。", "explanation": "这里应该用〈经历〉。宿命是一种观念，不是发生过的事，不能用“难忘”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "宿命：指命运早已注定的观念，与“让人觉得一切都是天意”相合。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的语体不合，且句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能让人觉得一切都是天意。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：“菜单”是点菜用的单子，与“天意”的观念无关。"}], "explanations": {"宿命": "宿命：指命运早已注定的观念，与“让人觉得一切都是天意”相合。", "玩意儿": "语域：“玩意儿”是口语，与书面的语体不合，且句意不通。", "冰箱": "语义：“冰箱”是家电，不能让人觉得一切都是天意。", "菜单": "语义：“菜单”是点菜用的单子，与“天意”的观念无关。"}, "sentence_index": 6, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的宿命很开朗。", "explanation": "这里应该用〈性格〉。宿命是观念，不能用来形容人的性格开朗。"}, {"text": "这次考试的宿命很好。", "explanation": "这里应该用〈成绩〉。宿命不是考试的结果，不能用来评价成绩好坏。"}, {"text": "这家饭店的宿命很周到。", "explanation": "这里应该用〈服务〉。宿命指观念，不能用来形容服务周到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他认为这是一只宿命。", "corrected_sentence": "他认为这是一种宿命。", "error_description": "量词用错：“只”用于动物，宿命是抽象观念，应说“一种宿命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他决心打开宿命。", "corrected_sentence": "他决心打破宿命。", "error_description": "动词搭配错误：宿命是注定无法改变的观念，应说“打破”，“打开”不能与之搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
