INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指别人的想法、感情或经历引起自己相同的感受，就像两个物体一起振动一样。", "primary_collocate": null, "pronunciation": "gòng míng", "ipa": "kʊŋ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当一则民间传说跨越千年仍能引发共鸣，其力量不在于事件的考古真实性，而在于它对人性困境的原型性捕捉。", "target_word": "共鸣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌写出了很多人的心声，引起了大家的共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事让我产生了强烈的共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读这本书时，我对主人公的遭遇很有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在电影里看到自己的生活，心里有了共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演讲者讲了自己的经历，听众都有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章说出了年轻人的烦恼，所以很容易得到共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很普通，却让很多读者产生了共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "furigana": "gòng míng", "sentence_source": "generated"}, {"text": "老师讲的那个小故事，在学生心中引起了共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的诗没有引起读者的共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共鳴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "共鸣：别人的想法、感情或经历引起自己相同的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利息", "is_correct": false, "explanation": "搭配：“引发”的对象是情感或事件，“利息”是经济概念，不能被引发。"}, {"text": "共鸣", "is_correct": true, "explanation": "共鸣：指读者因传说而产生相同的感受，与“引发”搭配，符合句意。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”指医疗操作，与句中传说引起的心理效应无关。"}, {"text": "货币", "is_correct": false, "explanation": "语义：“货币”是经济概念，传说不能引发它，句意不通。"}], "explanations": {"利息": "搭配：“引发”的对象是情感或事件，“利息”是经济概念，不能被引发。", "共鸣": "共鸣：指读者因传说而产生相同的感受，与“引发”搭配，符合句意。", "手术": "语义：“手术”指医疗操作，与句中传说引起的心理效应无关。", "货币": "语义：“货币”是经济概念，传说不能引发它，句意不通。"}, "sentence_index": 0, "correct_answer": "共鸣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这张旧桌子很有共鸣，所以把它搬回了家。", "explanation": "这里应该用〈喜欢〉。共鸣用于人或经历之间的感受相同，不能用来表示对一件物品的好感；表示喜爱应用“喜欢”。"}, {"text": "我对这个新同事很有共鸣，每次开会却都要跟他吵一架。", "explanation": "这里应该用〈敌意〉。共鸣表示感受一致、彼此认同，与“吵架”的对立态度矛盾；表示对立应用“敌意”。"}, {"text": "这种做法让我很有共鸣，我当场就对它大发脾气。", "explanation": "这里应该用〈愤怒〉。共鸣表示认同、感受一致，与“大发脾气”的情绪矛盾；表示生气应用“愤怒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "语义：“地震”指自然灾害，与文章中年轻人烦恼引起的情感联系无关。"}, {"text": "病毒", "is_correct": false, "explanation": "搭配：“得到”后一般接成果、机会、感受等，“病毒”通常说“感染”，不能说“很容易得到病毒”。"}, {"text": "共鸣", "is_correct": true, "explanation": "共鸣：指读者因文章说出自己的烦恼而产生相同感受，与“得到”搭配，句意通顺。"}, {"text": "磁铁", "is_correct": false, "explanation": "语义：“磁铁”是物体，与文章表达的读者感受无关，句意不通。"}], "explanations": {"地震": "语义：“地震”指自然灾害，与文章中年轻人烦恼引起的情感联系无关。", "病毒": "搭配：“得到”后一般接成果、机会、感受等，“病毒”通常说“感染”，不能说“很容易得到病毒”。", "共鸣": "共鸣：指读者因文章说出自己的烦恼而产生相同感受，与“得到”搭配，句意通顺。", "磁铁": "语义：“磁铁”是物体，与文章表达的读者感受无关，句意不通。"}, "sentence_index": 6, "correct_answer": "共鸣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这盘蛋糕很有共鸣，一口气吃了三块。", "explanation": "这里应该用〈喜爱〉。共鸣用于人或经历之间的感受相同，不能用来表示对食物的喜爱；表示喜欢吃应用“喜爱”。"}, {"text": "他对这个笑话很有共鸣，却当场大声骂它没意思。", "explanation": "这里应该用〈嫌弃〉。共鸣表示认同、感受一致，与“当场大声骂它没意思”的态度矛盾；表示厌恶、看不起应用“嫌弃”。"}, {"text": "我对他的说法一直很有共鸣，每次听到都想走开。", "explanation": "这里应该用〈反感〉。共鸣表示认同、感受一致，与“每次听到都想走开”的态度矛盾；表示厌烦、不愿接受应用“反感”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首老歌让我对童年深深的共鸣。", "corrected_sentence": "这首老歌让我对童年有了深深的共鸣。", "error_description": "漏掉“有了”：“共鸣”作宾语需要“有了”等动词带出，“让我对童年深深的共鸣”不成句，应为“有了深深的共鸣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段话让很多人在心里产生了一支共鸣。", "corrected_sentence": "这段话让很多人在心里产生了一阵共鸣。", "error_description": "量词错误：“支”多用于歌曲、队伍等，“共鸣”是一种感受，应用“阵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
