INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "密钥是用于加密或解密信息的秘密代码或钥匙。", "primary_collocate": null, "pronunciation": "mì yào", "ipa": "mi˥˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "发送方先生成一把密钥，再用它把文件加密。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有密钥，别人打不开这个加密文件。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把密钥发给我，我来解密这份文件。", "target_word": "密钥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心丢了密钥，文件再也读不出来了。", "target_word": "密钥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密钥越长，加密的信息就越安全。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行用密钥保护客户的账户信息。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把密钥只有管理员才知道。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每个月都会更换一次密钥。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑客想偷走我们的密钥。", "target_word": "密钥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "收到加密邮件后，要用密钥才能解开。", "target_word": "密钥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "密钥|加密解密所用的秘密代码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密钥", "is_correct": true, "explanation": "正确：“生成一把密钥”指加密所用的秘密代码，与“再用它把文件加密”相合。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛放花枝的器具，不能用来加密文件，句意不通。"}, {"text": "伞", "is_correct": false, "explanation": "语义：伞用于遮雨，不能用来加密文件，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能用来加密文件，句意不通。"}], "explanations": {"密钥": "正确：“生成一把密钥”指加密所用的秘密代码，与“再用它把文件加密”相合。", "花瓶": "语义：花瓶是盛放花枝的器具，不能用来加密文件，句意不通。", "伞": "语义：伞用于遮雨，不能用来加密文件，句意不通。", "椅子": "语义：椅子是家具，不能用来加密文件，句意不通。"}, "sentence_index": 0, "correct_answer": "密钥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用密钥炒了一盘青菜。", "explanation": "这里不应使用〈密钥〉：它指加解密所用的代码，不能用来炒菜。"}, {"text": "他的书包里装着一条密钥。", "explanation": "量词错误：〈条〉用于细长的物品，密钥应用〈把〉或〈个〉。"}, {"text": "她的抽屉里有一根密钥。", "explanation": "量词错误：〈根〉用于细长条状物，密钥应用〈把〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密钥", "is_correct": true, "explanation": "正确：“这把密钥”指保密的代码，与“只有管理员才知道”相合。"}, {"text": "刀", "is_correct": false, "explanation": "语义：刀不是只有管理员才知道的秘密，句意不通。"}, {"text": "扇子", "is_correct": false, "explanation": "语义：扇子不构成“只有管理员才知道”的保密对象。"}, {"text": "凳子", "is_correct": false, "explanation": "搭配：“凳子”不需要保密，与“只有管理员才知道”不搭。"}], "explanations": {"密钥": "正确：“这把密钥”指保密的代码，与“只有管理员才知道”相合。", "刀": "语义：刀不是只有管理员才知道的秘密，句意不通。", "扇子": "语义：扇子不构成“只有管理员才知道”的保密对象。", "凳子": "搭配：“凳子”不需要保密，与“只有管理员才知道”不搭。"}, "sentence_index": 6, "correct_answer": "密钥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收到加密邮件后，要用这张密钥才能解开。", "explanation": "量词错误：〈张〉用于纸张等平面物品，〈密钥〉应用〈把〉或〈个〉。"}, {"text": "收到加密邮件后，要用这只密钥才能解开。", "explanation": "量词错误：〈只〉多用于动物或成对的器物，〈密钥〉应用〈把〉或〈个〉。"}, {"text": "收到加密邮件后，要用这块密钥才能解开。", "explanation": "量词错误：〈块〉用于块状物，〈密钥〉应用〈把〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周都要更换一条密钥。", "corrected_sentence": "我们每周都要更换一把密钥。", "error_description": "错误在于量词。“密钥”应用〈把〉或〈个〉，〈条〉多用于细长的物品；正确为“一把密钥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把旧密钥换了掉。", "corrected_sentence": "我们把旧密钥换掉了。", "error_description": "错误在于“了”的位置。“换掉”是动补结构，“了”应放在补语“掉”之后的句末，正确为“把旧密钥换掉了”；“了”插在“换”和“掉”之间不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
