INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "启发指示，使人领悟道理。", "primary_collocate": null, "pronunciation": "qǐ shì", "ipa": "tɕʰi²¹⁴ ʂɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "虚拟世界因而成为理解21世纪社会性的一把密钥，其启示或许终将反哺现实世界的组织哲学与共同体构建。", "target_word": "启示", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个故事给了我很大的启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话对我是一个启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败给我们一个重要的启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多生活的启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从这件事中得到了启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验带给科学家新的启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的经历给年轻人很多启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然给了设计师不少启示。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的启示是要珍惜时间。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "啟示", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：事物或经历带给人的启发和领悟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7846ece-b54f-4e87-9fd6-ee570f2cbede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：启发指示，使人领悟道理，即本题目标词。"}, {"text": "气势", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是气势、气派。"}, {"text": "起始", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是开始、起点。"}, {"text": "喜事", "is_correct": false, "explanation": "x 与 q 声母不同，声调相同，意思是喜庆的事。"}], "explanations": {"启示": "启示：启发指示，使人领悟道理，即本题目标词。", "气势": "qì（第四声）与 qǐ（第三声）声调不同，意思是气势、气派。", "起始": "shǐ（第三声）与 shì（第四声）声调不同，意思是开始、起点。", "喜事": "x 与 q 声母不同，声调相同，意思是喜庆的事。"}, "sentence_index": null, "correct_answer": "启示"}, "level_3": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：此处为“启发、领悟”义，与“一把密钥”“反哺”的语境相合，是唯一能填入的词。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，不能“反哺”组织哲学与共同体构建，句意不通。"}, {"text": "段子", "is_correct": false, "explanation": "语域：段子是口语化的笑话，与这句学术化的书面语不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，无法作为理解社会性的密钥来反哺现实世界。"}], "explanations": {"启示": "启示：此处为“启发、领悟”义，与“一把密钥”“反哺”的语境相合，是唯一能填入的词。", "门票": "语义：门票是入场凭证，不能“反哺”组织哲学与共同体构建，句意不通。", "段子": "语域：段子是口语化的笑话，与这句学术化的书面语不合。", "天气": "语义：天气是自然现象，无法作为理解社会性的密钥来反哺现实世界。"}, "sentence_index": 0, "correct_answer": "启示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议上领导作了一个重要的启示。", "explanation": "这里应该用〈指示〉。指示是上级下达的指令，启示指启发领悟，不能由领导“作”出启示。"}, {"text": "警察在现场找到了一个重要的启示。", "explanation": "这里应该用〈线索〉。线索是可以在现场找到的东西，启示指启发领悟的道理，不能被“找到”。"}, {"text": "他在法庭上提交了一个启示，证明了被告有罪。", "explanation": "这里应该用〈证据〉。证据是用来证明事实的材料；启示指启发领悟的道理，不能在法庭上作为证据提交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：启发指示，使人领悟道理，即本题目标词。"}, {"text": "歧视", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是区别对待、看不起人。"}, {"text": "奇事", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇异的事情。"}, {"text": "此事", "is_correct": false, "explanation": "c 与 q 声母不同，声调相同，意思是这件事。"}], "explanations": {"启示": "启示：启发指示，使人领悟道理，即本题目标词。", "歧视": "qí（第二声）与 qǐ（第三声）声调不同，意思是区别对待、看不起人。", "奇事": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇异的事情。", "此事": "c 与 q 声母不同，声调相同，意思是这件事。"}, "sentence_index": null, "correct_answer": "启示"}, "level_3": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：此处指实验带来的启发与领悟，与“带给”搭配，是唯一能填入的词。"}, {"text": "旅馆", "is_correct": false, "explanation": "语义：旅馆是场所，不能被实验“带给”科学家。"}, {"text": "俚语", "is_correct": false, "explanation": "语域：俚语是口语化的用语，与这句书面语语境不合。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是自然声响，不是实验能“带给”科学家的东西。"}], "explanations": {"启示": "启示：此处指实验带来的启发与领悟，与“带给”搭配，是唯一能填入的词。", "旅馆": "语义：旅馆是场所，不能被实验“带给”科学家。", "俚语": "语域：俚语是口语化的用语，与这句书面语语境不合。", "雷声": "语义：雷声是自然声响，不是实验能“带给”科学家的东西。"}, "sentence_index": 6, "correct_answer": "启示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一张去北京的启示。", "explanation": "这里应该用〈车票〉。买去北京的车票，启示指启发领悟的道理，不能当作车票。"}, {"text": "这道题的启示是三十。", "explanation": "这里应该用〈答案〉。答案是问题的结果，启示指启发领悟的道理，不能表示数字结果。"}, {"text": "这张门票是进场的启示。", "explanation": "这里应该用〈凭证〉。凭证是用来证明身份或资格的东西，启示指启发领悟的道理，不能当作进场的凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事让我得到了很大的启示们。", "corrected_sentence": "这件事让我得到了很大的启示。", "error_description": "错误：“启示”后加了“们”。正确：“们”只用于指人，“启示”后不能加“们”，应说“很大的启示”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行给了我一只很大的启示。", "corrected_sentence": "这次旅行给了我一个很大的启示。", "error_description": "错误：量词“只”用于“启示”。正确：“启示”是抽象名词，应用量词“个”，说“一个很大的启示”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
