INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12059, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情在将来一定会发生或达到某种结果。", "primary_collocate": null, "pronunciation": "zhōng jiāng", "ipa": "ʈʂʊŋ˥ tɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "虚拟世界因而成为理解21世纪社会性的一把密钥，其启示或许终将反哺现实世界的组织哲学与共同体构建。", "target_word": "终将", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "终将", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "只要不放弃，你终将成功。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天已经来了，春天终将到来。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎话说得再多，真相终将出现。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子终将长大，要离开父母的家。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜再长，天终将亮。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力学习的人，终将有好结果。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信这座城市终将变得更美。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间会证明，正确的选择终将得到回报。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "終將", "label": "繁体"}], "register": "书面", "sense_fingerprint": "终将:副词，表示将来一定会发生或达到某种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff508bb-4dd4-4d17-9788-2be285a2506d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示将来必然实现，句中“终将反哺”描述的是长远的将来结果，填入后语义通顺。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上发生，与“终将”所表示的长远将来不符，也与“或许”的推测不搭。"}, {"text": "已经", "is_correct": false, "explanation": "时间：“已经”表示已然发生，与句中对将来启示的推测不符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能直接用在“或许”之后修饰“反哺”。"}], "explanations": {"终将": "“终将”表示将来必然实现，句中“终将反哺”描述的是长远的将来结果，填入后语义通顺。", "立刻": "语义：“立刻”指马上发生，与“终将”所表示的长远将来不符，也与“或许”的推测不搭。", "已经": "时间：“已经”表示已然发生，与句中对将来启示的推测不符。", "从来": "搭配：“从来”多与否定词连用，不能直接用在“或许”之后修饰“反哺”。"}, "sentence_index": 0, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天终将回家，我们都很高兴。", "explanation": "这里应该用〈终于〉。“终将”指将来必然出现的结果，句中的“昨天”已经过去，不能与“终将”搭配。"}, {"text": "去年，我们终将决定去北京。", "explanation": "这里应该用〈最终〉。这是去年已经做出的决定，“终将”只用来说将来必然出现的结果。"}, {"text": "我马上终将出发。", "explanation": "这里应该用〈即将〉。“终将”指遥远的将来必然出现的结果，“马上”说的是眼前的事，两者语义冲突，不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示经过一段时间必然实现，与“黑夜再长”的等待语境相合。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“天终将亮”所表示的必然结果相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“黑夜再长”所描述的仍需等待的情况矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生的动作，不能修饰“天亮”这类必然的自然变化。"}], "explanations": {"终将": "“终将”表示经过一段时间必然实现，与“黑夜再长”的等待语境相合。", "从不": "语义：“从不”表示从来没有，与“天终将亮”所表示的必然结果相矛盾。", "已经": "语义：“已经”表示已经发生，与“黑夜再长”所描述的仍需等待的情况矛盾。", "偶尔": "搭配：“偶尔”表示不常发生的动作，不能修饰“天亮”这类必然的自然变化。"}, "sentence_index": 6, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年终将没有放弃比赛。", "explanation": "这里应该用〈终究〉。“终将”指将来必然发生，句中的“去年”已经过去，不能用“终将”描述已经发生的事。"}, {"text": "那天，他终将决定留下来。", "explanation": "这里应该用〈最后〉。这是当天已经做出的决定，“终将”只用来说将来必然出现的结果。"}, {"text": "这场比赛终将谁会赢？", "explanation": "这里应该用〈到底〉。“终将”是陈述句中的副词，表示结果必然出现，不用于疑问句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨终将停了，我们可以出门了。", "corrected_sentence": "这场雨终将停，我们可以出门了。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然出现的结果，不能与表示已经完成的“了”搭配，应说“这场雨终将停”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "落后的技术终将被淘汰了。", "corrected_sentence": "落后的技术终将被淘汰。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然发生，不能与表示完成的“了”搭配，应说“落后的技术终将被淘汰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6e9e744-4847-4ffa-9912-38d63166b1ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指幼鸟长大后，衔食喂养其母鸟。比喻子女长大后，回报父母的养育之恩。", "primary_collocate": null, "pronunciation": "fǎn bǔ", "ipa": "fan˨˩˦ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "她出国留学多年，学成后便一心想着反哺年迈的母亲。", "target_word": "反哺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，要懂得反哺父母。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乌鸦长大后会反哺母鸟。", "target_word": "反哺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他工作以后，每月寄五千元回家，用来反哺父母。", "target_word": "反哺", "complexity_tier": "T3", "furigana": "fǎn bǔ", "sentence_source": "generated"}, {"text": "父母养大了我，现在轮到我反哺他们。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟长大了，开始反哺它的妈妈。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用自己的收入反哺老家的父母。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位企业家成功后，仍不忘父母的养育之恩，常常反哺他们。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能只靠父母，也要学会反哺。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在外打工多年，一直在反哺年迈的父母。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反哺了", "label": "完成体"}, {"form": "反哺过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "反哺|幼鸟喂养母鸟，比喻子女回报父母养育之恩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f96f18b6-c394-4703-a301-fe5590358afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反哺", "is_correct": true, "explanation": "fǎn bǔ（第三声）即本词，指子女长大后回报父母的养育之恩。"}, {"text": "反赌", "is_correct": false, "explanation": "反赌 fǎn dǔ 与 fǎn bǔ 只有第二音节声母不同（d 与 b），意思是反对赌博。"}, {"text": "反腐", "is_correct": false, "explanation": "反腐 fǎn fǔ 与 fǎn bǔ 只有第二音节声母不同（f 与 b），意思是反对腐败。"}, {"text": "反比", "is_correct": false, "explanation": "反比 fǎn bǐ 与 fǎn bǔ 只有第二音节韵母不同（i 与 u），意思是两个量的乘积恒定、此增彼减的关系。"}], "explanations": {"反哺": "fǎn bǔ（第三声）即本词，指子女长大后回报父母的养育之恩。", "反赌": "反赌 fǎn dǔ 与 fǎn bǔ 只有第二音节声母不同（d 与 b），意思是反对赌博。", "反腐": "反腐 fǎn fǔ 与 fǎn bǔ 只有第二音节声母不同（f 与 b），意思是反对腐败。", "反比": "反比 fǎn bǐ 与 fǎn bǔ 只有第二音节韵母不同（i 与 u），意思是两个量的乘积恒定、此增彼减的关系。"}, "sentence_index": null, "correct_answer": "反哺"}, "level_3": {"options": [{"text": "反哺", "is_correct": true, "explanation": "与上下文相符：学成后一心想着回报年迈母亲的养育之恩，正是“反哺”的用法。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：抛弃是舍弃不管，与“一心想着……”的回报之意正相反，句意不通。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：嫌弃是厌恶、不愿接近，与回报养育之恩的意思相反，句意不通。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物体或空间，不能说“装饰年迈的母亲”。"}], "explanations": {"反哺": "与上下文相符：学成后一心想着回报年迈母亲的养育之恩，正是“反哺”的用法。", "抛弃": "语义：抛弃是舍弃不管，与“一心想着……”的回报之意正相反，句意不通。", "嫌弃": "语义：嫌弃是厌恶、不愿接近，与回报养育之恩的意思相反，句意不通。", "装饰": "搭配：“装饰”的对象是物体或空间，不能说“装饰年迈的母亲”。"}, "sentence_index": 0, "correct_answer": "反哺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一定要反哺路人的恩情。", "explanation": "这里应该用〈报答〉。反哺专指子女对父母养育之恩的回报，对路人的恩情要用报答。"}, {"text": "他终于反哺了欠朋友的钱。", "explanation": "这里应该用〈偿还〉。反哺指回报养育之恩，不指归还金钱上的债务，欠钱还钱要用偿还。"}, {"text": "我们在宴会上反哺客人。", "explanation": "这里应该用〈答谢〉。反哺只用于子女与父母之间，宴会上对客人的感谢要用答谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反哺", "is_correct": true, "explanation": "与上下文相符：“用自己的收入”回报老家的父母，正是“反哺”的用法。"}, {"text": "花费", "is_correct": false, "explanation": "配价：“花费”的宾语是钱财或时间，不能直接接“老家的父母”作宾语。"}, {"text": "转让", "is_correct": false, "explanation": "配价：“转让”的宾语是财产或权利，不能说“转让老家的父母”。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”是用言语表达美好的愿望，与“用收入”的手段不相符。"}], "explanations": {"反哺": "与上下文相符：“用自己的收入”回报老家的父母，正是“反哺”的用法。", "花费": "配价：“花费”的宾语是钱财或时间，不能直接接“老家的父母”作宾语。", "转让": "配价：“转让”的宾语是财产或权利，不能说“转让老家的父母”。", "祝福": "语义：“祝福”是用言语表达美好的愿望，与“用收入”的手段不相符。"}, "sentence_index": 6, "correct_answer": "反哺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司终于反哺了受害工人。", "explanation": "这里应该用〈补偿〉。反哺只用于子女回报父母的恩情，对受害者的赔偿要用补偿。"}, {"text": "他去医院反哺病人。", "explanation": "这里应该用〈慰问〉。反哺指回报养育之恩，探望病人表示关心要用慰问。"}, {"text": "他反哺了路边的流浪猫。", "explanation": "这里应该用〈喂养〉。反哺专指子女回报父母的养育之恩，对流浪猫的照顾要用喂养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子长大了，应该反哺在父母。", "corrected_sentence": "孩子长大了，应该反哺父母。", "error_description": "错误在于“反哺”后多加了介词“在”。“反哺”是及物动词，后面直接接宾语，应说“反哺父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直在反哺在年迈的母亲。", "corrected_sentence": "她一直在反哺年迈的母亲。", "error_description": "错误在于“反哺”与宾语之间多加了“在”。“反哺”后直接接宾语，应说“反哺年迈的母亲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd438de31-d2f2-4485-ba1f-d93681089655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
