INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或鸟兽用脚向前移动。", "primary_collocate": null, "pronunciation": "zǒu", "ipa": "tsoʊ˨˩", "syllable_count": 1, "sentences": [{"text": "雨后，小猫在湿湿的草地上慢慢地走。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹第一次自己走到学校去。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一岁就会走了。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢地在公园里走着。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在地上走了几步，没有飞。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着这条小路一直往前走。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过那座桥，来到河边。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸭子走得很慢，一摇一摆的。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一个小时，我们都累了。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗在雪地上走着，留下了脚印。", "target_word": "走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走了", "label": "体标"}, {"form": "走着", "label": "体标"}, {"form": "走过", "label": "体标"}, {"form": "走开", "label": "复合"}], "register": "通用", "sense_fingerprint": "走|人或鸟兽用脚向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12883278-5600-40df-b779-2c94d6e49eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走", "is_correct": true, "explanation": "走表示用脚前行，与“小猫在湿草地上慢慢地”的动作相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中飞行，小猫不能说“飞”。"}, {"text": "驶", "is_correct": false, "explanation": "搭配：“驶”多用于车船，不能以“小猫”为主语。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中游动，与草地的场景不符。"}], "explanations": {"走": "走表示用脚前行，与“小猫在湿草地上慢慢地”的动作相符。", "飞": "语义：“飞”指在空中飞行，小猫不能说“飞”。", "驶": "搭配：“驶”多用于车船，不能以“小猫”为主语。", "游": "语义：“游”指在水中游动，与草地的场景不符。"}, "sentence_index": 0, "correct_answer": "走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蝴蝶在花丛中走。", "explanation": "这里应该用〈飞〉。蝴蝶靠翅膀在空中飞行，不说走。"}, {"text": "树叶在水面上走。", "explanation": "这里应该用〈漂〉。树叶随水流动，没有脚，要说漂。"}, {"text": "鱼在水里走。", "explanation": "这里应该用〈游〉。鱼靠游动前进，没有脚，不用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走", "is_correct": true, "explanation": "动词用法，“走过”表示经过那座桥，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能表示经过桥，“唱过那座桥”句意不通。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”指用手支撑，不能表示从桥上经过。"}, {"text": "喊", "is_correct": false, "explanation": "搭配：“喊”不与“桥”搭配作宾语，“喊过那座桥”不通。"}], "explanations": {"走": "动词用法，“走过”表示经过那座桥，与句意相符。", "唱": "语义：“唱”不能表示经过桥，“唱过那座桥”句意不通。", "扶": "语义：“扶”指用手支撑，不能表示从桥上经过。", "喊": "搭配：“喊”不与“桥”搭配作宾语，“喊过那座桥”不通。"}, "sentence_index": 6, "correct_answer": "走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蛇在草地上走了很远。", "explanation": "这里应该用〈爬〉。蛇没有脚，靠身体爬行，不能说走。"}, {"text": "他每天走摩托车去上班。", "explanation": "这里应该用〈骑〉。骑摩托车要说骑，不能说走。"}, {"text": "皮球在地上走了好远。", "explanation": "这里应该用〈滚〉。皮球靠滚动移动，不是用脚走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她走很快，不久就到了车站。", "corrected_sentence": "她走得很快，不久就到了车站。", "error_description": "错误：“走很快”；正确：“走得很快”。动词与状态补语之间要用“得”连接，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走得三次同一条路。", "corrected_sentence": "我们走过三次同一条路。", "error_description": "错误：“走得三次”；正确：“走过三次”。“得”后要接状态补语，不能直接接数量词，表示经历过几次要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：「用力」指使劲施力，「放松」指不再紧张施力，二者相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "散步", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}], "correct_answer": "放松", "explanations": {"放松": "反义：「用力」指使劲施力，「放松」指不再紧张施力，二者相对。", "睡觉": "与「用力」无反义关系，二者不构成对立。", "唱歌": "与「用力」无反义关系，二者不构成对立。", "散步": "与「用力」无反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松手", "is_correct": true, "explanation": "反义：「用力」指施力，「松手」指放开，二者相对。"}, {"text": "阅读", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "跳舞", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}, {"text": "写字", "is_correct": false, "explanation": "与「用力」无反义关系，二者不构成对立。"}], "correct_answer": "松手", "explanations": {"松手": "反义：「用力」指施力，「松手」指放开，二者相对。", "阅读": "与「用力」无反义关系，二者不构成对立。", "跳舞": "与「用力」无反义关系，二者不构成对立。", "写字": "与「用力」无反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使出身体的力气。", "primary_collocate": null, "pronunciation": "yòng lì", "ipa": "jʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "下面的空气用力推翅膀，让飞机上去。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "发动机要用力，才能让飞机向前。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他用力推开了那扇重门。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用力拉这根绳子。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用力吹，气球一下子大了。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再用力一点，车就动了。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用力地点了点头。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力跑到了车站。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用力敲了敲门。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬桌子的时候，大家一起用力。", "target_word": "用力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用了力", "label": "体标"}, {"form": "用过力", "label": "体标"}, {"form": "用力地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "使出力气（物体或人施力），强调力的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力」读作 yòng lì，指使出力气。"}, {"text": "运力", "is_correct": false, "explanation": "韵尾不同：「运力」第一音节为 yùn（n 韵尾），「用力」为 yòng（ng 韵尾），意思是运输能力。"}, {"text": "样例", "is_correct": false, "explanation": "韵母不同：「样」为 yàng，「用」为 yòng，两者只差一个元音，意思是样例。"}, {"text": "勇力", "is_correct": false, "explanation": "声调不同：「勇」为第三声 yǒng，「用」为第四声 yòng，意思是勇敢有力。"}], "explanations": {"用力": "正确。「用力」读作 yòng lì，指使出力气。", "运力": "韵尾不同：「运力」第一音节为 yùn（n 韵尾），「用力」为 yòng（ng 韵尾），意思是运输能力。", "样例": "韵母不同：「样」为 yàng，「用」为 yòng，两者只差一个元音，意思是样例。", "勇力": "声调不同：「勇」为第三声 yǒng，「用」为第四声 yòng，意思是勇敢有力。"}, "sentence_index": null, "correct_answer": "用力"}, "level_3": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力」修饰「推」，表示使劲推动翅膀。"}, {"text": "动手", "is_correct": false, "explanation": "语义：空气没有手，不能「动手」去推翅膀。"}, {"text": "动脑", "is_correct": false, "explanation": "搭配：「动脑」指动脑筋思考，不与「推翅膀」这样的身体动作搭配。"}, {"text": "挥手", "is_correct": false, "explanation": "语义：挥手是人的动作，空气不能挥手推动翅膀。"}], "explanations": {"用力": "正确。「用力」修饰「推」，表示使劲推动翅膀。", "动手": "语义：空气没有手，不能「动手」去推翅膀。", "动脑": "搭配：「动脑」指动脑筋思考，不与「推翅膀」这样的身体动作搭配。", "挥手": "语义：挥手是人的动作，空气不能挥手推动翅膀。"}, "sentence_index": 0, "correct_answer": "用力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力地答应了朋友的请求。", "explanation": "这里应该用〈爽快〉。用力指使出力气，答应请求是表态，应说〈爽快地答应〉。"}, {"text": "他用力地患上了一场感冒。", "explanation": "这里应该用〈不幸〉。用力指使出力气，患病不靠力气，应说〈不幸〉。"}, {"text": "他用力地决定了去北京。", "explanation": "这里应该用〈果断〉。用力指使出力气，做决定靠判断，应说〈果断〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用力", "is_correct": true, "explanation": "正确。「用力地」修饰「点头」，表示使劲点头。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：点头是无声的动作，「大声地点了点头」搭配不当。"}, {"text": "随口", "is_correct": false, "explanation": "语义：随口指随便说话，与点头的动作无关，句意不通。"}, {"text": "高喊", "is_correct": false, "explanation": "语义：高喊是发出声音的动作，与「点头」前后矛盾。"}], "explanations": {"用力": "正确。「用力地」修饰「点头」，表示使劲点头。", "大声": "搭配：点头是无声的动作，「大声地点了点头」搭配不当。", "随口": "语义：随口指随便说话，与点头的动作无关，句意不通。", "高喊": "语义：高喊是发出声音的动作，与「点头」前后矛盾。"}, "sentence_index": 6, "correct_answer": "用力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力地知道了这件事。", "explanation": "这里应该用〈得知〉。用力指使出力气，知道消息不靠力气，应说〈得知〉。"}, {"text": "他用力地原谅了朋友的错误。", "explanation": "这里应该用〈宽容〉。用力指使出力气，原谅是态度，应说〈宽容〉。"}, {"text": "她用力地为自己感到骄傲。", "explanation": "这里应该用〈自豪〉。用力指使出力气，骄傲是心情，应说〈自豪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用力得打开了窗户。", "corrected_sentence": "他用力地打开了窗户。", "error_description": "助词错误：状语「用力」后应用助词「地」，「得」用于补语。正确说法是「他用力地打开了窗户」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用力了把箱子搬上车。", "corrected_sentence": "他用了力把箱子搬上车。", "error_description": "语序错误：「用」与「力」是动词加宾语，「了」应放在「用」后，应说「用了力」，不能说「用力了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "站", "is_correct": false, "explanation": "站：指身体直立，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使物体向自己这边移动。"}, {"text": "跳", "is_correct": false, "explanation": "跳：指身体离开地面，与“推”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：指面部表情，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"站": "站：指身体直立，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使物体向自己这边移动。", "跳": "跳：指身体离开地面，与“推”没有反义关系。", "笑": "笑：指面部表情，与“推”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喝", "is_correct": false, "explanation": "喝：指用嘴吞咽液体，与“推”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡：指闭眼休息，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使物体向自己这边移动。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔记录文字，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"喝": "喝：指用嘴吞咽液体，与“推”没有反义关系。", "睡": "睡：指闭眼休息，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使物体向自己这边移动。", "写": "写：指用笔记录文字，与“推”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具使物体向自己前方或离开原位置移动。", "primary_collocate": null, "pronunciation": "tuī", "ipa": "tʰuei̯˥", "syllable_count": 1, "sentences": [{"text": "他用力把船推离了岸，然后跳上船。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手推门，门却打不开。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用木棍把大石头推到路边。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，我推不开窗户。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用小铲子把沙子推到一边。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力推开桌子，坐了下来。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士推着病人去做检查。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子推回桌子下面。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船靠岸了，他用竹竿推了一下船。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门很重，我用手推了好几次。", "target_word": "推", "complexity_tier": "T3", "furigana": "zhè shàn mén hěn zhòng wǒ yòng shǒu tuī le hǎo jǐ cì", "sentence_source": "generated"}], "morphological_forms": [{"form": "推了", "label": "体标"}, {"form": "推着", "label": "体标"}, {"form": "推过", "label": "体标"}, {"form": "推推", "label": "重叠"}, {"form": "推开", "label": "复合"}], "register": "中性", "sense_fingerprint": "推：用手或工具使物体离开原位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "腿", "is_correct": false, "explanation": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或工具使物体离开原位置。"}, {"text": "退", "is_correct": false, "explanation": "推（第一声）与退（第四声）声调不同，退指向后移动。"}, {"text": "堆", "is_correct": false, "explanation": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}], "explanations": {"腿": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。", "推": "正确答案。推 tuī（第一声），指用手或工具使物体离开原位置。", "退": "推（第一声）与退（第四声）声调不同，退指向后移动。", "堆": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "压", "is_correct": false, "explanation": "语义：压是向下按，不能表示船离开岸边。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“推”表示用力使船离开原位置，与“离了岸”一致。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”指放置，不能表示用力使船离开岸边。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，与把船推离岸边的动作无关。"}], "explanations": {"压": "语义：压是向下按，不能表示船离开岸边。", "推": "正确答案。“推”表示用力使船离开原位置，与“离了岸”一致。", "放": "搭配：“放”指放置，不能表示用力使船离开岸边。", "唱": "语义：唱是发声歌唱，与把船推离岸边的动作无关。"}, "sentence_index": 0, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用湿毛巾把桌子推干净了。", "explanation": "这里应该用〈擦〉。推是使物体移动，把桌面擦干净要用擦。"}, {"text": "我用力把门推向我身边，门终于开了。", "explanation": "这里应该用〈拉〉。推是使物体向前或离开原位置，把门往自己身边移动要用拉。"}, {"text": "他用力推住绳子，不让它掉下去。", "explanation": "这里应该用〈抓〉。推是使物体移动，握住绳子要用抓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吹", "is_correct": false, "explanation": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。"}, {"text": "催", "is_correct": false, "explanation": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或工具使物体离开原位置。"}, {"text": "追", "is_correct": false, "explanation": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}], "explanations": {"吹": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。", "催": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。", "推": "正确答案。推 tuī（第一声），指用手或工具使物体离开原位置。", "追": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能带“病人”作宾语去做检查。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，与“护士”带病人去检查的语境无关。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“推着”表示护士用手推动轮床或轮椅载着病人。"}, {"text": "读", "is_correct": false, "explanation": "语义：读是看书或念字，无法表示护士带病人去检查。"}], "explanations": {"吃": "搭配：“吃”的宾语应是食物，不能带“病人”作宾语去做检查。", "唱": "语义：唱是发声歌唱，与“护士”带病人去检查的语境无关。", "推": "正确答案。“推着”表示护士用手推动轮床或轮椅载着病人。", "读": "语义：读是看书或念字，无法表示护士带病人去检查。"}, "sentence_index": 6, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把脏衣服推干净了。", "explanation": "这里应该用〈洗〉。推是使物体移动，把衣服弄干净要用洗。"}, {"text": "他推起了孩子，走向门口。", "explanation": "这里应该用〈抱〉。推是使物体离开原位置，抱孩子要用双臂环住身体。"}, {"text": "他用手推住嘴，没有说出一句话。", "explanation": "这里应该用〈捂〉。推是使物体移动，用手盖住嘴要用捂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用手开推了厨房的门。", "corrected_sentence": "妈妈用手推开了厨房的门。", "error_description": "错误：“开推”。“开”是结果补语，应放在动词“推”之后，写作“推开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务员推车着走进了包间。", "corrected_sentence": "服务员推着餐车走进了包间。", "error_description": "错误：“推车着”。“着”应紧跟动词“推”，写作“推着餐车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理学中，使物体运动或形变的作用；也泛指能力、力量。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "这样就会产生一种向上的力，使飞机离开地面。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机翼上下的气流速度不同，因此会产生向上的力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种挡住飞机的力叫“阻力”。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "所以飞机的外形要做得光滑，使空气对它的力尽量减小。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引擎的作用就是产生向前的力，帮助飞机克服阻力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "飞机能否上升，取决于它受到的向上的力是否足够大。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果向前的力不够，飞机就会变慢，甚至飞不动。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们观察这种力的变化，再改进设计。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种压差垂直于气流方向，形成向上的力，即升力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升力", "label": "复合词"}, {"form": "阻力", "label": "复合词"}, {"form": "推力", "label": "复合词"}, {"form": "重力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "物理学中使物体运动或形变的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d954bdb-808a-46ea-869b-37621b1d7757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是力。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同（n 与 l），“逆”意思是逆向、倒着。"}], "explanations": {"力": "正确：lì（第四声），意思是力。", "离": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。", "礼": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。", "里": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。", "逆": "nì（第四声）与 lì 声母不同（n 与 l），“逆”意思是逆向、倒着。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：使飞机离开地面的是使物体运动的作用，即力。"}, {"text": "光", "is_correct": false, "explanation": "语义：光是光线，不是使物体运动的作用，不能使飞机离开地面。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不是作用，不能说“产生一种向上的水”。"}, {"text": "声", "is_correct": false, "explanation": "语义：声是声音，不是使物体运动的作用，不能使飞机离开地面。"}], "explanations": {"力": "正确：使飞机离开地面的是使物体运动的作用，即力。", "光": "语义：光是光线，不是使物体运动的作用，不能使飞机离开地面。", "水": "语义：水是液体，不是作用，不能说“产生一种向上的水”。", "声": "语义：声是声音，不是使物体运动的作用，不能使飞机离开地面。"}, "sentence_index": 0, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块电池可以储存很多力。", "explanation": "这里应该用〈能量〉。电池储存的是能量，力是物体之间的作用，不能被储存。"}, {"text": "他推着箱子，做了很多力。", "explanation": "这里应该用〈功〉。物理学中说“做功”，“力”不能和“做”搭配，应说“做了很多功”。"}, {"text": "他在墙上贴了一个力。", "explanation": "这里应该用〈海报〉。力是物体之间的作用，不能贴在墙上；贴在墙上的是海报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是力。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“理”意思是道理。"}, {"text": "李", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“李”意思是李子，也是姓。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“梨”意思是梨子。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}], "explanations": {"力": "正确：lì（第四声），意思是力。", "理": "lǐ（第三声）与 lì（第四声）声调不同，“理”意思是道理。", "李": "lǐ（第三声）与 lì（第四声）声调不同，“李”意思是李子，也是姓。", "梨": "lí（第二声）与 lì（第四声）声调不同，“梨”意思是梨子。", "日": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：句中指使飞机上升的作用，应为“力”。"}, {"text": "数", "is_correct": false, "explanation": "语义：“向上的数是否足够大”不通，数是数目，与飞机上升无关。"}, {"text": "油", "is_correct": false, "explanation": "语义：“向上的油是否足够大”不通，油是液体，与飞机上升无关。"}, {"text": "水", "is_correct": false, "explanation": "语义：“向上的水是否足够大”不通，水是液体，与飞机上升无关。"}], "explanations": {"力": "正确：句中指使飞机上升的作用，应为“力”。", "数": "语义：“向上的数是否足够大”不通，数是数目，与飞机上升无关。", "油": "语义：“向上的油是否足够大”不通，油是液体，与飞机上升无关。", "水": "语义：“向上的水是否足够大”不通，水是液体，与飞机上升无关。"}, "sentence_index": 6, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜的力很甜。", "explanation": "这里应该用〈味道〉。力没有甜不甜的说法；说甜的是味道。"}, {"text": "这个灯泡的力是六十瓦。", "explanation": "这里应该用〈功率〉。功率用“瓦”计量，表示做功的快慢；“力”用牛顿计量，不能用“瓦”。"}, {"text": "这条路的力很平。", "explanation": "这里应该用〈路面〉。力是作用，没有平不平的说法；说平的是路面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机受到一条向上的力，就能升空。", "corrected_sentence": "飞机受到一个向上的力，就能升空。", "error_description": "“力”的量词应为“个”，不能用“条”（“条”用于细长的东西）。应说“一个向上的力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用了一个很大地力，门就开了。", "corrected_sentence": "他用了一个很大的力，门就开了。", "error_description": "“力”前的修饰语“很大”应用结构助词“的”，不能用“地”（“地”用于状语）。应说“一个很大的力”，不说“一个很大地力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跑步", "is_correct": false, "explanation": "跑步：指快速用脚移动，与“向前走”没有反义关系。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：指在水中划动身体前进，与“向前走”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "画画：指用笔绘制图形，与“向前走”没有反义关系。"}], "correct_answer": "向后走", "explanations": {"跑步": "跑步：指快速用脚移动，与“向前走”没有反义关系。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。", "游泳": "游泳：指在水中划动身体前进，与“向前走”没有反义关系。", "画画": "画画：指用笔绘制图形，与“向前走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：指用笔写出文字，与“向前走”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书：指阅读书籍，与“向前走”没有反义关系。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}], "correct_answer": "向后走", "explanations": {"唱歌": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。", "写字": "写字：指用笔写出文字，与“向前走”没有反义关系。", "读书": "读书：指阅读书籍，与“向前走”没有反义关系。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "朝着前方行进。", "primary_collocate": null, "pronunciation": "xiàng qián zǒu", "ipa": "ɕi̯ɑŋ˥˩ tɕʰi̯ɛn˧˥ tsou̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "小船向前走的时候，水会阻碍它走快，这个叫阻力。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家排好队，慢慢向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，他还是一直向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有水，你别再向前走了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着老师向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着地图，向前走了十分钟。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到红灯，我们就不能向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很窄，我们只能一个一个向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要回头，向前走就对了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察让大家向前走，不要停在门口。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走了", "label": "体标"}, {"form": "向前走着", "label": "体标"}, {"form": "向前走过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向前走：朝着前方行进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停下", "is_correct": false, "explanation": "语义：小船停着时，水谈不上阻碍它走快，与“走快”的语境冲突。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“向前走”指朝前方行进，与“阻力”的语境吻合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：小船不会跳舞，与“水阻碍它走快”的语境完全不合。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”指飞机从空中落到地面，小船不能降落。"}], "explanations": {"停下": "语义：小船停着时，水谈不上阻碍它走快，与“走快”的语境冲突。", "向前走": "正确答案。“向前走”指朝前方行进，与“阻力”的语境吻合。", "跳舞": "语义：小船不会跳舞，与“水阻碍它走快”的语境完全不合。", "降落": "搭配：“降落”指飞机从空中落到地面，小船不能降落。"}, "sentence_index": 0, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直向前走在原地等我们。", "explanation": "这里应该用〈站〉。“向前走”表示朝前行进，与“在原地”矛盾，停在原地要用站。"}, {"text": "我们向前走了两步，又向前走回了原地。", "explanation": "这里应该用〈后退〉。“向前走”表示朝前行进，与“走回原地”的返回方向矛盾，往后移动要用后退。"}, {"text": "他倒着向前走，一直没有回头。", "explanation": "这里应该用〈倒着走〉。“倒着”与“向前”方向相反，不能同时修饰“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是身体随音乐摆动，与“看到红灯”后不能做的动作不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，与红灯前不能前进的语境不合。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“不能向前走”表示看到红灯后不能继续前行。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不是能被“不能”否定的行进动作，与红灯语境不搭配。"}], "explanations": {"跳舞": "语义：跳舞是身体随音乐摆动，与“看到红灯”后不能做的动作不合。", "睡觉": "语义：睡觉是休息，与红灯前不能前进的语境不合。", "向前走": "正确答案。“不能向前走”表示看到红灯后不能继续前行。", "吃饭": "搭配：“吃饭”不是能被“不能”否定的行进动作，与红灯语境不搭配。"}, "sentence_index": 6, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向前走在床上，一直没有醒。", "explanation": "这里应该用〈躺〉。“向前走”表示行进，躺在床上是静止的，要用躺。"}, {"text": "他向前走在地上，向老人磕了三个头。", "explanation": "这里应该用〈跪〉。“向前走”表示行进，磕头时要跪着，不能用走。"}, {"text": "他手脚并用，向前走上了墙。", "explanation": "这里应该用〈爬〉。“向前走”指在平地上朝前行进，不能表示沿墙面向上移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿着河岸向前走很快。", "corrected_sentence": "我们沿着河岸向前走得很快。", "error_description": "错误：“向前走很快”。缺少补语标记“得”，应写作“向前走得很快”，用“得”引出表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向前走着几步，就停了下来。", "corrected_sentence": "他向前走了几步，就停了下来。", "error_description": "错误：“向前走着几步”。“着”表示动作持续，不能接数量短语；表示完成的动作应用“了”，写作“向前走了几步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12078, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
